(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-025"]={"sura":25,"name_ar":"الفرقان","name_en":"Al-Furqan","verses":77,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":77,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=2\" class=\"link\">25:2</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:2 ஐ பார்க்கவும்"},"2":{"html":"<strong>மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>அல்லாஹ் பாக்கியமிக்கவன்</strong><br />\r\n<br />\r\nஇங்கு அல்லாஹ், தனது கண்ணியமிக்க தூதருக்கு (ஸல்) அருளிய மேன்மைமிக்க குர்ஆனுக்காகத் தன்னைத் தானே புகழ்கிறான். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الْحَمْدُ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنْزَلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَبْدِهِ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبَ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">عِوَجَا</span> <span class=\"quran-arabic-font text-success\">قَيِّماً</span> <span class=\"quran-arabic-font text-success\">لِّيُنْذِرَ</span> <span class=\"quran-arabic-font text-success\">بَأْسًا</span> <span class=\"quran-arabic-font text-success\">شَدِيدًا</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">لَّدُنْهُ</span> <span class=\"quran-arabic-font text-success\">وَيُبَشِّرَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">الصَّـلِحَاتِ</span><br />\r\n<br />\r\n(அனைத்துப் புகழும் அல்லாஹ்வுக்கே உரியது! அவன் தனது அடியார் மீது இவ்வேதத்தை அருளினான்; அதில் அவன் எவ்விதக் கோணலையும் வைக்கவில்லை. அவன் அதை நேரானதாக ஆக்கினான்; அவனிடமிருந்துள்ள கடுமையான வேதனையைக் குறித்து எச்சரிப்பதற்காகவும், நற்செயல்கள் புரியும் மூஃமின்களுக்கு (நம்பிக்கையாளர்களுக்கு) நற்செய்தி அறிவிப்பதற்காகவும்...) <a href=\"qurandisp.php?sura=18&ayah=1\" class=\"link\">18:1</a>-2. இங்கு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَبَارَكَ</span><br />\r\n<br />\r\n(அவன் பாக்கியமிக்கவன்.) இங்கு பயன்படுத்தப்பட்டுள்ள வினைச்சொல் வடிவம், தொடர்ச்சியான, நிரந்தரமான, நித்தியமான அருளைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">الْفُرْقَانَ</span><br />\r\n<br />\r\n(அவன் ஃபுர்கானை - சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறிவிக்கும் அளவுகோலை - அருளினான்). 'நஸ்ஸல' (Nazzala) எனும் வினைச்சொல் வடிவம், ஒரு காரியம் மீண்டும் மீண்டும், அதிகமாகச் செய்யப்படுவதைக் குறிக்கும். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَسُولِهِ</span> <span class=\"quran-arabic-font text-success\">وَالْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَنَزلَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلُ</span><br />\r\n<br />\r\n(மேலும், அவன் தனது தூதர் மீது (படிப்படியாக) அருளிய இவ்வேதத்தையும், இதற்கு முன்னர் அவன் (ஒரே நேரத்தில்) அருளிய வேதத்தையும் (நம்புங்கள்)) (<a href=\"qurandisp.php?sura=4&ayah=136\" class=\"link\">4:136</a>). இதற்கு முந்தைய வேதங்கள் ஒவ்வொன்றும் ஒரே நேரத்தில் அருளப்பட்டன. ஆனால், குர்ஆன் படிப்படியாக, பகுதி பகுதியாக, வசனத்திற்குப் பின் வசனமாக, சட்டங்களுக்குப் பின் சட்டங்களாக, அத்தியாயங்களுக்குப் பின் அத்தியாயங்களாக அருளப்பட்டது. இது மிகவும் நயமானது; மேலும் இது யாருக்கு வஹீ (இறைச்செய்தி) அருளப்பட்டதோ அவர் மீது அல்லாஹ் கொண்டுள்ள பெரும் அக்கறையைக் காட்டுகிறது. இந்த அத்தியாயத்தில் அல்லாஹ் பின்னர் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">جُمْلَةً</span> <span class=\"quran-arabic-font text-success\">وَحِدَةً</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِنُثَبِّتَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">فُؤَادَكَ</span> <span class=\"quran-arabic-font text-success\">وَرَتَّلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">تَرْتِيلاً</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَكَ</span> <span class=\"quran-arabic-font text-success\">بِمَثَلٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جِئْنَـكَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">تَفْسِيراً</span><br />\r\n<br />\r\n(மேலும், \"இந்தக் குர்ஆன் அவருக்கு ஏன் ஒரே தடவையில் அருளப்படவில்லை?\" என்று காஃபிர்கள் (நிராகரிப்பாளர்கள்) கேட்கின்றனர். இவ்வாறே (படிப்படியாக நாம் அருளினோம்); இதன் மூலம் உமது உள்ளத்தை நாம் உறுதிப்படுத்துவதற்காக. நாம் இதனை மிகத் தெளிவாகவும் முறைப்படியாகவும் ஓதிக் காண்பித்தோம். அவர்கள் உம்மிடம் எந்தவொரு வாதத்தைக் கொண்டு வந்தாலும், அதற்குரிய சத்தியத்தையும் மிகச்சிறந்த விளக்கத்தையும் நாம் உமக்குத் தராமல் இருப்பதில்லை.) (<a href=\"qurandisp.php?sura=25&ayah=32\" class=\"link\">25:32</a>-33). இந்த அத்தியாயத்திற்கு 'அல்-ஃபுர்கான்' என்று பெயரிடப்பட்டது, ஏனெனில் இது சத்தியத்திற்கும் அசத்தியத்திற்கும், நேர்வழிக்கும் வழிகேட்டிற்கும், சரிக்கும் தவறுக்கும், ஹலால் (அனுமதிக்கப்பட்டது) மற்றும் ஹராமுக்கும் (தடுக்கப்பட்டது) இடையில் தீர்ப்பளிக்கும் அளவுகோலாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَبْدِهِ</span><br />\r\n<br />\r\n(தனது அடியாருக்கு) இந்த வர்ணனை ஒரு பெரும் புகழ்ச்சியும் நன்மதிப்பும் ஆகும். ஏனெனில் அல்லாஹ் அவரைத் தன்னோடு இணைத்து, 'தனது அடியார்' என்று சிறப்பிக்கிறான். இஸ்ரா இரவாகிய மிக உன்னதமான நிகழ்வைக் குறிப்பிடும்போதும் அல்லாஹ் அவரை (ஸல்) இதே முறையில் வர்ணித்தான். அவன் கூறியது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">سُبْحَانَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَسْرَى</span> <span class=\"quran-arabic-font text-success\">بِعَبْدِهِ</span> <span class=\"quran-arabic-font text-success\">لَيْلاً</span><br />\r\n<br />\r\n(தனது அடியாரை ஓர் இரவில் அழைத்துச் சென்றவன் தூய்மையானவன்) (<a href=\"qurandisp.php?sura=17&ayah=1\" class=\"link\">17:1</a>). அவர் (ஸல்) எழுந்து நின்று அல்லாஹ்விடம் பிரார்த்தனை செய்ததை விவரிக்கும் போதும் அல்லாஹ் அவரை (ஸல்) இதே முறையில் வர்ணித்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَّمَا</span> <span class=\"quran-arabic-font text-success\">قَامَ</span> <span class=\"quran-arabic-font text-success\">عَبْدُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">يَدْعُوهُ</span> <span class=\"quran-arabic-font text-success\">كَادُواْ</span> <span class=\"quran-arabic-font text-success\">يَكُونُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">لِبَداً</span><br />\r\n<br />\r\n(மேலும், அல்லாஹ்வின் அடியார் அவனிடம் துஆ செய்தவராக (தொழுகையில்) நின்றபோது, அவர்கள் (ஜின்னினத்தோர்) அவர் மீது ஒருவர் மேல் ஒருவராக மொய்த்துக் கொள்ளத் தொடங்கினர் (அவர் ஓதுவதைக் கேட்பதற்காக).) (<a href=\"qurandisp.php?sura=72&ayah=19\" class=\"link\">72:19</a>). வேதம் அவருக்கு (ஸல்) எவ்வாறு அருளப்பட்டது என்பதையும், வானவர் அவரிடம் (ஸல்) எவ்வாறு இறங்கி வந்தார் என்பதையும் அல்லாஹ் விவரிக்கும்போதும் இந்த வர்ணனை இங்கு பயன்படுத்தப்பட்டுள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">نَزَّلَ</span> <span class=\"quran-arabic-font text-success\">الْفُرْقَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">عَبْدِهِ</span> <span class=\"quran-arabic-font text-success\">لِيَكُونَ</span> <span class=\"quran-arabic-font text-success\">لِلْعَـلَمِينَ</span> <span class=\"quran-arabic-font text-success\">نَذِيراً</span><br />\r\n<br />\r\n(அவன் பாக்கியமிக்கவன்; அவன் அகிலத்தாருக்கு எச்சரிக்கை செய்பவராகத் திகழும் பொருட்டு, தனது அடியார் மீது ஃபுர்கானை (சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறிவிக்கும் வேதத்தை) அருளினான்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِيَكُونَ</span> <span class=\"quran-arabic-font text-success\">لِلْعَـلَمِينَ</span> <span class=\"quran-arabic-font text-success\">نَذِيراً</span><br />\r\n<br />\r\n(அவர் (ஸல்) அகிலத்தாருக்கு எச்சரிக்கை செய்பவராகத் திகழும் பொருட்டு.) இதன் பொருள், அவர்தான் (ஸல்) இந்த மகத்தான, விரிவான மற்றும் தெளிவான வேதத்தைக் கொண்டு சிறப்பிக்கப்பட்டவர் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِ</span> <span class=\"quran-arabic-font text-success\">الْبَـطِلُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">خَلْفِهِ</span> <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">حَكِيمٍ</span> <span class=\"quran-arabic-font text-success\">حَمِيدٍ</span><br />\r\n<br />\r\n(எந்தப் பக்கத்திலிருந்தும் பொய் அதனிடம் நெருங்க முடியாது; (இது) ஞானமிக்கோனும் புகழுக்குரியோனுமாகிய (அல்லாஹ்விடமிருந்து) அருளப்பெற்றதாகும்.) (<a href=\"qurandisp.php?sura=41&ayah=42\" class=\"link\">41:42</a>). இதனை வலிமைமிக்க அளவுகோலாக ஆக்கியவன், வானத்தின் கீழ் வசிப்பவர்களுக்கும் பூமியின் மேல் இருப்பவர்களுக்கும் (அதாவது, மனிதகுலம் முழுமைக்கும்) இதனை எத்திவைப்பதற்காக அவரைத் (ஸல்) தேர்ந்தெடுத்தான். நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْأَحْمَرِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَسْوَد</span>»<br />\r\n<br />\r\n(நான் சிவப்பு மற்றும் கருப்பு (நிறத்தவர்) அனைவருக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) நூல்: முஸ்லிம் மேலும் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">أُعْطِيتُ</span> <span class=\"quran-arabic-font text-success\">خَمْسًا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُعْطَهُنَّ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَنْبِيَاءِ</span> <span class=\"quran-arabic-font text-success\">قَبْلِي</span>»<br />\r\n<br />\r\n(எனக்கு முன்பு எந்த நபிக்கும் வழங்கப்படாத ஐந்து விஷயங்கள் எனக்கு வழங்கப்பட்டுள்ளன.) நூல்: புகாரி, முஸ்லிம் அவற்றுள் அவர்கள் குறிப்பிட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">النَّبِيُّ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">خَاصَّةً</span> <span class=\"quran-arabic-font text-success\">وَبُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَامَّة</span>»<br />\r\n<br />\r\n(எனக்கு முன்னிருந்த ஒரு நபி அவரது சமூகத்தாருக்கு மட்டுமே அனுப்பப்பட்டார், ஆனால் நான் மனிதகுலம் முழுமைக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span><br />\r\n<br />\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன்...\") (<a href=\"qurandisp.php?sura=7&ayah=158\" class=\"link\">7:158</a>). இதன் பொருள் என்னவென்றால், என்னை அனுப்பியவன் வானங்கள் மற்றும் பூமியின் அதிபதி; அவன் ஒரு பொருளை \"ஆகு\" என்று கூறினால், அது ஆகிவிடும். அவனே உயிர்ப்பிப்பவன், மரணிக்கச் செய்பவன். அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">مُلْكُ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَتَّخِذْ</span> <span class=\"quran-arabic-font text-success\">وَلَداً</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُن</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">شَرِيكٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">المُلْكِ</span><br />\r\n<br />\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்கே உரியது. அவன் எவரையும் மகனாக ஆக்கிக் கொள்ளவில்லை; அவனது ஆட்சியில் அவனுக்குக் கூட்டாளி எவரும் இல்லை.) தான் சந்ததியையோ அல்லது கூட்டாளியையோ கொண்டிருப்பதற்கு அப்பாற்பட்டவன் என்று அல்லாஹ் கூறுகிறான். பின்னர் அவன் நமக்குக் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَخَلَقَ</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَيْءٍ</span> <span class=\"quran-arabic-font text-success\">فَقَدَّرَهُ</span> <span class=\"quran-arabic-font text-success\">تَقْدِيرًا</span><br />\r\n<br />\r\n(அவன் ஒவ்வொரு பொருளையும் படைத்து, அதற்குரிய அளவின்படி மிகத் துல்லியமாக நிர்ணயித்துள்ளான்.) அதாவது, அவனைத் தவிர உள்ள அனைத்தும் படைக்கப்பட்டவை, அவனுக்குக் கீழ்ப்பட்டவை. அவனே படைப்பவன், இரட்சகன், எஜமானன் மற்றும் வணக்கத்திற்குரிய இறைவன். அனைத்தும் அவனது அதிகாரம், கட்டுப்பாடு மற்றும் ஆற்றலுக்கு உட்பட்டவை.<br />\r\n<br />","text":"மக்காவில் அருளப்பட்டது\n\r\n\n\r\nبِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nஅல்லாஹ் பாக்கியமிக்கவன்\n\r\n\n\r\nஇங்கு அல்லாஹ், தனது கண்ணியமிக்க தூதருக்கு (ஸல்) அருளிய மேன்மைமிக்க குர்ஆனுக்காகத் தன்னைத் தானே புகழ்கிறான். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nالْحَمْدُ لِلَّهِ الَّذِى أَنْزَلَ عَلَى عَبْدِهِ الْكِتَـبَ وَلَمْ يَجْعَل لَّهُ عِوَجَا قَيِّماً لِّيُنْذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّـلِحَاتِ\n\r\n\n\r\n(அனைத்துப் புகழும் அல்லாஹ்வுக்கே உரியது! அவன் தனது அடியார் மீது இவ்வேதத்தை அருளினான்; அதில் அவன் எவ்விதக் கோணலையும் வைக்கவில்லை. அவன் அதை நேரானதாக ஆக்கினான்; அவனிடமிருந்துள்ள கடுமையான வேதனையைக் குறித்து எச்சரிப்பதற்காகவும், நற்செயல்கள் புரியும் மூஃமின்களுக்கு (நம்பிக்கையாளர்களுக்கு) நற்செய்தி அறிவிப்பதற்காகவும்...) 18:1-2. இங்கு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nتَبَارَكَ\n\r\n\n\r\n(அவன் பாக்கியமிக்கவன்.) இங்கு பயன்படுத்தப்பட்டுள்ள வினைச்சொல் வடிவம், தொடர்ச்சியான, நிரந்தரமான, நித்தியமான அருளைக் குறிக்கிறது.\n\r\n\n\r\nالَّذِى نَزَّلَ الْفُرْقَانَ\n\r\n\n\r\n(அவன் ஃபுர்கானை - சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறிவிக்கும் அளவுகோலை - அருளினான்). 'நஸ்ஸல' (Nazzala) எனும் வினைச்சொல் வடிவம், ஒரு காரியம் மீண்டும் மீண்டும், அதிகமாகச் செய்யப்படுவதைக் குறிக்கும். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nوَالْكِتَـبِ الَّذِى نَزَّلَ عَلَى رَسُولِهِ وَالْكِتَـبِ الَّذِى أَنَزلَ مِن قَبْلُ\n\r\n\n\r\n(மேலும், அவன் தனது தூதர் மீது (படிப்படியாக) அருளிய இவ்வேதத்தையும், இதற்கு முன்னர் அவன் (ஒரே நேரத்தில்) அருளிய வேதத்தையும் (நம்புங்கள்)) (4:136). இதற்கு முந்தைய வேதங்கள் ஒவ்வொன்றும் ஒரே நேரத்தில் அருளப்பட்டன. ஆனால், குர்ஆன் படிப்படியாக, பகுதி பகுதியாக, வசனத்திற்குப் பின் வசனமாக, சட்டங்களுக்குப் பின் சட்டங்களாக, அத்தியாயங்களுக்குப் பின் அத்தியாயங்களாக அருளப்பட்டது. இது மிகவும் நயமானது; மேலும் இது யாருக்கு வஹீ (இறைச்செய்தி) அருளப்பட்டதோ அவர் மீது அல்லாஹ் கொண்டுள்ள பெரும் அக்கறையைக் காட்டுகிறது. இந்த அத்தியாயத்தில் அல்லாஹ் பின்னர் கூறுவது போல:\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُواْ لَوْلاَ نُزِّلَ عَلَيْهِ الْقُرْءَانُ جُمْلَةً وَحِدَةً كَذَلِكَ لِنُثَبِّتَ بِهِ فُؤَادَكَ وَرَتَّلْنَاهُ تَرْتِيلاً - وَلاَ يَأْتُونَكَ بِمَثَلٍ إِلاَّ جِئْنَـكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيراً\n\r\n\n\r\n(மேலும், \"இந்தக் குர்ஆன் அவருக்கு ஏன் ஒரே தடவையில் அருளப்படவில்லை?\" என்று காஃபிர்கள் (நிராகரிப்பாளர்கள்) கேட்கின்றனர். இவ்வாறே (படிப்படியாக நாம் அருளினோம்); இதன் மூலம் உமது உள்ளத்தை நாம் உறுதிப்படுத்துவதற்காக. நாம் இதனை மிகத் தெளிவாகவும் முறைப்படியாகவும் ஓதிக் காண்பித்தோம். அவர்கள் உம்மிடம் எந்தவொரு வாதத்தைக் கொண்டு வந்தாலும், அதற்குரிய சத்தியத்தையும் மிகச்சிறந்த விளக்கத்தையும் நாம் உமக்குத் தராமல் இருப்பதில்லை.) (25:32-33). இந்த அத்தியாயத்திற்கு 'அல்-ஃபுர்கான்' என்று பெயரிடப்பட்டது, ஏனெனில் இது சத்தியத்திற்கும் அசத்தியத்திற்கும், நேர்வழிக்கும் வழிகேட்டிற்கும், சரிக்கும் தவறுக்கும், ஹலால் (அனுமதிக்கப்பட்டது) மற்றும் ஹராமுக்கும் (தடுக்கப்பட்டது) இடையில் தீர்ப்பளிக்கும் அளவுகோலாகும்.\n\r\n\n\r\nعَلَى عَبْدِهِ\n\r\n\n\r\n(தனது அடியாருக்கு) இந்த வர்ணனை ஒரு பெரும் புகழ்ச்சியும் நன்மதிப்பும் ஆகும். ஏனெனில் அல்லாஹ் அவரைத் தன்னோடு இணைத்து, 'தனது அடியார்' என்று சிறப்பிக்கிறான். இஸ்ரா இரவாகிய மிக உன்னதமான நிகழ்வைக் குறிப்பிடும்போதும் அல்லாஹ் அவரை (ஸல்) இதே முறையில் வர்ணித்தான். அவன் கூறியது போல:\n\r\n\n\r\nسُبْحَانَ الَّذِى أَسْرَى بِعَبْدِهِ لَيْلاً\n\r\n\n\r\n(தனது அடியாரை ஓர் இரவில் அழைத்துச் சென்றவன் தூய்மையானவன்) (17:1). அவர் (ஸல்) எழுந்து நின்று அல்லாஹ்விடம் பிரார்த்தனை செய்ததை விவரிக்கும் போதும் அல்லாஹ் அவரை (ஸல்) இதே முறையில் வர்ணித்தான்:\n\r\n\n\r\nوَأَنَّهُ لَّمَا قَامَ عَبْدُ اللَّهِ يَدْعُوهُ كَادُواْ يَكُونُونَ عَلَيْهِ لِبَداً\n\r\n\n\r\n(மேலும், அல்லாஹ்வின் அடியார் அவனிடம் துஆ செய்தவராக (தொழுகையில்) நின்றபோது, அவர்கள் (ஜின்னினத்தோர்) அவர் மீது ஒருவர் மேல் ஒருவராக மொய்த்துக் கொள்ளத் தொடங்கினர் (அவர் ஓதுவதைக் கேட்பதற்காக).) (72:19). வேதம் அவருக்கு (ஸல்) எவ்வாறு அருளப்பட்டது என்பதையும், வானவர் அவரிடம் (ஸல்) எவ்வாறு இறங்கி வந்தார் என்பதையும் அல்லாஹ் விவரிக்கும்போதும் இந்த வர்ணனை இங்கு பயன்படுத்தப்பட்டுள்ளது:\n\r\n\n\r\nتَبَارَكَ الَّذِى نَزَّلَ الْفُرْقَانَ عَلَى عَبْدِهِ لِيَكُونَ لِلْعَـلَمِينَ نَذِيراً\n\r\n\n\r\n(அவன் பாக்கியமிக்கவன்; அவன் அகிலத்தாருக்கு எச்சரிக்கை செய்பவராகத் திகழும் பொருட்டு, தனது அடியார் மீது ஃபுர்கானை (சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறிவிக்கும் வேதத்தை) அருளினான்.)\n\r\n\n\r\nلِيَكُونَ لِلْعَـلَمِينَ نَذِيراً\n\r\n\n\r\n(அவர் (ஸல்) அகிலத்தாருக்கு எச்சரிக்கை செய்பவராகத் திகழும் பொருட்டு.) இதன் பொருள், அவர்தான் (ஸல்) இந்த மகத்தான, விரிவான மற்றும் தெளிவான வேதத்தைக் கொண்டு சிறப்பிக்கப்பட்டவர் என்பதாகும்.\n\r\n\n\r\nلاَّ يَأْتِيهِ الْبَـطِلُ مِن بَيْنِ يَدَيْهِ وَلاَ مِنْ خَلْفِهِ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ\n\r\n\n\r\n(எந்தப் பக்கத்திலிருந்தும் பொய் அதனிடம் நெருங்க முடியாது; (இது) ஞானமிக்கோனும் புகழுக்குரியோனுமாகிய (அல்லாஹ்விடமிருந்து) அருளப்பெற்றதாகும்.) (41:42). இதனை வலிமைமிக்க அளவுகோலாக ஆக்கியவன், வானத்தின் கீழ் வசிப்பவர்களுக்கும் பூமியின் மேல் இருப்பவர்களுக்கும் (அதாவது, மனிதகுலம் முழுமைக்கும்) இதனை எத்திவைப்பதற்காக அவரைத் (ஸல்) தேர்ந்தெடுத்தான். நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«بُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَد»\n\r\n\n\r\n(நான் சிவப்பு மற்றும் கருப்பு (நிறத்தவர்) அனைவருக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) நூல்: முஸ்லிம் மேலும் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنِّي أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ مِنَ الْأَنْبِيَاءِ قَبْلِي»\n\r\n\n\r\n(எனக்கு முன்பு எந்த நபிக்கும் வழங்கப்படாத ஐந்து விஷயங்கள் எனக்கு வழங்கப்பட்டுள்ளன.) நூல்: புகாரி, முஸ்லிம் அவற்றுள் அவர்கள் குறிப்பிட்டார்கள்:\n\r\n\n\r\n«كَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً وَبُعِثْتُ إِلَى النَّاسِ عَامَّة»\n\r\n\n\r\n(எனக்கு முன்னிருந்த ஒரு நபி அவரது சமூகத்தாருக்கு மட்டுமே அனுப்பப்பட்டார், ஆனால் நான் மனிதகுலம் முழுமைக்கும் தூதராக அனுப்பப்பட்டுள்ளேன்.) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nقُلْ يَأَيُّهَا النَّاسُ إِنِّى رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا\n\r\n\n\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன்...\") (7:158). இதன் பொருள் என்னவென்றால், என்னை அனுப்பியவன் வானங்கள் மற்றும் பூமியின் அதிபதி; அவன் ஒரு பொருளை \"ஆகு\" என்று கூறினால், அது ஆகிவிடும். அவனே உயிர்ப்பிப்பவன், மரணிக்கச் செய்பவன். அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n\n\r\nالَّذِى لَهُ مُلْكُ السَّمَـوَتِ وَالْأَرْضِ وَلَمْ يَتَّخِذْ وَلَداً وَلَمْ يَكُن لَّهُ شَرِيكٌ فِى المُلْكِ\n\r\n\n\r\n(வானங்கள் மற்றும் பூமியின் ஆட்சி அவனுக்கே உரியது. அவன் எவரையும் மகனாக ஆக்கிக் கொள்ளவில்லை; அவனது ஆட்சியில் அவனுக்குக் கூட்டாளி எவரும் இல்லை.) தான் சந்ததியையோ அல்லது கூட்டாளியையோ கொண்டிருப்பதற்கு அப்பாற்பட்டவன் என்று அல்லாஹ் கூறுகிறான். பின்னர் அவன் நமக்குக் கூறுகிறான்:\n\r\n\n\r\nوَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا\n\r\n\n\r\n(அவன் ஒவ்வொரு பொருளையும் படைத்து, அதற்குரிய அளவின்படி மிகத் துல்லியமாக நிர்ணயித்துள்ளான்.) அதாவது, அவனைத் தவிர உள்ள அனைத்தும் படைக்கப்பட்டவை, அவனுக்குக் கீழ்ப்பட்டவை. அவனே படைப்பவன், இரட்சகன், எஜமானன் மற்றும் வணக்கத்திற்குரிய இறைவன். அனைத்தும் அவனது அதிகாரம், கட்டுப்பாடு மற்றும் ஆற்றலுக்கு உட்பட்டவை."},"3":{"html":"<strong>இணைவைப்பாளர்களின் அறிவீனம்</strong><br />\r\n<br />\r\nஅனைத்துப் பொருட்களையும் படைத்தவனும், அனைத்து விவகாரங்களையும் நிர்வகிப்பவனுமான அல்லாஹ்வை விடுத்து, ஏனையோரைத் தெய்வங்களாக ஆக்கிக்கொண்ட இணைவைப்பாளர்களின் அறியாமையைப் பற்றி அல்லாஹ் கூறுகிறான்;   இவ்வளவு இருந்தும், அவர்கள் அவனையன்றி சிலைகளை வணங்கினார்கள்; <span class=\"quran-arabic-font text-success\">﴾وَاتَّخَذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةً﴿</span> அந்தச் சிலைகளால் எதையும் படைக்க முடியாது, மாறாக அவையே படைக்கப்பட்டவை ஆகும். <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يَخْلُقُونَ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يُخْلَقُونَ﴿</span> அவைகளால் தங்களுக்குத் தாங்களே எவ்விதத் தீங்கும் செய்துகொள்ளவோ அல்லது எவ்வித நன்மையைச் செய்துகொள்ளவோ முடியாது. <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">لأَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">ضَرًّا</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَفْعًا﴿</span> அப்படியிருக்க, தங்களை வணங்குபவர்களுக்கு அவைகளால் என்ன செய்ய முடியும்? <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَمْلِكُونَ</span> <span class=\"quran-arabic-font text-success\">مَوْتاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">حَيَـوةً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نُشُوراً﴿</span><br />\r\n<br />\r\n(அவை மரணத்தையோ, வாழ்வையோ அல்லது மீண்டும் உயிர் கொடுத்து எழுப்புவதையோ தங்களின் கட்டுப்பாட்டில் கொண்டிருக்கவில்லை.) என்பதன் பொருள், அவைகளால் இவற்றில் எதையுமே செய்ய முடியாது என்பதாகும். அந்த ஆற்றல் அல்லாஹ்வுக்கு மட்டுமே உரியது. அவனே உயிரைக் கொடுப்பவனும், மரணத்தை ஏற்படுத்துபவனும் ஆவான். அவனே மறுமை நாளில் முந்தியவர்கள் மற்றும் பிந்தியவர்கள் என அனைத்து மக்களையும் மீண்டும் உயிர்ப்பிப்பான். <span class=\"quran-arabic-font text-success\">﴾مَّا</span> <span class=\"quran-arabic-font text-success\">خَلْقُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَعْثُكُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَنَفْسٍ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٍ﴿</span><br />\r\n<br />\r\n(உங்கள் அனைவரையும் படைப்பதும், மீண்டும் உயிர்ப்பிப்பதும் ஒரேயொரு நபரைப் (படைத்து உயிர்ப்பிப்பது) போன்றதே தவிர வேறில்லை) (<a href=\"qurandisp.php?sura=31&ayah=28\" class=\"link\">31:28</a>). இது பின்வரும் ஆயத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْرُنَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> <span class=\"quran-arabic-font text-success\">كَلَمْحٍ</span> <span class=\"quran-arabic-font text-success\">بِالْبَصَرِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நமது கட்டளை கண் சிமிட்டுவதைப் போல ஒரேயொரு முறைதான்.) (<a href=\"qurandisp.php?sura=54&ayah=50\" class=\"link\">54:50</a>) <span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">زَجْرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> - <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُم</span> <span class=\"quran-arabic-font text-success\">بِالسَّاهِرَةِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது ஒரேயொரு சப்தமாக (ஸஜ்ரா) தான் இருக்கும். அப்போது, இதோ! அவர்கள் (இறந்த பிறகு) பூமியின் மேற்பரப்பில் உயிருடன் வந்துவிடுவார்கள்.) (<a href=\"qurandisp.php?sura=79&ayah=13\" class=\"link\">79:13</a>-14) <span class=\"quran-arabic-font text-success\">﴾فَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">زَجْرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةٌ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது ஒரேயொரு சப்தமாகத்தான் இருக்கும், அப்போது இதோ, அவர்கள் (திகைத்து) பார்த்துக் கொண்டிருப்பார்கள்!) (<a href=\"qurandisp.php?sura=37&ayah=19\" class=\"link\">37:19</a>) <span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">صَيْحَةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">لَّدَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُحْضَرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அது ஒரேயொரு பெரும் சப்தமாகத் (ஸைஹா) தவிர வேறில்லை, அப்போது இதோ, அவர்கள் அனைவரும் நம்மிடம் கொண்டு வரப்படுவார்கள்!) (<a href=\"qurandisp.php?sura=36&ayah=53\" class=\"link\">36:53</a>). அவனே அல்லாஹ், அவனைத் தவிர வேறு எந்தக் கடவுளும் இல்லை; அவனைத் தவிர வேறு இரட்சகனும் இல்லை. அவன் ஒருவனைத் தவிர வேறு யாரும் வணங்கப்படக்கூடாது. ஏனெனில், அவன் எதை நாடுகிறானோ அது நடக்கும், அவன் எதை நாடவில்லையோ அது நடக்காது. அவனுக்குச் சந்ததிகளோ, பெற்றோரோ, நிகரானவர்களோ, ஒப்பானவர்களோ, எதிரிகளோ அல்லது இணையானவர்களோ இல்லை. அவன் ஏகமானவன்; அவன் எவரிடமும் தேவையற்றவன் (அஸ்-ஸமது), அனைத்துப் படைப்புகளும் அவனையே சார்ந்திருக்கின்றன. அவன் எவரையும் பெறவில்லை, அவனும் எவராலும் பெறப்படவில்லை. மேலும், அவனுக்கு நிகராக எவருமே இல்லை. <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> - <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الصَّمَدُ</span> - <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلِدْ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُولَدْ</span> - <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُنْ</span> <span class=\"quran-arabic-font text-success\">لَّهُ</span> <span class=\"quran-arabic-font text-success\">كُفُواً</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ﴿</span><br />\r\n<br />","text":"இணைவைப்பாளர்களின் அறிவீனம்\n\r\n\n\r\nஅனைத்துப் பொருட்களையும் படைத்தவனும், அனைத்து விவகாரங்களையும் நிர்வகிப்பவனுமான அல்லாஹ்வை விடுத்து, ஏனையோரைத் தெய்வங்களாக ஆக்கிக்கொண்ட இணைவைப்பாளர்களின் அறியாமையைப் பற்றி அல்லாஹ் கூறுகிறான்;   இவ்வளவு இருந்தும், அவர்கள் அவனையன்றி சிலைகளை வணங்கினார்கள்; ﴾وَاتَّخَذُواْ مِن دُونِهِ ءَالِهَةً﴿ அந்தச் சிலைகளால் எதையும் படைக்க முடியாது, மாறாக அவையே படைக்கப்பட்டவை ஆகும். ﴾لاَ يَخْلُقُونَ شَيْئاً وَهُمْ يُخْلَقُونَ﴿ அவைகளால் தங்களுக்குத் தாங்களே எவ்விதத் தீங்கும் செய்துகொள்ளவோ அல்லது எவ்வித நன்மையைச் செய்துகொள்ளவோ முடியாது. ﴾وَلاَ يَمْلِكُونَ لأَنفُسِهِمْ ضَرًّا وَلاَ نَفْعًا﴿ அப்படியிருக்க, தங்களை வணங்குபவர்களுக்கு அவைகளால் என்ன செய்ய முடியும்? ﴾وَلاَ يَمْلِكُونَ مَوْتاً وَلاَ حَيَـوةً وَلاَ نُشُوراً﴿\n\r\n\n\r\n(அவை மரணத்தையோ, வாழ்வையோ அல்லது மீண்டும் உயிர் கொடுத்து எழுப்புவதையோ தங்களின் கட்டுப்பாட்டில் கொண்டிருக்கவில்லை.) என்பதன் பொருள், அவைகளால் இவற்றில் எதையுமே செய்ய முடியாது என்பதாகும். அந்த ஆற்றல் அல்லாஹ்வுக்கு மட்டுமே உரியது. அவனே உயிரைக் கொடுப்பவனும், மரணத்தை ஏற்படுத்துபவனும் ஆவான். அவனே மறுமை நாளில் முந்தியவர்கள் மற்றும் பிந்தியவர்கள் என அனைத்து மக்களையும் மீண்டும் உயிர்ப்பிப்பான். ﴾مَّا خَلْقُكُمْ وَلاَ بَعْثُكُمْ إِلاَّ كَنَفْسٍ وَاحِدَةٍ﴿\n\r\n\n\r\n(உங்கள் அனைவரையும் படைப்பதும், மீண்டும் உயிர்ப்பிப்பதும் ஒரேயொரு நபரைப் (படைத்து உயிர்ப்பிப்பது) போன்றதே தவிர வேறில்லை) (31:28). இது பின்வரும் ஆயத்தைப் போன்றது: ﴾وَمَآ أَمْرُنَآ إِلاَّ وَاحِدَةٌ كَلَمْحٍ بِالْبَصَرِ ﴿\n\r\n\n\r\n(நமது கட்டளை கண் சிமிட்டுவதைப் போல ஒரேயொரு முறைதான்.) (54:50) ﴾فَإِنَّمَا هِىَ زَجْرَةٌ وَاحِدَةٌ - فَإِذَا هُم بِالسَّاهِرَةِ ﴿\n\r\n\n\r\n(நிச்சயமாக அது ஒரேயொரு சப்தமாக (ஸஜ்ரா) தான் இருக்கும். அப்போது, இதோ! அவர்கள் (இறந்த பிறகு) பூமியின் மேற்பரப்பில் உயிருடன் வந்துவிடுவார்கள்.) (79:13-14) ﴾فَإِنَّمَا هِىَ زَجْرَةٌ وَاحِدَةٌ فَإِذَا هُمْ يَنظُرُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக அது ஒரேயொரு சப்தமாகத்தான் இருக்கும், அப்போது இதோ, அவர்கள் (திகைத்து) பார்த்துக் கொண்டிருப்பார்கள்!) (37:19) ﴾إِن كَانَتْ إِلاَّ صَيْحَةً وَاحِدَةً فَإِذَا هُمْ جَمِيعٌ لَّدَيْنَا مُحْضَرُونَ ﴿\n\r\n\n\r\n(அது ஒரேயொரு பெரும் சப்தமாகத் (ஸைஹா) தவிர வேறில்லை, அப்போது இதோ, அவர்கள் அனைவரும் நம்மிடம் கொண்டு வரப்படுவார்கள்!) (36:53). அவனே அல்லாஹ், அவனைத் தவிர வேறு எந்தக் கடவுளும் இல்லை; அவனைத் தவிர வேறு இரட்சகனும் இல்லை. அவன் ஒருவனைத் தவிர வேறு யாரும் வணங்கப்படக்கூடாது. ஏனெனில், அவன் எதை நாடுகிறானோ அது நடக்கும், அவன் எதை நாடவில்லையோ அது நடக்காது. அவனுக்குச் சந்ததிகளோ, பெற்றோரோ, நிகரானவர்களோ, ஒப்பானவர்களோ, எதிரிகளோ அல்லது இணையானவர்களோ இல்லை. அவன் ஏகமானவன்; அவன் எவரிடமும் தேவையற்றவன் (அஸ்-ஸமது), அனைத்துப் படைப்புகளும் அவனையே சார்ந்திருக்கின்றன. அவன் எவரையும் பெறவில்லை, அவனும் எவராலும் பெறப்படவில்லை. மேலும், அவனுக்கு நிகராக எவருமே இல்லை. ﴾قُلْ هُوَ اللَّهُ أَحَدٌ - اللَّهُ الصَّمَدُ - لَمْ يَلِدْ وَلَمْ يُولَدْ - وَلَمْ يَكُنْ لَّهُ كُفُواً أَحَدٌ﴿"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=6\" class=\"link\">25:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:6 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=6\" class=\"link\">25:6</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:6 ஐ பார்க்கவும்"},"6":{"html":"<strong>குர்ஆனைப் பற்றி நிராகரிப்பாளர்கள் கூறியவை</strong><br />\r\n<br />\r\nநிராகரிப்பாளர்களின் அறியாமை நிறைந்த மனங்களின் முட்டாள்தனத்தைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் குர்ஆனைப் பற்றி இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِفْكٌ</span><br />\r\n<br />\r\n(இது ஒரு பொய்யே அன்றி வேறில்லை), அதாவது இது ஓர் உண்மையற்ற கூற்றாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">افْتَرَاهُ</span><br />\r\n<br />\r\n(அவர் இதனை இட்டுக் கட்டியுள்ளார்), அதாவது நபி (ஸல்) அவர்கள் இதனை உருவாக்கினார்கள் (என்று அவர்கள் கூறினர்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَعَانَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">ءَاخَرُونَ</span><br />\r\n<br />\r\n(மேலும் இதற்கு மற்றவர்களும் அவருக்கு உதவி புரிந்துள்ளனர்.) அதாவது, இதனைத் தொகுக்க அவர் மற்றவர்களின் உதவியைப் பெற்றுள்ளார் என்று அவர்கள் கூறினர். எனவே அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">ظُلْماً</span> <span class=\"quran-arabic-font text-success\">وَزُوراً</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் ஓர் அநியாயத்தையும் பெரும் பொய்யையுமே கொண்டு வந்துள்ளனர்.) அதாவது, அவர்களே பொய் சொல்கிறார்கள்; அவர்கள் கூறுவது உண்மைக்கு மாறானது என்பதை அவர்களின் மனச்சாட்சியே அறியும் என்பதால், அது பொய்யானது என்பதை அவர்களும் அறிவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَسَـطِيرُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">اكْتَتَبَهَا</span><br />\r\n<br />\r\n(இன்னும் அவர்கள் கூறுகிறார்கள்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவற்றை அவர் எழுதி வைத்துள்ளார்...\") அதாவது, முன்னோர்கள் எழுதியதை இவர் பிரதி எடுத்துள்ளார் என்று அவர்கள் கூறினர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَهِىَ</span> <span class=\"quran-arabic-font text-success\">تُمْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(மேலும் அவை அவருக்கு ஓதிக் காட்டப்படுகின்றன) அதாவது, அவை அவருக்கு வாசித்துக் காட்டப்படுகின்றன அல்லது ஓதப்படுகின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بُكْرَةً</span> <span class=\"quran-arabic-font text-success\">وَأَصِيلاً</span><br />\r\n<br />\r\n(காலையிலும் மாலையிலும்.) அதாவது நாளின் தொடக்கத்திலும் இறுதியிலும். இந்தக் கருத்து அப்பட்டமான பொய் என்பதால், இது உண்மையல்ல என்பதை எவரும் எளிதில் அறிந்து கொள்ளலாம். அல்லாஹ்வின் தூதர் முஹம்மது (ஸல்) அவர்கள் தம் வாழ்நாளின் ஆரம்பத்திலோ அல்லது இறுதியிலோ எழுதவோ அல்லது வாசிக்கவோ கற்றதில்லை என்பது 'முதவாதிர்' (தொடர்ச்சியான பலருடைய) அறிவிப்புகளின் மூலம் ஊர்ஜிதப்படுத்தப்பட்ட ஒரு பொதுவான உண்மையாகும். அவர் பிறந்ததிலிருந்து அவருடைய தூதுப்பணி தொடங்கும் வரை, ஏறக்குறைய நாற்பது ஆண்டுகள் அவர்களுடனேயே வாழ்ந்தார்கள். அவருடைய நேர்மை, தூய்மையான குணம் ஆகியவற்றையும், அவர் ஒருபோதும் பொய் சொல்லவோ ஒழுக்கமற்ற அல்லது தீய செயல்களில் ஈடுபடவோ மாட்டார் என்பதையும் அவர்கள் நன்கு அறிந்திருந்தார்கள். அவருடைய வாய்மையையும் நேர்மையையும் கண்ட அவர்கள், அவர் நபித்துவப் பொறுப்பைப் பெறுவதற்கு முன்பே, சிறு வயதிலிருந்தே அவரை 'அல்-அமீன்' (நம்பிக்கைக்குரியவர்) என்றே அழைத்து வந்தனர். அல்லாஹ் அவருக்கு வழங்கிய அந்தப் பெரும் கண்ணியத்தின் (நபித்துவத்தின்) போது, அவர்கள் அவருக்கு விரோதிகளாக மாறி, இவ்வாறான பொய்க்குற்றச்சாட்டுகளை அடுக்கினர். பகுத்தறிவுள்ள எவரும் அவர் இத்தகைய செயல்களிலிருந்து நீங்கியவர் என்பதை உணர்வார்கள். அவர் மீது என்ன குற்றம் சாட்டுவது என்று தெரியாமல் அவர்கள் தடுமாறினர். சில நேரங்களில் அவரை ஒரு சூனியக்காரர் என்றும், வேறு சில நேரங்களில் கவிஞர், பைத்தியக்காரர் அல்லது பொய்யர் என்றும் கூறினர். எனவே அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">انْظُرْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">ضَرَبُواْ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">الاٌّمْثَالَ</span> <span class=\"quran-arabic-font text-success\">فَضَلُّواْ</span> <span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعْونَ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span><br />\r\n<br />\r\n(அவர்கள் உமக்கு எத்தகைய உதாரணங்களைக் கூறுகிறார்கள் என்று பாரும். இதனால் அவர்கள் வழிதவறிவிட்டார்கள், நேர்வழியை அடைய அவர்களால் ஒருபோதும் இயலாது.) (<a href=\"qurandisp.php?sura=17&ayah=48\" class=\"link\">17:48</a>) அவர்களின் இந்தப் பிடிவாதத்திற்குப் பதிலளிக்கும் விதமாக அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَهُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضِ</span><br />\r\n<br />\r\n(கூறுவீராக: \"வானங்களிலும் பூமியிலும் உள்ள இரகசியங்களை அறிபவனே இதனை இறக்கிவைத்தான்.\") அதாவது, கடந்த கால மற்றும் வருங்கால தலைமுறைகளைப் பற்றிய உண்மையான செய்திகளையும், கடந்த கால மற்றும் எதிர்கால யதார்த்தங்களோடு ஒத்துப் போகும் தகவல்களையும் உள்ளடக்கிய குர்ஆனை அவன் வஹீயாக (இறைச்செய்தியாக) அருளியுள்ளான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">السِّرَّ</span><br />\r\n<br />\r\n(இரகசியத்தை அறிந்தவன்) என்பது, அல்லாஹ்வே வானங்களிலும் பூமியிலும் உள்ள மறைவானவற்றை அறிந்தவன் என்பதாகும்; வெளிப்படையாக இருப்பவற்றை அவன் அறிவது போலவே, அவற்றின் இரகசியங்களையும் அவன் நன்கு அறிவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் மிக்க மன்னிப்பவனாகவும், அளவற்ற கருணையாளனாகவும் இருக்கிறான்.) இது அவர்கள் பாவமன்னிப்புக் கேட்டு அல்லாஹ்வின் பக்கம் மீள்வதற்கான ஓர் அழைப்பாகும். அவனது கருணை விசாலமானது, அவனது பொறுமை அளவற்றது என்பதை இது அவர்களுக்கு உணர்த்துகிறது. அவனிடம் எவர் பாவமன்னிப்புக் கோருகிறாரோ, அவருடைய தவ்பாவை அவன் ஏற்றுக் கொள்கிறான். அவர்களுடைய இத்தனை பொய்கள், அநாகரீகமான செயல்கள், நிராகரிப்பு மற்றும் பிடிவாதங்களுக்கு மத்தியிலும், மேலும் அல்லாஹ்வின் தூதரைப் (ஸல்) பற்றியும் குர்ஆனைப் பற்றியும் அவர்கள் தரக்குறைவாகப் பேசிய போதிலும், அவர்கள் தங்கள் பாவங்களை விட்டுவிட்டு, இஸ்லாத்திற்கும் நேர்வழிக்கும் வர வேண்டுமென அல்லாஹ் அவர்களைத் தொடர்ந்து அழைக்கிறான். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَّقَدْ</span> <span class=\"quran-arabic-font text-success\">كَفَرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">ثَـلِثُ</span> <span class=\"quran-arabic-font text-success\">ثَلَـثَةٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٌ</span> <span class=\"quran-arabic-font text-success\">وَحِدٌ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يَنتَهُواْ</span> <span class=\"quran-arabic-font text-success\">عَمَّا</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">لَيَمَسَّنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابٌ</span> <span class=\"quran-arabic-font text-success\">أَلِيمٌ</span> - <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">يَتُوبُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَيَسْتَغْفِرُونَهُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُورٌ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٌ</span><br />\r\n<br />\r\n(நிச்சயமாக, \"அல்லாஹ் மூவரில் மூன்றாமவன்\" என்று கூறியவர்கள் நிராகரிப்பாளர்களாகி விட்டனர். அந்த ஒரே இறைவனைத் தவிர வேறு இறைவனில்லை. தாங்கள் கூறுவதிலிருந்து அவர்கள் விலகிக் கொள்ளாவிட்டால், அவர்களில் நிராகரிப்பவர்களுக்குத் துன்புறுத்தும் வேதனை நிச்சயமாக வந்தடையும். அவர்கள் அல்லாஹ்வின் பக்கம் பாவமன்னிப்புக் கோரித் திரும்ப மாட்டார்களா? இன்னும் அவனிடம் மன்னிப்புக் கேட்க மாட்டார்களா? அல்லாஹ்வோ மிக்க மன்னிப்பவன், அளவற்ற கருணையாளன்.) (<a href=\"qurandisp.php?sura=5&ayah=73\" class=\"link\">5:73</a>-74)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">فَتَنُواْ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُؤْمِنَـتِ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَتُوبُواْ</span> <span class=\"quran-arabic-font text-success\">فَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">الْحَرِيقِ</span><br />\r\n<br />\r\n(நிச்சயமாக விசுவாசமான ஆண்களையும் விசுவாசமான பெண்களையும் துன்புறுத்தி, பின்னர் அதற்காகப் பாவமன்னிப்புக் கோராதவர்களுக்கு நரகத்தின் வேதனையும், கருக வைக்கும் நெருப்பின் தண்டனையும் உண்டு.) (<a href=\"qurandisp.php?sura=85&ayah=10\" class=\"link\">85:10</a>)<br />\r\n<br />\r\nஅல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"இந்த அன்பையும் தாராளத்தன்மையையும் பாருங்கள்! அவர்கள் அவனுடைய நேசர்களைக் கொன்றனர்; அவனோ அவர்களைப் பாவமன்னிப்பிற்கும் தனது கருணைக்கும் அழைக்கிறான்.\"<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"குர்ஆனைப் பற்றி நிராகரிப்பாளர்கள் கூறியவை\n\r\n\n\r\nநிராகரிப்பாளர்களின் அறியாமை நிறைந்த மனங்களின் முட்டாள்தனத்தைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள் குர்ஆனைப் பற்றி இவ்வாறு கூறினார்கள்:\n\r\n\n\r\nإِنْ هَـذَا إِلاَّ إِفْكٌ\n\r\n\n\r\n(இது ஒரு பொய்யே அன்றி வேறில்லை), அதாவது இது ஓர் உண்மையற்ற கூற்றாகும்.\n\r\n\n\r\nافْتَرَاهُ\n\r\n\n\r\n(அவர் இதனை இட்டுக் கட்டியுள்ளார்), அதாவது நபி (ஸல்) அவர்கள் இதனை உருவாக்கினார்கள் (என்று அவர்கள் கூறினர்).\n\r\n\n\r\nوَأَعَانَهُ عَلَيْهِ قَوْمٌ ءَاخَرُونَ\n\r\n\n\r\n(மேலும் இதற்கு மற்றவர்களும் அவருக்கு உதவி புரிந்துள்ளனர்.) அதாவது, இதனைத் தொகுக்க அவர் மற்றவர்களின் உதவியைப் பெற்றுள்ளார் என்று அவர்கள் கூறினர். எனவே அல்லாஹ் கூறினான்:\n\r\n\n\r\nفَقَدْ جَآءُوا ظُلْماً وَزُوراً\n\r\n\n\r\n(நிச்சயமாக அவர்கள் ஓர் அநியாயத்தையும் பெரும் பொய்யையுமே கொண்டு வந்துள்ளனர்.) அதாவது, அவர்களே பொய் சொல்கிறார்கள்; அவர்கள் கூறுவது உண்மைக்கு மாறானது என்பதை அவர்களின் மனச்சாட்சியே அறியும் என்பதால், அது பொய்யானது என்பதை அவர்களும் அறிவார்கள்.\n\r\n\n\r\nوَقَالُواْ أَسَـطِيرُ الاٌّوَّلِينَ اكْتَتَبَهَا\n\r\n\n\r\n(இன்னும் அவர்கள் கூறுகிறார்கள்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவற்றை அவர் எழுதி வைத்துள்ளார்...\") அதாவது, முன்னோர்கள் எழுதியதை இவர் பிரதி எடுத்துள்ளார் என்று அவர்கள் கூறினர்.\n\r\n\n\r\nفَهِىَ تُمْلَى عَلَيْهِ\n\r\n\n\r\n(மேலும் அவை அவருக்கு ஓதிக் காட்டப்படுகின்றன) அதாவது, அவை அவருக்கு வாசித்துக் காட்டப்படுகின்றன அல்லது ஓதப்படுகின்றன.\n\r\n\n\r\nبُكْرَةً وَأَصِيلاً\n\r\n\n\r\n(காலையிலும் மாலையிலும்.) அதாவது நாளின் தொடக்கத்திலும் இறுதியிலும். இந்தக் கருத்து அப்பட்டமான பொய் என்பதால், இது உண்மையல்ல என்பதை எவரும் எளிதில் அறிந்து கொள்ளலாம். அல்லாஹ்வின் தூதர் முஹம்மது (ஸல்) அவர்கள் தம் வாழ்நாளின் ஆரம்பத்திலோ அல்லது இறுதியிலோ எழுதவோ அல்லது வாசிக்கவோ கற்றதில்லை என்பது 'முதவாதிர்' (தொடர்ச்சியான பலருடைய) அறிவிப்புகளின் மூலம் ஊர்ஜிதப்படுத்தப்பட்ட ஒரு பொதுவான உண்மையாகும். அவர் பிறந்ததிலிருந்து அவருடைய தூதுப்பணி தொடங்கும் வரை, ஏறக்குறைய நாற்பது ஆண்டுகள் அவர்களுடனேயே வாழ்ந்தார்கள். அவருடைய நேர்மை, தூய்மையான குணம் ஆகியவற்றையும், அவர் ஒருபோதும் பொய் சொல்லவோ ஒழுக்கமற்ற அல்லது தீய செயல்களில் ஈடுபடவோ மாட்டார் என்பதையும் அவர்கள் நன்கு அறிந்திருந்தார்கள். அவருடைய வாய்மையையும் நேர்மையையும் கண்ட அவர்கள், அவர் நபித்துவப் பொறுப்பைப் பெறுவதற்கு முன்பே, சிறு வயதிலிருந்தே அவரை 'அல்-அமீன்' (நம்பிக்கைக்குரியவர்) என்றே அழைத்து வந்தனர். அல்லாஹ் அவருக்கு வழங்கிய அந்தப் பெரும் கண்ணியத்தின் (நபித்துவத்தின்) போது, அவர்கள் அவருக்கு விரோதிகளாக மாறி, இவ்வாறான பொய்க்குற்றச்சாட்டுகளை அடுக்கினர். பகுத்தறிவுள்ள எவரும் அவர் இத்தகைய செயல்களிலிருந்து நீங்கியவர் என்பதை உணர்வார்கள். அவர் மீது என்ன குற்றம் சாட்டுவது என்று தெரியாமல் அவர்கள் தடுமாறினர். சில நேரங்களில் அவரை ஒரு சூனியக்காரர் என்றும், வேறு சில நேரங்களில் கவிஞர், பைத்தியக்காரர் அல்லது பொய்யர் என்றும் கூறினர். எனவே அல்லாஹ் கூறினான்:\n\r\n\n\r\nانْظُرْ كَيْفَ ضَرَبُواْ لَكَ الاٌّمْثَالَ فَضَلُّواْ فَلاَ يَسْتَطِيعْونَ سَبِيلاً\n\r\n\n\r\n(அவர்கள் உமக்கு எத்தகைய உதாரணங்களைக் கூறுகிறார்கள் என்று பாரும். இதனால் அவர்கள் வழிதவறிவிட்டார்கள், நேர்வழியை அடைய அவர்களால் ஒருபோதும் இயலாது.) (17:48) அவர்களின் இந்தப் பிடிவாதத்திற்குப் பதிலளிக்கும் விதமாக அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nقُلْ أَنزَلَهُ الَّذِى يَعْلَمُ السِّرَّ فِى السَّمَـوَتِ وَالاٌّرْضِ\n\r\n\n\r\n(கூறுவீராக: \"வானங்களிலும் பூமியிலும் உள்ள இரகசியங்களை அறிபவனே இதனை இறக்கிவைத்தான்.\") அதாவது, கடந்த கால மற்றும் வருங்கால தலைமுறைகளைப் பற்றிய உண்மையான செய்திகளையும், கடந்த கால மற்றும் எதிர்கால யதார்த்தங்களோடு ஒத்துப் போகும் தகவல்களையும் உள்ளடக்கிய குர்ஆனை அவன் வஹீயாக (இறைச்செய்தியாக) அருளியுள்ளான்.\n\r\n\n\r\nالَّذِى يَعْلَمُ السِّرَّ\n\r\n\n\r\n(இரகசியத்தை அறிந்தவன்) என்பது, அல்லாஹ்வே வானங்களிலும் பூமியிலும் உள்ள மறைவானவற்றை அறிந்தவன் என்பதாகும்; வெளிப்படையாக இருப்பவற்றை அவன் அறிவது போலவே, அவற்றின் இரகசியங்களையும் அவன் நன்கு அறிவான்.\n\r\n\n\r\nإِنَّهُ كَانَ غَفُوراً رَّحِيماً\n\r\n\n\r\n(நிச்சயமாக அவன் மிக்க மன்னிப்பவனாகவும், அளவற்ற கருணையாளனாகவும் இருக்கிறான்.) இது அவர்கள் பாவமன்னிப்புக் கேட்டு அல்லாஹ்வின் பக்கம் மீள்வதற்கான ஓர் அழைப்பாகும். அவனது கருணை விசாலமானது, அவனது பொறுமை அளவற்றது என்பதை இது அவர்களுக்கு உணர்த்துகிறது. அவனிடம் எவர் பாவமன்னிப்புக் கோருகிறாரோ, அவருடைய தவ்பாவை அவன் ஏற்றுக் கொள்கிறான். அவர்களுடைய இத்தனை பொய்கள், அநாகரீகமான செயல்கள், நிராகரிப்பு மற்றும் பிடிவாதங்களுக்கு மத்தியிலும், மேலும் அல்லாஹ்வின் தூதரைப் (ஸல்) பற்றியும் குர்ஆனைப் பற்றியும் அவர்கள் தரக்குறைவாகப் பேசிய போதிலும், அவர்கள் தங்கள் பாவங்களை விட்டுவிட்டு, இஸ்லாத்திற்கும் நேர்வழிக்கும் வர வேண்டுமென அல்லாஹ் அவர்களைத் தொடர்ந்து அழைக்கிறான். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nلَّقَدْ كَفَرَ الَّذِينَ قَالُواْ إِنَّ اللَّهَ ثَـلِثُ ثَلَـثَةٍ وَمَا مِنْ إِلَـهٍ إِلاَّ إِلَـهٌ وَحِدٌ وَإِن لَّمْ يَنتَهُواْ عَمَّا يَقُولُونَ لَيَمَسَّنَّ الَّذِينَ كَفَرُواْ مِنْهُمْ عَذَابٌ أَلِيمٌ - أَفَلاَ يَتُوبُونَ إِلَى اللَّهِ وَيَسْتَغْفِرُونَهُ وَاللَّهُ غَفُورٌ رَّحِيمٌ\n\r\n\n\r\n(நிச்சயமாக, \"அல்லாஹ் மூவரில் மூன்றாமவன்\" என்று கூறியவர்கள் நிராகரிப்பாளர்களாகி விட்டனர். அந்த ஒரே இறைவனைத் தவிர வேறு இறைவனில்லை. தாங்கள் கூறுவதிலிருந்து அவர்கள் விலகிக் கொள்ளாவிட்டால், அவர்களில் நிராகரிப்பவர்களுக்குத் துன்புறுத்தும் வேதனை நிச்சயமாக வந்தடையும். அவர்கள் அல்லாஹ்வின் பக்கம் பாவமன்னிப்புக் கோரித் திரும்ப மாட்டார்களா? இன்னும் அவனிடம் மன்னிப்புக் கேட்க மாட்டார்களா? அல்லாஹ்வோ மிக்க மன்னிப்பவன், அளவற்ற கருணையாளன்.) (5:73-74)\n\r\n\n\r\nإِنَّ الَّذِينَ فَتَنُواْ الْمُؤْمِنِينَ وَالْمُؤْمِنَـتِ ثُمَّ لَمْ يَتُوبُواْ فَلَهُمْ عَذَابُ جَهَنَّمَ وَلَهُمْ عَذَابُ الْحَرِيقِ\n\r\n\n\r\n(நிச்சயமாக விசுவாசமான ஆண்களையும் விசுவாசமான பெண்களையும் துன்புறுத்தி, பின்னர் அதற்காகப் பாவமன்னிப்புக் கோராதவர்களுக்கு நரகத்தின் வேதனையும், கருக வைக்கும் நெருப்பின் தண்டனையும் உண்டு.) (85:10)\n\r\n\n\r\nஅல்-ஹஸன் அல்-பஸரி அவர்கள் கூறினார்கள்: \"இந்த அன்பையும் தாராளத்தன்மையையும் பாருங்கள்! அவர்கள் அவனுடைய நேசர்களைக் கொன்றனர்; அவனோ அவர்களைப் பாவமன்னிப்பிற்கும் தனது கருணைக்கும் அழைக்கிறான்.\""},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"9":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=14\" class=\"link\">25:14</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:14 ஐ பார்க்கவும்"},"14":{"html":"<strong>இறைத்தூதரைப் பற்றி நிராகரிப்பாளர்கள் கூறியவை, அவர்களின் கூற்றுகளுக்கான மறுப்பு மற்றும் அவர்களின் இறுதி முடிவு</strong><br />\r\n<br />\r\nஆதாரமோ சான்றோ இன்றி சத்தியத்தை பிடிவாதமாக எதிர்த்து நிராகரிக்கும் நிராகரிப்பாளர்கள் குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அவர்களின் சாக்குப்போக்கு இதோ:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">لِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ﴿</span><br />\r\n(‘இந்தத் தூதருக்கு என்ன நேர்ந்தது? இவர் உணவு உண்கிறாரே!’) அதாவது, ‘நாங்கள் உண்பது போலவே இவரும் உண்கிறார், எங்களைப் போலவே இவருக்கும் ஏன் உணவு தேவைப்படுகிறது?’<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَمْشِى</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّسْوَاقِ﴿</span><br />\r\n(‘மேலும் சந்தைகளில் நடமாடுகிறாரே!’) அதாவது, அவர் வியாபாரம் செய்யவும் பிழைப்பு தேடவும் அடிக்கடி அங்கு சென்று வருகிறார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَوْلا</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مَلَكٌ</span> <span class=\"quran-arabic-font text-success\">فَيَكُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">نَذِيراً﴿</span><br />\r\n(‘அவருடன் சேர்ந்து எச்சரிக்கை செய்வதற்காக ஒரு வானவர் ஏன் அவரிடம் இறக்கப்படவில்லை?’) அவர்கள் இப்படிக் கூறிக் கொண்டிருந்தார்கள்: அவர் கூறுவது உண்மை என்பதற்குச் சாட்சியாக அல்லாஹ்விடமிருந்து ஒரு வானவர் ஏன் அவரிடம் வரவில்லை? இது ஃபிர்அவ்ன் கூறியதைப் போன்றதே:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">أَسْوِرَةٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذَهَبٍ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">مُقْتَرِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(“அப்படியானால், அவருக்குத் தங்கக் காப்புகள் ஏன் அணிவிக்கப்படவில்லை? அல்லது அவருடன் வானவர்கள் ஏன் வரவில்லை?”) (<a href=\"qurandisp.php?sura=43&ayah=53\" class=\"link\">43:53</a>). இந்த மக்களும் இதே போன்ற மனநிலையையே கொண்டிருந்தனர், மேலும் இதையே கூறினார்கள். அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">يُلْقَى</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">كَنْزٌ﴿</span><br />\r\n(‘அல்லது அவருக்கு ஒரு புதையல் ஏன் வழங்கப்படவில்லை?’) அதாவது, தனது தேவைகளுக்கும் விருப்பங்களுக்கும் அவர் செலவழிக்கக்கூடிய ஒரு புதையல்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">جَنَّةٌ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا﴿</span><br />\r\n(‘அல்லது அவர் உண்பதற்காக ஒரு தோட்டம் ஏன் அவருக்கு இல்லை?’) அதாவது, அவர் எங்கு சென்றாலும் அவருடனேயே இருக்கும் ஒரு தோட்டம். இவை அனைத்தும் அல்லாஹ்வுக்கு மிக எளிதானவையே, ஆனால் இவற்றைச் செய்யாமல் இருப்பதற்கு அவனிடம் ஒரு காரணம் இருந்தது; மேலும் அவனிடம் முழுமையான ஆதாரமும் வாதமும் உள்ளது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُونَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">تَتَّبِعُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَجُلاً</span> <span class=\"quran-arabic-font text-success\">مَّسْحُوراً﴿</span><br />\r\n(மேலும் அநியாயக்காரர்கள் கூறுகிறார்கள்: “சூனியம் செய்யப்பட்ட ஒரு மனிதரைத் தவிர வேறெவரையும் நீங்கள் பின்பற்றவில்லை.”) அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾انْظُرْ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">ضَرَبُواْ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">الاٌّمْثَالَ</span> <span class=\"quran-arabic-font text-success\">فَضَلُّواْ﴿</span><br />\r\n(‘(நபியே!) அவர்கள் உமக்கு எத்தகைய உவமைகளைக் கூறுகிறார்கள் என்று பாருங்கள்! அதனால் அவர்கள் வழிதவறிவிட்டனர்.’) அதாவது, நீர் ஒரு சூனியக்காரர் அல்லது சூனியம் செய்யப்பட்டவர் அல்லது பைத்தியக்காரர் அல்லது பொய்யர் அல்லது கவிஞர் என்று கூறி அவர்கள் உம்மைக் குற்றஞ்சாட்டினார்கள், உம்மைப் பொய்யாக்கினார்கள். ஆனால் இவையனைத்தும் தவறான கருத்துகளாகும். சிறு புத்தியுள்ள எவரும் அவர்கள் பொய் சொல்கிறார்கள் என்பதை அறிந்துகொள்வார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَضَلُّواْ﴿</span><br />\r\n(‘ஆகவே அவர்கள் வழிதவறிவிட்டனர்’) நேர்வழியின் பாதையிலிருந்து.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعُونَ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً﴿</span><br />\r\n(‘மேலும் அவர்களால் ஒரு பாதையையும் கண்டடைய முடியாது.’) சத்தியம் மற்றும் நேர்வழியின் பாதையை விட்டு வெளியேறும் எவரும், அவர் எந்தத் திசையில் சென்றாலும் வழிதவறியவரே. ஏனெனில் சத்தியம் ஒன்றே, அதன் வழிமுறை சீரானது, அதன் ஒரு பகுதி மற்ற பகுதியை உறுதிப்படுத்துகிறது. பின்னர் அல்லாஹ் தனது தூதரிடம் (ஸல்), அவன் நாடினால் அவர்கள் சொல்வதை விட மிகச் சிறந்த ஒன்றை இவ்வுலகிலேயே அவருக்கு வழங்க முடியும் என்று கூறுகிறான். அவன் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">خَيْراً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">جَنَّـتٍ</span> <span class=\"quran-arabic-font text-success\">تَجْرِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">تَحْتِهَا</span> <span class=\"quran-arabic-font text-success\">الاٌّنْهَـرُ</span> <span class=\"quran-arabic-font text-success\">وَيَجْعَل</span> <span class=\"quran-arabic-font text-success\">لَّكَ</span> <span class=\"quran-arabic-font text-success\">قُصُوراً﴿</span><br />\r\n(‘அவன் நாடினால், (அவர்கள் கூறுவதை) விடச் சிறந்ததை உமக்கு ஏற்படுத்தித் தரக்கூடியவன் பாக்கியமிக்கவன்; அதாவது, ஆறுகள் ஓடும் தோட்டங்களை உமக்கு ஏற்படுத்தித் தருவான்; இன்னும் உமக்கு மாளிகைகளையும் அவன் அமைத்துத் தருவான்.’) முஜாஹித் (ரஹ்) கூறினார்கள்: “இதன் பொருள் இவ்வுலகில் என்பதாகும்.” மேலும் அவர்கள் கூறினார்கள்: “குறைஷிகள் கல்லால் கட்டப்பட்ட ஒவ்வொரு வீட்டையும், அது பெரியதோ சிறிதோ, ‘அரண்மனை’ என்றே அழைப்பார்கள்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">كَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">بِالسَّاعَةِ﴿</span><br />\r\n(‘இல்லை, அவர்கள் மறுமை நாளைப் பொய்யாக்குகிறார்கள்.’) அதாவது, அவர்கள் தெளிவையும் வழிகாட்டுதலையும் தேடுவதால் இதைச் சொல்லவில்லை, மாறாகப் பிடிவாதமான நிராகரிப்பினால் இதைச் சொல்கிறார்கள். மறுமை நாள் மீதான அவர்களின் நம்பிக்கையின்மையே அவர்களை இவ்வாறு பேச வைக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَعْتَدْنَا﴿</span><br />\r\n(‘மேலும் நாம் தயார் செய்துள்ளோம்’) அதாவது, ‘நாம் ஆயத்தப்படுத்தி வைத்துள்ளோம்,’<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِمَن</span> <span class=\"quran-arabic-font text-success\">كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">بِالسَّاعَةِ</span> <span class=\"quran-arabic-font text-success\">سَعِيراً﴿</span><br />\r\n(‘மறுமை நாளைப் பொய்யாக்குபவர்களுக்காக, கொழுந்துவிட்டெரியும் நெருப்பை.’) அதாவது, நரக நெருப்பில் தாங்க முடியாத வெப்பமும் வேதனையும் கொண்ட தண்டனை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَتْهُمْ﴿</span><br />\r\n(‘அது அவர்களைக் காணும்போது’) அதாவது, நரகம் அவர்களைக் காணும்போது,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مِن</span> <span class=\"quran-arabic-font text-success\">مَّكَانِ</span> <span class=\"quran-arabic-font text-success\">بَعِيدٍ﴿</span><br />\r\n(‘தொலைதூர இடத்திலிருந்து’) அதாவது (மறுமை நாளில் மக்கள்) ஒன்றுதிரட்டப்படும் இடத்திலிருந்து,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">تَغَيُّظاً</span> <span class=\"quran-arabic-font text-success\">وَزَفِيراً﴿</span><br />\r\n(‘அதன் சீற்றத்தையும் முழக்கத்தையும் அவர்கள் கேட்பார்கள்.’) அதாவது, அவர்கள் மீதான கோபத்தால் அது அத்தகைய சத்தங்களை எழுப்பும். இது இந்த வசனத்தைப் போன்றது,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِذَآ</span> <span class=\"quran-arabic-font text-success\">أُلْقُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">سَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">شَهِيقًا</span> <span class=\"quran-arabic-font text-success\">وَهِىَ</span> <span class=\"quran-arabic-font text-success\">تَفُورُ</span> <span class=\"quran-arabic-font text-success\">تَكَادُ</span> <span class=\"quran-arabic-font text-success\">تَمَيَّزُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الغَيْظِ﴿</span><br />\r\n(‘அதில் அவர்கள் வீசப்படும்போது, அது கொதித்துக் கொண்டிருக்கும் நிலையில் அதன் பயங்கரமான மூச்சுச் சத்தத்தை அவர்கள் கேட்பார்கள். அது கோபத்தால் வெடித்துச் சிதறிவிடும் போலிருக்கும்.’) (<a href=\"qurandisp.php?sura=67&ayah=7\" class=\"link\">67:7</a>-8). அதாவது, அல்லாஹ்வை நிராகரித்தவர்கள் மீதுள்ள கடும் கோபத்தினால் அதன் ஒரு பகுதி மற்றொரு பகுதியிலிருந்து பிரியும் நிலைக்கு ஆளாகும்.<br />\r\n<br />\r\nஇமாம் அபூ ஜஃபர் பின் ஜரீர் (ரஹ்) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: “ஒரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அது சுருங்கி விரியும். அர்-ரஹ்மான் அதனிடம் ‘உனக்கு என்ன நேர்ந்தது?’ என்று கேட்பான். அதற்கு அது ‘அவன் என்னிடமிருந்து பாதுகாப்புத் தேடுகிறான்’ என்று கூறும். அப்போது அல்லாஹ், ‘என் அடியானை விட்டுவிடுங்கள்’ என்று கூறுவான். மற்றொரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அவன் ‘இறைவா, உன்னிடமிருந்து இதை நான் ஒருபோதும் எதிர்பார்க்கவில்லை’ என்பான். அல்லாஹ் ‘நீ என்ன எதிர்பார்த்தாய்?’ என்று கேட்பான். அதற்கு அவன் ‘உனது கருணை என்னையும் உள்ளடக்கும் அளவுக்குப் பறந்து விரிந்ததாக இருக்கும் என்று எதிர்பார்த்தேன்’ என்பான். அல்லாஹ் ‘என் அடியானை விட்டுவிடுங்கள்’ என்பான். இன்னொரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அப்போது பார்லியைப் பார்த்து ஒரு கழுதை கத்துவதைப் போல நரகம் அவனிடம் கத்தும். பிறகு அது ஒரு முனகலை வெளிப்படுத்தும், அது அனைவரையும் அச்சத்தில் ஆழ்த்தும்.” இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">تَغَيُّظاً</span> <span class=\"quran-arabic-font text-success\">وَزَفِيراً﴿</span><br />\r\n(அதன் சீற்றத்தையும் முழக்கத்தையும் அவர்கள் கேட்பார்கள்.) அப்துர்-ரஸ்ஸாக் (ரஹ்) அவர்கள் உபைத் பின் உமைர் (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: “நரகம் ஒரு முனகலை எழுப்பும். அதனால் அல்லாஹ்வுக்கு நெருக்கமான எந்த வானவரும் சரி, அனுப்பப்பட்ட எந்த நபியும் சரி, உடல் நடுங்கி முகங்குப்புற விழாமல் இருக்க மாட்டார்கள். இப்ராஹீம் (அலை) அவர்கள் கூட முழங்காலிட்டு வீழ்ந்து, ‘இறைவா, இன்றைய தினம் எனக்காகத் தவிர வேறு யாருக்காகவும் நான் உன்னிடம் இரட்சிப்பைக் கேட்கவில்லை’ என்று கூறுவார்கள்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">أُلْقُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">مَكَاناً</span> <span class=\"quran-arabic-font text-success\">ضَيِّقاً</span> <span class=\"quran-arabic-font text-success\">مُّقَرَّنِينَ﴿</span><br />\r\n(‘மேலும் அவர்கள் சங்கிலிகளால் பிணைக்கப்பட்டவர்களாக அதன் ஒரு குறுகிய இடத்தில் வீசப்படும்போது,’) இப்னு ஜரீர் (ரஹ்) அவர்கள் அபூ உபைதா அவர்கள் வழியாக அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: “அது ஒரு ஈட்டியின் முனை போன்ற குறுகலான இடமாகும்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مُقَرَّنِينَ﴿</span><br />\r\n(‘சங்கிலிகளால் பிணைக்கப்பட்டவர்களாக,’) அபூ ஸாலிஹ் (ரஹ்) கூறினார்கள்: “இதன் பொருள், அவர்களின் தோள்களோடு சேர்த்துப் பிணைக்கப்பட்டு என்பதாகும்.”<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾دَعَوْاْ</span> <span class=\"quran-arabic-font text-success\">هُنَالِكَ</span> <span class=\"quran-arabic-font text-success\">ثُبُوراً﴿</span><br />\r\n(‘அவர்கள் அங்கே அழிவைக் கோருவார்கள்.’) அதாவது, அவர்கள் துக்கம், மனவருத்தம் மற்றும் வேதனையில் பேரழிவைக் கூவி அழைப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لاَّ</span> <span class=\"quran-arabic-font text-success\">تَدْعُواْ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">ثُبُوراً</span> <span class=\"quran-arabic-font text-success\">وَاحِداً</span> <span class=\"quran-arabic-font text-success\">وَادْعُواْ</span> <span class=\"quran-arabic-font text-success\">ثُبُوراً</span> <span class=\"quran-arabic-font text-success\">كَثِيراً﴿</span><br />\r\n(‘இன்று ஒரு முறை மட்டும் அழிவைக் கோராதீர்கள்; மாறாகப் பலமுறை அழிவைக் கோருங்கள்.’)<br />\r\n<br />","text":"இறைத்தூதரைப் பற்றி நிராகரிப்பாளர்கள் கூறியவை, அவர்களின் கூற்றுகளுக்கான மறுப்பு மற்றும் அவர்களின் இறுதி முடிவு\n\r\n\n\r\nஆதாரமோ சான்றோ இன்றி சத்தியத்தை பிடிவாதமாக எதிர்த்து நிராகரிக்கும் நிராகரிப்பாளர்கள் குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அவர்களின் சாக்குப்போக்கு இதோ:\n\r\n﴾مَا لِهَـذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ﴿\n\r\n(‘இந்தத் தூதருக்கு என்ன நேர்ந்தது? இவர் உணவு உண்கிறாரே!’) அதாவது, ‘நாங்கள் உண்பது போலவே இவரும் உண்கிறார், எங்களைப் போலவே இவருக்கும் ஏன் உணவு தேவைப்படுகிறது?’\n\r\n﴾وَيَمْشِى فِى الاٌّسْوَاقِ﴿\n\r\n(‘மேலும் சந்தைகளில் நடமாடுகிறாரே!’) அதாவது, அவர் வியாபாரம் செய்யவும் பிழைப்பு தேடவும் அடிக்கடி அங்கு சென்று வருகிறார்.\n\r\n\n\r\n﴾لَوْلا أُنزِلَ إِلَيْهِ مَلَكٌ فَيَكُونَ مَعَهُ نَذِيراً﴿\n\r\n(‘அவருடன் சேர்ந்து எச்சரிக்கை செய்வதற்காக ஒரு வானவர் ஏன் அவரிடம் இறக்கப்படவில்லை?’) அவர்கள் இப்படிக் கூறிக் கொண்டிருந்தார்கள்: அவர் கூறுவது உண்மை என்பதற்குச் சாட்சியாக அல்லாஹ்விடமிருந்து ஒரு வானவர் ஏன் அவரிடம் வரவில்லை? இது ஃபிர்அவ்ன் கூறியதைப் போன்றதே:\n\r\n﴾فَلَوْلاَ أُلْقِىَ عَلَيْهِ أَسْوِرَةٌ مِّن ذَهَبٍ أَوْ جَآءَ مَعَهُ الْمَلَـئِكَةُ مُقْتَرِنِينَ ﴿\n\r\n(“அப்படியானால், அவருக்குத் தங்கக் காப்புகள் ஏன் அணிவிக்கப்படவில்லை? அல்லது அவருடன் வானவர்கள் ஏன் வரவில்லை?”) (43:53). இந்த மக்களும் இதே போன்ற மனநிலையையே கொண்டிருந்தனர், மேலும் இதையே கூறினார்கள். அவர்கள் கூறினார்கள்:\n\r\n﴾أَوْ يُلْقَى إِلَيْهِ كَنْزٌ﴿\n\r\n(‘அல்லது அவருக்கு ஒரு புதையல் ஏன் வழங்கப்படவில்லை?’) அதாவது, தனது தேவைகளுக்கும் விருப்பங்களுக்கும் அவர் செலவழிக்கக்கூடிய ஒரு புதையல்.\n\r\n\n\r\n﴾أَوْ تَكُونُ لَهُ جَنَّةٌ يَأْكُلُ مِنْهَا﴿\n\r\n(‘அல்லது அவர் உண்பதற்காக ஒரு தோட்டம் ஏன் அவருக்கு இல்லை?’) அதாவது, அவர் எங்கு சென்றாலும் அவருடனேயே இருக்கும் ஒரு தோட்டம். இவை அனைத்தும் அல்லாஹ்வுக்கு மிக எளிதானவையே, ஆனால் இவற்றைச் செய்யாமல் இருப்பதற்கு அவனிடம் ஒரு காரணம் இருந்தது; மேலும் அவனிடம் முழுமையான ஆதாரமும் வாதமும் உள்ளது.\n\r\n﴾وَقَالَ الظَّـلِمُونَ إِن تَتَّبِعُونَ إِلاَّ رَجُلاً مَّسْحُوراً﴿\n\r\n(மேலும் அநியாயக்காரர்கள் கூறுகிறார்கள்: “சூனியம் செய்யப்பட்ட ஒரு மனிதரைத் தவிர வேறெவரையும் நீங்கள் பின்பற்றவில்லை.”) அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾انْظُرْ كَيْفَ ضَرَبُواْ لَكَ الاٌّمْثَالَ فَضَلُّواْ﴿\n\r\n(‘(நபியே!) அவர்கள் உமக்கு எத்தகைய உவமைகளைக் கூறுகிறார்கள் என்று பாருங்கள்! அதனால் அவர்கள் வழிதவறிவிட்டனர்.’) அதாவது, நீர் ஒரு சூனியக்காரர் அல்லது சூனியம் செய்யப்பட்டவர் அல்லது பைத்தியக்காரர் அல்லது பொய்யர் அல்லது கவிஞர் என்று கூறி அவர்கள் உம்மைக் குற்றஞ்சாட்டினார்கள், உம்மைப் பொய்யாக்கினார்கள். ஆனால் இவையனைத்தும் தவறான கருத்துகளாகும். சிறு புத்தியுள்ள எவரும் அவர்கள் பொய் சொல்கிறார்கள் என்பதை அறிந்துகொள்வார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n﴾فَضَلُّواْ﴿\n\r\n(‘ஆகவே அவர்கள் வழிதவறிவிட்டனர்’) நேர்வழியின் பாதையிலிருந்து.\n\r\n\n\r\n﴾فَلاَ يَسْتَطِيعُونَ سَبِيلاً﴿\n\r\n(‘மேலும் அவர்களால் ஒரு பாதையையும் கண்டடைய முடியாது.’) சத்தியம் மற்றும் நேர்வழியின் பாதையை விட்டு வெளியேறும் எவரும், அவர் எந்தத் திசையில் சென்றாலும் வழிதவறியவரே. ஏனெனில் சத்தியம் ஒன்றே, அதன் வழிமுறை சீரானது, அதன் ஒரு பகுதி மற்ற பகுதியை உறுதிப்படுத்துகிறது. பின்னர் அல்லாஹ் தனது தூதரிடம் (ஸல்), அவன் நாடினால் அவர்கள் சொல்வதை விட மிகச் சிறந்த ஒன்றை இவ்வுலகிலேயே அவருக்கு வழங்க முடியும் என்று கூறுகிறான். அவன் கூறினான்:\n\r\n﴾تَبَارَكَ الَّذِى إِن شَآءَ جَعَلَ لَكَ خَيْراً مِّن ذلِكَ جَنَّـتٍ تَجْرِى مِن تَحْتِهَا الاٌّنْهَـرُ وَيَجْعَل لَّكَ قُصُوراً﴿\n\r\n(‘அவன் நாடினால், (அவர்கள் கூறுவதை) விடச் சிறந்ததை உமக்கு ஏற்படுத்தித் தரக்கூடியவன் பாக்கியமிக்கவன்; அதாவது, ஆறுகள் ஓடும் தோட்டங்களை உமக்கு ஏற்படுத்தித் தருவான்; இன்னும் உமக்கு மாளிகைகளையும் அவன் அமைத்துத் தருவான்.’) முஜாஹித் (ரஹ்) கூறினார்கள்: “இதன் பொருள் இவ்வுலகில் என்பதாகும்.” மேலும் அவர்கள் கூறினார்கள்: “குறைஷிகள் கல்லால் கட்டப்பட்ட ஒவ்வொரு வீட்டையும், அது பெரியதோ சிறிதோ, ‘அரண்மனை’ என்றே அழைப்பார்கள்.”\n\r\n\n\r\n﴾بَلْ كَذَّبُواْ بِالسَّاعَةِ﴿\n\r\n(‘இல்லை, அவர்கள் மறுமை நாளைப் பொய்யாக்குகிறார்கள்.’) அதாவது, அவர்கள் தெளிவையும் வழிகாட்டுதலையும் தேடுவதால் இதைச் சொல்லவில்லை, மாறாகப் பிடிவாதமான நிராகரிப்பினால் இதைச் சொல்கிறார்கள். மறுமை நாள் மீதான அவர்களின் நம்பிக்கையின்மையே அவர்களை இவ்வாறு பேச வைக்கிறது.\n\r\n\n\r\n﴾وَأَعْتَدْنَا﴿\n\r\n(‘மேலும் நாம் தயார் செய்துள்ளோம்’) அதாவது, ‘நாம் ஆயத்தப்படுத்தி வைத்துள்ளோம்,’\n\r\n\n\r\n﴾لِمَن كَذَّبَ بِالسَّاعَةِ سَعِيراً﴿\n\r\n(‘மறுமை நாளைப் பொய்யாக்குபவர்களுக்காக, கொழுந்துவிட்டெரியும் நெருப்பை.’) அதாவது, நரக நெருப்பில் தாங்க முடியாத வெப்பமும் வேதனையும் கொண்ட தண்டனை.\n\r\n\n\r\n﴾إِذَا رَأَتْهُمْ﴿\n\r\n(‘அது அவர்களைக் காணும்போது’) அதாவது, நரகம் அவர்களைக் காணும்போது,\n\r\n\n\r\n﴾مِن مَّكَانِ بَعِيدٍ﴿\n\r\n(‘தொலைதூர இடத்திலிருந்து’) அதாவது (மறுமை நாளில் மக்கள்) ஒன்றுதிரட்டப்படும் இடத்திலிருந்து,\n\r\n\n\r\n﴾سَمِعُواْ لَهَا تَغَيُّظاً وَزَفِيراً﴿\n\r\n(‘அதன் சீற்றத்தையும் முழக்கத்தையும் அவர்கள் கேட்பார்கள்.’) அதாவது, அவர்கள் மீதான கோபத்தால் அது அத்தகைய சத்தங்களை எழுப்பும். இது இந்த வசனத்தைப் போன்றது,\n\r\n﴾إِذَآ أُلْقُواْ فِيهَا سَمِعُواْ لَهَا شَهِيقًا وَهِىَ تَفُورُ تَكَادُ تَمَيَّزُ مِنَ الغَيْظِ﴿\n\r\n(‘அதில் அவர்கள் வீசப்படும்போது, அது கொதித்துக் கொண்டிருக்கும் நிலையில் அதன் பயங்கரமான மூச்சுச் சத்தத்தை அவர்கள் கேட்பார்கள். அது கோபத்தால் வெடித்துச் சிதறிவிடும் போலிருக்கும்.’) (67:7-8). அதாவது, அல்லாஹ்வை நிராகரித்தவர்கள் மீதுள்ள கடும் கோபத்தினால் அதன் ஒரு பகுதி மற்றொரு பகுதியிலிருந்து பிரியும் நிலைக்கு ஆளாகும்.\n\r\n\n\r\nஇமாம் அபூ ஜஃபர் பின் ஜரீர் (ரஹ்) அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: “ஒரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அது சுருங்கி விரியும். அர்-ரஹ்மான் அதனிடம் ‘உனக்கு என்ன நேர்ந்தது?’ என்று கேட்பான். அதற்கு அது ‘அவன் என்னிடமிருந்து பாதுகாப்புத் தேடுகிறான்’ என்று கூறும். அப்போது அல்லாஹ், ‘என் அடியானை விட்டுவிடுங்கள்’ என்று கூறுவான். மற்றொரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அவன் ‘இறைவா, உன்னிடமிருந்து இதை நான் ஒருபோதும் எதிர்பார்க்கவில்லை’ என்பான். அல்லாஹ் ‘நீ என்ன எதிர்பார்த்தாய்?’ என்று கேட்பான். அதற்கு அவன் ‘உனது கருணை என்னையும் உள்ளடக்கும் அளவுக்குப் பறந்து விரிந்ததாக இருக்கும் என்று எதிர்பார்த்தேன்’ என்பான். அல்லாஹ் ‘என் அடியானை விட்டுவிடுங்கள்’ என்பான். இன்னொரு மனிதன் நரகத்தை நோக்கி இழுத்துச் செல்லப்படுவான். அப்போது பார்லியைப் பார்த்து ஒரு கழுதை கத்துவதைப் போல நரகம் அவனிடம் கத்தும். பிறகு அது ஒரு முனகலை வெளிப்படுத்தும், அது அனைவரையும் அச்சத்தில் ஆழ்த்தும்.” இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் ஆகும்.\n\r\n\n\r\n﴾سَمِعُواْ لَهَا تَغَيُّظاً وَزَفِيراً﴿\n\r\n(அதன் சீற்றத்தையும் முழக்கத்தையும் அவர்கள் கேட்பார்கள்.) அப்துர்-ரஸ்ஸாக் (ரஹ்) அவர்கள் உபைத் பின் உமைர் (ரஹ்) அவர்கள் கூறியதாகப் பதிவு செய்துள்ளார்கள்: “நரகம் ஒரு முனகலை எழுப்பும். அதனால் அல்லாஹ்வுக்கு நெருக்கமான எந்த வானவரும் சரி, அனுப்பப்பட்ட எந்த நபியும் சரி, உடல் நடுங்கி முகங்குப்புற விழாமல் இருக்க மாட்டார்கள். இப்ராஹீம் (அலை) அவர்கள் கூட முழங்காலிட்டு வீழ்ந்து, ‘இறைவா, இன்றைய தினம் எனக்காகத் தவிர வேறு யாருக்காகவும் நான் உன்னிடம் இரட்சிப்பைக் கேட்கவில்லை’ என்று கூறுவார்கள்.”\n\r\n\n\r\n﴾وَإِذَا أُلْقُواْ مِنْهَا مَكَاناً ضَيِّقاً مُّقَرَّنِينَ﴿\n\r\n(‘மேலும் அவர்கள் சங்கிலிகளால் பிணைக்கப்பட்டவர்களாக அதன் ஒரு குறுகிய இடத்தில் வீசப்படும்போது,’) இப்னு ஜரீர் (ரஹ்) அவர்கள் அபூ உபைதா அவர்கள் வழியாக அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாக அறிவிக்கிறார்கள்: “அது ஒரு ஈட்டியின் முனை போன்ற குறுகலான இடமாகும்.”\n\r\n\n\r\n﴾مُقَرَّنِينَ﴿\n\r\n(‘சங்கிலிகளால் பிணைக்கப்பட்டவர்களாக,’) அபூ ஸாலிஹ் (ரஹ்) கூறினார்கள்: “இதன் பொருள், அவர்களின் தோள்களோடு சேர்த்துப் பிணைக்கப்பட்டு என்பதாகும்.”\n\r\n\n\r\n﴾دَعَوْاْ هُنَالِكَ ثُبُوراً﴿\n\r\n(‘அவர்கள் அங்கே அழிவைக் கோருவார்கள்.’) அதாவது, அவர்கள் துக்கம், மனவருத்தம் மற்றும் வேதனையில் பேரழிவைக் கூவி அழைப்பார்கள்.\n\r\n\n\r\n﴾لاَّ تَدْعُواْ الْيَوْمَ ثُبُوراً وَاحِداً وَادْعُواْ ثُبُوراً كَثِيراً﴿\n\r\n(‘இன்று ஒரு முறை மட்டும் அழிவைக் கோராதீர்கள்; மாறாகப் பலமுறை அழிவைக் கோருங்கள்.’)"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=16\" class=\"link\">25:16</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:16 ஐ பார்க்கவும்"},"16":{"html":"<strong>நரகம் சிறந்ததா அல்லது சொர்க்கமா?</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் கூறுகிறான்: \"முஹம்மதே (ஸல்)! அழிவுக்குரியவர்கள் நரகத்தில் முகங்குப்புற இழுத்துச் செல்லப்படுவார்கள் என நாம் உங்களுக்கு விவரித்த அந்த நிலை, அதாவது நரகம் அவர்களைக் கடுகடுப்பான முகத்தோடும், வெறுப்புடனும், பெரும் இரைச்சலுடனும் வரவேற்கும் நிலை சிறந்ததா? அங்கு அவர்கள் அதன் மிக நெருக்கமான இடங்களில், கைகள் தோள்களுடன் சேர்த்துத் தளையிடப்பட்ட நிலையில் வீசப்படுவார்கள். அவர்களால் நகரவோ, உதவிக்கு அழைக்கவோ அல்லது அந்த இக்கட்டான நிலையிலிருந்து தப்பிக்கவோ இயலாது. இத்தகைய நிலை சிறந்ததா? அல்லது தனது அடியார்களில் இறையச்சமுடையவர்களுக்கு அல்லாஹ் வாக்களித்திருக்கும் நிலையான சொர்க்கம் சிறந்ததா? அவர்கள் இவ்வுலகில் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடந்ததற்காக, ஒரு வெகுமதியாகவும் இறுதிச் சேருமிடமாகவும் அதனை அவன் அவர்களுக்காகத் தயார் செய்துள்ளான்.\" <span class=\"quran-arabic-font text-success\">﴾كَانَتْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جَزَآءً</span> <span class=\"quran-arabic-font text-success\">وَمَصِيراً﴿</span> <span class=\"quran-arabic-font text-success\">﴾لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَشَآءُونَ﴿</span><br />\r\n<br />\r\n(அங்கு அவர்கள் விரும்பும் அனைத்து இன்பங்களும் அவர்களுக்கு உண்டு.) அதாவது உணவுகள், பானங்கள், ஆடைகள், தங்குமிடங்கள், வாகனங்கள் மற்றும் அழகான காட்சிகள் என எந்தக் கண்ணும் பார்த்திராத, எந்தக் காதும் கேட்டிராத, எந்த மனித உள்ளமும் கற்பனை செய்திராத இன்பங்கள் அங்கு உண்டு. <span class=\"quran-arabic-font text-success\">﴾خَالِدِينَ﴿</span> அவர்கள் அதில் என்றென்றும் தங்குவார்கள்; அது ஒருபோதும் நீங்காது அல்லது முடிவுக்கு வராது; அவர்கள் அதை விட்டு வெளியேறவும் மாட்டார்கள். இது அல்லாஹ் தான் அருள் புரிந்தவர்களுக்கும், கருணை காட்டியவர்களுக்கும் அளித்த வாக்குறுதியாகும். அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾كَانَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">وَعْداً</span> <span class=\"quran-arabic-font text-success\">مَّسْئُولاً﴿</span><br />\r\n<br />\r\n(இது உமது இறைவனின் மீது பொறுப்பான, நிறைவேற்றப்பட வேண்டிய வாக்குறுதியாகும்.) அதாவது, இது நிச்சயமாக நிகழ்ந்தேறும். அபூ ஜஃபர் இப்னு ஜரீர் அவர்கள் சில அரபு மொழி அறிஞர்களிடமிருந்து அறிவிக்கிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَعْداً</span> <span class=\"quran-arabic-font text-success\">مَّسْئُولاً﴿</span> (வஅதன் மஸ்ஊலா) என்பதற்கு 'உறுதியாக நிறைவேற்றப்பட வேண்டிய ஒரு வாக்குறுதி' என்று பொருள். முஹம்மத் பின் கஅபு அல்-குரளீ (ரஹ்) அவர்கள், \"மலக்குகள் அவர்களுக்காக இதனை (இறைவனிடம்) வேண்டுகின்றனர்\" என்று கூறிவிட்டு, \"எங்கள் இறைவா! நீ அவர்களுக்கு வாக்களித்த நிலையான சொர்க்கச் சோலைகளில் அவர்களையும்... நுழையச் செய்வாயாக!\" (<a href=\"qurandisp.php?sura=40&ayah=8\" class=\"link\">40:8</a>) என்ற வசனத்தை ஓதிக்காட்டினார்கள். இந்தச் சூறாவில் அல்லாஹ் நரகத்தைப் பற்றித் தெரிவித்துவிட்டு, பிறகு சொர்க்கவாசிகளின் நிலையைப் பற்றிக் குறிப்பிடுகிறான். இது ஸூரத்து அஸ்-ஸாஃப்பாத்தில் அல்லாஹ் சொர்க்கவாசிகளின் உயரிய நிலையையும், அதன் அழகையும், மகிழ்ச்சியையும் விவரித்துவிட்டு, பிறகு இவ்வாறு கூறுவதைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾أَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">نُّزُلاً</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">شَجَرَةُ</span> <span class=\"quran-arabic-font text-success\">الزَّقُّومِ</span> - <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَاهَا</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">لِلظَّالِمِينَ</span> - <span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">شَجَرَةٌ</span> <span class=\"quran-arabic-font text-success\">تَخْرُجُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَصْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span> - <span class=\"quran-arabic-font text-success\">طَلْعُهَا</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">رُءُوسُ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينِ</span> - <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَآكِلُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَمَالِئُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">الْبُطُونَ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">لَشَوْباً</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٍ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">مَرْجِعَهُمْ</span> <span class=\"quran-arabic-font text-success\">لإِلَى</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمِ</span> - <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَلْفَوْاْ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَهُمْ</span> <span class=\"quran-arabic-font text-success\">ضَآلِّينَ</span> - <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ءَاثَارِهِمْ</span> <span class=\"quran-arabic-font text-success\">يُهْرَعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உபசரிப்பில் இது சிறந்ததா அல்லது ஸக்கூம் மரமா? நிச்சயமாக நாம் அதனை அநியாயக்காரர்களுக்கு ஒரு சோதனையாக ஆக்கினோம். மெய்யாகவே அது நரகத்தின் அடிப்பகுதியிலிருந்து முளைக்கும் ஒரு மரமாகும். அதன் குலைகள் ஷைத்தான்களின் தலைகளைப் போன்று இருக்கும். நிச்சயமாக அவர்கள் அதிலிருந்து உண்டு, அதைக் கொண்டே தங்களின் வயிறுகளை நிரப்புவார்கள். அதன் பிறகு, அவர்களுக்குக் கொதிக்கும் நீர் கலந்த பானம் அளிக்கப்படும். பின்னர் அவர்கள் நிச்சயமாக நரக நெருப்பிற்கே திரும்புவார்கள். நிச்சயமாக அவர்கள் தங்கள் தந்தையர்களை வழிகேட்டிலேயே கண்டார்கள். ஆகவே அவர்கள் தங்களின் முன்னோர்களின் அடிச்சுவடுகளைப் பின்பற்றி விரைகின்றனர்.) (<a href=\"qurandisp.php?sura=37&ayah=62\" class=\"link\">37:62</a>-70)<br />\r\n<br />","text":"நரகம் சிறந்ததா அல்லது சொர்க்கமா?\n\r\n\n\r\nஇங்கே அல்லாஹ் கூறுகிறான்: \"முஹம்மதே (ஸல்)! அழிவுக்குரியவர்கள் நரகத்தில் முகங்குப்புற இழுத்துச் செல்லப்படுவார்கள் என நாம் உங்களுக்கு விவரித்த அந்த நிலை, அதாவது நரகம் அவர்களைக் கடுகடுப்பான முகத்தோடும், வெறுப்புடனும், பெரும் இரைச்சலுடனும் வரவேற்கும் நிலை சிறந்ததா? அங்கு அவர்கள் அதன் மிக நெருக்கமான இடங்களில், கைகள் தோள்களுடன் சேர்த்துத் தளையிடப்பட்ட நிலையில் வீசப்படுவார்கள். அவர்களால் நகரவோ, உதவிக்கு அழைக்கவோ அல்லது அந்த இக்கட்டான நிலையிலிருந்து தப்பிக்கவோ இயலாது. இத்தகைய நிலை சிறந்ததா? அல்லது தனது அடியார்களில் இறையச்சமுடையவர்களுக்கு அல்லாஹ் வாக்களித்திருக்கும் நிலையான சொர்க்கம் சிறந்ததா? அவர்கள் இவ்வுலகில் அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடந்ததற்காக, ஒரு வெகுமதியாகவும் இறுதிச் சேருமிடமாகவும் அதனை அவன் அவர்களுக்காகத் தயார் செய்துள்ளான்.\" ﴾كَانَتْ لَهُمْ جَزَآءً وَمَصِيراً﴿ ﴾لَّهُمْ فِيهَا مَا يَشَآءُونَ﴿\n\r\n\n\r\n(அங்கு அவர்கள் விரும்பும் அனைத்து இன்பங்களும் அவர்களுக்கு உண்டு.) அதாவது உணவுகள், பானங்கள், ஆடைகள், தங்குமிடங்கள், வாகனங்கள் மற்றும் அழகான காட்சிகள் என எந்தக் கண்ணும் பார்த்திராத, எந்தக் காதும் கேட்டிராத, எந்த மனித உள்ளமும் கற்பனை செய்திராத இன்பங்கள் அங்கு உண்டு. ﴾خَالِدِينَ﴿ அவர்கள் அதில் என்றென்றும் தங்குவார்கள்; அது ஒருபோதும் நீங்காது அல்லது முடிவுக்கு வராது; அவர்கள் அதை விட்டு வெளியேறவும் மாட்டார்கள். இது அல்லாஹ் தான் அருள் புரிந்தவர்களுக்கும், கருணை காட்டியவர்களுக்கும் அளித்த வாக்குறுதியாகும். அவன் கூறுகிறான்: ﴾كَانَ عَلَى رَبِّكَ وَعْداً مَّسْئُولاً﴿\n\r\n\n\r\n(இது உமது இறைவனின் மீது பொறுப்பான, நிறைவேற்றப்பட வேண்டிய வாக்குறுதியாகும்.) அதாவது, இது நிச்சயமாக நிகழ்ந்தேறும். அபூ ஜஃபர் இப்னு ஜரீர் அவர்கள் சில அரபு மொழி அறிஞர்களிடமிருந்து அறிவிக்கிறார்கள்: ﴾وَعْداً مَّسْئُولاً﴿ (வஅதன் மஸ்ஊலா) என்பதற்கு 'உறுதியாக நிறைவேற்றப்பட வேண்டிய ஒரு வாக்குறுதி' என்று பொருள். முஹம்மத் பின் கஅபு அல்-குரளீ (ரஹ்) அவர்கள், \"மலக்குகள் அவர்களுக்காக இதனை (இறைவனிடம்) வேண்டுகின்றனர்\" என்று கூறிவிட்டு, \"எங்கள் இறைவா! நீ அவர்களுக்கு வாக்களித்த நிலையான சொர்க்கச் சோலைகளில் அவர்களையும்... நுழையச் செய்வாயாக!\" (40:8) என்ற வசனத்தை ஓதிக்காட்டினார்கள். இந்தச் சூறாவில் அல்லாஹ் நரகத்தைப் பற்றித் தெரிவித்துவிட்டு, பிறகு சொர்க்கவாசிகளின் நிலையைப் பற்றிக் குறிப்பிடுகிறான். இது ஸூரத்து அஸ்-ஸாஃப்பாத்தில் அல்லாஹ் சொர்க்கவாசிகளின் உயரிய நிலையையும், அதன் அழகையும், மகிழ்ச்சியையும் விவரித்துவிட்டு, பிறகு இவ்வாறு கூறுவதைப் போன்றதாகும்: ﴾أَذَلِكَ خَيْرٌ نُّزُلاً أَمْ شَجَرَةُ الزَّقُّومِ - إِنَّا جَعَلْنَاهَا فِتْنَةً لِلظَّالِمِينَ - إِنَّهَا شَجَرَةٌ تَخْرُجُ فِى أَصْلِ الْجَحِيمِ - طَلْعُهَا كَأَنَّهُ رُءُوسُ الشَّيَاطِينِ - فَإِنَّهُمْ لَآكِلُونَ مِنْهَا فَمَالِئُونَ مِنْهَا الْبُطُونَ - ثُمَّ إِنَّ لَهُمْ عَلَيْهَا لَشَوْباً مِنْ حَمِيمٍ - ثُمَّ إِنَّ مَرْجِعَهُمْ لإِلَى الْجَحِيمِ - إِنَّهُمْ أَلْفَوْاْ ءَابَآءَهُمْ ضَآلِّينَ - فَهُمْ عَلَى ءَاثَارِهِمْ يُهْرَعُونَ ﴿\n\r\n\n\r\n(உபசரிப்பில் இது சிறந்ததா அல்லது ஸக்கூம் மரமா? நிச்சயமாக நாம் அதனை அநியாயக்காரர்களுக்கு ஒரு சோதனையாக ஆக்கினோம். மெய்யாகவே அது நரகத்தின் அடிப்பகுதியிலிருந்து முளைக்கும் ஒரு மரமாகும். அதன் குலைகள் ஷைத்தான்களின் தலைகளைப் போன்று இருக்கும். நிச்சயமாக அவர்கள் அதிலிருந்து உண்டு, அதைக் கொண்டே தங்களின் வயிறுகளை நிரப்புவார்கள். அதன் பிறகு, அவர்களுக்குக் கொதிக்கும் நீர் கலந்த பானம் அளிக்கப்படும். பின்னர் அவர்கள் நிச்சயமாக நரக நெருப்பிற்கே திரும்புவார்கள். நிச்சயமாக அவர்கள் தங்கள் தந்தையர்களை வழிகேட்டிலேயே கண்டார்கள். ஆகவே அவர்கள் தங்களின் முன்னோர்களின் அடிச்சுவடுகளைப் பின்பற்றி விரைகின்றனர்.) (37:62-70)"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=19\" class=\"link\">25:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:19 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=19\" class=\"link\">25:19</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:19 ஐ பார்க்கவும்"},"19":{"html":"<strong>மறுமை நாளில் இணைவைப்பவர்களின் தெய்வங்கள் அவர்களைக் கைவிடுவார்கள்</strong><br />\r\n<br />\r\nமறுமை நாளில் என்ன நிகழும் என்பதைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அன்று, அல்லாஹ்வையன்றி இணைவைப்பாளர்கள் எவர்களை வணங்கிக் கொண்டிருந்தார்களோ - வானவர்கள் மற்றும் பிறர் - அவர்கள் இணைவைப்பவர்களைக் கடிந்து கொள்வார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَحْشُرُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n(அவன் அவர்களையும், அல்லாஹ்வையன்றி அவர்கள் எவற்றை வணங்கினார்களோ அவற்றையும் ஒன்று திரட்டும் நாளில்.) முஜாஹித் (ரஹ்) கூறினார்கள்: \"இதன் பொருள் ஈஸா (அலை), உஸைர் (அலை) மற்றும் வானவர்கள் என்பதாகும்.\"<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَءَنتُمْ</span> <span class=\"quran-arabic-font text-success\">أَضْلَلْتُمْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِى</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">ضَلُّواْ</span> <span class=\"quran-arabic-font text-success\">السَّبِيلَ﴿</span><br />\r\n(அவன் கேட்பான்: \"என்னுடைய இந்த அடியார்களை வழிகெடுத்தவர்கள் நீங்கள்தாமா? அல்லது அவர்களே வழி தவறினார்களா?\") வணங்கப்பட்டவர்களிடம் அல்லாஹ் கேட்பான்: \"என்னைத் தவிர்த்து உங்களை வணங்குமாறு இவர்களை நீங்கள்தான் அழைத்தீர்களா அல்லது எவ்வித அழைப்புமின்றி அவர்கள் தாங்களாகவே உங்களை வணங்கினார்களா?\" இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">عِيسَى</span> <span class=\"quran-arabic-font text-success\">ابْنَ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">أَءَنتَ</span> <span class=\"quran-arabic-font text-success\">قُلتَ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">اتَّخِذُونِى</span> <span class=\"quran-arabic-font text-success\">وَأُمِّىَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَيْنِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">أَقُولَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَيْسَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">بِحَقٍّ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُ</span> <span class=\"quran-arabic-font text-success\">قُلْتُهُ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">عَلِمْتَهُ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">نَفْسِى</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">نَفْسِكَ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">عَلَّـمُ</span> <span class=\"quran-arabic-font text-success\">الْغُيُوبِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قُلْتُ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَمَرْتَنِى</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n(மேலும் அல்லாஹ், \"மர்யமின் மகன் ஈஸாவே (அலை)! அல்லாஹ்வைத் தவிர்த்து என்னையும் என் தாயாரையும் இரு கடவுள்களாக ஆக்கிக்கொள்ளுங்கள் என்று மக்களிடம் நீர் கூறினீரா?\" எனக் கேட்கும்போது, அவர் கூறுவார்: \"நீ தூய்மையானவன்! எனக்கு உரிமையில்லாத ஒன்றைச் சொல்வதற்கு எனக்குத் தகுதியில்லை. நான் அவ்வாறு கூறியிருந்தால், நிச்சயமாக நீ அதனை அறிந்திருப்பாய். என் உள்ளத்தில் இருப்பதை நீ அறிவாய்; ஆனால் உன்னிடத்தில் இருப்பதை நான் அறியமாட்டேன். நிச்சயமாக நீயே மறைவானவற்றை எல்லாம் நன்கறிந்தவன். நீ எனக்குக் கட்டளையிட்டதைத் தவிர வேறெதையும் நான் அவர்களிடம் கூறவில்லை.\") (<a href=\"qurandisp.php?sura=5&ayah=116\" class=\"link\">5:116</a>-117) மறுமை நாளில் அந்தத் தெய்வங்கள் அளிக்கப்போகும் பதிலைப் பற்றி அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">يَنبَغِى</span> <span class=\"quran-arabic-font text-success\">لَنَآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّتَّخِذَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآءَ﴿</span><br />\r\n(அவர்கள் கூறுவார்கள்: \"நீ தூய்மையானவன்! உன்னையன்றி வேறெவரையும் பாதுகாவலர்களாக (அவ்லியாக்களாக) நாங்கள் ஆக்கிக்கொள்வது (நத்தகித) எங்களுக்குத் தகுமானதல்ல...\") பெரும்பான்மையான அறிஞர்கள் 'நத்தகித' <span class=\"quran-arabic-font text-success\">﴾نَّتَّخِذَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِكَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآءَ﴿</span> என்ற சொல்லின் 'நூன்' எழுத்திற்கு ஃபத்ஹா (Fathah) வைத்து ஓதுகின்றனர்.<br />\r\n<br />\r\n(\"...உன்னையன்றி வேறெவரையும் பாதுகாவலர்களாக நாங்கள் ஆக்கிக்கொள்வது எங்களுக்குத் தகுமானதல்ல,\") அதாவது, \"படைக்கப்பட்ட எவருக்கும் - எங்களுக்கோ அல்லது அவர்களுக்கோ - உன்னைத் தவிர வேறு யாரையும் வணங்குவது தகாது. நாங்கள் அவர்களை அதற்கு அழைக்கவில்லை. மாறாக, எங்கள் தூண்டுதலோ அல்லது சம்மதமோ இன்றி அவர்கள் தாங்களாகவே அவ்வாறு செய்தார்கள். அவர்களிலிருந்தும் அவர்களின் வணக்கத்திலிருந்தும் நாங்கள் விலகிக் கொள்கிறோம்.\" இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَحْشُرُهُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعاً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">لِلْمَلَـئِكَةِ</span> <span class=\"quran-arabic-font text-success\">أَهَـؤُلاَءِ</span> <span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُونَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سُبْحَـنَكَ﴿</span><br />\r\n(அவன் அவர்கள் அனைவரையும் ஒன்று திரட்டும் நாளில், வானவர்களிடம்: \"உங்களைத்தான் இவர்கள் வணங்கிக் கொண்டிருந்தார்களா?\" என்று கேட்பான். அதற்கு அவர்கள் (வானவர்கள்): \"நீ தூய்மையானவன்!\" என்று கூறுவார்கள்.) (<a href=\"qurandisp.php?sura=34&ayah=40\" class=\"link\">34:40</a>-41) இதர அறிஞர்கள் இச்சொல்லின் 'நூன்' எழுத்திற்கு 'தம்மா' (Dammah) வைத்து 'நுத்தகித' என்று ஓதி, இத்தொடருக்கு இவ்வாறு விளக்கம் அளிக்கின்றனர்: \"உன்னையன்றி (எங்களை) பாதுகாவலர்களாகவோ உதவியாளர்களாகவோ (அவ்லியாக்களாகவோ) ஆக்கிக்கொள்ளப்படுவது எங்களுக்குத் தகுதியல்ல.\" அதாவது, \"யாரும் எங்களை வணங்குவது முறையல்ல, ஏனெனில் நாங்களும் உனது அடியார்களே; உனது தேவையுடையவர்களே.\" இந்த விளக்கமும் முந்தைய விளக்கத்திற்கு நெருக்கமானதே.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَـكِن</span> <span class=\"quran-arabic-font text-success\">مَّتَّعْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَءَابَآءَهُمْ﴿</span><br />\r\n(ஆனால், நீ அவர்களுக்கும் அவர்களின் தந்தைமார்களுக்கும் சுகபோகங்களை அளித்தாய்.) இதன் பொருள்: \"நீண்ட காலம் சுகபோகங்களில் திளைத்ததால் அவர்கள் உனது நினைவூட்டலை (திக்ரு) மறந்துவிட்டார்கள். அதாவது, உனக்கு எவ்வித இணையும் துணையுமின்றி உன்னை மட்டுமே வணங்குமாறு தூதர்கள் வழியாக அனுப்பப்பட்ட போதனைகளை அவர்கள் மறந்துவிட்டனர்.\"<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">بُوراً﴿</span><br />\r\n(மேலும், அவர்கள் அழிந்துபோகும் மக்களாகி விட்டனர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள், அவர்கள் அழிக்கப்பட்டார்கள் என்பதாகும்.\" ஹஸன் அல்-பஸரீ மற்றும் மாலிக் ஆகியோர் அஸ்-ஸுஹ்ரீயிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்களிடம் எவ்வித நன்மையும் இருக்கவில்லை.\" மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَقَدْ</span> <span class=\"quran-arabic-font text-success\">كَذَّبُوكُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَقُولُونَ﴿</span><br />\r\n(இவ்வாறு நீங்கள் கூறுவதை அவர்கள் பொய்யாக்குவார்கள்.) அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கிக் கொண்டிருந்தவர்கள், தங்களை உங்களின் பாதுகாவலர்கள் என்றும் அல்லாஹ்விடம் நெருக்கி வைப்பவர்கள் என்றும் நீங்கள் கூறியதை பொய்யென நிரூபிப்பார்கள்.\" இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">مِمَّن</span> <span class=\"quran-arabic-font text-success\">يَدْعُو</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَجِيبُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الْقِيَـمَةِ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">دُعَآئِهِمْ</span> <span class=\"quran-arabic-font text-success\">غَـفِلُونَ</span> - <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">حُشِرَ</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْدَآءً</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِعِبَادَتِهِمْ</span> <span class=\"quran-arabic-font text-success\">كَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அல்லாஹ்வையன்றி, மறுமை நாள் வரை தங்களுக்குப் பதிலளிக்காதவர்களை அழைப்பவரை விட வழிகெட்டவர் யார்? அவர்களோ இவர்களின் அழைப்பைப் பற்றி அறியாதவர்களாக இருக்கின்றனர். மனிதர்கள் ஒன்று திரட்டப்படும் போது, அவர்கள் இவர்களுக்கு விரோதிகளாக மாறிவிடுவார்கள்; அவர்களின் வணக்கத்தையும் நிராகரிப்பார்கள்.) (<a href=\"qurandisp.php?sura=46&ayah=5\" class=\"link\">46:5</a>-6)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْتَطِيعُونَ</span> <span class=\"quran-arabic-font text-success\">صَرْفاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَصْراً﴿</span><br />\r\n(அப்போது நீங்கள் (வேதனையைத்) தடுத்துக் கொள்ளவோ அல்லது உதவியைப் பெறவோ முடியாது.) அதாவது, அவர்களால் தங்களுக்கு வரும் வேதனையைத் தடுக்கவும் முடியாது, தங்களுக்குத் தாங்களே உதவிக் கொள்ளவும் முடியாது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَن</span> <span class=\"quran-arabic-font text-success\">يَظْلِم</span> <span class=\"quran-arabic-font text-success\">مِّنكُمْ﴿</span><br />\r\n(உங்களில் எவர் அநீதி இழைக்கிறாரோ,) அதாவது, அல்லாஹ்வுக்கு இணை வைக்கிறாரோ,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾نُذِقْهُ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">كَبِيراً﴿</span><br />\r\n(அவரை ஒரு பெரிய வேதனையைச் சுவைக்கச் செய்வோம்.)<br />\r\n<br />","text":"மறுமை நாளில் இணைவைப்பவர்களின் தெய்வங்கள் அவர்களைக் கைவிடுவார்கள்\n\r\n\n\r\nமறுமை நாளில் என்ன நிகழும் என்பதைப் பற்றி அல்லாஹ் நமக்குக் கூறுகிறான். அன்று, அல்லாஹ்வையன்றி இணைவைப்பாளர்கள் எவர்களை வணங்கிக் கொண்டிருந்தார்களோ - வானவர்கள் மற்றும் பிறர் - அவர்கள் இணைவைப்பவர்களைக் கடிந்து கொள்வார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَيَوْمَ يَحْشُرُهُمْ وَمَا يَعْبُدُونَ مِن دُونِ اللَّهِ﴿\n\r\n(அவன் அவர்களையும், அல்லாஹ்வையன்றி அவர்கள் எவற்றை வணங்கினார்களோ அவற்றையும் ஒன்று திரட்டும் நாளில்.) முஜாஹித் (ரஹ்) கூறினார்கள்: \"இதன் பொருள் ஈஸா (அலை), உஸைர் (அலை) மற்றும் வானவர்கள் என்பதாகும்.\"\n\r\n﴾فَيَقُولُ أَءَنتُمْ أَضْلَلْتُمْ عِبَادِى هَـؤُلاَءِ أَمْ هُمْ ضَلُّواْ السَّبِيلَ﴿\n\r\n(அவன் கேட்பான்: \"என்னுடைய இந்த அடியார்களை வழிகெடுத்தவர்கள் நீங்கள்தாமா? அல்லது அவர்களே வழி தவறினார்களா?\") வணங்கப்பட்டவர்களிடம் அல்லாஹ் கேட்பான்: \"என்னைத் தவிர்த்து உங்களை வணங்குமாறு இவர்களை நீங்கள்தான் அழைத்தீர்களா அல்லது எவ்வித அழைப்புமின்றி அவர்கள் தாங்களாகவே உங்களை வணங்கினார்களா?\" இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n﴾وَإِذْ قَالَ اللَّهُ يَا عِيسَى ابْنَ مَرْيَمَ أَءَنتَ قُلتَ لِلنَّاسِ اتَّخِذُونِى وَأُمِّىَ إِلَـهَيْنِ مِن دُونِ اللَّهِ قَالَ سُبْحَـنَكَ مَا يَكُونُ لِى أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ إِن كُنتُ قُلْتُهُ فَقَدْ عَلِمْتَهُ تَعْلَمُ مَا فِى نَفْسِى وَلاَ أَعْلَمُ مَا فِى نَفْسِكَ إِنَّكَ أَنتَ عَلَّـمُ الْغُيُوبِ مَا قُلْتُ لَهُمْ إِلاَّ مَآ أَمَرْتَنِى بِهِ﴿\n\r\n(மேலும் அல்லாஹ், \"மர்யமின் மகன் ஈஸாவே (அலை)! அல்லாஹ்வைத் தவிர்த்து என்னையும் என் தாயாரையும் இரு கடவுள்களாக ஆக்கிக்கொள்ளுங்கள் என்று மக்களிடம் நீர் கூறினீரா?\" எனக் கேட்கும்போது, அவர் கூறுவார்: \"நீ தூய்மையானவன்! எனக்கு உரிமையில்லாத ஒன்றைச் சொல்வதற்கு எனக்குத் தகுதியில்லை. நான் அவ்வாறு கூறியிருந்தால், நிச்சயமாக நீ அதனை அறிந்திருப்பாய். என் உள்ளத்தில் இருப்பதை நீ அறிவாய்; ஆனால் உன்னிடத்தில் இருப்பதை நான் அறியமாட்டேன். நிச்சயமாக நீயே மறைவானவற்றை எல்லாம் நன்கறிந்தவன். நீ எனக்குக் கட்டளையிட்டதைத் தவிர வேறெதையும் நான் அவர்களிடம் கூறவில்லை.\") (5:116-117) மறுமை நாளில் அந்தத் தெய்வங்கள் அளிக்கப்போகும் பதிலைப் பற்றி அல்லாஹ் கூறுகிறான்:\n\r\n﴾قَالُواْ سُبْحَـنَكَ مَا كَانَ يَنبَغِى لَنَآ أَن نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ﴿\n\r\n(அவர்கள் கூறுவார்கள்: \"நீ தூய்மையானவன்! உன்னையன்றி வேறெவரையும் பாதுகாவலர்களாக (அவ்லியாக்களாக) நாங்கள் ஆக்கிக்கொள்வது (நத்தகித) எங்களுக்குத் தகுமானதல்ல...\") பெரும்பான்மையான அறிஞர்கள் 'நத்தகித' ﴾نَّتَّخِذَ مِن دُونِكَ مِنْ أَوْلِيَآءَ﴿ என்ற சொல்லின் 'நூன்' எழுத்திற்கு ஃபத்ஹா (Fathah) வைத்து ஓதுகின்றனர்.\n\r\n\n\r\n(\"...உன்னையன்றி வேறெவரையும் பாதுகாவலர்களாக நாங்கள் ஆக்கிக்கொள்வது எங்களுக்குத் தகுமானதல்ல,\") அதாவது, \"படைக்கப்பட்ட எவருக்கும் - எங்களுக்கோ அல்லது அவர்களுக்கோ - உன்னைத் தவிர வேறு யாரையும் வணங்குவது தகாது. நாங்கள் அவர்களை அதற்கு அழைக்கவில்லை. மாறாக, எங்கள் தூண்டுதலோ அல்லது சம்மதமோ இன்றி அவர்கள் தாங்களாகவே அவ்வாறு செய்தார்கள். அவர்களிலிருந்தும் அவர்களின் வணக்கத்திலிருந்தும் நாங்கள் விலகிக் கொள்கிறோம்.\" இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾وَيَوْمَ يَحْشُرُهُمْ جَمِيعاً ثُمَّ يَقُولُ لِلْمَلَـئِكَةِ أَهَـؤُلاَءِ إِيَّاكُمْ كَانُواْ يَعْبُدُونَ قَالُواْ سُبْحَـنَكَ﴿\n\r\n(அவன் அவர்கள் அனைவரையும் ஒன்று திரட்டும் நாளில், வானவர்களிடம்: \"உங்களைத்தான் இவர்கள் வணங்கிக் கொண்டிருந்தார்களா?\" என்று கேட்பான். அதற்கு அவர்கள் (வானவர்கள்): \"நீ தூய்மையானவன்!\" என்று கூறுவார்கள்.) (34:40-41) இதர அறிஞர்கள் இச்சொல்லின் 'நூன்' எழுத்திற்கு 'தம்மா' (Dammah) வைத்து 'நுத்தகித' என்று ஓதி, இத்தொடருக்கு இவ்வாறு விளக்கம் அளிக்கின்றனர்: \"உன்னையன்றி (எங்களை) பாதுகாவலர்களாகவோ உதவியாளர்களாகவோ (அவ்லியாக்களாகவோ) ஆக்கிக்கொள்ளப்படுவது எங்களுக்குத் தகுதியல்ல.\" அதாவது, \"யாரும் எங்களை வணங்குவது முறையல்ல, ஏனெனில் நாங்களும் உனது அடியார்களே; உனது தேவையுடையவர்களே.\" இந்த விளக்கமும் முந்தைய விளக்கத்திற்கு நெருக்கமானதே.\n\r\n﴾وَلَـكِن مَّتَّعْتَهُمْ وَءَابَآءَهُمْ﴿\n\r\n(ஆனால், நீ அவர்களுக்கும் அவர்களின் தந்தைமார்களுக்கும் சுகபோகங்களை அளித்தாய்.) இதன் பொருள்: \"நீண்ட காலம் சுகபோகங்களில் திளைத்ததால் அவர்கள் உனது நினைவூட்டலை (திக்ரு) மறந்துவிட்டார்கள். அதாவது, உனக்கு எவ்வித இணையும் துணையுமின்றி உன்னை மட்டுமே வணங்குமாறு தூதர்கள் வழியாக அனுப்பப்பட்ட போதனைகளை அவர்கள் மறந்துவிட்டனர்.\"\n\r\n﴾وَكَانُواْ قَوْماً بُوراً﴿\n\r\n(மேலும், அவர்கள் அழிந்துபோகும் மக்களாகி விட்டனர்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"இதன் பொருள், அவர்கள் அழிக்கப்பட்டார்கள் என்பதாகும்.\" ஹஸன் அல்-பஸரீ மற்றும் மாலிக் ஆகியோர் அஸ்-ஸுஹ்ரீயிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்களிடம் எவ்வித நன்மையும் இருக்கவில்லை.\" மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n﴾فَقَدْ كَذَّبُوكُمْ بِمَا تَقُولُونَ﴿\n\r\n(இவ்வாறு நீங்கள் கூறுவதை அவர்கள் பொய்யாக்குவார்கள்.) அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கிக் கொண்டிருந்தவர்கள், தங்களை உங்களின் பாதுகாவலர்கள் என்றும் அல்லாஹ்விடம் நெருக்கி வைப்பவர்கள் என்றும் நீங்கள் கூறியதை பொய்யென நிரூபிப்பார்கள்.\" இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n﴾وَمَنْ أَضَلُّ مِمَّن يَدْعُو مِن دُونِ اللَّهِ مَن لاَّ يَسْتَجِيبُ لَهُ إِلَى يَوْمِ الْقِيَـمَةِ وَهُمْ عَن دُعَآئِهِمْ غَـفِلُونَ - وَإِذَا حُشِرَ النَّاسُ كَانُواْ لَهُمْ أَعْدَآءً وَكَانُواْ بِعِبَادَتِهِمْ كَـفِرِينَ ﴿\n\r\n(அல்லாஹ்வையன்றி, மறுமை நாள் வரை தங்களுக்குப் பதிலளிக்காதவர்களை அழைப்பவரை விட வழிகெட்டவர் யார்? அவர்களோ இவர்களின் அழைப்பைப் பற்றி அறியாதவர்களாக இருக்கின்றனர். மனிதர்கள் ஒன்று திரட்டப்படும் போது, அவர்கள் இவர்களுக்கு விரோதிகளாக மாறிவிடுவார்கள்; அவர்களின் வணக்கத்தையும் நிராகரிப்பார்கள்.) (46:5-6)\n\r\n﴾فَمَا تَسْتَطِيعُونَ صَرْفاً وَلاَ نَصْراً﴿\n\r\n(அப்போது நீங்கள் (வேதனையைத்) தடுத்துக் கொள்ளவோ அல்லது உதவியைப் பெறவோ முடியாது.) அதாவது, அவர்களால் தங்களுக்கு வரும் வேதனையைத் தடுக்கவும் முடியாது, தங்களுக்குத் தாங்களே உதவிக் கொள்ளவும் முடியாது.\n\r\n﴾وَمَن يَظْلِم مِّنكُمْ﴿\n\r\n(உங்களில் எவர் அநீதி இழைக்கிறாரோ,) அதாவது, அல்லாஹ்வுக்கு இணை வைக்கிறாரோ,\n\r\n﴾نُذِقْهُ عَذَاباً كَبِيراً﴿\n\r\n(அவரை ஒரு பெரிய வேதனையைச் சுவைக்கச் செய்வோம்.)"},"20":{"html":"<span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">تَسْتَطِيعُونَ</span> <span class=\"quran-arabic-font text-success\">صَرْفاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">نَصْراً</span><br />\r\n(தண்டனையைத்) தடுத்துக் கொள்ளவோ அல்லது உதவி பெறவோ உங்களால் முடியாது. அதாவது: அவர்களால் தங்களிடமிருந்து வேதனையைத் தடுத்துக் கொள்ள முடியாது, தங்களுக்குத் தாங்களே உதவிக் கொள்ளவும் முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَظْلِم</span> <span class=\"quran-arabic-font text-success\">مِّنكُمْ</span><br />\r\n(மேலும், உங்களில் எவர் அநீதி இழைக்கிறாரோ,) அதாவது அல்லாஹ்வுடைய வணக்கத்தில் பிறரை இணை வைப்பதன் மூலம் அநீதி இழைக்கிறாரோ,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نُذِقْهُ</span> <span class=\"quran-arabic-font text-success\">عَذَاباً</span> <span class=\"quran-arabic-font text-success\">كَبِيراً</span><br />\r\n(அவருக்கு நாம் பெரும் வேதனையைச் சுவைக்கச் செய்வோம்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">قَبْلَكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ</span> <span class=\"quran-arabic-font text-success\">وَيَمْشُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّسْوَاقِ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">أَتَصْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بَصِيراً</span><br />\r\n(20. (நபியே!) உமக்கு முன்னால் நாம் அனுப்பிய தூதர்கள் அனைவரும் உணவு உண்பவர்களாகவும், கடைவீதிகளில் நடமாடுபவர்களாகவுமே இருந்தனர். உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம்; நீங்கள் பொறுமை காப்பீர்களா? உமது இறைவன் அனைத்தையும் பார்ப்பவனாக இருக்கிறான்.)<br />\r\n<br />\r\n<strong>முந்தைய தூதர்கள் அனைவரும் மனிதர்களே</strong><br />\r\n<br />\r\nதான் அனுப்பிய முந்தைய தூதர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: அவர்கள் அனைவரும் ஊட்டச்சத்திற்காக உணவு உட்கொள்பவர்களாக இருந்தனர். அவர்கள் வியாபாரத்தில் ஈடுபடுவதற்காகவும் வாழ்வாதாரத்தைத் தேடுவதற்காகவும் கடைவீதிகளில் நடமாடினர். இது அவர்களது தூதுத்துவத் தகுதியை எந்தவிதத்திலும் பாதிக்காது; ஏனெனில் அல்லாஹ் அவர்களுக்கு நற்பண்புகளை வழங்கினான், நன்மையான சொற்களைப் பேசவும் நற்செயல்களைச் செய்யவும் அவர்களுக்கு அருள் புரிந்தான். மேலும் அவர்களுக்கு அற்புதங்களையும் தெளிவான அத்தாட்சிகளையும் வழங்கினான். சீரிய சிந்தனை உடைய எவரும் அவர்கள் அல்லாஹ்விடமிருந்து கொண்டு வந்த செய்திகள் உண்மையானவை என்பதை இதன் மூலம் உறுதிப்படுத்திக் கொள்ளலாம். இந்த வசனம் பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رِجَالاً</span> <span class=\"quran-arabic-font text-success\">نُّوحِى</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span><br />\r\n(நபியே! உமக்கு முன்னரும் ஊர்வாசிகளில் ஆண்களையே தவிர (வேறெவரையும்) நாம் தூதர்களாக அனுப்பவில்லை; அவர்களுக்கு நாம் வஹீ (இறைச்செய்தி) அறிவித்தோம்.) (<a href=\"qurandisp.php?sura=12&ayah=109\" class=\"link\">12:109</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">جَسَداً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَأْكُلُونَ</span> <span class=\"quran-arabic-font text-success\">الطَّعَامَ</span><br />\r\n(மேலும், உணவு உண்ணாத உடல்களாக நாம் அவர்களை ஆக்கவில்லை.) (<a href=\"qurandisp.php?sura=21&ayah=8\" class=\"link\">21:8</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">أَتَصْبِرُونَ</span><br />\r\n(மேலும், உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம்; நீங்கள் பொறுமையாக இருப்பீர்களா?) இதன் பொருள்: \"உங்களில் யார் கீழ்ப்படிகிறார்கள், யார் மாறுசெய்கிறார்கள் என்பதைப் பார்ப்பதற்காக உங்களில் சிலரை மற்றவர்கள் மூலம் நாம் சோதிக்கிறோம்.\"<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَتَصْبِرُونَ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بَصِيراً</span><br />\r\n(நீங்கள் பொறுமையாக இருப்பீர்களா? உமது இறைவன் அனைத்தையும் பார்ப்பவனாக இருக்கிறான்.) அதாவது, வஹீ (இறைச்செய்தி)யைப் பெறுவதற்குத் தகுதியானவர் யார் என்பதை அவன் நன்கு அறிவான். இதனை அல்லாஹ் வேறொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">يَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">رِسَالَتَهُ</span><br />\r\n(அல்லாஹ் தனது தூதுத்துவத்தை எங்கு ஒப்படைக்க வேண்டும் என்பதை மிக நன்கறிந்தவன்.) (<a href=\"qurandisp.php?sura=6&ayah=124\" class=\"link\">6:124</a>). தான் அனுப்பிய தூதின் மூலம் நேர்வழி பெறத் தகுதியானவர் யார், தகுதியற்றவர் யார் என்பதையும் அவன் நன்கு அறிவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْضَكُمْ</span> <span class=\"quran-arabic-font text-success\">لِبَعْضٍ</span> <span class=\"quran-arabic-font text-success\">فِتْنَةً</span> <span class=\"quran-arabic-font text-success\">أَتَصْبِرُونَ</span><br />\r\n(மேலும், உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம். நீங்கள் பொறுமையாக இருப்பீர்களா?) முஹம்மது பின் இஸ்ஹாக் அவர்கள் கூறினார்கள்: \"எனது தூதர்களை எவரும் எதிர்க்காத ஒரு உலகமாக இது இருக்க வேண்டும் என்று நான் நாடியிருந்தால், அவ்வாறே ஆக்கியிருக்க முடியும். ஆனால் அவர்கள் மூலம் எனது அடியார்களைச் சோதிக்க நான் விரும்பினேன்\" என்று அல்லாஹ் கூறுகிறான்.<br />\r\n<br />\r\nஸஹீஹ் முஸ்லிமில் இயாத் பின் ஹிமார் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالى</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">مُبْتَلِيكَ</span> <span class=\"quran-arabic-font text-success\">وَمُبْتَلٍ</span> <span class=\"quran-arabic-font text-success\">بِك</span>»<br />\r\n(அல்லாஹ் கூறுகிறான்: \"நிச்சயமாக நான் உன்னைச் சோதிப்பேன், உன்னைக் கொண்டு மற்றவர்களையும் சோதிப்பேன்.\")<br />\r\n<br />\r\nநபி (ஸல்) அவர்களுக்கு ஒரு நபியாகவும் மன்னராகவும் இருப்பதற்கும், அல்லது ஓர் அடியாராகவும் தூதராகவும் இருப்பதற்கும் இடையில் தேர்வு வழங்கப்பட்டது; அப்போது அவர்கள் ஓர் அடியாராகவும் தூதராகவும் இருப்பதையே தேர்ந்தெடுத்தார்கள் என்று ஸஹீஹில் பதிவாகியுள்ளது.<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />\r\n<br />","text":"فَمَا تَسْتَطِيعُونَ صَرْفاً وَلاَ نَصْراً\n\r\n(தண்டனையைத்) தடுத்துக் கொள்ளவோ அல்லது உதவி பெறவோ உங்களால் முடியாது. அதாவது: அவர்களால் தங்களிடமிருந்து வேதனையைத் தடுத்துக் கொள்ள முடியாது, தங்களுக்குத் தாங்களே உதவிக் கொள்ளவும் முடியாது.\n\r\n\n\r\nوَمَن يَظْلِم مِّنكُمْ\n\r\n(மேலும், உங்களில் எவர் அநீதி இழைக்கிறாரோ,) அதாவது அல்லாஹ்வுடைய வணக்கத்தில் பிறரை இணை வைப்பதன் மூலம் அநீதி இழைக்கிறாரோ,\n\r\n\n\r\nنُذِقْهُ عَذَاباً كَبِيراً\n\r\n(அவருக்கு நாம் பெரும் வேதனையைச் சுவைக்கச் செய்வோம்.)\n\r\n\n\r\nوَمَآ أَرْسَلْنَا قَبْلَكَ مِنَ الْمُرْسَلِينَ إِلاَّ إِنَّهُمْ لَيَأْكُلُونَ الطَّعَامَ وَيَمْشُونَ فِى الاٌّسْوَاقِ وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيراً\n\r\n(20. (நபியே!) உமக்கு முன்னால் நாம் அனுப்பிய தூதர்கள் அனைவரும் உணவு உண்பவர்களாகவும், கடைவீதிகளில் நடமாடுபவர்களாகவுமே இருந்தனர். உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம்; நீங்கள் பொறுமை காப்பீர்களா? உமது இறைவன் அனைத்தையும் பார்ப்பவனாக இருக்கிறான்.)\n\r\n\n\r\nமுந்தைய தூதர்கள் அனைவரும் மனிதர்களே\n\r\n\n\r\nதான் அனுப்பிய முந்தைய தூதர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: அவர்கள் அனைவரும் ஊட்டச்சத்திற்காக உணவு உட்கொள்பவர்களாக இருந்தனர். அவர்கள் வியாபாரத்தில் ஈடுபடுவதற்காகவும் வாழ்வாதாரத்தைத் தேடுவதற்காகவும் கடைவீதிகளில் நடமாடினர். இது அவர்களது தூதுத்துவத் தகுதியை எந்தவிதத்திலும் பாதிக்காது; ஏனெனில் அல்லாஹ் அவர்களுக்கு நற்பண்புகளை வழங்கினான், நன்மையான சொற்களைப் பேசவும் நற்செயல்களைச் செய்யவும் அவர்களுக்கு அருள் புரிந்தான். மேலும் அவர்களுக்கு அற்புதங்களையும் தெளிவான அத்தாட்சிகளையும் வழங்கினான். சீரிய சிந்தனை உடைய எவரும் அவர்கள் அல்லாஹ்விடமிருந்து கொண்டு வந்த செய்திகள் உண்மையானவை என்பதை இதன் மூலம் உறுதிப்படுத்திக் கொள்ளலாம். இந்த வசனம் பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nوَمَآ أَرْسَلْنَا مِن قَبْلِكَ إِلاَّ رِجَالاً نُّوحِى إِلَيْهِمْ مِّنْ أَهْلِ الْقُرَى\n\r\n(நபியே! உமக்கு முன்னரும் ஊர்வாசிகளில் ஆண்களையே தவிர (வேறெவரையும்) நாம் தூதர்களாக அனுப்பவில்லை; அவர்களுக்கு நாம் வஹீ (இறைச்செய்தி) அறிவித்தோம்.) (12:109).\n\r\n\n\r\nوَمَا جَعَلْنَـهُمْ جَسَداً لاَّ يَأْكُلُونَ الطَّعَامَ\n\r\n(மேலும், உணவு உண்ணாத உடல்களாக நாம் அவர்களை ஆக்கவில்லை.) (21:8).\n\r\n\n\r\nوَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ\n\r\n(மேலும், உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம்; நீங்கள் பொறுமையாக இருப்பீர்களா?) இதன் பொருள்: \"உங்களில் யார் கீழ்ப்படிகிறார்கள், யார் மாறுசெய்கிறார்கள் என்பதைப் பார்ப்பதற்காக உங்களில் சிலரை மற்றவர்கள் மூலம் நாம் சோதிக்கிறோம்.\"\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَتَصْبِرُونَ وَكَانَ رَبُّكَ بَصِيراً\n\r\n(நீங்கள் பொறுமையாக இருப்பீர்களா? உமது இறைவன் அனைத்தையும் பார்ப்பவனாக இருக்கிறான்.) அதாவது, வஹீ (இறைச்செய்தி)யைப் பெறுவதற்குத் தகுதியானவர் யார் என்பதை அவன் நன்கு அறிவான். இதனை அல்லாஹ் வேறொரு வசனத்தில் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\nاللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُ\n\r\n(அல்லாஹ் தனது தூதுத்துவத்தை எங்கு ஒப்படைக்க வேண்டும் என்பதை மிக நன்கறிந்தவன்.) (6:124). தான் அனுப்பிய தூதின் மூலம் நேர்வழி பெறத் தகுதியானவர் யார், தகுதியற்றவர் யார் என்பதையும் அவன் நன்கு அறிவான்.\n\r\n\n\r\nوَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً أَتَصْبِرُونَ\n\r\n(மேலும், உங்களில் சிலரைச் சிலருக்குச் சோதனையாக ஆக்கினோம். நீங்கள் பொறுமையாக இருப்பீர்களா?) முஹம்மது பின் இஸ்ஹாக் அவர்கள் கூறினார்கள்: \"எனது தூதர்களை எவரும் எதிர்க்காத ஒரு உலகமாக இது இருக்க வேண்டும் என்று நான் நாடியிருந்தால், அவ்வாறே ஆக்கியிருக்க முடியும். ஆனால் அவர்கள் மூலம் எனது அடியார்களைச் சோதிக்க நான் விரும்பினேன்\" என்று அல்லாஹ் கூறுகிறான்.\n\r\n\n\r\nஸஹீஹ் முஸ்லிமில் இயாத் பின் ஹிமார் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَقُولُ اللهُ تَعَالى: إِنِّي مُبْتَلِيكَ وَمُبْتَلٍ بِك»\n\r\n(அல்லாஹ் கூறுகிறான்: \"நிச்சயமாக நான் உன்னைச் சோதிப்பேன், உன்னைக் கொண்டு மற்றவர்களையும் சோதிப்பேன்.\")\n\r\n\n\r\nநபி (ஸல்) அவர்களுக்கு ஒரு நபியாகவும் மன்னராகவும் இருப்பதற்கும், அல்லது ஓர் அடியாராகவும் தூதராகவும் இருப்பதற்கும் இடையில் தேர்வு வழங்கப்பட்டது; அப்போது அவர்கள் ஓர் அடியாராகவும் தூதராகவும் இருப்பதையே தேர்ந்தெடுத்தார்கள் என்று ஸஹீஹில் பதிவாகியுள்ளது."},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=24\" class=\"link\">25:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:24 ஐ பார்க்கவும்"},"22":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=24\" class=\"link\">25:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:24 ஐ பார்க்கவும்"},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=24\" class=\"link\">25:24</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:24 ஐ பார்க்கவும்"},"24":{"html":"<strong>நிராகரிப்பாளர்களின் பிடிவாதம்</strong><br />\r\n<br />\r\nநிராகரிப்பாளர்கள் தங்கள் இறைமறுப்பில் எவ்வளவு பிடிவாதமாக இருந்தார்கள் என்பதை அல்லாஹ் விவரிக்கிறான். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span><br />\r\n<br />\r\n(எங்கள் மீது ஏன் வானவர்கள் இறக்கப்படவில்லை?) அதாவது, 'நாங்கள் அவர்களை எங்கள் கண்களால் நேரில் பார்க்க வேண்டும்; மேலும் முஹம்மது (ஸல்) அவர்கள் அல்லாஹ்வின் தூதர் தான் என்று அவர்கள் எங்களிடம் கூற வேண்டும்' என்பது இதன் பொருள். இது அவர்கள் முன்பு கூறியதைப் போன்றதே:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَأْتِىَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةِ</span> <span class=\"quran-arabic-font text-success\">قَبِيلاً</span><br />\r\n<br />\r\n(அல்லது நீங்கள் அல்லாஹ்வையும் வானவர்களையும் எங்கள் முன் நேருக்கு நேர் கொண்டு வர வேண்டும்) (<a href=\"qurandisp.php?sura=17&ayah=92\" class=\"link\">17:92</a>). இதனாலேயே அவர்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نَرَى</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span><br />\r\n<br />\r\n(அல்லது நாங்கள் ஏன் எங்கள் இறைவனைப் பார்க்கக் கூடாது?) என்றும் கேட்டனர். அதற்கு அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَقَدِ</span> <span class=\"quran-arabic-font text-success\">اسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَعَتَوْا</span> <span class=\"quran-arabic-font text-success\">عُتُوّاً</span> <span class=\"quran-arabic-font text-success\">كَبِيراً</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் தங்களுக்குள்ளேயே பெருமிதம் கொண்டார்கள்; மேலும் அவர்கள் பெரும் வரம்பு மீறலாக நடந்து கொண்டார்கள்.) அல்லாஹ் மேலும் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّنَا</span> <span class=\"quran-arabic-font text-success\">نَزَّلْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span> <span class=\"quran-arabic-font text-success\">وَكَلَّمَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَى</span><br />\r\n<br />\r\n(நாம் அவர்களிடம் வானவர்களை இறக்கி வைத்திருந்தாலும், மரணித்தவர்கள் அவர்களுடன் பேசியிருந்தாலும்...) (<a href=\"qurandisp.php?sura=6&ayah=111\" class=\"link\">6:111</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">بُشْرَى</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">حِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - அன்று குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது. மேலும் அவர்கள் (வானவர்கள்), \"தடை செய்யப்பட்ட ஒரு தடுப்பு\" (ஹிஜ்ரன் மஹ்ஜூரா) என்று கூறுவார்கள்.) அதாவது, அவர்கள் வானவர்களைக் காணும் போது, அது அவர்களுக்கு ஒரு நல்ல நாளாக இருக்காது; ஏனெனில் அன்று அவர்களுக்கு எந்த நற்செய்தியும் இருக்காது. இது அவர்கள் மரணிக்கும் நேரத்திலும் உறுதி செய்யப்படுகிறது. அப்போது வானவர்கள் அவர்களுக்கு நரகத்தைப் பற்றியும், அடக்கியாள்பவனான அல்லாஹ்வின் கோபத்தைப் பற்றியும் அறிவிக்கிறார்கள். நிராகரிப்பவனின் ஆன்மா வெளியே எடுக்கப்படும்போது, வானவர்கள் அதனிடம், \"தீய உடலிலிருந்து வெளியே வா, ஓ தீய ஆன்மாவே! கொடூரமான வெப்பக் காற்றுக்கும், கொதிக்கும் நீருக்கும், கரும்புகையின் நிழலுக்கும் வெளியே வா!\" என்று கூறுகிறார்கள். அது வெளியே வர மறுத்து உடல் முழுவதும் சிதறுகிறது; அதனால் வானவர்கள் அவனை அடிக்கிறார்கள். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">يَتَوَفَّى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">يَضْرِبُونَ</span> <span class=\"quran-arabic-font text-success\">وُجُوهَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَدْبَـرَهُمْ</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களின் உயிர்களை வானவர்கள் கைப்பற்றும் போது நீங்கள் பார்க்க முடிந்தால்; அவர்கள் அவர்களின் முகங்களிலும் முதுகுகளிலும் அடித்துக் கொண்டே...) (<a href=\"qurandisp.php?sura=8&ayah=50\" class=\"link\">8:50</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">تَرَى</span> <span class=\"quran-arabic-font text-success\">إِذِ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">غَمَرَاتِ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">بَاسِطُواْ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيهِمْ</span><br />\r\n<br />\r\n(அநீதியாளர்கள் மரண வேதனையில் இருக்கும்போது, வானவர்கள் தங்கள் கைகளை நீட்டியிருப்பதை நீங்கள் பார்க்க முடிந்தால்...) அதாவது அவர்களை அடிப்பதற்காக கைகளை நீட்டியபடி:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَخْرِجُواْ</span> <span class=\"quran-arabic-font text-success\">أَنفُسَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُجْزَوْنَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْهُونِ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَكُنتُمْ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِهِ</span> <span class=\"quran-arabic-font text-success\">تَسْتَكْبِرُونَ</span><br />\r\n<br />\r\n((கூறுவார்கள்): \"உங்கள் ஆன்மாக்களை வெளியேற்றுங்கள்! இன்று நீங்கள் இழிவான வேதனையைக் கூலியாக வழங்கப்படுவீர்கள். ஏனெனில், நீங்கள் அல்லாஹ்வைப் பற்றி உண்மையில்லாததைக் கூறி வந்தீர்கள்; மேலும் அவனுடைய வசனங்களைப் பெருமையுடன் புறக்கணித்தீர்கள்!\") (<a href=\"qurandisp.php?sura=6&ayah=93\" class=\"link\">6:93</a>). எனவே தான் இந்த வசனத்தில் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">بُشْرَى</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">لِّلْمُجْرِمِينَ</span><br />\r\n<br />\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது.) மரணத்தை நெருங்கும் போது விசுவாசிகளின் (முஃமின்களின்) நிலை இதற்கு நேர்மாறானது; அவர்களுக்கு மகிழ்ச்சியான செய்திகள் வழங்கப்படுகின்றன. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَقَـمُواْ</span> <span class=\"quran-arabic-font text-success\">تَتَنَزَّلُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةُ</span> <span class=\"quran-arabic-font text-success\">أَلاَّ</span> <span class=\"quran-arabic-font text-success\">تَخَافُواْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَحْزَنُواْ</span> <span class=\"quran-arabic-font text-success\">وَأَبْشِرُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تُوعَدُونَ</span> - <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">أَوْلِيَآؤُكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">وَفِى</span> <span class=\"quran-arabic-font text-success\">الاٌّخِرَةِ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَشْتَهِى</span> <span class=\"quran-arabic-font text-success\">أَنفُسُكُمْ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَدَّعُونَ</span> - <span class=\"quran-arabic-font text-success\">نُزُلاً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">غَفُورٍ</span> <span class=\"quran-arabic-font text-success\">رَّحِيمٍ</span><br />\r\n<br />\r\n(நிச்சயமாக, \"எங்கள் இறைவன் அல்லாஹ்\" என்று கூறி, பின்னர் அதில் உறுதியாக நின்றவர்கள் மீது வானவர்கள் இறங்கி, \"நீங்கள் பயப்படாதீர்கள், கவலைப்படாதீர்கள்! உங்களுக்கு வாக்களிக்கப்பட்ட சுவர்க்கத்தைக் கொண்டு மகிழ்ச்சி அடையுங்கள்! இவ்வுலக வாழ்விலும் மறுமையிலும் நாங்களே உங்கள் நண்பர்கள். அங்கு உங்கள் ஆன்மாக்கள் விரும்புவதும், நீங்கள் கேட்பதும் உங்களுக்கு உண்டு. இது மிக்க மன்னிப்பவனும், பெருங்கருணையாளனுமானவனிடமிருந்து ஒரு விருந்தாகும்\" என்று கூறுவார்கள்.) (<a href=\"qurandisp.php?sura=41&ayah=30\" class=\"link\">41:30</a>-32). அல்-பரா பின் ஆசிப் (ரழி) அவர்கள் அறிவித்துள்ள ஒரு ஆதாரப்பூர்வமான ஹதீஸில், மரண நேரத்தில் விசுவாசியின் ஆன்மாவிடம் வானவர்கள் இவ்வாறு கூறுவார்கள்: \"நல்ல உடலில் குடியிருந்த நல்ல ஆன்மாவே, நீ அதில் இருந்தபடியே வெளியே வா! அமைதிக்கும், நறுமணங்களுக்கும், உன் மீது கோபப்படாத இறைவனிடமும் வெளியே வா.\"<br />\r\n<br />\r\nமற்ற அறிஞர்கள், இந்த வசனம்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">بُشْرَى</span><br />\r\n<br />\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - எந்த நற்செய்தியும் இல்லை) என்பது மறுமை நாளைக் குறிக்கிறது என்று கூறுகிறார்கள். இது முஜாஹித், அத்-தஹ்ஹாக் மற்றும் பலரின் கருத்தாகும். ஆனால் இந்த இரண்டு கருத்துக்களுக்கும் இடையில் முரண்பாடு இல்லை. ஏனெனில் மரண நாள் மற்றும் மறுமை நாள் ஆகிய இரண்டிலுமே வானவர்கள் விசுவாசிகளுக்கும் நிராகரிப்பாளர்களுக்கும் தோன்றுவார்கள். விசுவாசிகளுக்கு இறைவனின் கருணை மற்றும் திருப்தி பற்றிய நற்செய்திகளைக் கூறுவார்கள்; நிராகரிப்பாளர்களுக்கோ வருத்தத்தையும் துக்கத்தையும் தரும் செய்திகளையே அறிவிப்பார்கள். எனவே, அந்த நாளில் குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">حِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(மேலும் அவர்கள் (வானவர்கள்) கூறுவார்கள்: \"ஹிஜ்ரன் மஹ்ஜூரா.\") வானவர்கள் நிராகரிப்பாளர்களிடம்: \"இன்று வெற்றி உங்களுக்குத் தடுக்கப்பட்டுள்ளது\" என்று கூறுவார்கள். 'அல்-ஹிஜ்ர்' என்பதன் அடிப்படைப் பொருள் 'தடுத்தல்' அல்லது 'தடை செய்தல்' என்பதாகும். இதனாலேயே, ஒருவர் திவாலாகும் போதோ அல்லது பருவமடையாதவராக இருக்கும் போதோ அவரது சொத்தை அவர் செலவழிக்கக் கூடாது என நீதிபதி தடை விதித்தால், \"ஹஜர அல்-காதி அலா ஃபுலான்\" என்று கூறப்படுகிறது. கஃபாவிற்கு அருகிலுள்ள தாழ்வான அரைவட்ட சுவருக்கும் 'அல்-ஹிஜ்ர்' என்று பெயர்; ஏனெனில் அது மக்கள் அதன் உள்ளே தவாஃப் செய்வதைத் தடுத்து, அதன் பின்னால் செல்ல வைக்கிறது. புத்தியும் 'அல்-ஹிஜ்ர்' எனப்படுகிறது, ஏனெனில் அது ஒரு மனிதனை தனக்குத் தகுதியில்லாத காரியங்களில் ஈடுபடுவதிலிருந்து தடுக்கிறது. முடிவாக, இந்த வசனத்தில் உள்ள \"அவர்கள் கூறுவார்கள்\" என்ற சொல் வானவர்களைக் குறிக்கிறது. இது முஜாஹித், இக்ரிமா, அல்-ஹசன், அத்-தஹ்ஹாக், கதாதா, அதிய்யா அல்-அவ்ஃபி, அதா அல்-குராசானி மற்றும் பலரின் கருத்தாகும்; இப்னு ஜரீர் அவர்களும் இதையே ஆதரிக்கிறார்கள். எனினும், இது சிலை வணங்குபவர்களின் கூற்றைக் குறிப்பதாக இப்னு ஜுரைஜ் கூறியிருப்பதை இப்னு ஜரீர் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْمَلَـئِكَةَ</span><br />\r\n<br />\r\n(அவர்கள் வானவர்களைக் காணும் நாளில்) அதாவது, அவர்கள் வானவர்களிடமிருந்து தஞ்சம் தேடுவார்கள். ஏனெனில், ஒரு பேரழிவோ கஷ்டமோ ஏற்படும் போது அரேபியர்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(\"ஹிஜ்ரன் மஹ்ஜூரா\") என்று கூறும் வழக்கம் இருந்தது. இப்னு ஜுரைஜ் அவர்களின் கருத்தில் ஒரு நுணுக்கம் இருந்தாலும், சூழலைப் பார்க்கும் போது இது உண்மையான பொருளாக இருக்க வாய்ப்பில்லை. பெரும்பாலான அறிஞர்களும் வேறு விதமாகவே விளக்கியுள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدِمْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span><br />\r\n<br />\r\n(மேலும் அவர்கள் செய்த செயல்கள் எதுவாக இருப்பினும், நாம் அவற்றை நோக்கிச் செல்வோம்.) இது மறுமை நாளைக் குறிக்கிறது. அப்போது அல்லாஹ் மனிதர்களின் நன்மைகள் மற்றும் தீமைகள் குறித்து கணக்குக் கேட்பான். சிலை வணங்குபவர்கள் தங்களுக்குப் பாதுகாப்பைத் தரும் என்று நம்பிய அந்தச் செயல்கள் அவர்களுக்கு எந்தப் பலனையும் தராது என்று அல்லாஹ் கூறுகிறான். ஏனெனில் அந்தச் செயல்கள் தூய எண்ணத்துடனோ அல்லது அல்லாஹ் வகுத்த சட்டங்களுக்கு (ஷரீஅத்) இணங்கவோ செய்யப்படவில்லை. அல்லாஹ்வின் சட்டங்களுக்கு உட்படாத எந்தவொரு செயலும் பயனற்றதாகும். நிராகரிப்பாளர்களின் செயல்கள் இவ்விரண்டில் ஒன்றைக் கொண்டிருக்காது அல்லது இரண்டுமே இல்லாமலும் இருக்கலாம்; அத்தகைய நிலையில் அவை ஒருபோதும் ஏற்றுக்கொள்ளப்பட மாட்டாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَدِمْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">عَمِلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span> <span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">هَبَآءً</span> <span class=\"quran-arabic-font text-success\">مَّنثُوراً</span><br />\r\n<br />\r\n(மேலும் அவர்கள் செய்த செயல்களை நாம் நோக்கிச் சென்று, அவற்றைச் சிதறிய மிதக்கும் தூசிக் துகள்களாக ஆக்குவோம்.) சுஃப்யான் அத்-தவ்ரி, அபூ இஸ்ஹாக் வழியாக, அலி (ரழி) அவர்கள் பின்வருமாறு விளக்கியதாக அறிவிக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">هَبَآءً</span> <span class=\"quran-arabic-font text-success\">مَّنثُوراً</span><br />\r\n<br />\r\n(மேலும் அத்தகைய செயல்களைச் சிதறிய மிதக்கும் தூசிக் துகள்களாக (ஹபா) ஆக்குவோம்.) \"ஒரு சிறிய துளை வழியாக சூரிய ஒளி வரும்போது தெரியும் தூசுப் படலமே இதுவாகும்.\" இதே போன்ற கருத்து வேறொரு அறிவிப்பாளர் தொடர் வழியாகவும் அலி (ரழி) அவர்களிடமிருந்து வந்துள்ளது. மேலும் இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, சயீத் பின் ஜுபைர், அஸ்-சுத்தி, அத்-தஹ்ஹாக் ஆகியோரும் இவ்வாறே கூறியுள்ளனர். அல்-ஹசன் அல்-பஸ்ரி அவர்கள் கூறும்போது, \"இது ஒரு சிறிய ஜன்னல் வழியாக வரும் கதிர்களைக் குறிக்கும்; அதை எவராலும் பிடிக்க முடியாது\" என்றார்கள். அபூ அல்-அஹ்வாஸ், அபூ இஸ்ஹாக் வழியாக, அலி (ரழி) அவர்கள், \"ஹபா என்பது கால்நடைகளால் எழுப்பப்படும் புழுதியைக் குறிக்கும்\" என்று கூறியதாகவும் அறிவித்துள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَبَآءً</span> <span class=\"quran-arabic-font text-success\">مَّنثُوراً</span><br />\r\n<br />\r\n(சிதறிய மிதக்கும் தூசிக் துகள்கள் (ஹபா).) கதாதா அவர்கள், \"காற்றால் அடித்துச் செல்லப்படும் காய்ந்த இலைகளைப் பார்த்திருக்கிறீர்களா? இது அவற்றையே குறிக்கும்\" என்றார். யஃலா பின் உபைத் அவர்கள், \"இது காற்றால் கிளறப்படும் சாம்பல் அல்லது தூசியைக் குறிக்கும்\" என்று கூறினார். சுருக்கமாகச் சொன்னால், இந்த கருத்துக்கள் அனைத்தும் நிராகரிப்பாளர்களின் செயல்கள் எவ்விதப் பலனும் தராத பயனற்ற சிதறிய பொருளைப் போன்றது என்பதையே சுட்டிக்காட்டுகின்றன. அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَّثَلُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَالُهُمْ</span> <span class=\"quran-arabic-font text-success\">كَرَمَادٍ</span> <span class=\"quran-arabic-font text-success\">اشْتَدَّتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الرِّيحُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَاصِفٍ</span><br />\r\n<br />\r\n(தங்கள் இறைவனை நிராகரித்தவர்களின் செயல்களுக்கு உதாரணம் சாம்பலைப் போன்றது; புயல் காற்று வீசும் நாளில் அதன் மீது காற்று கடுமையாக வீசுகிறது) (<a href=\"qurandisp.php?sura=14&ayah=18\" class=\"link\">14:18</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُبْطِلُواْ</span> <span class=\"quran-arabic-font text-success\">صَدَقَـتِكُم</span> <span class=\"quran-arabic-font text-success\">بِالْمَنِّ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّذَى</span><br />\r\n<br />\r\n(விசுவாசிகளே! நீங்கள் செய்த தர்மங்களை உபகாரம் செய்ததாகச் சொல்லிக் காட்டுவதாலும், மனவேதனை தருவதாலும் வீணாக்காதீர்கள்.) இந்த வசனத்தில் அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَقْدِرُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">كَسَبُواْ</span><br />\r\n<br />\r\n(அவர்கள் சம்பாதித்தவற்றிலிருந்து எதற்கும் அவர்கள் சக்தி பெறமாட்டார்கள்) (<a href=\"qurandisp.php?sura=2&ayah=264\" class=\"link\">2:264</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْمَـلُهُمْ</span> <span class=\"quran-arabic-font text-success\">كَسَرَابٍ</span> <span class=\"quran-arabic-font text-success\">بِقِيعَةٍ</span> <span class=\"quran-arabic-font text-success\">يَحْسَبُهُ</span> <span class=\"quran-arabic-font text-success\">الظَّمْآنُ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَهُ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَجِدْهُ</span> <span class=\"quran-arabic-font text-success\">شَيْئاً</span><br />\r\n<br />\r\n(நிராகரிப்பவர்களின் செயல்கள் சமவெளியில் தோன்றும் கானல் நீரைப் போன்றவை. தாகித்திருப்பவன் அதனைத் தண்ணீர் என்று எண்ணுகிறான்; ஆனால் அவன் அங்கு வரும்போது எதனையும் காணமாட்டான்) (<a href=\"qurandisp.php?sura=24&ayah=39\" class=\"link\">24:39</a>).<br />\r\n<br />\r\n<strong>சொர்க்கவாசிகளின் தங்குமிடம்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">مَقِيلاً</span><br />\r\n<br />\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) அதாவது, மறுமை நாளில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَوِى</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">وَأَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَآئِزُونَ</span><br />\r\n<br />\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றி பெற்றவர்கள்) (<a href=\"qurandisp.php?sura=59&ayah=20\" class=\"link\">59:20</a>). ஏனெனில், சொர்க்கவாசிகள் உயர்ந்த நிலைகளுக்கும் பாதுகாப்பான குடியிருப்புகளுக்கும் செல்வார்கள். அவர்கள் பாதுகாப்பு, அழகு மற்றும் நன்மைகள் நிறைந்த இடத்தில் இருப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">حَسُنَتْ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَمُقَاماً</span><br />\r\n<br />\r\n(அதில் அவர்கள் நிலைத்திருப்பார்கள்; தங்குமிடமாகவும் ஓய்விடமாகவும் அது மிகச் சிறந்தது.) (<a href=\"qurandisp.php?sura=25&ayah=76\" class=\"link\">25:76</a>). மாறாக, நரகவாசிகள் மிகக் கீழான நிலைகளுக்கும் தீராத வருத்தத்திற்கும் செல்வார்கள்; அங்கு அவர்கள் அனைத்து விதமான வேதனைகளையும் அனுபவிப்பார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">سَآءَتْ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَمُقَاماً</span><br />\r\n<br />\r\n(நிச்சயமாக அது (நரகம்) தங்குமிடமாகவும் ஓய்விடமாகவும் மிகவும் தீயது.) (<a href=\"qurandisp.php?sura=25&ayah=66\" class=\"link\">25:66</a>). அதாவது, பார்ப்பதற்கும் தங்குவதற்கும் அது மிக மோசமான இடம்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">مَقِيلاً</span><br />\r\n<br />\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) அதாவது, அவர்கள் செய்த நற்செயல்களுக்குப் பிரதிபலனாக, அவர்கள் அடைய வேண்டிய நிலைகளை அடைவார்கள். இது நரகவாசிகளின் நிலைக்கு முற்றிலும் மாறுபட்டது; ஏனெனில் நரகவாசிகளிடம் சொர்க்கத்தில் நுழைவதற்கோ அல்லது நரகத்திலிருந்து தப்புவதற்கோ தகுதியான ஒரு செயல் கூட இருக்காது. பாக்கியவான்களின் நிலையை சபிக்கப்பட்டவர்களின் நிலையோடு அல்லாஹ் ஒப்பிட்டுக் காட்டுகிறான்.<br />\r\n<br />\r\nசயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள்: \"மதிய நேரத்திற்குள்ளாகவே அல்லாஹ் தனது தீர்ப்புகளை முடித்து விடுவான்; அதன் பின் சொர்க்கவாசிகள் சொர்க்கத்திலும், நரகவாசிகள் நரகத்திலும் தங்கள் மதிய ஓய்வை எடுப்பார்கள்.\" அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">مَقِيلاً</span><br />\r\n<br />\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) இக்ரிமா அவர்கள் கூறினார்கள்: \"சொர்க்கவாசிகள் சொர்க்கத்தில் நுழையும் நேரத்தையும், நரகவாசிகள் நரகத்தில் நுழையும் நேரத்தையும் நான் அறிவேன். இவ்வுலகில் மக்கள் தங்கள் மதிய ஓய்வுக்காக (Siesta) குடும்பத்தினரிடம் திரும்பும் முற்பகல் நேரமே அதுவாகும். நரகவாசிகள் நரகத்திற்குச் செல்வார்கள்; ஆனால் சொர்க்கவாசிகள் சொர்க்கத்திற்கு அழைத்துச் செல்லப்பட்டு அங்கு மதிய ஓய்வை எடுப்பார்கள். அவர்களுக்கு திமிங்கலத்தின் கல்லீரல் உணவாக வழங்கப்பட்டு அவர்கள் வயிறார உண்பார்கள்.\" இதையே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَصْحَـبُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">خَيْرٌ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنُ</span> <span class=\"quran-arabic-font text-success\">مَقِيلاً</span><br />\r\n<br />\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.)<br />\r\n<br />","text":"நிராகரிப்பாளர்களின் பிடிவாதம்\n\r\n\n\r\nநிராகரிப்பாளர்கள் தங்கள் இறைமறுப்பில் எவ்வளவு பிடிவாதமாக இருந்தார்கள் என்பதை அல்லாஹ் விவரிக்கிறான். அவர்கள் கூறினார்கள்:\n\r\n\n\r\nلَوْلاَ أُنزِلَ عَلَيْنَا الْمَلَـئِكَةُ\n\r\n\n\r\n(எங்கள் மீது ஏன் வானவர்கள் இறக்கப்படவில்லை?) அதாவது, 'நாங்கள் அவர்களை எங்கள் கண்களால் நேரில் பார்க்க வேண்டும்; மேலும் முஹம்மது (ஸல்) அவர்கள் அல்லாஹ்வின் தூதர் தான் என்று அவர்கள் எங்களிடம் கூற வேண்டும்' என்பது இதன் பொருள். இது அவர்கள் முன்பு கூறியதைப் போன்றதே:\n\r\n\n\r\nأَوْ تَأْتِىَ بِاللَّهِ وَالْمَلَـئِكَةِ قَبِيلاً\n\r\n\n\r\n(அல்லது நீங்கள் அல்லாஹ்வையும் வானவர்களையும் எங்கள் முன் நேருக்கு நேர் கொண்டு வர வேண்டும்) (17:92). இதனாலேயே அவர்கள்:\n\r\n\n\r\nأَوْ نَرَى رَبَّنَا\n\r\n\n\r\n(அல்லது நாங்கள் ஏன் எங்கள் இறைவனைப் பார்க்கக் கூடாது?) என்றும் கேட்டனர். அதற்கு அல்லாஹ் கூறினான்:\n\r\n\n\r\nلَقَدِ اسْتَكْبَرُواْ فِى أَنفُسِهِمْ وَعَتَوْا عُتُوّاً كَبِيراً\n\r\n\n\r\n(நிச்சயமாக அவர்கள் தங்களுக்குள்ளேயே பெருமிதம் கொண்டார்கள்; மேலும் அவர்கள் பெரும் வரம்பு மீறலாக நடந்து கொண்டார்கள்.) அல்லாஹ் மேலும் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ أَنَّنَا نَزَّلْنَآ إِلَيْهِمُ الْمَلَـئِكَةَ وَكَلَّمَهُمُ الْمَوْتَى\n\r\n\n\r\n(நாம் அவர்களிடம் வானவர்களை இறக்கி வைத்திருந்தாலும், மரணித்தவர்கள் அவர்களுடன் பேசியிருந்தாலும்...) (6:111)\n\r\n\n\r\nيَوْمَ يَرَوْنَ الْمَلَـئِكَةَ لاَ بُشْرَى يَوْمَئِذٍ لِّلْمُجْرِمِينَ وَيَقُولُونَ حِجْراً مَّحْجُوراً\n\r\n\n\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - அன்று குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது. மேலும் அவர்கள் (வானவர்கள்), \"தடை செய்யப்பட்ட ஒரு தடுப்பு\" (ஹிஜ்ரன் மஹ்ஜூரா) என்று கூறுவார்கள்.) அதாவது, அவர்கள் வானவர்களைக் காணும் போது, அது அவர்களுக்கு ஒரு நல்ல நாளாக இருக்காது; ஏனெனில் அன்று அவர்களுக்கு எந்த நற்செய்தியும் இருக்காது. இது அவர்கள் மரணிக்கும் நேரத்திலும் உறுதி செய்யப்படுகிறது. அப்போது வானவர்கள் அவர்களுக்கு நரகத்தைப் பற்றியும், அடக்கியாள்பவனான அல்லாஹ்வின் கோபத்தைப் பற்றியும் அறிவிக்கிறார்கள். நிராகரிப்பவனின் ஆன்மா வெளியே எடுக்கப்படும்போது, வானவர்கள் அதனிடம், \"தீய உடலிலிருந்து வெளியே வா, ஓ தீய ஆன்மாவே! கொடூரமான வெப்பக் காற்றுக்கும், கொதிக்கும் நீருக்கும், கரும்புகையின் நிழலுக்கும் வெளியே வா!\" என்று கூறுகிறார்கள். அது வெளியே வர மறுத்து உடல் முழுவதும் சிதறுகிறது; அதனால் வானவர்கள் அவனை அடிக்கிறார்கள். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَلَوْ تَرَى إِذْ يَتَوَفَّى الَّذِينَ كَفَرُواْ الْمَلَـئِكَةُ يَضْرِبُونَ وُجُوهَهُمْ وَأَدْبَـرَهُمْ\n\r\n\n\r\n(நிராகரிப்பவர்களின் உயிர்களை வானவர்கள் கைப்பற்றும் போது நீங்கள் பார்க்க முடிந்தால்; அவர்கள் அவர்களின் முகங்களிலும் முதுகுகளிலும் அடித்துக் கொண்டே...) (8:50)\n\r\n\n\r\nوَلَوْ تَرَى إِذِ الظَّـلِمُونَ فِى غَمَرَاتِ الْمَوْتِ وَالْمَلَـئِكَةُ بَاسِطُواْ أَيْدِيهِمْ\n\r\n\n\r\n(அநீதியாளர்கள் மரண வேதனையில் இருக்கும்போது, வானவர்கள் தங்கள் கைகளை நீட்டியிருப்பதை நீங்கள் பார்க்க முடிந்தால்...) அதாவது அவர்களை அடிப்பதற்காக கைகளை நீட்டியபடி:\n\r\n\n\r\nأَخْرِجُواْ أَنفُسَكُمُ الْيَوْمَ تُجْزَوْنَ عَذَابَ الْهُونِ بِمَا كُنتُمْ تَقُولُونَ عَلَى اللَّهِ غَيْرَ الْحَقِّ وَكُنتُمْ عَنْ ءَايَـتِهِ تَسْتَكْبِرُونَ\n\r\n\n\r\n((கூறுவார்கள்): \"உங்கள் ஆன்மாக்களை வெளியேற்றுங்கள்! இன்று நீங்கள் இழிவான வேதனையைக் கூலியாக வழங்கப்படுவீர்கள். ஏனெனில், நீங்கள் அல்லாஹ்வைப் பற்றி உண்மையில்லாததைக் கூறி வந்தீர்கள்; மேலும் அவனுடைய வசனங்களைப் பெருமையுடன் புறக்கணித்தீர்கள்!\") (6:93). எனவே தான் இந்த வசனத்தில் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَوْمَ يَرَوْنَ الْمَلَـئِكَةَ لاَ بُشْرَى يَوْمَئِذٍ لِّلْمُجْرِمِينَ\n\r\n\n\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது.) மரணத்தை நெருங்கும் போது விசுவாசிகளின் (முஃமின்களின்) நிலை இதற்கு நேர்மாறானது; அவர்களுக்கு மகிழ்ச்சியான செய்திகள் வழங்கப்படுகின்றன. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ الَّذِينَ قَالُواْ رَبُّنَا اللَّهُ ثُمَّ اسْتَقَـمُواْ تَتَنَزَّلُ عَلَيْهِمُ الْمَلَـئِكَةُ أَلاَّ تَخَافُواْ وَلاَ تَحْزَنُواْ وَأَبْشِرُواْ بِالْجَنَّةِ الَّتِى كُنتُمْ تُوعَدُونَ - نَحْنُ أَوْلِيَآؤُكُمْ فِى الْحَيَوةِ الدُّنْيَا وَفِى الاٌّخِرَةِ وَلَكُمْ فِيهَا مَا تَشْتَهِى أَنفُسُكُمْ وَلَكُمْ فِيهَا مَا تَدَّعُونَ - نُزُلاً مِّنْ غَفُورٍ رَّحِيمٍ\n\r\n\n\r\n(நிச்சயமாக, \"எங்கள் இறைவன் அல்லாஹ்\" என்று கூறி, பின்னர் அதில் உறுதியாக நின்றவர்கள் மீது வானவர்கள் இறங்கி, \"நீங்கள் பயப்படாதீர்கள், கவலைப்படாதீர்கள்! உங்களுக்கு வாக்களிக்கப்பட்ட சுவர்க்கத்தைக் கொண்டு மகிழ்ச்சி அடையுங்கள்! இவ்வுலக வாழ்விலும் மறுமையிலும் நாங்களே உங்கள் நண்பர்கள். அங்கு உங்கள் ஆன்மாக்கள் விரும்புவதும், நீங்கள் கேட்பதும் உங்களுக்கு உண்டு. இது மிக்க மன்னிப்பவனும், பெருங்கருணையாளனுமானவனிடமிருந்து ஒரு விருந்தாகும்\" என்று கூறுவார்கள்.) (41:30-32). அல்-பரா பின் ஆசிப் (ரழி) அவர்கள் அறிவித்துள்ள ஒரு ஆதாரப்பூர்வமான ஹதீஸில், மரண நேரத்தில் விசுவாசியின் ஆன்மாவிடம் வானவர்கள் இவ்வாறு கூறுவார்கள்: \"நல்ல உடலில் குடியிருந்த நல்ல ஆன்மாவே, நீ அதில் இருந்தபடியே வெளியே வா! அமைதிக்கும், நறுமணங்களுக்கும், உன் மீது கோபப்படாத இறைவனிடமும் வெளியே வா.\"\n\r\n\n\r\nமற்ற அறிஞர்கள், இந்த வசனம்:\n\r\n\n\r\nيَوْمَ يَرَوْنَ الْمَلَـئِكَةَ لاَ بُشْرَى\n\r\n\n\r\n(அவர்கள் வானவர்களைக் காணும் நாளில் - எந்த நற்செய்தியும் இல்லை) என்பது மறுமை நாளைக் குறிக்கிறது என்று கூறுகிறார்கள். இது முஜாஹித், அத்-தஹ்ஹாக் மற்றும் பலரின் கருத்தாகும். ஆனால் இந்த இரண்டு கருத்துக்களுக்கும் இடையில் முரண்பாடு இல்லை. ஏனெனில் மரண நாள் மற்றும் மறுமை நாள் ஆகிய இரண்டிலுமே வானவர்கள் விசுவாசிகளுக்கும் நிராகரிப்பாளர்களுக்கும் தோன்றுவார்கள். விசுவாசிகளுக்கு இறைவனின் கருணை மற்றும் திருப்தி பற்றிய நற்செய்திகளைக் கூறுவார்கள்; நிராகரிப்பாளர்களுக்கோ வருத்தத்தையும் துக்கத்தையும் தரும் செய்திகளையே அறிவிப்பார்கள். எனவே, அந்த நாளில் குற்றவாளிகளுக்கு எந்த நற்செய்தியும் இருக்காது.\n\r\n\n\r\nوَيَقُولُونَ حِجْراً مَّحْجُوراً\n\r\n\n\r\n(மேலும் அவர்கள் (வானவர்கள்) கூறுவார்கள்: \"ஹிஜ்ரன் மஹ்ஜூரா.\") வானவர்கள் நிராகரிப்பாளர்களிடம்: \"இன்று வெற்றி உங்களுக்குத் தடுக்கப்பட்டுள்ளது\" என்று கூறுவார்கள். 'அல்-ஹிஜ்ர்' என்பதன் அடிப்படைப் பொருள் 'தடுத்தல்' அல்லது 'தடை செய்தல்' என்பதாகும். இதனாலேயே, ஒருவர் திவாலாகும் போதோ அல்லது பருவமடையாதவராக இருக்கும் போதோ அவரது சொத்தை அவர் செலவழிக்கக் கூடாது என நீதிபதி தடை விதித்தால், \"ஹஜர அல்-காதி அலா ஃபுலான்\" என்று கூறப்படுகிறது. கஃபாவிற்கு அருகிலுள்ள தாழ்வான அரைவட்ட சுவருக்கும் 'அல்-ஹிஜ்ர்' என்று பெயர்; ஏனெனில் அது மக்கள் அதன் உள்ளே தவாஃப் செய்வதைத் தடுத்து, அதன் பின்னால் செல்ல வைக்கிறது. புத்தியும் 'அல்-ஹிஜ்ர்' எனப்படுகிறது, ஏனெனில் அது ஒரு மனிதனை தனக்குத் தகுதியில்லாத காரியங்களில் ஈடுபடுவதிலிருந்து தடுக்கிறது. முடிவாக, இந்த வசனத்தில் உள்ள \"அவர்கள் கூறுவார்கள்\" என்ற சொல் வானவர்களைக் குறிக்கிறது. இது முஜாஹித், இக்ரிமா, அல்-ஹசன், அத்-தஹ்ஹாக், கதாதா, அதிய்யா அல்-அவ்ஃபி, அதா அல்-குராசானி மற்றும் பலரின் கருத்தாகும்; இப்னு ஜரீர் அவர்களும் இதையே ஆதரிக்கிறார்கள். எனினும், இது சிலை வணங்குபவர்களின் கூற்றைக் குறிப்பதாக இப்னு ஜுரைஜ் கூறியிருப்பதை இப்னு ஜரீர் பதிவு செய்துள்ளார்.\n\r\n\n\r\nيَوْمَ يَرَوْنَ الْمَلَـئِكَةَ\n\r\n\n\r\n(அவர்கள் வானவர்களைக் காணும் நாளில்) அதாவது, அவர்கள் வானவர்களிடமிருந்து தஞ்சம் தேடுவார்கள். ஏனெனில், ஒரு பேரழிவோ கஷ்டமோ ஏற்படும் போது அரேபியர்கள்:\n\r\n\n\r\nحِجْراً مَّحْجُوراً\n\r\n\n\r\n(\"ஹிஜ்ரன் மஹ்ஜூரா\") என்று கூறும் வழக்கம் இருந்தது. இப்னு ஜுரைஜ் அவர்களின் கருத்தில் ஒரு நுணுக்கம் இருந்தாலும், சூழலைப் பார்க்கும் போது இது உண்மையான பொருளாக இருக்க வாய்ப்பில்லை. பெரும்பாலான அறிஞர்களும் வேறு விதமாகவே விளக்கியுள்ளனர்.\n\r\n\n\r\nوَقَدِمْنَآ إِلَى مَا عَمِلُواْ مِنْ عَمَلٍ\n\r\n\n\r\n(மேலும் அவர்கள் செய்த செயல்கள் எதுவாக இருப்பினும், நாம் அவற்றை நோக்கிச் செல்வோம்.) இது மறுமை நாளைக் குறிக்கிறது. அப்போது அல்லாஹ் மனிதர்களின் நன்மைகள் மற்றும் தீமைகள் குறித்து கணக்குக் கேட்பான். சிலை வணங்குபவர்கள் தங்களுக்குப் பாதுகாப்பைத் தரும் என்று நம்பிய அந்தச் செயல்கள் அவர்களுக்கு எந்தப் பலனையும் தராது என்று அல்லாஹ் கூறுகிறான். ஏனெனில் அந்தச் செயல்கள் தூய எண்ணத்துடனோ அல்லது அல்லாஹ் வகுத்த சட்டங்களுக்கு (ஷரீஅத்) இணங்கவோ செய்யப்படவில்லை. அல்லாஹ்வின் சட்டங்களுக்கு உட்படாத எந்தவொரு செயலும் பயனற்றதாகும். நிராகரிப்பாளர்களின் செயல்கள் இவ்விரண்டில் ஒன்றைக் கொண்டிருக்காது அல்லது இரண்டுமே இல்லாமலும் இருக்கலாம்; அத்தகைய நிலையில் அவை ஒருபோதும் ஏற்றுக்கொள்ளப்பட மாட்டாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقَدِمْنَآ إِلَى مَا عَمِلُواْ مِنْ عَمَلٍ فَجَعَلْنَاهُ هَبَآءً مَّنثُوراً\n\r\n\n\r\n(மேலும் அவர்கள் செய்த செயல்களை நாம் நோக்கிச் சென்று, அவற்றைச் சிதறிய மிதக்கும் தூசிக் துகள்களாக ஆக்குவோம்.) சுஃப்யான் அத்-தவ்ரி, அபூ இஸ்ஹாக் வழியாக, அலி (ரழி) அவர்கள் பின்வருமாறு விளக்கியதாக அறிவிக்கிறார்கள்:\n\r\n\n\r\nفَجَعَلْنَاهُ هَبَآءً مَّنثُوراً\n\r\n\n\r\n(மேலும் அத்தகைய செயல்களைச் சிதறிய மிதக்கும் தூசிக் துகள்களாக (ஹபா) ஆக்குவோம்.) \"ஒரு சிறிய துளை வழியாக சூரிய ஒளி வரும்போது தெரியும் தூசுப் படலமே இதுவாகும்.\" இதே போன்ற கருத்து வேறொரு அறிவிப்பாளர் தொடர் வழியாகவும் அலி (ரழி) அவர்களிடமிருந்து வந்துள்ளது. மேலும் இப்னு அப்பாஸ் (ரழி), முஜாஹித், இக்ரிமா, சயீத் பின் ஜுபைர், அஸ்-சுத்தி, அத்-தஹ்ஹாக் ஆகியோரும் இவ்வாறே கூறியுள்ளனர். அல்-ஹசன் அல்-பஸ்ரி அவர்கள் கூறும்போது, \"இது ஒரு சிறிய ஜன்னல் வழியாக வரும் கதிர்களைக் குறிக்கும்; அதை எவராலும் பிடிக்க முடியாது\" என்றார்கள். அபூ அல்-அஹ்வாஸ், அபூ இஸ்ஹாக் வழியாக, அலி (ரழி) அவர்கள், \"ஹபா என்பது கால்நடைகளால் எழுப்பப்படும் புழுதியைக் குறிக்கும்\" என்று கூறியதாகவும் அறிவித்துள்ளார்.\n\r\n\n\r\nهَبَآءً مَّنثُوراً\n\r\n\n\r\n(சிதறிய மிதக்கும் தூசிக் துகள்கள் (ஹபா).) கதாதா அவர்கள், \"காற்றால் அடித்துச் செல்லப்படும் காய்ந்த இலைகளைப் பார்த்திருக்கிறீர்களா? இது அவற்றையே குறிக்கும்\" என்றார். யஃலா பின் உபைத் அவர்கள், \"இது காற்றால் கிளறப்படும் சாம்பல் அல்லது தூசியைக் குறிக்கும்\" என்று கூறினார். சுருக்கமாகச் சொன்னால், இந்த கருத்துக்கள் அனைத்தும் நிராகரிப்பாளர்களின் செயல்கள் எவ்விதப் பலனும் தராத பயனற்ற சிதறிய பொருளைப் போன்றது என்பதையே சுட்டிக்காட்டுகின்றன. அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nمَّثَلُ الَّذِينَ كَفَرُواْ بِرَبِّهِمْ أَعْمَالُهُمْ كَرَمَادٍ اشْتَدَّتْ بِهِ الرِّيحُ فِى يَوْمٍ عَاصِفٍ\n\r\n\n\r\n(தங்கள் இறைவனை நிராகரித்தவர்களின் செயல்களுக்கு உதாரணம் சாம்பலைப் போன்றது; புயல் காற்று வீசும் நாளில் அதன் மீது காற்று கடுமையாக வீசுகிறது) (14:18).\n\r\n\n\r\nيأَيُّهَا الَّذِينَ ءَامَنُواْ لاَ تُبْطِلُواْ صَدَقَـتِكُم بِالْمَنِّ وَالاٌّذَى\n\r\n\n\r\n(விசுவாசிகளே! நீங்கள் செய்த தர்மங்களை உபகாரம் செய்ததாகச் சொல்லிக் காட்டுவதாலும், மனவேதனை தருவதாலும் வீணாக்காதீர்கள்.) இந்த வசனத்தில் அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nلاَّ يَقْدِرُونَ عَلَى شَىْءٍ مِّمَّا كَسَبُواْ\n\r\n\n\r\n(அவர்கள் சம்பாதித்தவற்றிலிருந்து எதற்கும் அவர்கள் சக்தி பெறமாட்டார்கள்) (2:264).\n\r\n\n\r\nوَالَّذِينَ كَفَرُواْ أَعْمَـلُهُمْ كَسَرَابٍ بِقِيعَةٍ يَحْسَبُهُ الظَّمْآنُ مَآءً حَتَّى إِذَا جَآءَهُ لَمْ يَجِدْهُ شَيْئاً\n\r\n\n\r\n(நிராகரிப்பவர்களின் செயல்கள் சமவெளியில் தோன்றும் கானல் நீரைப் போன்றவை. தாகித்திருப்பவன் அதனைத் தண்ணீர் என்று எண்ணுகிறான்; ஆனால் அவன் அங்கு வரும்போது எதனையும் காணமாட்டான்) (24:39).\n\r\n\n\r\nசொர்க்கவாசிகளின் தங்குமிடம்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَصْحَـبُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرّاً وَأَحْسَنُ مَقِيلاً\n\r\n\n\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) அதாவது, மறுமை நாளில்.\n\r\n\n\r\nلاَ يَسْتَوِى أَصْحَـبُ النَّارِ وَأَصْحَـبُ الْجَنَّةِ أَصْحَـبُ الْجَنَّةِ هُمُ الْفَآئِزُونَ\n\r\n\n\r\n(நரகவாசிகளும் சொர்க்கவாசிகளும் சமமாக மாட்டார்கள். சொர்க்கவாசிகளே வெற்றி பெற்றவர்கள்) (59:20). ஏனெனில், சொர்க்கவாசிகள் உயர்ந்த நிலைகளுக்கும் பாதுகாப்பான குடியிருப்புகளுக்கும் செல்வார்கள். அவர்கள் பாதுகாப்பு, அழகு மற்றும் நன்மைகள் நிறைந்த இடத்தில் இருப்பார்கள்.\n\r\n\n\r\nخَـلِدِينَ فِيهَا حَسُنَتْ مُسْتَقَرّاً وَمُقَاماً\n\r\n\n\r\n(அதில் அவர்கள் நிலைத்திருப்பார்கள்; தங்குமிடமாகவும் ஓய்விடமாகவும் அது மிகச் சிறந்தது.) (25:76). மாறாக, நரகவாசிகள் மிகக் கீழான நிலைகளுக்கும் தீராத வருத்தத்திற்கும் செல்வார்கள்; அங்கு அவர்கள் அனைத்து விதமான வேதனைகளையும் அனுபவிப்பார்கள்.\n\r\n\n\r\nإِنَّهَا سَآءَتْ مُسْتَقَرّاً وَمُقَاماً\n\r\n\n\r\n(நிச்சயமாக அது (நரகம்) தங்குமிடமாகவும் ஓய்விடமாகவும் மிகவும் தீயது.) (25:66). அதாவது, பார்ப்பதற்கும் தங்குவதற்கும் அது மிக மோசமான இடம்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَصْحَـبُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرّاً وَأَحْسَنُ مَقِيلاً\n\r\n\n\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) அதாவது, அவர்கள் செய்த நற்செயல்களுக்குப் பிரதிபலனாக, அவர்கள் அடைய வேண்டிய நிலைகளை அடைவார்கள். இது நரகவாசிகளின் நிலைக்கு முற்றிலும் மாறுபட்டது; ஏனெனில் நரகவாசிகளிடம் சொர்க்கத்தில் நுழைவதற்கோ அல்லது நரகத்திலிருந்து தப்புவதற்கோ தகுதியான ஒரு செயல் கூட இருக்காது. பாக்கியவான்களின் நிலையை சபிக்கப்பட்டவர்களின் நிலையோடு அல்லாஹ் ஒப்பிட்டுக் காட்டுகிறான்.\n\r\n\n\r\nசயீத் பின் ஜுபைர் அவர்கள் கூறினார்கள்: \"மதிய நேரத்திற்குள்ளாகவே அல்லாஹ் தனது தீர்ப்புகளை முடித்து விடுவான்; அதன் பின் சொர்க்கவாசிகள் சொர்க்கத்திலும், நரகவாசிகள் நரகத்திலும் தங்கள் மதிய ஓய்வை எடுப்பார்கள்.\" அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَصْحَـبُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرّاً وَأَحْسَنُ مَقِيلاً\n\r\n\n\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.) இக்ரிமா அவர்கள் கூறினார்கள்: \"சொர்க்கவாசிகள் சொர்க்கத்தில் நுழையும் நேரத்தையும், நரகவாசிகள் நரகத்தில் நுழையும் நேரத்தையும் நான் அறிவேன். இவ்வுலகில் மக்கள் தங்கள் மதிய ஓய்வுக்காக (Siesta) குடும்பத்தினரிடம் திரும்பும் முற்பகல் நேரமே அதுவாகும். நரகவாசிகள் நரகத்திற்குச் செல்வார்கள்; ஆனால் சொர்க்கவாசிகள் சொர்க்கத்திற்கு அழைத்துச் செல்லப்பட்டு அங்கு மதிய ஓய்வை எடுப்பார்கள். அவர்களுக்கு திமிங்கலத்தின் கல்லீரல் உணவாக வழங்கப்பட்டு அவர்கள் வயிறார உண்பார்கள்.\" இதையே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَصْحَـبُ الْجَنَّةِ يَوْمَئِذٍ خَيْرٌ مُّسْتَقَرّاً وَأَحْسَنُ مَقِيلاً\n\r\n\n\r\n(சுவர்க்கவாசிகள் அந்த நாளில் சிறந்த தங்குமிடத்தையும், மிக அழகான ஓய்விடத்தையும் கொண்டிருப்பார்கள்.)"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=29\" class=\"link\">25:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:29 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=29\" class=\"link\">25:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:29 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=29\" class=\"link\">25:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:29 ஐ பார்க்கவும்"},"28":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=29\" class=\"link\">25:29</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:29 ஐ பார்க்கவும்"},"29":{"html":"<strong>மறுமை நாளின் திடுக்கிடும் நிகழ்வுகளும், அநியாயக்காரர்கள் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு நேர்வழியைப் பின்பற்றியிருக்க வேண்டுமே என ஏங்குவதும்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் மறுமை நாளின் பயங்கரங்களைப் பற்றியும், அன்று நிகழவிருக்கும் மகத்தான நிகழ்வுகளைப் பற்றியும் நமக்குக் கூறுகிறான். பார்வைகளைப் பறிக்கக்கூடிய பிரம்மாண்டமான ஒளியின் நிழலாகிய மேகக்கூட்டங்களால் வானங்கள் பிளக்கப்படுவதும் அதில் அடங்கும். அந்நாளில் வானவர்கள் வானிலிருந்து இறங்கி வந்து, மக்கள் ஒன்றுதிரட்டப்படும் இடத்தில் அனைத்துப் படைப்புகளையும் சூழ்ந்துகொள்வார்கள். பின்னர், கண்ணியமும் உயர்வும் மிக்க இறைவனாகிய அல்லாஹ் தீர்ப்பு வழங்குவதற்காக வருவான். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"இது அல்லாஹ் கூறுவதைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾هَلْ</span> <span class=\"quran-arabic-font text-success\">يَنظُرُونَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَأْتِيَهُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ظُلَلٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْغَمَامِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةُ﴿</span> (மேகங்களின் நிழல்களில் அல்லாஹ்வும் வானவர்களும் அவர்களிடம் வருவதைத் தவிர வேறு எதையேனும் அவர்கள் எதிர்பார்க்கிறார்களா?)\" (<a href=\"qurandisp.php?sura=2&ayah=210\" class=\"link\">2:210</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ﴿</span><br />\r\n(அந்நாளில் உண்மையான அதிகாரம் அளவற்ற அருளாளனுக்கே உரியது). இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾لِّمَنِ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكُ</span> <span class=\"quran-arabic-font text-success\">الْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">لِلَّهِ</span> <span class=\"quran-arabic-font text-success\">الْوَحِدِ</span> <span class=\"quran-arabic-font text-success\">الْقَهَّارِ﴿</span> (“இன்றைய தினம் ஆட்சி யாருக்குரியது? அடக்கியாளும் ஒருவனான அல்லாஹ்வுக்கே உரியது!”) (<a href=\"qurandisp.php?sura=40&ayah=16\" class=\"link\">40:16</a>). ஸஹீஹ் நூல்களில் இவ்வாறு இடம்பெற்றுள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span> <span class=\"quran-arabic-font text-success\">يَطْوِي</span> <span class=\"quran-arabic-font text-success\">السَّمَوَاتِ</span> <span class=\"quran-arabic-font text-success\">بِيَمِينِهِ،</span> <span class=\"quran-arabic-font text-success\">وَيَأْخُذُ</span> <span class=\"quran-arabic-font text-success\">الْأَرَضِينَ</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">الْأُخْرَى،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span>: <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الْمَلِكُ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">الدَّيَّانُ،</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">مُلُوكُ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ؟</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْجَبَّارُونَ؟</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْمُتَكَبِّرُونَ؟</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (உயர்ந்தோனாகிய அல்லாஹ் வானங்களைத் தனது வலது கையால் சுருட்டி, பூமிகளைத் தனது மற்றொரு கையால் பிடித்துக் கொள்வான். பின்னர் அவன் கூறுவான்: “நானே அரசன், நானே நீதிபதி. பூமியின் மன்னர்கள் எங்கே? அக்கிரமக்காரர்கள் எங்கே? பெருமையடித்தவர்கள் எங்கே?”).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">يَوْماً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">عَسِيراً﴿</span><br />\r\n(மேலும் அது நிராகரிப்பாளர்களுக்குக் கடினமான நாளாக இருக்கும்). அதாவது அந்நாள் மிகவும் சிரமமானதாக இருக்கும். ஏனெனில் அது நீதியும் தீர்க்கமான தீர்ப்பும் வழங்கப்படும் நாளாகும். அல்லாஹ் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾فَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَئِذٍ</span> <span class=\"quran-arabic-font text-success\">يَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عَسِيرٌ</span> - <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">غَيْرُ</span> <span class=\"quran-arabic-font text-success\">يَسِيرٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span> (நிச்சயமாக அந்நாள் ஒரு கடினமான நாளாகும்; அது நிராகரிப்பாளர்களுக்கு எளிதானதல்ல) (<a href=\"qurandisp.php?sura=74&ayah=9\" class=\"link\">74:9</a>-10). மறுமை நாளில் நிராகரிப்பாளர்களின் நிலை இவ்வாறே இருக்கும். ஆனால் இறைநம்பிக்கையாளர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يَحْزُنُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْفَزَعُ</span> <span class=\"quran-arabic-font text-success\">الاٌّكْبَرُ﴿</span> (அந்த மாபெரும் திடுக்கிடும் நிகழ்வு அவர்களைத் துயரப்படுத்தாது).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَعَضُّ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَنِي</span> <span class=\"quran-arabic-font text-success\">اتَّخَذْتُ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அநியாயக்காரன் தன் கைகளைக் கடித்துக்கொண்டு, “அந்தோ! நான் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு வழியைத் தேர்ந்தெடுத்திருக்க வேண்டாமா?” என்று கூறும் நாளை (நினைவுகூருவீராக)). அல்லாஹ்வின் தூதர் (ஸல்) காட்டிய வழியையும், அவர் (ஸல்) அல்லாஹ்விடமிருந்து கொண்டு வந்த சந்தேகத்திற்கு இடமற்ற தெளிவான உண்மையையும் நிராகரித்துவிட்டு, வேறு பாதையைப் பின்பற்றிய அநியாயக்காரன் அடையும் கைசேதத்தைப் பற்றி இங்கே அல்லாஹ் கூறுகிறான். மறுமை நாள் வரும்போது அவன் மிகவும் வருந்துவான்; ஆனால் அந்த வருத்தம் அவனுக்கு எந்தப் பயனும் அளிக்காது. மாறாக, துக்கத்தாலும் கவலையாலும் அவன் தன் கைகளைக் கடித்துக்கொள்வான். இந்த வசனம் உக்பா பின் அபீ முஐத் என்பவரைப் பற்றி அல்லது நாசமடைந்தவர்களில் வேறொருவரைப் பற்றி இறக்கப்பட்டிருந்தாலும், இது ஒவ்வொரு அநியாயக்காரனுக்கும் பொருந்தும். அல்லாஹ் பின்வருமாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">تُقَلَّبُ</span> <span class=\"quran-arabic-font text-success\">وُجُوهُهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">النَّارِ﴿</span> (நெருப்பில் அவர்களுடைய முகங்கள் புரட்டப்படும் நாளில்...) (<a href=\"qurandisp.php?sura=33&ayah=66\" class=\"link\">33:66</a>). இவ்வாறு ஒவ்வொரு அநியாயக்காரனும் மறுமை நாளில் உச்சகட்டக் கைசேதத்தை உணர்ந்து, தன் கைகளைக் கடித்துக்கொண்டு பின்வருமாறு கூறுவான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَيَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَعَضُّ</span> <span class=\"quran-arabic-font text-success\">الظَّـلِمُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لَيْتَنِي</span> <span class=\"quran-arabic-font text-success\">اتَّخَذْتُ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولِ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span> - <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">وَيْلَتَى</span> <span class=\"quran-arabic-font text-success\">لَيْتَنِى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">أَتَّخِذْ</span> <span class=\"quran-arabic-font text-success\">فُلاَناً</span> <span class=\"quran-arabic-font text-success\">خَلِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(“அந்தோ! நான் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு வழியைத் தேர்ந்தெடுத்திருக்க வேண்டாமா? எனக்கு ஏற்பட்ட அழிவே! நான் இன்னாரை ஒரு நெருங்கிய நண்பனாக ஆக்கிக்கொள்ளாமல் இருந்திருக்கக்கூடாதா!” என்று கூறுவான்). அதாவது, நேர்வழியிலிருந்து அவனைத் திசைதிருப்பி, வழிகேட்டின் பாதையைப் பின்பற்றச் செய்த வழிகெடுப்பவர்களில் ஒருவன். இது உமையா பின் கலஃபையோ அல்லது அவனது சகோதரன் உபை பின் கலஃபையோ அல்லது வேறு யாரையுமோ குறிக்கலாம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَّقَدْ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّنِى</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرِ﴿</span><br />\r\n(நிச்சயமாக அவன் இந்த நல்லுபதேசத்திலிருந்து (குர்ஆனிலிருந்து) என்னை வழிதவறச் செய்துவிட்டான்), <span class=\"quran-arabic-font text-success\">﴾بَعْدَ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَآءَنِى﴿</span> (அது என்னிடம் வந்த பிறகு). அதாவது அச்செய்தி என்னை வந்தடைந்த பின்னரும் அவன் என்னை வழிகெடுத்தான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَكَانَ</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَـنُ</span> <span class=\"quran-arabic-font text-success\">لِلإِنْسَـنِ</span> <span class=\"quran-arabic-font text-success\">خَذُولاً﴿</span> (மேலும் ஷைத்தான் மனிதனுக்கு (நெருக்கடியான நேரத்தில்) உதவி செய்யாமல் கைவிட்டுவிடுபவனாக இருக்கிறான்). அதாவது, அவன் மனிதனை உண்மையிலிருந்து விலக்கி வழிகெடுத்து, அவனைப் பொய்யான காரியங்களில் ஈடுபடுத்தி, அவற்றுக்கே அழைக்கிறான். பின்னர் (ஆபத்து நேரத்தில்) அவனைக் கைவிட்டு விடுகிறான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"மறுமை நாளின் திடுக்கிடும் நிகழ்வுகளும், அநியாயக்காரர்கள் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு நேர்வழியைப் பின்பற்றியிருக்க வேண்டுமே என ஏங்குவதும்\n\r\n\n\r\nஇங்கே அல்லாஹ் மறுமை நாளின் பயங்கரங்களைப் பற்றியும், அன்று நிகழவிருக்கும் மகத்தான நிகழ்வுகளைப் பற்றியும் நமக்குக் கூறுகிறான். பார்வைகளைப் பறிக்கக்கூடிய பிரம்மாண்டமான ஒளியின் நிழலாகிய மேகக்கூட்டங்களால் வானங்கள் பிளக்கப்படுவதும் அதில் அடங்கும். அந்நாளில் வானவர்கள் வானிலிருந்து இறங்கி வந்து, மக்கள் ஒன்றுதிரட்டப்படும் இடத்தில் அனைத்துப் படைப்புகளையும் சூழ்ந்துகொள்வார்கள். பின்னர், கண்ணியமும் உயர்வும் மிக்க இறைவனாகிய அல்லாஹ் தீர்ப்பு வழங்குவதற்காக வருவான். முஜாஹித் (ரஹ்) அவர்கள் கூறினார்கள்: \"இது அல்லாஹ் கூறுவதைப் போன்றதாகும்: ﴾هَلْ يَنظُرُونَ إِلاَّ أَن يَأْتِيَهُمُ اللَّهُ فِي ظُلَلٍ مِّنَ الْغَمَامِ وَالْمَلَـئِكَةُ﴿ (மேகங்களின் நிழல்களில் அல்லாஹ்வும் வானவர்களும் அவர்களிடம் வருவதைத் தவிர வேறு எதையேனும் அவர்கள் எதிர்பார்க்கிறார்களா?)\" (2:210).\n\r\n\n\r\n﴾الْمُلْكُ يَوْمَئِذٍ الْحَقُّ لِلرَّحْمَـنِ﴿\n\r\n(அந்நாளில் உண்மையான அதிகாரம் அளவற்ற அருளாளனுக்கே உரியது). இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾لِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَحِدِ الْقَهَّارِ﴿ (“இன்றைய தினம் ஆட்சி யாருக்குரியது? அடக்கியாளும் ஒருவனான அல்லாஹ்வுக்கே உரியது!”) (40:16). ஸஹீஹ் நூல்களில் இவ்வாறு இடம்பெற்றுள்ளது: ﴾«أَنَّ اللهَ تَعَالَى يَطْوِي السَّمَوَاتِ بِيَمِينِهِ، وَيَأْخُذُ الْأَرَضِينَ بِيَدِهِ الْأُخْرَى، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ أَنَا الدَّيَّانُ، أَيْنَ مُلُوكُ الْأَرْضِ؟ أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟»﴿ (உயர்ந்தோனாகிய அல்லாஹ் வானங்களைத் தனது வலது கையால் சுருட்டி, பூமிகளைத் தனது மற்றொரு கையால் பிடித்துக் கொள்வான். பின்னர் அவன் கூறுவான்: “நானே அரசன், நானே நீதிபதி. பூமியின் மன்னர்கள் எங்கே? அக்கிரமக்காரர்கள் எங்கே? பெருமையடித்தவர்கள் எங்கே?”).\n\r\n\n\r\n﴾وَكَانَ يَوْماً عَلَى الْكَـفِرِينَ عَسِيراً﴿\n\r\n(மேலும் அது நிராகரிப்பாளர்களுக்குக் கடினமான நாளாக இருக்கும்). அதாவது அந்நாள் மிகவும் சிரமமானதாக இருக்கும். ஏனெனில் அது நீதியும் தீர்க்கமான தீர்ப்பும் வழங்கப்படும் நாளாகும். அல்லாஹ் கூறுவது போல: ﴾فَذَلِكَ يَوْمَئِذٍ يَوْمٌ عَسِيرٌ - عَلَى الْكَـفِرِينَ غَيْرُ يَسِيرٍ ﴿ (நிச்சயமாக அந்நாள் ஒரு கடினமான நாளாகும்; அது நிராகரிப்பாளர்களுக்கு எளிதானதல்ல) (74:9-10). மறுமை நாளில் நிராகரிப்பாளர்களின் நிலை இவ்வாறே இருக்கும். ஆனால் இறைநம்பிக்கையாளர்களைப் பற்றி அல்லாஹ் கூறுகிறான்: ﴾لاَ يَحْزُنُهُمُ الْفَزَعُ الاٌّكْبَرُ﴿ (அந்த மாபெரும் திடுக்கிடும் நிகழ்வு அவர்களைத் துயரப்படுத்தாது).\n\r\n\n\r\n﴾وَيَوْمَ يَعَضُّ الظَّـلِمُ عَلَى يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلاً ﴿\n\r\n(அநியாயக்காரன் தன் கைகளைக் கடித்துக்கொண்டு, “அந்தோ! நான் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு வழியைத் தேர்ந்தெடுத்திருக்க வேண்டாமா?” என்று கூறும் நாளை (நினைவுகூருவீராக)). அல்லாஹ்வின் தூதர் (ஸல்) காட்டிய வழியையும், அவர் (ஸல்) அல்லாஹ்விடமிருந்து கொண்டு வந்த சந்தேகத்திற்கு இடமற்ற தெளிவான உண்மையையும் நிராகரித்துவிட்டு, வேறு பாதையைப் பின்பற்றிய அநியாயக்காரன் அடையும் கைசேதத்தைப் பற்றி இங்கே அல்லாஹ் கூறுகிறான். மறுமை நாள் வரும்போது அவன் மிகவும் வருந்துவான்; ஆனால் அந்த வருத்தம் அவனுக்கு எந்தப் பயனும் அளிக்காது. மாறாக, துக்கத்தாலும் கவலையாலும் அவன் தன் கைகளைக் கடித்துக்கொள்வான். இந்த வசனம் உக்பா பின் அபீ முஐத் என்பவரைப் பற்றி அல்லது நாசமடைந்தவர்களில் வேறொருவரைப் பற்றி இறக்கப்பட்டிருந்தாலும், இது ஒவ்வொரு அநியாயக்காரனுக்கும் பொருந்தும். அல்லாஹ் பின்வருமாறு கூறுகிறான்: ﴾يَوْمَ تُقَلَّبُ وُجُوهُهُمْ فِى النَّارِ﴿ (நெருப்பில் அவர்களுடைய முகங்கள் புரட்டப்படும் நாளில்...) (33:66). இவ்வாறு ஒவ்வொரு அநியாயக்காரனும் மறுமை நாளில் உச்சகட்டக் கைசேதத்தை உணர்ந்து, தன் கைகளைக் கடித்துக்கொண்டு பின்வருமாறு கூறுவான்:\n\r\n\n\r\n﴾وَيَوْمَ يَعَضُّ الظَّـلِمُ عَلَى يَدَيْهِ يَقُولُ يَا لَيْتَنِي اتَّخَذْتُ مَعَ الرَّسُولِ سَبِيلاً - يَا وَيْلَتَى لَيْتَنِى لَمْ أَتَّخِذْ فُلاَناً خَلِيلاً ﴿\n\r\n(“அந்தோ! நான் அல்லாஹ்வின் தூதருடன் (ஸல்) ஒரு வழியைத் தேர்ந்தெடுத்திருக்க வேண்டாமா? எனக்கு ஏற்பட்ட அழிவே! நான் இன்னாரை ஒரு நெருங்கிய நண்பனாக ஆக்கிக்கொள்ளாமல் இருந்திருக்கக்கூடாதா!” என்று கூறுவான்). அதாவது, நேர்வழியிலிருந்து அவனைத் திசைதிருப்பி, வழிகேட்டின் பாதையைப் பின்பற்றச் செய்த வழிகெடுப்பவர்களில் ஒருவன். இது உமையா பின் கலஃபையோ அல்லது அவனது சகோதரன் உபை பின் கலஃபையோ அல்லது வேறு யாரையுமோ குறிக்கலாம்.\n\r\n\n\r\n﴾لَّقَدْ أَضَلَّنِى عَنِ الذِّكْرِ﴿\n\r\n(நிச்சயமாக அவன் இந்த நல்லுபதேசத்திலிருந்து (குர்ஆனிலிருந்து) என்னை வழிதவறச் செய்துவிட்டான்), ﴾بَعْدَ إِذْ جَآءَنِى﴿ (அது என்னிடம் வந்த பிறகு). அதாவது அச்செய்தி என்னை வந்தடைந்த பின்னரும் அவன் என்னை வழிகெடுத்தான். அல்லாஹ் கூறுகிறான்: ﴾وَكَانَ الشَّيْطَـنُ لِلإِنْسَـنِ خَذُولاً﴿ (மேலும் ஷைத்தான் மனிதனுக்கு (நெருக்கடியான நேரத்தில்) உதவி செய்யாமல் கைவிட்டுவிடுபவனாக இருக்கிறான்). அதாவது, அவன் மனிதனை உண்மையிலிருந்து விலக்கி வழிகெடுத்து, அவனைப் பொய்யான காரியங்களில் ஈடுபடுத்தி, அவற்றுக்கே அழைக்கிறான். பின்னர் (ஆபத்து நேரத்தில்) அவனைக் கைவிட்டு விடுகிறான்."},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=31\" class=\"link\">25:31</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:31 ஐ பார்க்கவும்"},"31":{"html":"<strong>அல்லாஹ்வின் தூதர் தம் எதிரிகளுக்கு எதிராக முறையிடுவார்கள்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمِي</span> <span class=\"quran-arabic-font text-success\">اتَّخَذُوا</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">مَهْجُورًا</span><br />\r\n<br />\r\n(தூதர் கூறினார்: \"என் இறைவா! நிச்சயமாக என் சமூகத்தார் இந்தக் குர்ஆனைப் புறக்கணித்துவிட்டனர்.\")<br />\r\n<br />\r\nதனது தூதரும் நபியுமான முஹம்மது (ஸல்) அவர்கள், \"என் இறைவா! நிச்சயமாக எனது சமூகத்தினர் இந்த குர்ஆனைப் புறக்கணித்துவிட்டனர்\" என்று எவ்வாறு முறையிடுவார்கள் என்பதை அல்லாஹ் கூறுகிறான். இணைவைப்பாளர்கள் குர்ஆனைச் செவிமடுக்க மாட்டார்கள். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُوا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَسْمَعُوا</span> <span class=\"quran-arabic-font text-success\">لِهَذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنِ</span> <span class=\"quran-arabic-font text-success\">وَالْغَوْا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(நிராகரிப்பவர்கள் கூறுகின்றனர்: \"இந்த குர்ஆனை நீங்கள் செவியுறாதீர்கள்; அது ஓதப்படும்போது கூச்சலிடுங்கள்.\") (<a href=\"qurandisp.php?sura=41&ayah=26\" class=\"link\">41:26</a>). நபி (ஸல்) அவர்கள் அவர்களுக்கு குர்ஆனை ஓதிக்காட்டும்போது, அவர்கள் அதைக் கேட்காமல் இருப்பதற்காக வீண் பேச்சுகளைப் பேசுவார்கள் அல்லது வேறு ஏதேனும் விஷயங்களைப் பற்றிப் பேசுவார்கள். இதுவும் குர்ஆனைப் புறக்கணிப்பதன் ஒரு வடிவமாகும். அதன்பேரில் நம்பிக்கை கொள்ளாமல் இருப்பது, அதன் கருத்துகளைச் சிந்தித்து விளங்காமல் இருப்பது, அதன்படி செயல்படாமல் அதன் கட்டளைகளைப் புறக்கணிப்பது மற்றும் அதன் விலக்கல்களைப் பேணாமல் இருப்பது ஆகிய அனைத்தும் குர்ஆனைப் புறக்கணிப்பதே ஆகும். மேலும் கவிதைகள், வீண் பேச்சுகள், பாடல்கள் அல்லது வேறு ஏதேனும் பொழுதுபோக்குகளில் மூழ்கி குர்ஆனை விட்டு விலகிச் செல்வதும் அதைப் புறக்கணிப்பதே ஆகும். தான் நாடுவதைச் செய்ய ஆற்றலுள்ளவனும், அருட்கொடைகளை வாரி வழங்குபவனுமான கண்ணியமிக்க அல்லாஹ்விடம், அவனது கோபத்திற்கு ஆளாக்கும் இத்தகைய செயல்களில் இருந்து நம்மைப் பாதுகாக்குமாறு வேண்டுகிறோம். மேலும், அவனது வேதத்தைப் பாதுகாத்து, அதனைப் புரிந்து கொண்டு, அவன் விரும்பும் மற்றும் திருப்தியடையும் வகையில் இரவும் பகலும் அதன் கட்டளைகளைப் பின்பற்றி நடக்கும் நற்பேற்றை நமக்கு வழங்குமாறும் அவனிடம் வேண்டுகிறோம். நிச்சயமாக அவன் தாராளமானவனும் மிக்க அன்புடையவனும் ஆவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">نَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">عَدُوّاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span><br />\r\n<br />\r\n(இவ்வாறே, ஒவ்வொரு நபிக்கும் குற்றவாளிகளிலிருந்து நாம் ஒரு எதிரியை ஏற்படுத்தினோம்.) இதன் பொருள், \"முஹம்மதே (ஸல்)! குர்ஆனை இழிவுபடுத்தும் இத்தகைய மக்கள் உங்களுக்கு இருப்பதைப் போலவே, முந்தைய ஒவ்வொரு சமுதாயத்திலும் நாம் ஒவ்வொரு நபிக்கும் (அலை) குற்றவாளிகளிலிருந்து ஒரு எதிரியை ஏற்படுத்தியிருந்தோம். அவர்கள் மக்களைத் தங்கள் வழிகேடு மற்றும் நிராகரிப்பின் பக்கம் அழைத்தனர்\" என்பதாகும். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لِكُلِّ</span> <span class=\"quran-arabic-font text-success\">نَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">عَدُوّاً</span> <span class=\"quran-arabic-font text-success\">شَيَاطِينَ</span> <span class=\"quran-arabic-font text-success\">الإِنْسِ</span> <span class=\"quran-arabic-font text-success\">وَالْجِنِّ</span><br />\r\n<br />\r\n(இவ்வாறே, ஒவ்வொரு நபிக்கும் மனிதர்களிலும் ஜின்களிலும் உள்ள ஷைத்தான்களை நாம் எதிரிகளாக்கினோம்) என்று இந்த இரு வசனங்களிலும் (<a href=\"qurandisp.php?sura=6&ayah=112\" class=\"link\">6:112</a>) கூறப்பட்டுள்ளது. அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَفَى</span> <span class=\"quran-arabic-font text-success\">بِرَبِّكَ</span> <span class=\"quran-arabic-font text-success\">هَادِياً</span> <span class=\"quran-arabic-font text-success\">وَنَصِيراً</span><br />\r\n<br />\r\n(ஆனால், வழிகாட்டியாகவும் உதவியாளனாகவும் உமது இறைவனே போதுமானவன்.) அதாவது, அல்லாஹ்வின் தூதரைப் (ஸல்) பின்பற்றி, அவனது வேதத்தின் மீது நம்பிக்கை கொள்கிறவருக்கு, அல்லாஹ் இவ்வுலகிலும் மறுமையிலும் வழிகாட்டியாகவும் உதவியாளனாகவும் இருப்பான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَادِياً</span> <span class=\"quran-arabic-font text-success\">وَنَصِيراً</span><br />\r\n<br />\r\n(வழிகாட்டியாகவும் உதவியாளனாகவும்.) ஏனெனில், குர்ஆனின் மூலம் எவரும் நேர்வழி பெற்றுவிடக் கூடாது என்பதற்காக, மக்கள் அதனைப் பின்பற்றுவதைத் தடுக்க இணைவைப்பாளர்கள் முயன்றனர். குர்ஆனின் வழியை விடத் தங்கள் வழியே மேலோங்க வேண்டும் என்று அவர்கள் விரும்பினர். எனவே அல்லாஹ் கூறுகிறான்: \"உமது இறைவனே போதுமானவன்\" என்று கூறப்பட்டுள்ளது.<br />\r\n<br />","text":"அல்லாஹ்வின் தூதர் தம் எதிரிகளுக்கு எதிராக முறையிடுவார்கள்\n\r\n\n\r\nوَقَالَ الرَّسُولُ يَا رَبِّ إِنَّ قَوْمِي اتَّخَذُوا هَذَا الْقُرْآنَ مَهْجُورًا\n\r\n\n\r\n(தூதர் கூறினார்: \"என் இறைவா! நிச்சயமாக என் சமூகத்தார் இந்தக் குர்ஆனைப் புறக்கணித்துவிட்டனர்.\")\n\r\n\n\r\nதனது தூதரும் நபியுமான முஹம்மது (ஸல்) அவர்கள், \"என் இறைவா! நிச்சயமாக எனது சமூகத்தினர் இந்த குர்ஆனைப் புறக்கணித்துவிட்டனர்\" என்று எவ்வாறு முறையிடுவார்கள் என்பதை அல்லாஹ் கூறுகிறான். இணைவைப்பாளர்கள் குர்ஆனைச் செவிமடுக்க மாட்டார்கள். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَقَالَ الَّذِينَ كَفَرُوا لاَ تَسْمَعُوا لِهَذَا الْقُرْآنِ وَالْغَوْا فِيهِ\n\r\n\n\r\n(நிராகரிப்பவர்கள் கூறுகின்றனர்: \"இந்த குர்ஆனை நீங்கள் செவியுறாதீர்கள்; அது ஓதப்படும்போது கூச்சலிடுங்கள்.\") (41:26). நபி (ஸல்) அவர்கள் அவர்களுக்கு குர்ஆனை ஓதிக்காட்டும்போது, அவர்கள் அதைக் கேட்காமல் இருப்பதற்காக வீண் பேச்சுகளைப் பேசுவார்கள் அல்லது வேறு ஏதேனும் விஷயங்களைப் பற்றிப் பேசுவார்கள். இதுவும் குர்ஆனைப் புறக்கணிப்பதன் ஒரு வடிவமாகும். அதன்பேரில் நம்பிக்கை கொள்ளாமல் இருப்பது, அதன் கருத்துகளைச் சிந்தித்து விளங்காமல் இருப்பது, அதன்படி செயல்படாமல் அதன் கட்டளைகளைப் புறக்கணிப்பது மற்றும் அதன் விலக்கல்களைப் பேணாமல் இருப்பது ஆகிய அனைத்தும் குர்ஆனைப் புறக்கணிப்பதே ஆகும். மேலும் கவிதைகள், வீண் பேச்சுகள், பாடல்கள் அல்லது வேறு ஏதேனும் பொழுதுபோக்குகளில் மூழ்கி குர்ஆனை விட்டு விலகிச் செல்வதும் அதைப் புறக்கணிப்பதே ஆகும். தான் நாடுவதைச் செய்ய ஆற்றலுள்ளவனும், அருட்கொடைகளை வாரி வழங்குபவனுமான கண்ணியமிக்க அல்லாஹ்விடம், அவனது கோபத்திற்கு ஆளாக்கும் இத்தகைய செயல்களில் இருந்து நம்மைப் பாதுகாக்குமாறு வேண்டுகிறோம். மேலும், அவனது வேதத்தைப் பாதுகாத்து, அதனைப் புரிந்து கொண்டு, அவன் விரும்பும் மற்றும் திருப்தியடையும் வகையில் இரவும் பகலும் அதன் கட்டளைகளைப் பின்பற்றி நடக்கும் நற்பேற்றை நமக்கு வழங்குமாறும் அவனிடம் வேண்டுகிறோம். நிச்சயமாக அவன் தாராளமானவனும் மிக்க அன்புடையவனும் ஆவான்.\n\r\n\n\r\nوَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوّاً مِّنَ الْمُجْرِمِينَ\n\r\n\n\r\n(இவ்வாறே, ஒவ்வொரு நபிக்கும் குற்றவாளிகளிலிருந்து நாம் ஒரு எதிரியை ஏற்படுத்தினோம்.) இதன் பொருள், \"முஹம்மதே (ஸல்)! குர்ஆனை இழிவுபடுத்தும் இத்தகைய மக்கள் உங்களுக்கு இருப்பதைப் போலவே, முந்தைய ஒவ்வொரு சமுதாயத்திலும் நாம் ஒவ்வொரு நபிக்கும் (அலை) குற்றவாளிகளிலிருந்து ஒரு எதிரியை ஏற்படுத்தியிருந்தோம். அவர்கள் மக்களைத் தங்கள் வழிகேடு மற்றும் நிராகரிப்பின் பக்கம் அழைத்தனர்\" என்பதாகும். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَكَذَلِكَ جَعَلْنَا لِكُلِّ نَبِيٍّ عَدُوّاً شَيَاطِينَ الإِنْسِ وَالْجِنِّ\n\r\n\n\r\n(இவ்வாறே, ஒவ்வொரு நபிக்கும் மனிதர்களிலும் ஜின்களிலும் உள்ள ஷைத்தான்களை நாம் எதிரிகளாக்கினோம்) என்று இந்த இரு வசனங்களிலும் (6:112) கூறப்பட்டுள்ளது. அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nوَكَفَى بِرَبِّكَ هَادِياً وَنَصِيراً\n\r\n\n\r\n(ஆனால், வழிகாட்டியாகவும் உதவியாளனாகவும் உமது இறைவனே போதுமானவன்.) அதாவது, அல்லாஹ்வின் தூதரைப் (ஸல்) பின்பற்றி, அவனது வேதத்தின் மீது நம்பிக்கை கொள்கிறவருக்கு, அல்லாஹ் இவ்வுலகிலும் மறுமையிலும் வழிகாட்டியாகவும் உதவியாளனாகவும் இருப்பான்.\n\r\n\n\r\nهَادِياً وَنَصِيراً\n\r\n\n\r\n(வழிகாட்டியாகவும் உதவியாளனாகவும்.) ஏனெனில், குர்ஆனின் மூலம் எவரும் நேர்வழி பெற்றுவிடக் கூடாது என்பதற்காக, மக்கள் அதனைப் பின்பற்றுவதைத் தடுக்க இணைவைப்பாளர்கள் முயன்றனர். குர்ஆனின் வழியை விடத் தங்கள் வழியே மேலோங்க வேண்டும் என்று அவர்கள் விரும்பினர். எனவே அல்லாஹ் கூறுகிறான்: \"உமது இறைவனே போதுமானவன்\" என்று கூறப்பட்டுள்ளது."},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=34\" class=\"link\">25:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:34 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=34\" class=\"link\">25:34</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:34 ஐ பார்க்கவும்"},"34":{"html":"<strong>குர்ஆன் ஏன் படிப்படியாக அருளப்பட்டது என்பதற்கான காரணம், நிராகரிப்பாளர்களுக்கு மறுப்பு மற்றும் அவர்களின் தீய நிலை</strong><br />\r\n<br />\r\nநிராகரிப்பாளர்கள் எழுப்பிய பல ஆட்சேபனைகள், அவர்களின் பிடிவாதம் மற்றும் தங்களுக்குச் சம்பந்தமில்லாத விஷயங்களைப் பற்றி அவர்கள் பேசியது குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள்: <span class=\"quran-arabic-font text-success\">﴾لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">نُزِّلَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْقُرْءَانُ</span> <span class=\"quran-arabic-font text-success\">جُمْلَةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً﴿</span> (\"இந்தக் குர்ஆன் அவருக்கு ஏன் ஒரே முறையாக அருளப்படவில்லை?\") என்று கூறினார்கள். அதாவது, அவருக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்ட இந்தக் குர்ஆன், தவ்ராத், இன்ஜீல், ஸபூர் மற்றும் பிற முந்தைய இறைவேதங்களைப் போல ஏன் ஒரே நேரத்தில் அருளப்படவில்லை (என்று கேட்டார்கள்). அவர்களுக்குப் பதிலளிக்கும் விதமாக, இறைநம்பிக்கையாளர்களின் உள்ளங்களை உறுதிப்படுத்துவதற்காக, நிகழ்வுகள் மற்றும் சூழ்நிலைகளுக்கு ஏற்பவும், தேவையான சட்டதிட்டங்களுக்கு ஏற்பவும், இருபத்தி மூன்று ஆண்டுகளில் இது படிப்படியாக அருளப்பட்டது என்று அல்லாஹ் கூறுகிறான். அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقُرْءانًا</span> <span class=\"quran-arabic-font text-success\">فَرَقْنَاهُ﴿</span> (மேலும் (இது) ஒரு குர்ஆன், இதனை நாம் (பாகங்களாகப்) பிரித்துள்ளோம்...) (<a href=\"qurandisp.php?sura=17&ayah=106\" class=\"link\">17:106</a>).<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِنُثَبِّتَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">فُؤَادَكَ</span> <span class=\"quran-arabic-font text-success\">وَرَتَّلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">تَرْتِيلاً﴿</span> (\"அதன் மூலம் உமது உள்ளத்தை நாம் உறுதிப்படுத்துவதற்காகவே (இவ்வாறு செய்தோம்). மேலும், நாம் அதனை உமக்குத் தெளிவான முறையில் படிப்படியாக ஓதி காண்பித்தோம்.\") இதன் பொருள்: \"நாம் அதனை விளக்கியுள்ளோம்\" என்று கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள். \"நாம் அதன் விளக்கத்தை அளித்துள்ளோம்\" என்று அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரஹ்) அவர்கள் கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَكَ</span> <span class=\"quran-arabic-font text-success\">بِمَثَلٍ﴿</span> (\"அவர்கள் உம்மிடம் எந்த ஓர் உதாரணத்தைக் கொண்டு வந்தாலும்,\") அதாவது எந்த ஒரு வாதத்தையோ அல்லது சந்தேகத்தையோ அவர்கள் எழுப்பினாலும், <span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جِئْنَاكَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">تَفْسِيراً﴿</span> (\"நாம் உமக்கு உண்மையையும், மிகச் சிறந்த விளக்கத்தையும் அளிக்காமல் இருப்பதில்லை.\") அவர்கள் சத்தியத்தை (உண்மையை) எதிர்ப்பதற்காக எதைக் கூறினாலும், அவர்கள் கூறுவதை விட மிகத் தெளிவாகவும், அழகாகவும் அந்த விஷயத்தின் உண்மையை நாம் அவர்களுக்குப் பதிலாகக் கூறுகிறோம்.<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாவது: \"குர்ஆன் முழுமையாக ஒரே நேரத்தில் லைலத்துல் கத்ர் இரவில் முதல் வானத்திற்கு இறக்கப்பட்டது. பிறகு அது இருபது ஆண்டுகளில் (படிப்படியாக) அருளப்பட்டது\" என்று அபூ அப்துர் ரஹ்மான் அந்-நஸாயீ பதிவு செய்துள்ளார். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَأْتُونَكَ</span> <span class=\"quran-arabic-font text-success\">بِمَثَلٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">جِئْنَاكَ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَأَحْسَنَ</span> <span class=\"quran-arabic-font text-success\">تَفْسِيراً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (\"அவர்கள் உம்மிடம் எந்த ஓர் உதாரணத்தைக் கொண்டு வந்தாலும், நாம் உமக்கு உண்மையையும், மிகச் சிறந்த விளக்கத்தையும் அளிக்காமல் இருப்பதில்லை.\") மேலும்: <span class=\"quran-arabic-font text-success\">﴾وَقُرْءانًا</span> <span class=\"quran-arabic-font text-success\">فَرَقْنَاهُ</span> <span class=\"quran-arabic-font text-success\">لِتَقْرَأَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مُكْثٍ</span> <span class=\"quran-arabic-font text-success\">وَنَزَّلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">تَنْزِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (\"மேலும், மனிதர்களுக்கு நீர் நிதானமாக ஓதிக் காண்பிப்பதற்காகவே இந்தக் குர்ஆனை நாம் பாகங்களாகப் பிரித்தோம்; மேலும் நாம் இதனைப் படிப்படியாகவே இறக்கி வைத்தோம்.\") (<a href=\"qurandisp.php?sura=17&ayah=106\" class=\"link\">17:106</a>).<br />\r\n<br />\r\nபிறகு, மறுமை நாளில் எழுப்பப்பட்டு நரகத்தை நோக்கி ஒன்றுதிரட்டப்படும் போது நிராகரிப்பாளர்களின் பயங்கரமான நிலையைப் பற்றி அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُحْشَرُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وُجُوهِهِمْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">أُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">شَرٌّ</span> <span class=\"quran-arabic-font text-success\">مَّكَاناً</span> <span class=\"quran-arabic-font text-success\">وَأَضَلُّ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span> (\"எவர்கள் தங்கள் முகங்குப்புற நரகத்தை நோக்கி ஒன்றுதிரட்டப்படுவார்களோ, அவர்கள் தாம் தங்குமிடத்தால் மிகக் கெட்டவர்கள்; மேலும் நேரான பாதையிலிருந்து மிகவும் வழிதவறியவர்கள்.\")<br />\r\n<br />\r\nபுகாரீ, முஸ்லிம் ஆகிய ஸஹீஹ் நூல்களில் அனஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஒரு மனிதர், \"அல்லாஹ்வின் தூதரே! மறுமை நாளில் நிராகரிப்பாளர் எவ்வாறு தன் முகத்தால் (நடந்து) ஒன்றுதிரட்டப்படுவார்?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">أَمْشَاهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رِجْلَيْهِ</span> <span class=\"quran-arabic-font text-success\">قَادِرٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُمْشِيَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">وَجْهِهِ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (\"இவ்வுலகில் அவனை இரண்டு கால்களால் நடக்கச் செய்தவன், மறுமை நாளில் அவனை அவனது முகத்தால் நடக்கச் செய்ய ஆற்றல் பெற்றவன்.\") கத்தாதா (ரஹ்) அவர்கள் (இதைக் கேட்டு): \"ஆம்! எங்கள் இறைவனின் கண்ணியத்தின் மீது ஆணையாக!\" என்று கூறினார்கள்.<br />\r\n<br />","text":"குர்ஆன் ஏன் படிப்படியாக அருளப்பட்டது என்பதற்கான காரணம், நிராகரிப்பாளர்களுக்கு மறுப்பு மற்றும் அவர்களின் தீய நிலை\n\r\n\n\r\nநிராகரிப்பாளர்கள் எழுப்பிய பல ஆட்சேபனைகள், அவர்களின் பிடிவாதம் மற்றும் தங்களுக்குச் சம்பந்தமில்லாத விஷயங்களைப் பற்றி அவர்கள் பேசியது குறித்து அல்லாஹ் நமக்குக் கூறுகிறான். அவர்கள்: ﴾لَوْلاَ نُزِّلَ عَلَيْهِ الْقُرْءَانُ جُمْلَةً وَاحِدَةً﴿ (\"இந்தக் குர்ஆன் அவருக்கு ஏன் ஒரே முறையாக அருளப்படவில்லை?\") என்று கூறினார்கள். அதாவது, அவருக்கு வஹீ (இறைச்செய்தி)யாக அருளப்பட்ட இந்தக் குர்ஆன், தவ்ராத், இன்ஜீல், ஸபூர் மற்றும் பிற முந்தைய இறைவேதங்களைப் போல ஏன் ஒரே நேரத்தில் அருளப்படவில்லை (என்று கேட்டார்கள்). அவர்களுக்குப் பதிலளிக்கும் விதமாக, இறைநம்பிக்கையாளர்களின் உள்ளங்களை உறுதிப்படுத்துவதற்காக, நிகழ்வுகள் மற்றும் சூழ்நிலைகளுக்கு ஏற்பவும், தேவையான சட்டதிட்டங்களுக்கு ஏற்பவும், இருபத்தி மூன்று ஆண்டுகளில் இது படிப்படியாக அருளப்பட்டது என்று அல்லாஹ் கூறுகிறான். அவன் கூறுகிறான்: ﴾وَقُرْءانًا فَرَقْنَاهُ﴿ (மேலும் (இது) ஒரு குர்ஆன், இதனை நாம் (பாகங்களாகப்) பிரித்துள்ளோம்...) (17:106).\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾كَذَلِكَ لِنُثَبِّتَ بِهِ فُؤَادَكَ وَرَتَّلْنَاهُ تَرْتِيلاً﴿ (\"அதன் மூலம் உமது உள்ளத்தை நாம் உறுதிப்படுத்துவதற்காகவே (இவ்வாறு செய்தோம்). மேலும், நாம் அதனை உமக்குத் தெளிவான முறையில் படிப்படியாக ஓதி காண்பித்தோம்.\") இதன் பொருள்: \"நாம் அதனை விளக்கியுள்ளோம்\" என்று கத்தாதா (ரஹ்) அவர்கள் கூறினார்கள். \"நாம் அதன் விளக்கத்தை அளித்துள்ளோம்\" என்று அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் (ரஹ்) அவர்கள் கூறினார்கள்.\n\r\n\n\r\n﴾وَلاَ يَأْتُونَكَ بِمَثَلٍ﴿ (\"அவர்கள் உம்மிடம் எந்த ஓர் உதாரணத்தைக் கொண்டு வந்தாலும்,\") அதாவது எந்த ஒரு வாதத்தையோ அல்லது சந்தேகத்தையோ அவர்கள் எழுப்பினாலும், ﴾إِلاَّ جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيراً﴿ (\"நாம் உமக்கு உண்மையையும், மிகச் சிறந்த விளக்கத்தையும் அளிக்காமல் இருப்பதில்லை.\") அவர்கள் சத்தியத்தை (உண்மையை) எதிர்ப்பதற்காக எதைக் கூறினாலும், அவர்கள் கூறுவதை விட மிகத் தெளிவாகவும், அழகாகவும் அந்த விஷயத்தின் உண்மையை நாம் அவர்களுக்குப் பதிலாகக் கூறுகிறோம்.\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாவது: \"குர்ஆன் முழுமையாக ஒரே நேரத்தில் லைலத்துல் கத்ர் இரவில் முதல் வானத்திற்கு இறக்கப்பட்டது. பிறகு அது இருபது ஆண்டுகளில் (படிப்படியாக) அருளப்பட்டது\" என்று அபூ அப்துர் ரஹ்மான் அந்-நஸாயீ பதிவு செய்துள்ளார். அல்லாஹ் கூறுகிறான்: ﴾وَلاَ يَأْتُونَكَ بِمَثَلٍ إِلاَّ جِئْنَاكَ بِالْحَقِّ وَأَحْسَنَ تَفْسِيراً ﴿ (\"அவர்கள் உம்மிடம் எந்த ஓர் உதாரணத்தைக் கொண்டு வந்தாலும், நாம் உமக்கு உண்மையையும், மிகச் சிறந்த விளக்கத்தையும் அளிக்காமல் இருப்பதில்லை.\") மேலும்: ﴾وَقُرْءانًا فَرَقْنَاهُ لِتَقْرَأَهُ عَلَى النَّاسِ عَلَى مُكْثٍ وَنَزَّلْنَاهُ تَنْزِيلاً ﴿ (\"மேலும், மனிதர்களுக்கு நீர் நிதானமாக ஓதிக் காண்பிப்பதற்காகவே இந்தக் குர்ஆனை நாம் பாகங்களாகப் பிரித்தோம்; மேலும் நாம் இதனைப் படிப்படியாகவே இறக்கி வைத்தோம்.\") (17:106).\n\r\n\n\r\nபிறகு, மறுமை நாளில் எழுப்பப்பட்டு நரகத்தை நோக்கி ஒன்றுதிரட்டப்படும் போது நிராகரிப்பாளர்களின் பயங்கரமான நிலையைப் பற்றி அல்லாஹ் கூறுகிறான்: ﴾الَّذِينَ يُحْشَرُونَ عَلَى وُجُوهِهِمْ إِلَى جَهَنَّمَ أُوْلَـئِكَ شَرٌّ مَّكَاناً وَأَضَلُّ سَبِيلاً ﴿ (\"எவர்கள் தங்கள் முகங்குப்புற நரகத்தை நோக்கி ஒன்றுதிரட்டப்படுவார்களோ, அவர்கள் தாம் தங்குமிடத்தால் மிகக் கெட்டவர்கள்; மேலும் நேரான பாதையிலிருந்து மிகவும் வழிதவறியவர்கள்.\")\n\r\n\n\r\nபுகாரீ, முஸ்லிம் ஆகிய ஸஹீஹ் நூல்களில் அனஸ் (ரழி) அவர்கள் அறிவிக்கிறார்கள்: ஒரு மனிதர், \"அல்லாஹ்வின் தூதரே! மறுமை நாளில் நிராகரிப்பாளர் எவ்வாறு தன் முகத்தால் (நடந்து) ஒன்றுதிரட்டப்படுவார்?\" என்று கேட்டார். அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِنَّ الَّذِي أَمْشَاهُ عَلَى رِجْلَيْهِ قَادِرٌ عَلَى أَنْ يُمْشِيَهُ عَلَى وَجْهِهِ يَوْمَ الْقِيَامَة»﴿ (\"இவ்வுலகில் அவனை இரண்டு கால்களால் நடக்கச் செய்தவன், மறுமை நாளில் அவனை அவனது முகத்தால் நடக்கச் செய்ய ஆற்றல் பெற்றவன்.\") கத்தாதா (ரஹ்) அவர்கள் (இதைக் கேட்டு): \"ஆம்! எங்கள் இறைவனின் கண்ணியத்தின் மீது ஆணையாக!\" என்று கூறினார்கள்."},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=40\" class=\"link\">25:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:40 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=40\" class=\"link\">25:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:40 ஐ பார்க்கவும்"},"37":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=40\" class=\"link\">25:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:40 ஐ பார்க்கவும்"},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=40\" class=\"link\">25:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:40 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=40\" class=\"link\">25:40</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:40 ஐ பார்க்கவும்"},"40":{"html":"<strong>குரைஷி இணைவைப்பாளர்களை அச்சுறுத்துதல்</strong><br />\r\n<br />\r\nதனது தூதர் முஹம்மது (ஸல்) அவர்களை நிராகரித்து எதிர்த்த இணைவைப்பாளர்களை அல்லாஹ் அச்சுறுத்துகிறான். தங்களது தூதர்களை நிராகரித்த முந்தைய சமூகங்களுக்கு அவன் அனுப்பிய தண்டனை மற்றும் வேதனையான வேதனை குறித்து அவர்களை எச்சரிக்கிறான். அல்லாஹ் மூஸா (அலை) அவர்களைப் பற்றிக் குறிப்பிடுவதிலிருந்து தொடங்குகிறான். அவருக்கு ஒரு உதவியாளராக - அதாவது அவருக்கு உதவி செய்து ஆதரவளிக்கக்கூடிய மற்றொரு நபியாக - அவருடைய சகோதரர் ஹாரூன் (அலை) அவர்களையும் சேர்த்து அல்லாஹ் அனுப்பினான். ஆனால், ஃபிர்அவ்னும் அவனது தலைவர்களும் அவர்கள் இருவரையும் பொய்ப்பித்தனர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">دَمَّرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">وَلِلْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">أَمْثَـلُهَا</span><br />\r\n<br />\r\n(அல்லாஹ் அவர்களை அடியோடு அழித்துவிட்டான், மேலும் நிராகரிப்பாளர்களுக்கும் இது போன்றதே (காத்திருக்கிறது)) (<a href=\"qurandisp.php?sura=47&ayah=10\" class=\"link\">47:10</a>). நூஹ் (அலை) அவர்களின் சமூகத்தினர் அவரைப் பொய்ப்பித்தபோது, அல்லாஹ் அவர்களையும் அவ்வாறே அழித்தான். ஏனெனில், ஒரு தூதரை நிராகரிப்பவர் அனைத்து தூதர்களையும் நிராகரித்தவர் ஆவார்; ஏனெனில், ஒரு தூதருக்கும் மற்றொரு தூதருக்கும் இடையில் எந்த வேறுபாடும் இல்லை. அல்லாஹ் தனது தூதர்கள் அனைவரையும் அவர்களிடம் அனுப்பியிருந்தாலும், அவர்கள் அனைவரையும் அவர்கள் நிராகரித்திருப்பார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقَوْمَ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">لَّمَّا</span> <span class=\"quran-arabic-font text-success\">كَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">الرُّسُلَ</span><br />\r\n<br />\r\n(நூஹ் உடைய சமூகத்தினர் தூதர்களைப் பொய்ப்பித்தபோது,) அல்லாஹ் நூஹ் (அலை) அவர்களை மட்டுமே அவர்களிடம் அனுப்பியிருந்த போதிலும், அவர் 950 ஆண்டுகள் அவர்களிடையே தங்கியிருந்து, அவர்களை அல்லாஹ்வின் பக்கம் அழைத்து, அவனது தண்டனையைக் குறித்து எச்சரித்து வந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">قَلِيلٌ</span><br />\r\n<br />\r\n(அவருடன் மிகச் சிலரைத் தவிர வேறு எவரும் ஈமான் கொள்ளவில்லை) (<a href=\"qurandisp.php?sura=11&ayah=40\" class=\"link\">11:40</a>). இதன் காரணமாக, அல்லாஹ் அவர்கள் அனைவரையும் மூழ்கடித்தான். மேலும் கப்பலில் ஏறியவர்களைத் தவிர, ஆதமின் சந்ததிகளில் எவரையும் பூமியில் உயிருடன் விட்டுவைக்கவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلْنَـهُمْ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاسِ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span><br />\r\n<br />\r\n(மேலும், அவர்களை மனிதர்களுக்கு ஓர் அத்தாட்சியாக ஆக்கினோம்.) அதாவது, இதிலிருந்து ஒரு படிப்பினை பெற வேண்டும். இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">طَغَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءُ</span> <span class=\"quran-arabic-font text-success\">حَمَلْنَـكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْجَارِيَةِ</span> - <span class=\"quran-arabic-font text-success\">لِنَجْعَلَهَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">تَذْكِرَةً</span> <span class=\"quran-arabic-font text-success\">وَتَعِيَهَآ</span> <span class=\"quran-arabic-font text-success\">أُذُنٌ</span> <span class=\"quran-arabic-font text-success\">وَعِيَةٌ</span><br />\r\n<br />\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டிப் பொங்கியபோது, நாம் உங்களைக் கப்பலில் சுமந்தோம். அதனை உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காகவும், அதனை நினைவில் கொள்ளும் காதுகள் நினைவில் கொள்வதற்காகவும்) (<a href=\"qurandisp.php?sura=69&ayah=11\" class=\"link\">69:11</a>-12). இதன் பொருள்: \"நீங்கள் கடலின் ஆழமான பகுதிகளில் பயணம் செய்வதற்காக, நீங்கள் ஏறிச் செல்லும் கப்பல்களை நாம் உங்களுக்காக விட்டுவைத்தோம். இதன் மூலம், அல்லாஹ் உங்களை மூழ்குவதிலிருந்து காப்பாற்றிய அவனது அருட்கொடையை நீங்கள் நினைவு கூர்வதற்காகவும், அவனை விசுவாசித்து அவனது கட்டளைகளைப் பின்பற்றியவர்களின் சந்ததிகளாக உங்களை ஆக்கியதற்காகவும் ஆகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعَاداً</span> <span class=\"quran-arabic-font text-success\">وَثَمُودَاْ</span> <span class=\"quran-arabic-font text-success\">وَأَصْحَـبَ</span> <span class=\"quran-arabic-font text-success\">الرَّسِّ</span><br />\r\n<br />\r\n(மேலும், ஆது, ஸமூது மற்றும் அர்-ரஸ் வாசிகளை (அழித்தோம்).) இவர்களுடைய வரலாற்றை சூரத்துல் அஃராஃப் போன்ற ஒன்றுக்கு மேற்பட்ட சூராக்களில் நாம் ஏற்கனவே விளக்கியுள்ளோம், எனவே அதை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை. அர்-ரஸ் வாசிகளைப் பற்றி இப்னு ஜுரைஜ் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்கள் ஸமூது சமூகத்தின் கிராமங்களில் ஒன்றின் மக்கள்.\" அத்-தவ்ரீ அவர்கள் அபூ பக்ர் வழியாக இக்ரிமா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அர்-ரஸ் என்பது அவர்கள் தங்களது நபியைப் புதைத்த (ரஸ்ஸு) ஒரு கிணறு ஆகும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَقُرُوناً</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span><br />\r\n<br />\r\n(மேலும் இவற்றுக்கு இடையே இன்னும் பல தலைமுறையினரையும் (அழித்தோம்).) இதன் பொருள், இங்கே குறிப்பிடப்பட்டுள்ளவர்களைத் தவிர இன்னும் பல சமூகங்களை நாம் அழித்தோம். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلاًّ</span> <span class=\"quran-arabic-font text-success\">ضَرَبْنَا</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْأَمْثَالَ</span><br />\r\n<br />\r\n(ஒவ்வொருவருக்கும் நாம் உதாரணங்களை விவரித்தோம்,) அதாவது, \"நாம் அவர்களுக்கு ஆதாரங்களைக் காட்டி, தெளிவான சான்றுகளை வழங்கினோம்\" என்று கத்தாதா (ரழி) அவர்கள் கூறினார்கள். \"அவர்களுக்கு எந்தப் புகாரும் (சாக்குப்போக்கும்) இருக்கவில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلاًّ</span> <span class=\"quran-arabic-font text-success\">تَبَّرْنَا</span> <span class=\"quran-arabic-font text-success\">تَتْبِيراً</span><br />\r\n<br />\r\n(ஒவ்வொருவரையும் நாம் அடியோடு அழித்துவிட்டோம்.) இதன் பொருள் \"நாம் அவர்களை முழுமையாக அழித்துவிட்டோம்.\" இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَمْ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span><br />\r\n<br />\r\n(நூஹிற்குப் பிறகு எத்தனையோ தலைமுறையினரை நாம் அழித்திருக்கிறோம்!) (<a href=\"qurandisp.php?sura=17&ayah=17\" class=\"link\">17:17</a>). இங்கு 'தலைமுறைகள்' (குரூன்) என்பது மனிதர்களில் இருந்த சமூகங்களைக் குறிக்கும். இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَنشَأْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِمْ</span> <span class=\"quran-arabic-font text-success\">قُرُوناً</span> <span class=\"quran-arabic-font text-success\">ءَاخَرِينَ</span><br />\r\n<br />\r\n(பின்னர், அவர்களுக்குப் பிறகு மற்றத் தலைமுறையினரை நாம் உருவாக்கினோம்.) (<a href=\"qurandisp.php?sura=23&ayah=42\" class=\"link\">23:42</a>). ஒரு தலைமுறை என்பது 120 ஆண்டுகள் என்று சிலர் வரையறுத்தனர், அல்லது நூறு ஆண்டுகள், அல்லது எண்பது, அல்லது நாற்பது ஆண்டுகள் என்றும் கூறப்பட்டது. மிகச் சரியான கருத்து என்னவென்றால், ஒரு தலைமுறை என்பது ஒரே காலத்தில் வாழும் சமகாலத்தைய சமூகங்களைக் குறிக்கும். அவர்கள் மறைந்து மற்றவர்கள் வரும்போது அது அடுத்த தலைமுறையாகும். புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹான நூல்களிலும் பதிவு செய்யப்பட்டுள்ளபடி:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الْقُرُونِ</span> <span class=\"quran-arabic-font text-success\">قَرْنِي،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَلُونَهُمْ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَلُونَهُم</span>»<br />\r\n<br />\r\n(தலைமுறைகளில் சிறந்தது எனது தலைமுறை, பின்னர் அதைத் தொடர்ந்து வருபவர்கள், பின்னர் அவர்களைத் தொடர்ந்து வருபவர்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَتَوْا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْقَرْيَةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِى</span> <span class=\"quran-arabic-font text-success\">أُمْطِرَتْ</span> <span class=\"quran-arabic-font text-success\">مَطَرَ</span> <span class=\"quran-arabic-font text-success\">السَّوْءِ</span><br />\r\n<br />\r\n(மேலும், தீய மழை பொழியப்பட்ட அந்த ஊரைக் கடந்து அவர்கள் நிச்சயமாகச் சென்றிருக்கிறார்கள்.) இது லூத் (அலை) அவர்களின் சமூகம் வாழ்ந்த 'ஸொதோம்' நகரத்தைக் குறிக்கிறது. அல்லாஹ் அந்த ஊரைத் தலைகீழாகப் புரட்டியும், அதன் மீது சுடப்பட்ட களிமண் கற்களை மழையாகப் பொழியச் செய்தும் அழித்த விதத்தை இது குறிக்கிறது. அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَمْطَرْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مَّطَراً</span> <span class=\"quran-arabic-font text-success\">فَسَآءَ</span> <span class=\"quran-arabic-font text-success\">مَطَرُ</span> <span class=\"quran-arabic-font text-success\">الْمُنذَرِينَ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் மீது நாம் மழையைப் பொழியச் செய்தோம். எச்சரிக்கப்பட்டவர்களின் அந்த மழை மிக மோசமானதாக இருந்தது!) (<a href=\"qurandisp.php?sura=26&ayah=176\" class=\"link\">26:176</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">لَّتَمُرُّونَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مُّصْبِحِينَ</span> - <span class=\"quran-arabic-font text-success\">وَبِالَّيْلِ</span> <span class=\"quran-arabic-font text-success\">أَفَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக நீங்கள் காலையிலும் இரவிலும் அவர்களைக் கடந்து செல்கிறீர்கள்; நீங்கள் சிந்திக்க மாட்டீர்களா?) (<a href=\"qurandisp.php?sura=37&ayah=137\" class=\"link\">37:137</a>-138),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهَا</span> <span class=\"quran-arabic-font text-success\">لَبِسَبِيلٍ</span> <span class=\"quran-arabic-font text-success\">مُّقِيمٍ</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக அந்த ஊர் (இன்றும் அழியாத) பாதையில் இருக்கிறது.) (<a href=\"qurandisp.php?sura=15&ayah=76\" class=\"link\">15:76</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُمَا</span> <span class=\"quran-arabic-font text-success\">لَبِإِمَامٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(நிச்சயமாக அவை இரண்டும் வெளிப்படையான நெடுஞ்சாலையிலேயே இருக்கின்றன.) (<a href=\"qurandisp.php?sura=15&ayah=79\" class=\"link\">15:79</a>). அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَفَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَهَا</span><br />\r\n<br />\r\n(அவர்கள் அதனைப் பார்க்கவில்லையா?) அதாவது, தூதரை நிராகரித்ததற்கும், அல்லாஹ்வின் கட்டளைகளுக்கு மாறு செய்ததற்கும் அந்த ஊர் மக்களுக்கு ஏற்பட்ட தண்டனையிலிருந்து அவர்கள் ஒரு பாடம் பெற்றிருக்க வேண்டாமா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَرْجُونَ</span> <span class=\"quran-arabic-font text-success\">نُشُوراً</span><br />\r\n<br />\r\n(அப்படியல்ல! அவர்கள் மீளெழுப்பப்படுவதை எதிர்பார்க்கவில்லை.) அதாவது, அந்த ஊரைக் கடந்து சென்ற நிராகரிப்பாளர்கள் எந்தப் பாடத்தையும் பெறவில்லை, ஏனெனில் அவர்களுக்கு மறுமை நாளில் மீண்டும் உயிர்ப்பிக்கப்படுவோம் என்பதில் நம்பிக்கை இருக்கவில்லை.<br />\r\n<br />","text":"குரைஷி இணைவைப்பாளர்களை அச்சுறுத்துதல்\n\r\n\n\r\nதனது தூதர் முஹம்மது (ஸல்) அவர்களை நிராகரித்து எதிர்த்த இணைவைப்பாளர்களை அல்லாஹ் அச்சுறுத்துகிறான். தங்களது தூதர்களை நிராகரித்த முந்தைய சமூகங்களுக்கு அவன் அனுப்பிய தண்டனை மற்றும் வேதனையான வேதனை குறித்து அவர்களை எச்சரிக்கிறான். அல்லாஹ் மூஸா (அலை) அவர்களைப் பற்றிக் குறிப்பிடுவதிலிருந்து தொடங்குகிறான். அவருக்கு ஒரு உதவியாளராக - அதாவது அவருக்கு உதவி செய்து ஆதரவளிக்கக்கூடிய மற்றொரு நபியாக - அவருடைய சகோதரர் ஹாரூன் (அலை) அவர்களையும் சேர்த்து அல்லாஹ் அனுப்பினான். ஆனால், ஃபிர்அவ்னும் அவனது தலைவர்களும் அவர்கள் இருவரையும் பொய்ப்பித்தனர்:\n\r\n\n\r\nدَمَّرَ اللَّهُ عَلَيْهِمْ وَلِلْكَـفِرِينَ أَمْثَـلُهَا\n\r\n\n\r\n(அல்லாஹ் அவர்களை அடியோடு அழித்துவிட்டான், மேலும் நிராகரிப்பாளர்களுக்கும் இது போன்றதே (காத்திருக்கிறது)) (47:10). நூஹ் (அலை) அவர்களின் சமூகத்தினர் அவரைப் பொய்ப்பித்தபோது, அல்லாஹ் அவர்களையும் அவ்வாறே அழித்தான். ஏனெனில், ஒரு தூதரை நிராகரிப்பவர் அனைத்து தூதர்களையும் நிராகரித்தவர் ஆவார்; ஏனெனில், ஒரு தூதருக்கும் மற்றொரு தூதருக்கும் இடையில் எந்த வேறுபாடும் இல்லை. அல்லாஹ் தனது தூதர்கள் அனைவரையும் அவர்களிடம் அனுப்பியிருந்தாலும், அவர்கள் அனைவரையும் அவர்கள் நிராகரித்திருப்பார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَقَوْمَ نُوحٍ لَّمَّا كَذَّبُواْ الرُّسُلَ\n\r\n\n\r\n(நூஹ் உடைய சமூகத்தினர் தூதர்களைப் பொய்ப்பித்தபோது,) அல்லாஹ் நூஹ் (அலை) அவர்களை மட்டுமே அவர்களிடம் அனுப்பியிருந்த போதிலும், அவர் 950 ஆண்டுகள் அவர்களிடையே தங்கியிருந்து, அவர்களை அல்லாஹ்வின் பக்கம் அழைத்து, அவனது தண்டனையைக் குறித்து எச்சரித்து வந்தார்கள்.\n\r\n\n\r\nوَمَآ ءَامَنَ مَعَهُ إِلاَّ قَلِيلٌ\n\r\n\n\r\n(அவருடன் மிகச் சிலரைத் தவிர வேறு எவரும் ஈமான் கொள்ளவில்லை) (11:40). இதன் காரணமாக, அல்லாஹ் அவர்கள் அனைவரையும் மூழ்கடித்தான். மேலும் கப்பலில் ஏறியவர்களைத் தவிர, ஆதமின் சந்ததிகளில் எவரையும் பூமியில் உயிருடன் விட்டுவைக்கவில்லை.\n\r\n\n\r\nوَجَعَلْنَـهُمْ لِلنَّاسِ ءَايَةً\n\r\n\n\r\n(மேலும், அவர்களை மனிதர்களுக்கு ஓர் அத்தாட்சியாக ஆக்கினோம்.) அதாவது, இதிலிருந்து ஒரு படிப்பினை பெற வேண்டும். இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nإِنَّا لَمَّا طَغَا الْمَآءُ حَمَلْنَـكُمْ فِى الْجَارِيَةِ - لِنَجْعَلَهَا لَكُمْ تَذْكِرَةً وَتَعِيَهَآ أُذُنٌ وَعِيَةٌ\n\r\n\n\r\n(நிச்சயமாக, நீர் அதன் எல்லையைத் தாண்டிப் பொங்கியபோது, நாம் உங்களைக் கப்பலில் சுமந்தோம். அதனை உங்களுக்கு ஒரு நினைவூட்டலாக ஆக்குவதற்காகவும், அதனை நினைவில் கொள்ளும் காதுகள் நினைவில் கொள்வதற்காகவும்) (69:11-12). இதன் பொருள்: \"நீங்கள் கடலின் ஆழமான பகுதிகளில் பயணம் செய்வதற்காக, நீங்கள் ஏறிச் செல்லும் கப்பல்களை நாம் உங்களுக்காக விட்டுவைத்தோம். இதன் மூலம், அல்லாஹ் உங்களை மூழ்குவதிலிருந்து காப்பாற்றிய அவனது அருட்கொடையை நீங்கள் நினைவு கூர்வதற்காகவும், அவனை விசுவாசித்து அவனது கட்டளைகளைப் பின்பற்றியவர்களின் சந்ததிகளாக உங்களை ஆக்கியதற்காகவும் ஆகும்.\"\n\r\n\n\r\nوَعَاداً وَثَمُودَاْ وَأَصْحَـبَ الرَّسِّ\n\r\n\n\r\n(மேலும், ஆது, ஸமூது மற்றும் அர்-ரஸ் வாசிகளை (அழித்தோம்).) இவர்களுடைய வரலாற்றை சூரத்துல் அஃராஃப் போன்ற ஒன்றுக்கு மேற்பட்ட சூராக்களில் நாம் ஏற்கனவே விளக்கியுள்ளோம், எனவே அதை இங்கே மீண்டும் கூற வேண்டிய அவசியமில்லை. அர்-ரஸ் வாசிகளைப் பற்றி இப்னு ஜுரைஜ் அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அவர்கள் ஸமூது சமூகத்தின் கிராமங்களில் ஒன்றின் மக்கள்.\" அத்-தவ்ரீ அவர்கள் அபூ பக்ர் வழியாக இக்ரிமா (ரழி) அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"அர்-ரஸ் என்பது அவர்கள் தங்களது நபியைப் புதைத்த (ரஸ்ஸு) ஒரு கிணறு ஆகும்.\"\n\r\n\n\r\nوَقُرُوناً بَيْنَ ذَلِكَ كَثِيراً\n\r\n\n\r\n(மேலும் இவற்றுக்கு இடையே இன்னும் பல தலைமுறையினரையும் (அழித்தோம்).) இதன் பொருள், இங்கே குறிப்பிடப்பட்டுள்ளவர்களைத் தவிர இன்னும் பல சமூகங்களை நாம் அழித்தோம். அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَكُلاًّ ضَرَبْنَا لَهُ الْأَمْثَالَ\n\r\n\n\r\n(ஒவ்வொருவருக்கும் நாம் உதாரணங்களை விவரித்தோம்,) அதாவது, \"நாம் அவர்களுக்கு ஆதாரங்களைக் காட்டி, தெளிவான சான்றுகளை வழங்கினோம்\" என்று கத்தாதா (ரழி) அவர்கள் கூறினார்கள். \"அவர்களுக்கு எந்தப் புகாரும் (சாக்குப்போக்கும்) இருக்கவில்லை.\"\n\r\n\n\r\nوَكُلاًّ تَبَّرْنَا تَتْبِيراً\n\r\n\n\r\n(ஒவ்வொருவரையும் நாம் அடியோடு அழித்துவிட்டோம்.) இதன் பொருள் \"நாம் அவர்களை முழுமையாக அழித்துவிட்டோம்.\" இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَكَمْ أَهْلَكْنَا مِنَ الْقُرُونِ مِن بَعْدِ نُوحٍ\n\r\n\n\r\n(நூஹிற்குப் பிறகு எத்தனையோ தலைமுறையினரை நாம் அழித்திருக்கிறோம்!) (17:17). இங்கு 'தலைமுறைகள்' (குரூன்) என்பது மனிதர்களில் இருந்த சமூகங்களைக் குறிக்கும். இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nثُمَّ أَنشَأْنَا مِن بَعْدِهِمْ قُرُوناً ءَاخَرِينَ\n\r\n\n\r\n(பின்னர், அவர்களுக்குப் பிறகு மற்றத் தலைமுறையினரை நாம் உருவாக்கினோம்.) (23:42). ஒரு தலைமுறை என்பது 120 ஆண்டுகள் என்று சிலர் வரையறுத்தனர், அல்லது நூறு ஆண்டுகள், அல்லது எண்பது, அல்லது நாற்பது ஆண்டுகள் என்றும் கூறப்பட்டது. மிகச் சரியான கருத்து என்னவென்றால், ஒரு தலைமுறை என்பது ஒரே காலத்தில் வாழும் சமகாலத்தைய சமூகங்களைக் குறிக்கும். அவர்கள் மறைந்து மற்றவர்கள் வரும்போது அது அடுத்த தலைமுறையாகும். புகாரி, முஸ்லிம் ஆகிய இரு ஸஹீஹான நூல்களிலும் பதிவு செய்யப்பட்டுள்ளபடி:\n\r\n\n\r\n«خَيْرُ الْقُرُونِ قَرْنِي، ثُمَّ الَّذِينَ يَلُونَهُمْ، ثُمَّ الَّذِينَ يَلُونَهُم»\n\r\n\n\r\n(தலைமுறைகளில் சிறந்தது எனது தலைமுறை, பின்னர் அதைத் தொடர்ந்து வருபவர்கள், பின்னர் அவர்களைத் தொடர்ந்து வருபவர்கள்.)\n\r\n\n\r\nوَلَقَدْ أَتَوْا عَلَى الْقَرْيَةِ الَّتِى أُمْطِرَتْ مَطَرَ السَّوْءِ\n\r\n\n\r\n(மேலும், தீய மழை பொழியப்பட்ட அந்த ஊரைக் கடந்து அவர்கள் நிச்சயமாகச் சென்றிருக்கிறார்கள்.) இது லூத் (அலை) அவர்களின் சமூகம் வாழ்ந்த 'ஸொதோம்' நகரத்தைக் குறிக்கிறது. அல்லாஹ் அந்த ஊரைத் தலைகீழாகப் புரட்டியும், அதன் மீது சுடப்பட்ட களிமண் கற்களை மழையாகப் பொழியச் செய்தும் அழித்த விதத்தை இது குறிக்கிறது. அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَأَمْطَرْنَا عَلَيْهِم مَّطَراً فَسَآءَ مَطَرُ الْمُنذَرِينَ\n\r\n\n\r\n(மேலும், அவர்கள் மீது நாம் மழையைப் பொழியச் செய்தோம். எச்சரிக்கப்பட்டவர்களின் அந்த மழை மிக மோசமானதாக இருந்தது!) (26:176),\n\r\n\n\r\nوَإِنَّكُمْ لَّتَمُرُّونَ عَلَيْهِمْ مُّصْبِحِينَ - وَبِالَّيْلِ أَفَلاَ تَعْقِلُونَ\n\r\n\n\r\n(நிச்சயமாக நீங்கள் காலையிலும் இரவிலும் அவர்களைக் கடந்து செல்கிறீர்கள்; நீங்கள் சிந்திக்க மாட்டீர்களா?) (37:137-138),\n\r\n\n\r\nوَإِنَّهَا لَبِسَبِيلٍ مُّقِيمٍ\n\r\n\n\r\n(மேலும் நிச்சயமாக அந்த ஊர் (இன்றும் அழியாத) பாதையில் இருக்கிறது.) (15:76),\n\r\n\n\r\nوَإِنَّهُمَا لَبِإِمَامٍ مُّبِينٍ\n\r\n\n\r\n(நிச்சயமாக அவை இரண்டும் வெளிப்படையான நெடுஞ்சாலையிலேயே இருக்கின்றன.) (15:79). அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَفَلَمْ يَكُونُواْ يَرَوْنَهَا\n\r\n\n\r\n(அவர்கள் அதனைப் பார்க்கவில்லையா?) அதாவது, தூதரை நிராகரித்ததற்கும், அல்லாஹ்வின் கட்டளைகளுக்கு மாறு செய்ததற்கும் அந்த ஊர் மக்களுக்கு ஏற்பட்ட தண்டனையிலிருந்து அவர்கள் ஒரு பாடம் பெற்றிருக்க வேண்டாமா?\n\r\n\n\r\nبَلْ كَانُواْ لاَ يَرْجُونَ نُشُوراً\n\r\n\n\r\n(அப்படியல்ல! அவர்கள் மீளெழுப்பப்படுவதை எதிர்பார்க்கவில்லை.) அதாவது, அந்த ஊரைக் கடந்து சென்ற நிராகரிப்பாளர்கள் எந்தப் பாடத்தையும் பெறவில்லை, ஏனெனில் அவர்களுக்கு மறுமை நாளில் மீண்டும் உயிர்ப்பிக்கப்படுவோம் என்பதில் நம்பிக்கை இருக்கவில்லை."},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=44\" class=\"link\">25:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:44 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=44\" class=\"link\">25:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:44 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=44\" class=\"link\">25:44</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:44 ஐ பார்க்கவும்"},"44":{"html":"<strong>நிராகரிப்பாளர்கள் தூதரை எப்படிக் கேலி செய்தார்கள்</strong><br />\r\n<br />\r\n<br />\r\nநிராகரிப்பாளர்கள் அல்லாஹ்வின் தூதரைச் (ஸல்) சந்தித்தபோது அவரை எவ்வாறு கேலி செய்தார்கள் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">رَآكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">يَتَّخِذُونَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُزُواً﴿</span><br />\r\n<br />\r\n<br />\r\n(நிராகரிப்பாளர்கள் உம்மைக் காணும்போது, உம்மை ஒரு கேலிப் பொருளாகவே தவிர அவர்கள் கருதுவதில்லை) (<a href=\"qurandisp.php?sura=21&ayah=36\" class=\"link\">21:36</a>). அதாவது, அவர்கள் அவரிடம் (ஸல்) குறைகளையும் பலவீனங்களையும் தேட முயன்றார்கள். இங்கே அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">رَأَوْكَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">يَتَّخِذُونَكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُزُواً</span> <span class=\"quran-arabic-font text-success\">أَهَـذَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">بَعَثَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர்கள் உம்மைக் காணும்போது, \"அல்லாஹ் தூதராக அனுப்பியவர் இவர்தானா?\" என்று உம்மை ஏளனம் செய்யாமல் இருப்பதில்லை.) அதாவது, அவரைச் (ஸல்) சிறுமைப்படுத்தும் நோக்கத்திலும், தாழ்வாகக் கருதியுமே அவர்கள் இப்படிக் கூறினார்கள். எனவே அல்லாஹ் அவர்களுக்குப் பதிலளிக்கும் விதமாக: <span class=\"quran-arabic-font text-success\">﴾وَلَقَدِ</span> <span class=\"quran-arabic-font text-success\">اسْتُهْزِىءَ</span> <span class=\"quran-arabic-font text-success\">بِرُسُلٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَبْلِكَ﴿</span><br />\r\n<br />\r\n<br />\r\n(நிச்சயமாக உமக்கு முன்னிருந்த தூதர்களும் கேலி செய்யப்பட்டார்கள்) (<a href=\"qurandisp.php?sura=6&ayah=10\" class=\"link\">6:10</a>) என்று கூறினான். <span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">كَادَ</span> <span class=\"quran-arabic-font text-success\">لَيُضِلُّنَا</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتِنَا</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">صَبَرْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا﴿</span><br />\r\n<br />\r\n<br />\r\n(அவர் எங்களை எங்கள் தெய்வங்களை வணங்குவதிலிருந்து கிட்டத்தட்ட வழிதவறச் செய்திருப்பார்,) அதாவது, \"நாங்கள் எங்களது வழியில் உறுதியாகவும் பொறுமையாகவும் இருந்திராவிட்டால், சிலைகளை வணங்குவதிலிருந்து அவர் எங்களைத் தடுத்திருப்பார்\" என்று அவர்கள் கூறினர். எனவே, அல்லாஹ் அவர்களை எச்சரிக்கும் விதமாக இவ்வாறு கூறினான்: <span class=\"quran-arabic-font text-success\">﴾وَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً﴿</span><br />\r\n<br />\r\n<br />\r\n(வேதனையை அவர்கள் நேரில் காணும்போது யார் மிக மோசமான வழிகேட்டில் இருக்கிறார்கள் என்பதை அறிந்துகொள்வார்கள்...)<br />\r\n<br />\r\n<strong>அவர்கள் தங்கள் மன இச்சைகளையே தெய்வங்களாகக் கொண்டனர்; கால்நடைகளை விடவும் வழிதவறியவர்கள்</strong><br />\r\n<br />\r\n<br />\r\nபிறகு அல்லாஹ் தன் தூதரிடம் (ஸல்) கூறுகிறான், ஒருவன் வழிதவறியவனாகவும் துரதிர்ஷ்டசாலியாகவும் இருக்க வேண்டும் என்று அல்லாஹ் விதித்துவிட்டால், அவனைப் புகழுக்குரியவனான அல்லாஹ்வைத் தவிர வேறு எவராலும் நேர்வழிப்படுத்த முடியாது: <span class=\"quran-arabic-font text-success\">﴾أَرَءَيْتَ</span> <span class=\"quran-arabic-font text-success\">مَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَهُ</span> <span class=\"quran-arabic-font text-success\">هَوَاهُ﴿</span><br />\r\n<br />\r\n<br />\r\n(தனது மன இச்சையையே தனது தெய்வமாக ஆக்கிக்கொண்டவனை நீர் பார்த்தீரா?) அதாவது, அவன் தனது விருப்பங்களில் எதை விரும்புகிறானோ, எதைச் சிறந்தது என்று கருதுகிறானோ, அதுவே அவனது மார்க்கமாகவும் வழியாகவும் மாறிவிடுகிறது. அல்லாஹ் கூறுவது போல்: <span class=\"quran-arabic-font text-success\">﴾أَفَمَن</span> <span class=\"quran-arabic-font text-success\">زُيِّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">سُوءَ</span> <span class=\"quran-arabic-font text-success\">عَمَلِهِ</span> <span class=\"quran-arabic-font text-success\">فَرَءَاهُ</span> <span class=\"quran-arabic-font text-success\">حَسَناً</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يُضِلُّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ﴿</span><br />\r\n<br />\r\n<br />\r\n(எவனுக்குத் தனது தீய செயல் அழகாக்கப்பட்டு, அதை அவன் நன்மையானதாகக் காண்கிறானோ அவன் நேர்வழி பெற்றவனைப் போன்றவனா? நிச்சயமாக அல்லாஹ் தான் நாடியவர்களை வழிகேட்டில் விடுகிறான்.) (<a href=\"qurandisp.php?sura=35&ayah=8\" class=\"link\">35:8</a>) <span class=\"quran-arabic-font text-success\">﴾أَفَأَنتَ</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">وَكِيلاً﴿</span><br />\r\n<br />\r\n<br />\r\n(அப்படியிருக்க, நீர் அவருக்குப் பொறுப்பாளராக இருக்க முடியுமா?) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஜாஹிலிய்யா (அறியாமை) காலத்தில், ஒரு மனிதன் ஒரு வெள்ளைக் கல்லைச் சிறிது காலம் வணங்குவான்; அதைவிட அழகான வேறொரு கல்லைக் கண்டால், முந்தையதை விட்டுவிட்டு இதைக் கும்பிடத் தொடங்கிவிடுவான்.\" பிறகு அல்லாஹ் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾أَمْ</span> <span class=\"quran-arabic-font text-success\">تَحْسَبُ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُونَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَعْقِلُونَ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَالْأَنْعَامِ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">أَضَلُّ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً﴿</span><br />\r\n<br />\r\n<br />\r\n(அல்லது அவர்களில் பெரும்பாலோர் செவிமடுக்கிறார்கள் அல்லது விளங்குகிறார்கள் என்று நீர் கருதுகிறீரா? அவர்கள் கால்நடைகளைப் போன்றவர்கள்; இல்லை, (அதைவிட) வழிகேடர்கள்.) அதாவது, இவர்கள் மேயும் கால்நடைகளை விட மோசமானவர்கள். கால்நடைகள் எதற்காகப் படைக்கப்பட்டனவோ அந்தப் பணியை மட்டும் செய்கின்றன. ஆனால், இந்த மனிதர்களோ எவ்வித இணையும் கற்பிக்காமல் அல்லாஹ்வை மாத்திரமே வணங்குவதற்காகப் படைக்கப்பட்டனர். எனினும், அவர்களுக்கு எதிராகத் தெளிவான அத்தாட்சிகள் சமர்ப்பிக்கப்பட்டு, தூதர்கள் அனுப்பப்பட்ட பிறகும் அவர்கள் அல்லாஹ்வுடன் மற்றவைகளையும் வணங்குகிறார்கள்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"நிராகரிப்பாளர்கள் தூதரை எப்படிக் கேலி செய்தார்கள்\n\r\n\n\r\n\n\r\nநிராகரிப்பாளர்கள் அல்லாஹ்வின் தூதரைச் (ஸல்) சந்தித்தபோது அவரை எவ்வாறு கேலி செய்தார்கள் என்பதை அல்லாஹ் நமக்குக் கூறுகிறான். இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾وَإِذَا رَآكَ الَّذِينَ كَفَرُواْ إِن يَتَّخِذُونَكَ إِلاَّ هُزُواً﴿\n\r\n\n\r\n\n\r\n(நிராகரிப்பாளர்கள் உம்மைக் காணும்போது, உம்மை ஒரு கேலிப் பொருளாகவே தவிர அவர்கள் கருதுவதில்லை) (21:36). அதாவது, அவர்கள் அவரிடம் (ஸல்) குறைகளையும் பலவீனங்களையும் தேட முயன்றார்கள். இங்கே அல்லாஹ் கூறுகிறான்: ﴾وَإِذَا رَأَوْكَ إِن يَتَّخِذُونَكَ إِلاَّ هُزُواً أَهَـذَا الَّذِى بَعَثَ اللَّهُ رَسُولاً ﴿\n\r\n\n\r\n\n\r\n(அவர்கள் உம்மைக் காணும்போது, \"அல்லாஹ் தூதராக அனுப்பியவர் இவர்தானா?\" என்று உம்மை ஏளனம் செய்யாமல் இருப்பதில்லை.) அதாவது, அவரைச் (ஸல்) சிறுமைப்படுத்தும் நோக்கத்திலும், தாழ்வாகக் கருதியுமே அவர்கள் இப்படிக் கூறினார்கள். எனவே அல்லாஹ் அவர்களுக்குப் பதிலளிக்கும் விதமாக: ﴾وَلَقَدِ اسْتُهْزِىءَ بِرُسُلٍ مِّن قَبْلِكَ﴿\n\r\n\n\r\n\n\r\n(நிச்சயமாக உமக்கு முன்னிருந்த தூதர்களும் கேலி செய்யப்பட்டார்கள்) (6:10) என்று கூறினான். ﴾إِن كَادَ لَيُضِلُّنَا عَنْ ءَالِهَتِنَا لَوْلاَ أَن صَبَرْنَا عَلَيْهَا﴿\n\r\n\n\r\n\n\r\n(அவர் எங்களை எங்கள் தெய்வங்களை வணங்குவதிலிருந்து கிட்டத்தட்ட வழிதவறச் செய்திருப்பார்,) அதாவது, \"நாங்கள் எங்களது வழியில் உறுதியாகவும் பொறுமையாகவும் இருந்திராவிட்டால், சிலைகளை வணங்குவதிலிருந்து அவர் எங்களைத் தடுத்திருப்பார்\" என்று அவர்கள் கூறினர். எனவே, அல்லாஹ் அவர்களை எச்சரிக்கும் விதமாக இவ்வாறு கூறினான்: ﴾وَسَوْفَ يَعْلَمُونَ حِينَ يَرَوْنَ الْعَذَابَ مَنْ أَضَلُّ سَبِيلاً﴿\n\r\n\n\r\n\n\r\n(வேதனையை அவர்கள் நேரில் காணும்போது யார் மிக மோசமான வழிகேட்டில் இருக்கிறார்கள் என்பதை அறிந்துகொள்வார்கள்...)\n\r\n\n\r\nஅவர்கள் தங்கள் மன இச்சைகளையே தெய்வங்களாகக் கொண்டனர்; கால்நடைகளை விடவும் வழிதவறியவர்கள்\n\r\n\n\r\n\n\r\nபிறகு அல்லாஹ் தன் தூதரிடம் (ஸல்) கூறுகிறான், ஒருவன் வழிதவறியவனாகவும் துரதிர்ஷ்டசாலியாகவும் இருக்க வேண்டும் என்று அல்லாஹ் விதித்துவிட்டால், அவனைப் புகழுக்குரியவனான அல்லாஹ்வைத் தவிர வேறு எவராலும் நேர்வழிப்படுத்த முடியாது: ﴾أَرَءَيْتَ مَنِ اتَّخَذَ إِلَـهَهُ هَوَاهُ﴿\n\r\n\n\r\n\n\r\n(தனது மன இச்சையையே தனது தெய்வமாக ஆக்கிக்கொண்டவனை நீர் பார்த்தீரா?) அதாவது, அவன் தனது விருப்பங்களில் எதை விரும்புகிறானோ, எதைச் சிறந்தது என்று கருதுகிறானோ, அதுவே அவனது மார்க்கமாகவும் வழியாகவும் மாறிவிடுகிறது. அல்லாஹ் கூறுவது போல்: ﴾أَفَمَن زُيِّنَ لَهُ سُوءَ عَمَلِهِ فَرَءَاهُ حَسَناً فَإِنَّ اللَّهَ يُضِلُّ مَن يَشَآءُ﴿\n\r\n\n\r\n\n\r\n(எவனுக்குத் தனது தீய செயல் அழகாக்கப்பட்டு, அதை அவன் நன்மையானதாகக் காண்கிறானோ அவன் நேர்வழி பெற்றவனைப் போன்றவனா? நிச்சயமாக அல்லாஹ் தான் நாடியவர்களை வழிகேட்டில் விடுகிறான்.) (35:8) ﴾أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلاً﴿\n\r\n\n\r\n\n\r\n(அப்படியிருக்க, நீர் அவருக்குப் பொறுப்பாளராக இருக்க முடியுமா?) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"ஜாஹிலிய்யா (அறியாமை) காலத்தில், ஒரு மனிதன் ஒரு வெள்ளைக் கல்லைச் சிறிது காலம் வணங்குவான்; அதைவிட அழகான வேறொரு கல்லைக் கண்டால், முந்தையதை விட்டுவிட்டு இதைக் கும்பிடத் தொடங்கிவிடுவான்.\" பிறகு அல்லாஹ் கூறினான்: ﴾أَمْ تَحْسَبُ أَنَّ أَكْثَرَهُمْ يَسْمَعُونَ أَوْ يَعْقِلُونَ إِنْ هُمْ إِلاَّ كَالْأَنْعَامِ بَلْ هُمْ أَضَلُّ سَبِيلاً﴿\n\r\n\n\r\n\n\r\n(அல்லது அவர்களில் பெரும்பாலோர் செவிமடுக்கிறார்கள் அல்லது விளங்குகிறார்கள் என்று நீர் கருதுகிறீரா? அவர்கள் கால்நடைகளைப் போன்றவர்கள்; இல்லை, (அதைவிட) வழிகேடர்கள்.) அதாவது, இவர்கள் மேயும் கால்நடைகளை விட மோசமானவர்கள். கால்நடைகள் எதற்காகப் படைக்கப்பட்டனவோ அந்தப் பணியை மட்டும் செய்கின்றன. ஆனால், இந்த மனிதர்களோ எவ்வித இணையும் கற்பிக்காமல் அல்லாஹ்வை மாத்திரமே வணங்குவதற்காகப் படைக்கப்பட்டனர். எனினும், அவர்களுக்கு எதிராகத் தெளிவான அத்தாட்சிகள் சமர்ப்பிக்கப்பட்டு, தூதர்கள் அனுப்பப்பட்ட பிறகும் அவர்கள் அல்லாஹ்வுடன் மற்றவைகளையும் வணங்குகிறார்கள்."},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=47\" class=\"link\">25:47</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:47 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=47\" class=\"link\">25:47</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:47 ஐ பார்க்கவும்"},"47":{"html":"<strong>படைத்தவனின் இருப்பிற்கும் அவனது பூரணமான ஆற்றலுக்குமான சான்றுகள்</strong><br />\r\n<br />\r\nபல்வேறு பொருட்களையும், ஒன்றுக்கொன்று எதிரான இணைகளையும் படைப்பதில் தனக்குள்ள பூரணமான ஆற்றலையும், தனது இருப்புக்கான சான்றுகளையும் இங்கே அல்லாஹ் விளக்கத் தொடங்குகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">مَدَّ</span> <span class=\"quran-arabic-font text-success\">الظِّلَّ﴿</span><br />\r\n<br />\r\n(நிழலை உமது இறைவன் எவ்வாறு பரப்பினான் என்பதை நீர் பார்க்கவில்லையா?) இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), அபுல் ஆலியா, அபூ மாலிக், மஸ்ரூக், முஜாஹித், ஸயீத் பின் ஜுபைர், அந்நகயீ, அழ்ழஹ்ஹாக், அல்-ஹஸன், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் கூறினார்கள்: \"இது அதிகாலைத் தொடக்கத்திலிருந்து சூரியன் உதிக்கும் வரையுள்ள காலத்தைக் குறிக்கிறது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">لَجَعَلَهُ</span> <span class=\"quran-arabic-font text-success\">سَاكِناً﴿</span><br />\r\n<br />\r\n(அவன் நாடியிருந்தால், அதை அசையாமல் ஆக்கியிருப்பான்.) அதாவது, அசைவற்றதாக, ஒருபோதும் மாறாததாக ஆக்கியிருப்பான். இது இந்தத் திருவசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">أَرَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">سَرْمَداً﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"கவனித்தீர்களா? அல்லாஹ் இரவை உங்களுக்குத் தொடர்ச்சியானதாக ஆக்கிவிட்டால்...\") (<a href=\"qurandisp.php?sura=28&ayah=71\" class=\"link\">28:71</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">دَلِيلاً﴿</span><br />\r\n<br />\r\n(பின்னர் நாம் சூரியனை அதற்கு வழிகாட்டியாக ஆக்கினோம்.) அதாவது, சூரியன் உதிக்காவிட்டால் நிழல் என்பது இருந்திருக்காது. ஏனெனில் ஒரு விஷயம் அதற்கு எதிரான ஒன்றைக் கொண்டுதான் அறியப்படுகிறது. கதாதா மற்றும் அஸ்-ஸுத்தீ கூறினார்கள்: \"சூரியன் ஒரு வழிகாட்டியாகும்; நிழல் மறையும் வரை அது நிழலைப் பின்தொடர்கிறது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">قَبَضْنَاهُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْنَا</span> <span class=\"quran-arabic-font text-success\">قَبْضاً</span> <span class=\"quran-arabic-font text-success\">يَسِيراً﴿</span><br />\r\n<br />\r\n(பின்னர் நாம் அதை நம்மிடம் படிப்படியாகச் சுருக்கிக் கொள்கிறோம்.) இது நிழலைக் குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَسِيراً﴿</span><br />\r\n<br />\r\n(படிப்படியாக) அதாவது மெதுவாக. அஸ்-ஸுத்தீ கூறினார்: \"பூமியில் ஒரு கூரை அல்லது மரத்தின் அடியில் தவிர வேறெந்த நிழலும் மிஞ்சாத வரை அது மென்மையாகவும் மறைவாகவும் சுருக்கப்படுகிறது; அப்போது சூரியன் அதற்கு மேலே உள்ள அனைத்தின் மீதும் பிரகாசிக்கிறது.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَبْضاً</span> <span class=\"quran-arabic-font text-success\">يَسِيراً﴿</span><br />\r\n<br />\r\n(படிப்படியாகச் சுருக்குதல்.) அய்யூப் பின் மூஸா கூறினார்: \"சிறிது சிறிதாக.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">لِبَاساً﴿</span><br />\r\n<br />\r\n(இன்னும் அவன்தான் உங்களுக்கு இரவைப் போர்வையாக ஆக்கினான்.) அது அனைத்துப் பொருட்களையும் மூடி மறைக்கிறது. இது இந்தத் திருவசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">يَغْشَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மூடிக்கொள்ளும் இரவின் மீது சத்தியமாக) (<a href=\"qurandisp.php?sura=92&ayah=1\" class=\"link\">92:1</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالنَّوْمَ</span> <span class=\"quran-arabic-font text-success\">سُبَاتاً﴿</span><br />\r\n<br />\r\n(மேலும் தூக்கத்தை ஓர் ஓய்வாக ஆக்கினான்.) அதாவது, உடல்கள் ஓய்வெடுப்பதற்காக இயக்கத்தை நிறுத்துவதாகும். வாழ்வாதாரத்தைத் தேடி பகல் நேரத்தில் மேற்கொள்ளும் தொடர்ச்சியான உழைப்பால் உடலின் உறுப்புகளும் சக்திகளும் சோர்வடைகின்றன. இரவு வந்து அமைதி நிலவும்போது அவை அசைவதை நிறுத்தி ஓய்வெடுக்கின்றன; இவ்வாறு தூக்கம் உடலுக்கும் ஆன்மாவுக்கும் புத்துணர்ச்சி அளிப்பதாக அமைகிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارَ</span> <span class=\"quran-arabic-font text-success\">نُشُوراً﴿</span><br />\r\n<br />\r\n(மேலும் பகலை நுஷூர் (பரவிச் செல்லும் நேரமாக) ஆக்கினான்.) அதாவது மக்கள் தங்கள் வாழ்வாதாரத்தைத் தேடவும், தங்கள் பணிகளைக் கவனிக்கவும் அதிகாலையில் எழுகின்றனர். இது இந்தத் திருவசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمِن</span> <span class=\"quran-arabic-font text-success\">رَّحْمَتِهِ</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارَ</span> <span class=\"quran-arabic-font text-success\">لِتَسْكُنُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">وَلِتَبتَغُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">فَضْلِهِ﴿</span><br />\r\n<br />\r\n(அவன் தனது அருளால்தான் உங்களுக்கு இரவையும் பகலையும் ஆக்கினான்; நீங்கள் அதில் ஓய்வெடுக்கவும், அவனது அருளைத் தேடவும்...) (<a href=\"qurandisp.php?sura=28&ayah=73\" class=\"link\">28:73</a>)<br />\r\n<br />","text":"படைத்தவனின் இருப்பிற்கும் அவனது பூரணமான ஆற்றலுக்குமான சான்றுகள்\n\r\n\n\r\nபல்வேறு பொருட்களையும், ஒன்றுக்கொன்று எதிரான இணைகளையும் படைப்பதில் தனக்குள்ள பூரணமான ஆற்றலையும், தனது இருப்புக்கான சான்றுகளையும் இங்கே அல்லாஹ் விளக்கத் தொடங்குகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n﴾أَلَمْ تَرَ إِلَى رَبِّكَ كَيْفَ مَدَّ الظِّلَّ﴿\n\r\n\n\r\n(நிழலை உமது இறைவன் எவ்வாறு பரப்பினான் என்பதை நீர் பார்க்கவில்லையா?) இப்னு அப்பாஸ் (ரழி), இப்னு உமர் (ரழி), அபுல் ஆலியா, அபூ மாலிக், மஸ்ரூக், முஜாஹித், ஸயீத் பின் ஜுபைர், அந்நகயீ, அழ்ழஹ்ஹாக், அல்-ஹஸன், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் கூறினார்கள்: \"இது அதிகாலைத் தொடக்கத்திலிருந்து சூரியன் உதிக்கும் வரையுள்ள காலத்தைக் குறிக்கிறது.\"\n\r\n\n\r\n﴾وَلَوْ شَآءَ لَجَعَلَهُ سَاكِناً﴿\n\r\n\n\r\n(அவன் நாடியிருந்தால், அதை அசையாமல் ஆக்கியிருப்பான்.) அதாவது, அசைவற்றதாக, ஒருபோதும் மாறாததாக ஆக்கியிருப்பான். இது இந்தத் திருவசனத்தைப் போன்றது:\n\r\n﴾قُلْ أَرَأَيْتُمْ إِن جَعَلَ اللَّهُ عَلَيْكُمُ اللَّيْلَ سَرْمَداً﴿\n\r\n\n\r\n(கூறுவீராக: \"கவனித்தீர்களா? அல்லாஹ் இரவை உங்களுக்குத் தொடர்ச்சியானதாக ஆக்கிவிட்டால்...\") (28:71)\n\r\n\n\r\n﴾ثُمَّ جَعَلْنَا الشَّمْسَ عَلَيْهِ دَلِيلاً﴿\n\r\n\n\r\n(பின்னர் நாம் சூரியனை அதற்கு வழிகாட்டியாக ஆக்கினோம்.) அதாவது, சூரியன் உதிக்காவிட்டால் நிழல் என்பது இருந்திருக்காது. ஏனெனில் ஒரு விஷயம் அதற்கு எதிரான ஒன்றைக் கொண்டுதான் அறியப்படுகிறது. கதாதா மற்றும் அஸ்-ஸுத்தீ கூறினார்கள்: \"சூரியன் ஒரு வழிகாட்டியாகும்; நிழல் மறையும் வரை அது நிழலைப் பின்தொடர்கிறது.\"\n\r\n\n\r\n﴾ثُمَّ قَبَضْنَاهُ إِلَيْنَا قَبْضاً يَسِيراً﴿\n\r\n\n\r\n(பின்னர் நாம் அதை நம்மிடம் படிப்படியாகச் சுருக்கிக் கொள்கிறோம்.) இது நிழலைக் குறிக்கிறது.\n\r\n\n\r\n﴾يَسِيراً﴿\n\r\n\n\r\n(படிப்படியாக) அதாவது மெதுவாக. அஸ்-ஸுத்தீ கூறினார்: \"பூமியில் ஒரு கூரை அல்லது மரத்தின் அடியில் தவிர வேறெந்த நிழலும் மிஞ்சாத வரை அது மென்மையாகவும் மறைவாகவும் சுருக்கப்படுகிறது; அப்போது சூரியன் அதற்கு மேலே உள்ள அனைத்தின் மீதும் பிரகாசிக்கிறது.\"\n\r\n\n\r\n﴾قَبْضاً يَسِيراً﴿\n\r\n\n\r\n(படிப்படியாகச் சுருக்குதல்.) அய்யூப் பின் மூஸா கூறினார்: \"சிறிது சிறிதாக.\"\n\r\n\n\r\n﴾وَهُوَ الَّذِى جَعَلَ لَكُمُ اللَّيْلَ لِبَاساً﴿\n\r\n\n\r\n(இன்னும் அவன்தான் உங்களுக்கு இரவைப் போர்வையாக ஆக்கினான்.) அது அனைத்துப் பொருட்களையும் மூடி மறைக்கிறது. இது இந்தத் திருவசனத்தைப் போன்றது:\n\r\n﴾وَاللَّيْلِ إِذَا يَغْشَى ﴿\n\r\n\n\r\n(மூடிக்கொள்ளும் இரவின் மீது சத்தியமாக) (92:1).\n\r\n\n\r\n﴾وَالنَّوْمَ سُبَاتاً﴿\n\r\n\n\r\n(மேலும் தூக்கத்தை ஓர் ஓய்வாக ஆக்கினான்.) அதாவது, உடல்கள் ஓய்வெடுப்பதற்காக இயக்கத்தை நிறுத்துவதாகும். வாழ்வாதாரத்தைத் தேடி பகல் நேரத்தில் மேற்கொள்ளும் தொடர்ச்சியான உழைப்பால் உடலின் உறுப்புகளும் சக்திகளும் சோர்வடைகின்றன. இரவு வந்து அமைதி நிலவும்போது அவை அசைவதை நிறுத்தி ஓய்வெடுக்கின்றன; இவ்வாறு தூக்கம் உடலுக்கும் ஆன்மாவுக்கும் புத்துணர்ச்சி அளிப்பதாக அமைகிறது.\n\r\n\n\r\n﴾وَجَعَلَ النَّهَارَ نُشُوراً﴿\n\r\n\n\r\n(மேலும் பகலை நுஷூர் (பரவிச் செல்லும் நேரமாக) ஆக்கினான்.) அதாவது மக்கள் தங்கள் வாழ்வாதாரத்தைத் தேடவும், தங்கள் பணிகளைக் கவனிக்கவும் அதிகாலையில் எழுகின்றனர். இது இந்தத் திருவசனத்தைப் போன்றது:\n\r\n﴾وَمِن رَّحْمَتِهِ جَعَلَ لَكُمُ اللَّيْلَ وَالنَّهَارَ لِتَسْكُنُواْ فِيهِ وَلِتَبتَغُواْ مِن فَضْلِهِ﴿\n\r\n\n\r\n(அவன் தனது அருளால்தான் உங்களுக்கு இரவையும் பகலையும் ஆக்கினான்; நீங்கள் அதில் ஓய்வெடுக்கவும், அவனது அருளைத் தேடவும்...) (28:73)"},"48":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=50\" class=\"link\">25:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:50 ஐ பார்க்கவும்"},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=50\" class=\"link\">25:50</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:50 ஐ பார்க்கவும்"},"50":{"html":"<strong>இதுவும் அவனது முழுமையான ஆற்றல் மற்றும் மேலான அதிகாரத்தின் ஒரு பகுதியாகும்:</strong><br />\r\n<br />\r\nஅல்லாஹ் காற்றுகளை நற்செய்தி கூறக்கூடிய தூதுவர்களாக அனுப்புகிறான்; அதாவது, அக்காற்றுகள் மேகங்களைத் தங்களுக்குப் பின்னால் கொண்டு வருகின்றன. காற்றுகள் அனுப்பப்படும் நோக்கத்தைப் பொறுத்து அவை பல வகைப்படும். சில மேகங்களை உருவாக்குகின்றன, சில மேகங்களைச் சுமந்து செல்கின்றன அல்லது அவற்றைத் தள்ளிச் செல்கின்றன, இன்னும் சில மேகங்களின் வருகையை அறிவிக்கும் நற்செய்தி அறிவிப்பாளர்களாக அவற்றுக்கு முன்னால் வருகின்றன. சில காற்றுகள் பூமியைக் கிளறுவதற்காக (மழைக்கு முன்னால்) வீசுகின்றன, மற்றும் சில மழை பொழியச் செய்வதற்காக மேகங்களைக் கருவுறச் செய்கின்றன (நீர் நிரப்புகின்றன). அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">مَآءً</span> <span class=\"quran-arabic-font text-success\">طَهُوراً</span><br />\r\n<br />\r\n(வானத்திலிருந்து தூய்மையான நீரை நாம் இறக்கினோம்), அதாவது, அதைக் கொண்டு தூய்மைப்படுத்துவதற்காக. அபூ ஸயீத் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! புதாஆ கிணற்று நீரைக் கொண்டு நாங்கள் 'உளூ' செய்யலாமா? ஏனெனில், அது குப்பைகளும் நாய்களின் இறைச்சிகளும் வீசப்படக்கூடிய ஒரு கிணறு\" என்று கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَاءَ</span> <span class=\"quran-arabic-font text-success\">طَهُورٌ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يُنَجِّسُهُ</span> <span class=\"quran-arabic-font text-success\">شَيْء</span>»<br />\r\n<br />\r\n(தண்ணீர் தூய்மையானது, எதுவொன்றும் அதை அசுத்தப்படுத்தாது.) இதனை அஷ்-ஷாஃபியீ மற்றும் அஹ்மத் ஆகியோர் பதிவு செய்து, ஸஹீஹ் என வகைப்படுத்தியுள்ளனர். மேலும் அபூ தாவூத் மற்றும் அத்-திர்மிதீ ஆகியோர் இதனை 'ஹஸன்' எனவும், அந்-நஸாயீ அவர்களும் இதனைப் பதிவு செய்துள்ளனர். அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّنُحْيِىَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَلْدَةً</span> <span class=\"quran-arabic-font text-success\">مَّيْتاً</span><br />\r\n<br />\r\n(அதன் மூலம் மரணித்த நிலத்திற்கு நாம் உயிர் கொடுப்பதற்காக,) இதன் பொருள், நீண்ட காலமாக மழைக்காகக் காத்திருந்த ஒரு நிலமாகும். அது தாவரங்களோ அல்லது வேறெதுவுமோ இன்றி வறண்டு கிடக்கும். அதன் மீது மழை பொழியும் போது, அது உயிர் பெறுகிறது. அல்லாஹ் கூறுவது போல, அதன் குன்றுகள் பலவிதமான வண்ண மலர்களால் சூழப்படுகின்றன:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِذَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">الْمَآءَ</span> <span class=\"quran-arabic-font text-success\">اهْتَزَّتْ</span> <span class=\"quran-arabic-font text-success\">وَرَبَتْ</span><br />\r\n<br />\r\n(ஆனால் நாம் அதன் மீது தண்ணீரை இறக்கும்போது, அது அசைந்து (உயிர் பெற்று) வளர்ந்து செழிக்கிறது...) (<a href=\"qurandisp.php?sura=41&ayah=39\" class=\"link\">41:39</a>). அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَنُسْقِيَهُ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">خَلَقْنَآ</span> <span class=\"quran-arabic-font text-success\">أَنْعَـماً</span> <span class=\"quran-arabic-font text-success\">وَأَنَاسِىَّ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span><br />\r\n<br />\r\n(நாம் படைத்த ஏராளமான கால்நடைகளுக்கும் மனிதர்களுக்கும் அதிலிருந்து நாம் புகட்டுகிறோம்.) அதாவது, கால்நடைகள் போன்ற விலங்குகள் அதிலிருந்து அருந்தவும், நீரின் தேவை அதிகம் உள்ள மக்கள் அதைப் பருகவும், தங்கள் பயிர்களுக்கும் கனிகளுக்கும் நீர் பாய்ச்சவும் நாம் அவ்வாறு செய்கிறோம். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يُنَزِّلُ</span> <span class=\"quran-arabic-font text-success\">الْغَيْثَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">قَنَطُواْ</span><br />\r\n<br />\r\n(அவர்கள் நம்பிக்கையிழந்த பிறகு மழையை இறக்கி வைப்பவன் அவன்தான்,) (<a href=\"qurandisp.php?sura=42&ayah=28\" class=\"link\">42:28</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَانظُرْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">آثَارِ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">يُحْيِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">بَعْدَ</span> <span class=\"quran-arabic-font text-success\">مَوْتِهَا</span><br />\r\n<br />\r\n(அல்லாஹ்வின் அருளின் அடையாளங்களை நோக்கிப் பார்ப்பீராக! பூமி மரணித்த பிறகு அதை அவன் எப்படி உயிர்ப்பிக்கிறான் என்பதை (கவனிப்பீராக).) (<a href=\"qurandisp.php?sura=30&ayah=50\" class=\"link\">30:50</a>). அவனது கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَرَّفْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِيَذَّكَّرُواْ</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அதை அவர்களுக்கு இடையே அவர்கள் நினைவுகூரும் பொருட்டு விநியோகித்துள்ளோம்) இதன் பொருள், 'நாம் ஒரு நிலத்தில் மழை பொழியச் செய்கிறோம், மற்றொரு நிலத்தில் பொழியச் செய்வதில்லை. நாம் மேகங்களை ஒரு நிலத்தைக் கடந்து செல்லச் செய்து மற்றொரு நிலத்திற்கு கொண்டு செல்கிறோம்; அங்குள்ள மக்கள் செழிப்படைய போதுமான மழையை வழங்குகிறோம், ஆனால் முதல் நிலத்தில் ஒரு துளி கூட விழுவதில்லை'.<br />\r\n<br />\r\nஇதற்குப் பின்னால் ஒரு காரணமும் பெரும் ஞானமும் உள்ளது. இப்னு அப்பாஸ் (ரழி) மற்றும் இப்னு மஸ்ஊத் (ரழி) ஆகியோர் கூறினார்கள்: \"ஓர் ஆண்டில் பெய்யும் மழை அளவு மற்றொரு ஆண்டை விட அதிகமாக இருப்பதில்லை, ஆனால் அல்லாஹ் தான் நாடியபடி மழையை விநியோகிக்கிறான்.\" பின்னர் அவர்கள் இந்த வசனத்தை ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">صَرَّفْنَاهُ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">لِيَذَّكَّرُواْ</span> <span class=\"quran-arabic-font text-success\">فَأَبَى</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كُفُوراً</span><br />\r\n<br />\r\n(நிச்சயமாக நாம் அதை (மழையை) அவர்களுக்கு இடையே அவர்கள் நினைவுகூரும் பொருட்டு விநியோகித்துள்ளோம். ஆனால் மனிதர்களில் பெரும்பாலோர் நன்றிகெட்டத்தனத்தைத் தவிர (வேறெதையும்) ஏற்க மறுக்கிறார்கள்.)\" அதாவது, காய்ந்து போன பூமிக்கு அல்லாஹ் உயிர் கொடுக்கும்போது, மடிந்து போன எலும்புகளுக்கும் உயிர் கொடுக்க அவன் ஆற்றல் மிக்கவன் என்பதை அவர்கள் நினைத்துப் பார்க்க வேண்டும். அல்லது மழை மறுக்கப்பட்டவர்கள், தாங்கள் செய்த பாவங்களின் காரணமாகவே இச்சோதனையை அனுபவிக்கிறார்கள் என்பதை உணர்ந்து அந்தப் பாவங்களைக் கைவிட வேண்டும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَبَى</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كُفُورًا</span><br />\r\n<br />\r\n(ஆனால் மனிதர்களில் பெரும்பாலோர் நன்றிகெட்டத்தனத்தைத் தவிர (வேறெதையும்) ஏற்க மறுக்கிறார்கள்.) இக்ரிமா அவர்கள் கூறினார்கள், \"இது, இன்னென்ன நட்சத்திரத்தால்தான் மழை பெய்கிறது என்று கூறுபவர்களைக் குறிக்கிறது.\" இக்ரிமாவின் இந்தக் கருத்து, ஸஹீஹ் முஸ்லிமில் பதிவாகியுள்ள ஒரு ஸஹீஹான ஹதீஸை ஒத்துள்ளது; ஒரு முறை இரவு மழை பெய்ததற்குப் பிறகு, காலையில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் ஸஹாபாக்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَتَدْرُونَ</span> <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ؟</span>»<br />\r\n<br />\r\n(உங்கள் இறைவன் என்ன கூறினான் என்று உங்களுக்குத் தெரியுமா?) அதற்கு அவர்கள், \"அல்லாஹ்வும் அவனுடைய தூதருமே நன்கு அறிந்தவர்கள்\" என்றனர். அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">أَصْبَحَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِي</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">وَكَافِرٌ،</span> <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">مُطِرْنَا</span> <span class=\"quran-arabic-font text-success\">بِفَضْلِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">وَرَحْمَتِهِ</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">بِي،</span> <span class=\"quran-arabic-font text-success\">كَافِرٌ</span> <span class=\"quran-arabic-font text-success\">بِالْكَوْكَبِ،</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">مُطِرْنَا</span> <span class=\"quran-arabic-font text-success\">بِنَوْءِ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،</span> <span class=\"quran-arabic-font text-success\">فَذَاكَ</span> <span class=\"quran-arabic-font text-success\">كَافِرٌ</span> <span class=\"quran-arabic-font text-success\">بِي،</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنٌ</span> <span class=\"quran-arabic-font text-success\">بِالْكَوْكَب</span>»<br />\r\n<br />\r\n(அல்லாஹ் கூறினான்: \"எனது அடியார்களில் சிலர் என் மீது நம்பிக்கை கொண்டவர்களாகவும், சிலர் என்னை நிராகரிப்பவர்களாகவும் விடியலை அடைந்தனர். 'அல்லாஹ்வின் அருளாலும் கிருபையாலும் நமக்கு மழை பொழிந்தது' என்று கூறியவர், என் மீது நம்பிக்கை கொண்டவராகவும் நட்சத்திரங்களை நிராகரிப்பவராகவும் இருக்கிறார். ஆனால், 'இன்னென்ன நட்சத்திரத்தினால் நமக்கு மழை பொழிந்தது' என்று கூறியவரோ, என்னை நிராகரிப்பவராகவும் நட்சத்திரங்களை நம்புபவராகவும் இருக்கிறார்.\")<br />\r\n<br />","text":"இதுவும் அவனது முழுமையான ஆற்றல் மற்றும் மேலான அதிகாரத்தின் ஒரு பகுதியாகும்:\n\r\n\n\r\nஅல்லாஹ் காற்றுகளை நற்செய்தி கூறக்கூடிய தூதுவர்களாக அனுப்புகிறான்; அதாவது, அக்காற்றுகள் மேகங்களைத் தங்களுக்குப் பின்னால் கொண்டு வருகின்றன. காற்றுகள் அனுப்பப்படும் நோக்கத்தைப் பொறுத்து அவை பல வகைப்படும். சில மேகங்களை உருவாக்குகின்றன, சில மேகங்களைச் சுமந்து செல்கின்றன அல்லது அவற்றைத் தள்ளிச் செல்கின்றன, இன்னும் சில மேகங்களின் வருகையை அறிவிக்கும் நற்செய்தி அறிவிப்பாளர்களாக அவற்றுக்கு முன்னால் வருகின்றன. சில காற்றுகள் பூமியைக் கிளறுவதற்காக (மழைக்கு முன்னால்) வீசுகின்றன, மற்றும் சில மழை பொழியச் செய்வதற்காக மேகங்களைக் கருவுறச் செய்கின்றன (நீர் நிரப்புகின்றன). அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَأَنزَلْنَا مِنَ السَّمَآءِ مَآءً طَهُوراً\n\r\n\n\r\n(வானத்திலிருந்து தூய்மையான நீரை நாம் இறக்கினோம்), அதாவது, அதைக் கொண்டு தூய்மைப்படுத்துவதற்காக. அபூ ஸயீத் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்வின் தூதரே! புதாஆ கிணற்று நீரைக் கொண்டு நாங்கள் 'உளூ' செய்யலாமா? ஏனெனில், அது குப்பைகளும் நாய்களின் இறைச்சிகளும் வீசப்படக்கூடிய ஒரு கிணறு\" என்று கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ الْمَاءَ طَهُورٌ لَا يُنَجِّسُهُ شَيْء»\n\r\n\n\r\n(தண்ணீர் தூய்மையானது, எதுவொன்றும் அதை அசுத்தப்படுத்தாது.) இதனை அஷ்-ஷாஃபியீ மற்றும் அஹ்மத் ஆகியோர் பதிவு செய்து, ஸஹீஹ் என வகைப்படுத்தியுள்ளனர். மேலும் அபூ தாவூத் மற்றும் அத்-திர்மிதீ ஆகியோர் இதனை 'ஹஸன்' எனவும், அந்-நஸாயீ அவர்களும் இதனைப் பதிவு செய்துள்ளனர். அவனது கூற்று:\n\r\n\n\r\nلِّنُحْيِىَ بِهِ بَلْدَةً مَّيْتاً\n\r\n\n\r\n(அதன் மூலம் மரணித்த நிலத்திற்கு நாம் உயிர் கொடுப்பதற்காக,) இதன் பொருள், நீண்ட காலமாக மழைக்காகக் காத்திருந்த ஒரு நிலமாகும். அது தாவரங்களோ அல்லது வேறெதுவுமோ இன்றி வறண்டு கிடக்கும். அதன் மீது மழை பொழியும் போது, அது உயிர் பெறுகிறது. அல்லாஹ் கூறுவது போல, அதன் குன்றுகள் பலவிதமான வண்ண மலர்களால் சூழப்படுகின்றன:\n\r\n\n\r\nفَإِذَآ أَنزَلْنَا عَلَيْهَا الْمَآءَ اهْتَزَّتْ وَرَبَتْ\n\r\n\n\r\n(ஆனால் நாம் அதன் மீது தண்ணீரை இறக்கும்போது, அது அசைந்து (உயிர் பெற்று) வளர்ந்து செழிக்கிறது...) (41:39). அவனது கூற்று:\n\r\n\n\r\nوَنُسْقِيَهُ مِمَّا خَلَقْنَآ أَنْعَـماً وَأَنَاسِىَّ كَثِيراً\n\r\n\n\r\n(நாம் படைத்த ஏராளமான கால்நடைகளுக்கும் மனிதர்களுக்கும் அதிலிருந்து நாம் புகட்டுகிறோம்.) அதாவது, கால்நடைகள் போன்ற விலங்குகள் அதிலிருந்து அருந்தவும், நீரின் தேவை அதிகம் உள்ள மக்கள் அதைப் பருகவும், தங்கள் பயிர்களுக்கும் கனிகளுக்கும் நீர் பாய்ச்சவும் நாம் அவ்வாறு செய்கிறோம். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nوَهُوَ الَّذِى يُنَزِّلُ الْغَيْثَ مِن بَعْدِ مَا قَنَطُواْ\n\r\n\n\r\n(அவர்கள் நம்பிக்கையிழந்த பிறகு மழையை இறக்கி வைப்பவன் அவன்தான்,) (42:28)\n\r\n\n\r\nفَانظُرْ إِلَى آثَارِ رَحْمَةِ اللَّهِ كَيْفَ يُحْيِي الْأَرْضَ بَعْدَ مَوْتِهَا\n\r\n\n\r\n(அல்லாஹ்வின் அருளின் அடையாளங்களை நோக்கிப் பார்ப்பீராக! பூமி மரணித்த பிறகு அதை அவன் எப்படி உயிர்ப்பிக்கிறான் என்பதை (கவனிப்பீராக).) (30:50). அவனது கூற்று:\n\r\n\n\r\nوَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ لِيَذَّكَّرُواْ\n\r\n\n\r\n(நிச்சயமாக நாம் அதை அவர்களுக்கு இடையே அவர்கள் நினைவுகூரும் பொருட்டு விநியோகித்துள்ளோம்) இதன் பொருள், 'நாம் ஒரு நிலத்தில் மழை பொழியச் செய்கிறோம், மற்றொரு நிலத்தில் பொழியச் செய்வதில்லை. நாம் மேகங்களை ஒரு நிலத்தைக் கடந்து செல்லச் செய்து மற்றொரு நிலத்திற்கு கொண்டு செல்கிறோம்; அங்குள்ள மக்கள் செழிப்படைய போதுமான மழையை வழங்குகிறோம், ஆனால் முதல் நிலத்தில் ஒரு துளி கூட விழுவதில்லை'.\n\r\n\n\r\nஇதற்குப் பின்னால் ஒரு காரணமும் பெரும் ஞானமும் உள்ளது. இப்னு அப்பாஸ் (ரழி) மற்றும் இப்னு மஸ்ஊத் (ரழி) ஆகியோர் கூறினார்கள்: \"ஓர் ஆண்டில் பெய்யும் மழை அளவு மற்றொரு ஆண்டை விட அதிகமாக இருப்பதில்லை, ஆனால் அல்லாஹ் தான் நாடியபடி மழையை விநியோகிக்கிறான்.\" பின்னர் அவர்கள் இந்த வசனத்தை ஓதினார்கள்:\n\r\n\n\r\nوَلَقَدْ صَرَّفْنَاهُ بَيْنَهُمْ لِيَذَّكَّرُواْ فَأَبَى أَكْثَرُ النَّاسِ إِلاَّ كُفُوراً\n\r\n\n\r\n(நிச்சயமாக நாம் அதை (மழையை) அவர்களுக்கு இடையே அவர்கள் நினைவுகூரும் பொருட்டு விநியோகித்துள்ளோம். ஆனால் மனிதர்களில் பெரும்பாலோர் நன்றிகெட்டத்தனத்தைத் தவிர (வேறெதையும்) ஏற்க மறுக்கிறார்கள்.)\" அதாவது, காய்ந்து போன பூமிக்கு அல்லாஹ் உயிர் கொடுக்கும்போது, மடிந்து போன எலும்புகளுக்கும் உயிர் கொடுக்க அவன் ஆற்றல் மிக்கவன் என்பதை அவர்கள் நினைத்துப் பார்க்க வேண்டும். அல்லது மழை மறுக்கப்பட்டவர்கள், தாங்கள் செய்த பாவங்களின் காரணமாகவே இச்சோதனையை அனுபவிக்கிறார்கள் என்பதை உணர்ந்து அந்தப் பாவங்களைக் கைவிட வேண்டும்.\n\r\n\n\r\nفَأَبَى أَكْثَرُ النَّاسِ إِلاَّ كُفُورًا\n\r\n\n\r\n(ஆனால் மனிதர்களில் பெரும்பாலோர் நன்றிகெட்டத்தனத்தைத் தவிர (வேறெதையும்) ஏற்க மறுக்கிறார்கள்.) இக்ரிமா அவர்கள் கூறினார்கள், \"இது, இன்னென்ன நட்சத்திரத்தால்தான் மழை பெய்கிறது என்று கூறுபவர்களைக் குறிக்கிறது.\" இக்ரிமாவின் இந்தக் கருத்து, ஸஹீஹ் முஸ்லிமில் பதிவாகியுள்ள ஒரு ஸஹீஹான ஹதீஸை ஒத்துள்ளது; ஒரு முறை இரவு மழை பெய்ததற்குப் பிறகு, காலையில் அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தங்கள் ஸஹாபாக்களிடம் கூறினார்கள்:\n\r\n\n\r\n«أَتَدْرُونَ مَاذَا قَالَ رَبُّكُمْ؟»\n\r\n\n\r\n(உங்கள் இறைவன் என்ன கூறினான் என்று உங்களுக்குத் தெரியுமா?) அதற்கு அவர்கள், \"அல்லாஹ்வும் அவனுடைய தூதருமே நன்கு அறிந்தவர்கள்\" என்றனர். அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«قَالَ: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ، فَأَمَّا مَنْ قَالَ: مُطِرْنَا بِفَضْلِ اللهِ وَرَحْمَتِهِ فَذَاكَ مُؤْمِنٌ بِي، كَافِرٌ بِالْكَوْكَبِ، وَأَمَّا مَنْ قَالَ: مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا، فَذَاكَ كَافِرٌ بِي، مُؤْمِنٌ بِالْكَوْكَب»\n\r\n\n\r\n(அல்லாஹ் கூறினான்: \"எனது அடியார்களில் சிலர் என் மீது நம்பிக்கை கொண்டவர்களாகவும், சிலர் என்னை நிராகரிப்பவர்களாகவும் விடியலை அடைந்தனர். 'அல்லாஹ்வின் அருளாலும் கிருபையாலும் நமக்கு மழை பொழிந்தது' என்று கூறியவர், என் மீது நம்பிக்கை கொண்டவராகவும் நட்சத்திரங்களை நிராகரிப்பவராகவும் இருக்கிறார். ஆனால், 'இன்னென்ன நட்சத்திரத்தினால் நமக்கு மழை பொழிந்தது' என்று கூறியவரோ, என்னை நிராகரிப்பவராகவும் நட்சத்திரங்களை நம்புபவராகவும் இருக்கிறார்.\")"},"51":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=54\" class=\"link\">25:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:54 ஐ பார்க்கவும்"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=54\" class=\"link\">25:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:54 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=54\" class=\"link\">25:54</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:54 ஐ பார்க்கவும்"},"54":{"html":"<strong>நபியின் தூதுத்துவத்தின் உலகளாவிய தன்மை, அவருக்கு வழங்கப்பட்ட உதவி மற்றும் மனிதகுலத்திற்கு அல்லாஹ்வின் அருட்கொடைகள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">شِئْنَا</span> <span class=\"quran-arabic-font text-success\">لَبَعَثْنَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">نَّذِيراً</span><br />\r\n<br />\r\n(நாம் நாடியிருந்தால், ஒவ்வொரு ஊரிலும் ஓர் எச்சரிக்கையாளரை எழுப்பியிருப்போம்.) அதாவது, அவர்களை அல்லாஹ்வின் பக்கம் அழைப்பதற்காக (அவ்வாறு செய்திருப்போம்). ஆனால் முஹம்மதே (ஸல்)! பூமிப்பந்தின் அனைத்து மக்களுக்கும் தூதராக அனுப்பப்படுவதற்கு நாம் உங்களையே தனித்துவப்படுத்தியுள்ளோம். மேலும் இந்த குர்ஆனை மக்களுக்கு எடுத்துரைக்குமாறு உங்களுக்குக் கட்டளையிட்டுள்ளோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِأُنذِرَكُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span><br />\r\n<br />\r\n(அதன் மூலம் உங்களையும், அது எவரைச் சென்றடைகிறதோ அவர்களையும் நான் எச்சரிப்பதற்காக இது எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது) (<a href=\"qurandisp.php?sura=6&ayah=19\" class=\"link\">6:19</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَحْزَابِ</span> <span class=\"quran-arabic-font text-success\">فَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مَوْعِدُهُ</span><br />\r\n<br />\r\n(ஆனால் பல்வேறு கூட்டத்தாரில் எவர் இதனை நிராகரிக்கிறாரோ, அவருக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பாகும்) (<a href=\"qurandisp.php?sura=11&ayah=17\" class=\"link\">11:17</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّتُنذِرَ</span> <span class=\"quran-arabic-font text-success\">أُمَّ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">حَوْلَهَا</span><br />\r\n<br />\r\n(நகரங்களின் தாயையும் (மக்காவையும்), அதைச் சுற்றியுள்ளவர்களையும் நீங்கள் எச்சரிப்பதற்காக) (<a href=\"qurandisp.php?sura=42&ayah=7\" class=\"link\">42:7</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّاسُ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span><br />\r\n<br />\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன்...\") (<a href=\"qurandisp.php?sura=7&ayah=158\" class=\"link\">7:158</a>). இரண்டு ஸஹீஹ் (புஹாரி, முஸ்லிம்) நூல்களிலும் நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">بُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْأَحْمَرِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَسْوَد</span>»<br />\r\n<br />\r\n(நான் சிவப்பர்களுக்கும் கருப்பர்களுக்கும் (அனைத்து இனத்தவர்களுக்கும்) தூதராக அனுப்பப்பட்டுள்ளேன்.) மேலும்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">النَّبِيُّ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">خَاصَّةً،</span> <span class=\"quran-arabic-font text-success\">وَبُعِثْتُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">عَامَّة</span>»<br />\r\n<br />\r\n(...ஒரு நபி அவரது சமூகத்தாருக்கு மட்டுமே பிரத்யேகமாக அனுப்பப்படுவார், ஆனால் நான் மனிதகுலம் முழுமைக்கும் பொதுவாக அனுப்பப்பட்டுள்ளேன்.) அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَلاَ</span> <span class=\"quran-arabic-font text-success\">تُطِعِ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرِينَ</span> <span class=\"quran-arabic-font text-success\">وَجَـهِدْهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span><br />\r\n<br />\r\n(எனவே நிராகரிப்பாளர்களுக்குக் கீழ்ப்படியாதீர்கள்; இதைக் (குர்ஆனைக்) கொண்டு அவர்களுடன் பெரும் போராட்டத்தை மேற்கொள்ளுங்கள்.) அதாவது குர்ஆனைக் கொண்டு போராடுங்கள் என்று பொருள். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">جِهَاداً</span> <span class=\"quran-arabic-font text-success\">كَبيراً</span><br />\r\n<br />\r\n(ஒரு மாபெரும் போராட்டத்தை.) இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">النَّبِىُّ</span> <span class=\"quran-arabic-font text-success\">جَـهِدِ</span> <span class=\"quran-arabic-font text-success\">الْكُفَّـرَ</span> <span class=\"quran-arabic-font text-success\">وَالْمُنَـفِقِينَ</span><br />\r\n<br />\r\n(நபியே! நிராகரிப்பாளர்களுடனும் நயவஞ்சகர்களுடனும் கடுமையாகப் போராடுவீராக!) (<a href=\"qurandisp.php?sura=9&ayah=73\" class=\"link\">9:73</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">مَرَجَ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَيْنِ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">عَذْبٌ</span> <span class=\"quran-arabic-font text-success\">فُرَاتٌ</span> <span class=\"quran-arabic-font text-success\">وَهَـذَا</span> <span class=\"quran-arabic-font text-success\">مِلْحٌ</span> <span class=\"quran-arabic-font text-success\">أُجَاجٌ</span><br />\r\n<br />\r\n(அவன்தான் இரண்டு கடல்களையும் ஒன்றாக ஓடச் செய்கிறான்; இது குடிக்க இனிமையான நன்னீர், அதுவோ கசப்பான உவர்நீர்.) அதாவது, அல்லாஹ் இனிமையான நீர் மற்றும் உவர்ப்பான நீர் என இரு வகையான நீரைப் படைத்துள்ளான். நன்னீர் என்பது ஆறுகள், நீரூற்றுகள் மற்றும் கிணறுகளில் காணப்படுவதாகும்; அது தாகத்தைத் தணிக்கும் இனிமையான நீர். இது இப்னு ஜுரைஜ் மற்றும் இப்னு ஜரீர் ஆகியோரின் கருத்தாகும். இதில் எவ்வித சந்தேகமும் இல்லை, ஏனெனில் படைப்பில் எங்குமே குடிக்க இனிமையான நீரைக் கொண்ட கடல் கிடையாது. அல்லாஹ் யதார்த்தமான உண்மையை நமக்குக் கூறுகிறான், இதன் மூலம் அவனது அடியார்கள் தங்களுக்கு வழங்கப்பட்ட அருட்கொடைகளை உணர்ந்து அவனுக்கு நன்றி செலுத்த வேண்டும். நன்னீர் என்பது மக்கள் வாழும் பகுதிகளில் பாய்கிறது. அல்லாஹ் அதனைத் தனது படைப்பினங்களுக்கு அவர்களின் தேவைகளுக்கு ஏற்பப் பங்கிட்டுள்ளான்; ஒவ்வொரு நிலப்பகுதியிலும் அங்கிருப்பவர்களுக்கும் அவர்களின் விவசாயத்திற்கும் தேவையான அளவு ஆறுகளையும் நீரூற்றுகளையும் ஏற்படுத்தியுள்ளான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهَـذَا</span> <span class=\"quran-arabic-font text-success\">مِلْحٌ</span> <span class=\"quran-arabic-font text-success\">أُجَاجٌ</span><br />\r\n<br />\r\n(அதுவோ உவர்ப்பானதும் கசப்பானதுமாகும்;) அதாவது அது மிகவும் உப்பாகவும், கசப்பாகவும், தொண்டையில் இறங்குவதற்கு எளிதாக இல்லாமலும் இருக்கும். இது கிழக்கு மற்றும் மேற்கில் அறியப்பட்ட கடல்களைப் போன்றது: அட்லாண்டிக் பெருங்கடல் மற்றும் அதனுடன் இணையும் ஜலசந்திகள், செங்கடல், அரபிக் கடல், பாரசீக வளைகுடா, சீனக் கடல், இந்தியப் பெருங்கடல், மத்தியதரைக் கடல், கருங்கடல் போன்றவை. இக்கடல்கள் அனைத்தும் ஓடாமல் ஓரிடத்தில் நிலைத்திருப்பவை, ஆனால் குளிர்காலத்திலும் பலத்த காற்று வீசும்போதும் பொங்கி எழும் தன்மை கொண்டவை. இவை அலைகளின் ஏற்றவற்றங்களைக் கொண்டுள்ளன. ஒவ்வொரு மாதத்தின் தொடக்கத்திலும் அலைகள் ஏறி இறங்கும்; மாதம் முடியும்போது அவை பழைய நிலைக்குத் திரும்பும். அடுத்த மாதப் பிறை தோன்றும் போது மீண்டும் அலைகளின் ஏற்றம் தொடங்கி 14-ஆம் நாள் வரை நீடிக்கும், பின்னர் குறையும். முழுமையான ஆற்றல் கொண்ட தூயவனாகிய அல்லாஹ் இந்த விதிகளை அமைத்துள்ளான். இக்கடல்கள் தேங்கி நிற்கின்றன. அதன் நீர் உப்பாக இல்லாவிட்டால், காற்று துர்நாற்றம் வீசக்கூடும், அதனால் பூமி முழுவதும் அழுகிப்போகும் வாய்ப்புள்ளது. மேலும் கடலில் இறக்கும் உயிரினங்களால் பூமி பாழாகிவிடும் என்பதால், அதன் நீரை அவன் உப்பாக ஆக்கினான். அதன் நீர் உப்பாக இருப்பதால், அதன் காற்று ஆரோக்கியமானது மற்றும் அதில் செத்து மிதப்பவை (உண்ண) அனுமதிக்கப்பட்டவை. இதனால்தான், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கடல்நீரைக் கொண்டு உளூ செய்யலாமா என்று கேட்கப்பட்டபோது, அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الطَّهُورُ</span> <span class=\"quran-arabic-font text-success\">مَاؤُهُ،</span> <span class=\"quran-arabic-font text-success\">الْحِلُّ</span> <span class=\"quran-arabic-font text-success\">مَيْتَتُه</span>»<br />\r\n<br />\r\n(அதன் நீர் தூய்மையானது, அதில் செத்து மிதப்பவை அனுமதிக்கப்பட்டவை.) இதனை இமாம் மாலிக், அஷ்-ஷாஃபிஈ, அஹ்மத் மற்றும் சுனன் நூலாசிரியர்கள் 'ஜையித்' (ஆதாரப்பூர்வமான) அறிவிப்பாளர் தொடருடன் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">بَرْزَخاً</span> <span class=\"quran-arabic-font text-success\">وَحِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(மேலும் அவற்றுக்கிடையே ஒரு திரையையும் மீற முடியாத ஒரு தடையையும் அவன் ஏற்படுத்தினான்.) அதாவது, நன்னீருக்கும் உவர்நீருக்கும் இடையில்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بَرْزَخاً</span><br />\r\n<br />\r\n(திரை) என்பது ஒரு தடுப்பாகும், இது நிலப்பகுதியைக் குறிக்கும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَحِجْراً</span> <span class=\"quran-arabic-font text-success\">مَّحْجُوراً</span><br />\r\n<br />\r\n(மீற முடியாத தடை) என்பது, ஒன்றோடொன்று கலப்பதைத் தடுக்கும் ஒரு தடையாகும். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَرَجَ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَيْنِ</span> <span class=\"quran-arabic-font text-success\">يَلْتَقِيَانِ</span> - <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span> <span class=\"quran-arabic-font text-success\">بَرْزَخٌ</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">يَبْغِيَانِ</span> <span class=\"quran-arabic-font text-success\">فَبِأَىِّ</span> <span class=\"quran-arabic-font text-success\">ءَالاءِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكُمَا</span> <span class=\"quran-arabic-font text-success\">تُكَذِّبَانِ</span><br />\r\n<br />\r\n(அவன் இரு கடல்களையும் சந்திக்கச் செய்கிறான். அவற்றுக்கிடையே ஒரு திரை உள்ளது; அதை அவை மீறாது. ஆகவே, உங்கள் இறைவனின் அருட்கொடைகளில் எதனை நீங்கள் இருவரும் பொய்ப்பிப்பீர்கள்?) (<a href=\"qurandisp.php?sura=55&ayah=19\" class=\"link\">55:19</a>-21)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمَّن</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضَ</span> <span class=\"quran-arabic-font text-success\">قَرَاراً</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">خِلاَلَهَآ</span> <span class=\"quran-arabic-font text-success\">أَنْهَاراً</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">رَوَاسِىَ</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَيْنِ</span> <span class=\"quran-arabic-font text-success\">حَاجِزاً</span> <span class=\"quran-arabic-font text-success\">أَءِلـهٌ</span> <span class=\"quran-arabic-font text-success\">مَّعَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُونَ</span><br />\r\n<br />\r\n(பூமியை வசிக்கத்தக்க இடமாக ஆக்கியவனும், அதன் இடையே ஆறுகளை ஓடச் செய்தவனும், அதற்காக உறுதியான மலைகளை அமைத்தவனும், இரு கடல்களுக்கிடையே ஒரு தடுப்பை ஏற்படுத்தியவனும் யார்? அல்லாஹ்வுடன் வேறு ஏதேனும் ஒரு கடவுள் இருக்கின்றாரா? இல்லை! அவர்களில் பெரும்பாலானோர் அறியமாட்டார்கள்.) (<a href=\"qurandisp.php?sura=27&ayah=61\" class=\"link\">27:61</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَآءِ</span> <span class=\"quran-arabic-font text-success\">بَشَراً</span><br />\r\n<br />\r\n(அவன்தான் மனிதனை நீரிலிருந்து படைத்தான்,) அதாவது, அவன் மனிதனை ஒரு பலவீனமான விந்துத் துளியிலிருந்து (நுத்ஃபா) படைத்து, அவனுக்கு ஒரு வடிவத்தைக் கொடுத்து, அவன் நாடியபடி ஆண், பெண் என அவனது உருவத்தை முழுமைப்படுத்தினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَجَعَلَهُ</span> <span class=\"quran-arabic-font text-success\">نَسَباً</span> <span class=\"quran-arabic-font text-success\">وَصِهْراً</span><br />\r\n<br />\r\n(மேலும் அவனுக்காக இரத்த உறவுகளையும், திருமண பந்தங்கள் மூலமான உறவுகளையும் ஏற்படுத்தினான்.) ஆரம்பத்தில் அவன் ஒருவருடைய பிள்ளையாக இருக்கிறான், பிறகு திருமணம் செய்து ஒருவருக்கு மருமகனாகிறான், பின்னர் அவனுக்கே மருமகன்களும் திருமண உறவு முறைகளும் உருவாகின்றன. இவை அனைத்தும் ஒரு அற்பமான திரவத்திலிருந்து உருவாகின்றன. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">قَدِيراً</span><br />\r\n<br />\r\n(மேலும் உமது இறைவன் தான் நாடியதைச் செய்ய பேராற்றல் உடையவன்.)<br />\r\n<br />","text":"நபியின் தூதுத்துவத்தின் உலகளாவிய தன்மை, அவருக்கு வழங்கப்பட்ட உதவி மற்றும் மனிதகுலத்திற்கு அல்லாஹ்வின் அருட்கொடைகள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ شِئْنَا لَبَعَثْنَا فِى كُلِّ قَرْيَةٍ نَّذِيراً\n\r\n\n\r\n(நாம் நாடியிருந்தால், ஒவ்வொரு ஊரிலும் ஓர் எச்சரிக்கையாளரை எழுப்பியிருப்போம்.) அதாவது, அவர்களை அல்லாஹ்வின் பக்கம் அழைப்பதற்காக (அவ்வாறு செய்திருப்போம்). ஆனால் முஹம்மதே (ஸல்)! பூமிப்பந்தின் அனைத்து மக்களுக்கும் தூதராக அனுப்பப்படுவதற்கு நாம் உங்களையே தனித்துவப்படுத்தியுள்ளோம். மேலும் இந்த குர்ஆனை மக்களுக்கு எடுத்துரைக்குமாறு உங்களுக்குக் கட்டளையிட்டுள்ளோம்.\n\r\n\n\r\nلِأُنذِرَكُم بِهِ وَمَن بَلَغَ\n\r\n\n\r\n(அதன் மூலம் உங்களையும், அது எவரைச் சென்றடைகிறதோ அவர்களையும் நான் எச்சரிப்பதற்காக இது எனக்கு வஹீ (இறைச்செய்தி) அறிவிக்கப்பட்டுள்ளது) (6:19).\n\r\n\n\r\nوَمَن يَكْفُرْ بِهِ مِنَ الْأَحْزَابِ فَالنَّارُ مَوْعِدُهُ\n\r\n\n\r\n(ஆனால் பல்வேறு கூட்டத்தாரில் எவர் இதனை நிராகரிக்கிறாரோ, அவருக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பாகும்) (11:17).\n\r\n\n\r\nلِّتُنذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا\n\r\n\n\r\n(நகரங்களின் தாயையும் (மக்காவையும்), அதைச் சுற்றியுள்ளவர்களையும் நீங்கள் எச்சரிப்பதற்காக) (42:7).\n\r\n\n\r\nقُلْ يَأَيُّهَا النَّاسُ إِنِّى رَسُولُ اللَّهِ إِلَيْكُمْ جَمِيعًا\n\r\n\n\r\n(கூறுவீராக: \"மனிதர்களே! நிச்சயமாக நான் உங்கள் அனைவருக்கும் அல்லாஹ்வின் தூதராக அனுப்பப்பட்டுள்ளேன்...\") (7:158). இரண்டு ஸஹீஹ் (புஹாரி, முஸ்லிம்) நூல்களிலும் நபி (ஸல்) அவர்கள் பின்வருமாறு கூறினார்கள் எனப் பதிவு செய்யப்பட்டுள்ளது:\n\r\n\n\r\n«بُعِثْتُ إِلَى الْأَحْمَرِ وَالْأَسْوَد»\n\r\n\n\r\n(நான் சிவப்பர்களுக்கும் கருப்பர்களுக்கும் (அனைத்து இனத்தவர்களுக்கும்) தூதராக அனுப்பப்பட்டுள்ளேன்.) மேலும்:\n\r\n\n\r\n«وَكَانَ النَّبِيُّ يُبْعَثُ إِلَى قَوْمِهِ خَاصَّةً، وَبُعِثْتُ إِلَى النَّاسِ عَامَّة»\n\r\n\n\r\n(...ஒரு நபி அவரது சமூகத்தாருக்கு மட்டுமே பிரத்யேகமாக அனுப்பப்படுவார், ஆனால் நான் மனிதகுலம் முழுமைக்கும் பொதுவாக அனுப்பப்பட்டுள்ளேன்.) அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَلاَ تُطِعِ الْكَـفِرِينَ وَجَـهِدْهُمْ بِهِ\n\r\n\n\r\n(எனவே நிராகரிப்பாளர்களுக்குக் கீழ்ப்படியாதீர்கள்; இதைக் (குர்ஆனைக்) கொண்டு அவர்களுடன் பெரும் போராட்டத்தை மேற்கொள்ளுங்கள்.) அதாவது குர்ஆனைக் கொண்டு போராடுங்கள் என்று பொருள். இது இப்னு அப்பாஸ் (ரழி) அவர்களின் கருத்தாகும்.\n\r\n\n\r\nجِهَاداً كَبيراً\n\r\n\n\r\n(ஒரு மாபெரும் போராட்டத்தை.) இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَأَيُّهَا النَّبِىُّ جَـهِدِ الْكُفَّـرَ وَالْمُنَـفِقِينَ\n\r\n\n\r\n(நபியே! நிராகரிப்பாளர்களுடனும் நயவஞ்சகர்களுடனும் கடுமையாகப் போராடுவீராக!) (9:73)\n\r\n\n\r\nوَهُوَ الَّذِى مَرَجَ الْبَحْرَيْنِ هَـذَا عَذْبٌ فُرَاتٌ وَهَـذَا مِلْحٌ أُجَاجٌ\n\r\n\n\r\n(அவன்தான் இரண்டு கடல்களையும் ஒன்றாக ஓடச் செய்கிறான்; இது குடிக்க இனிமையான நன்னீர், அதுவோ கசப்பான உவர்நீர்.) அதாவது, அல்லாஹ் இனிமையான நீர் மற்றும் உவர்ப்பான நீர் என இரு வகையான நீரைப் படைத்துள்ளான். நன்னீர் என்பது ஆறுகள், நீரூற்றுகள் மற்றும் கிணறுகளில் காணப்படுவதாகும்; அது தாகத்தைத் தணிக்கும் இனிமையான நீர். இது இப்னு ஜுரைஜ் மற்றும் இப்னு ஜரீர் ஆகியோரின் கருத்தாகும். இதில் எவ்வித சந்தேகமும் இல்லை, ஏனெனில் படைப்பில் எங்குமே குடிக்க இனிமையான நீரைக் கொண்ட கடல் கிடையாது. அல்லாஹ் யதார்த்தமான உண்மையை நமக்குக் கூறுகிறான், இதன் மூலம் அவனது அடியார்கள் தங்களுக்கு வழங்கப்பட்ட அருட்கொடைகளை உணர்ந்து அவனுக்கு நன்றி செலுத்த வேண்டும். நன்னீர் என்பது மக்கள் வாழும் பகுதிகளில் பாய்கிறது. அல்லாஹ் அதனைத் தனது படைப்பினங்களுக்கு அவர்களின் தேவைகளுக்கு ஏற்பப் பங்கிட்டுள்ளான்; ஒவ்வொரு நிலப்பகுதியிலும் அங்கிருப்பவர்களுக்கும் அவர்களின் விவசாயத்திற்கும் தேவையான அளவு ஆறுகளையும் நீரூற்றுகளையும் ஏற்படுத்தியுள்ளான்.\n\r\n\n\r\nوَهَـذَا مِلْحٌ أُجَاجٌ\n\r\n\n\r\n(அதுவோ உவர்ப்பானதும் கசப்பானதுமாகும்;) அதாவது அது மிகவும் உப்பாகவும், கசப்பாகவும், தொண்டையில் இறங்குவதற்கு எளிதாக இல்லாமலும் இருக்கும். இது கிழக்கு மற்றும் மேற்கில் அறியப்பட்ட கடல்களைப் போன்றது: அட்லாண்டிக் பெருங்கடல் மற்றும் அதனுடன் இணையும் ஜலசந்திகள், செங்கடல், அரபிக் கடல், பாரசீக வளைகுடா, சீனக் கடல், இந்தியப் பெருங்கடல், மத்தியதரைக் கடல், கருங்கடல் போன்றவை. இக்கடல்கள் அனைத்தும் ஓடாமல் ஓரிடத்தில் நிலைத்திருப்பவை, ஆனால் குளிர்காலத்திலும் பலத்த காற்று வீசும்போதும் பொங்கி எழும் தன்மை கொண்டவை. இவை அலைகளின் ஏற்றவற்றங்களைக் கொண்டுள்ளன. ஒவ்வொரு மாதத்தின் தொடக்கத்திலும் அலைகள் ஏறி இறங்கும்; மாதம் முடியும்போது அவை பழைய நிலைக்குத் திரும்பும். அடுத்த மாதப் பிறை தோன்றும் போது மீண்டும் அலைகளின் ஏற்றம் தொடங்கி 14-ஆம் நாள் வரை நீடிக்கும், பின்னர் குறையும். முழுமையான ஆற்றல் கொண்ட தூயவனாகிய அல்லாஹ் இந்த விதிகளை அமைத்துள்ளான். இக்கடல்கள் தேங்கி நிற்கின்றன. அதன் நீர் உப்பாக இல்லாவிட்டால், காற்று துர்நாற்றம் வீசக்கூடும், அதனால் பூமி முழுவதும் அழுகிப்போகும் வாய்ப்புள்ளது. மேலும் கடலில் இறக்கும் உயிரினங்களால் பூமி பாழாகிவிடும் என்பதால், அதன் நீரை அவன் உப்பாக ஆக்கினான். அதன் நீர் உப்பாக இருப்பதால், அதன் காற்று ஆரோக்கியமானது மற்றும் அதில் செத்து மிதப்பவை (உண்ண) அனுமதிக்கப்பட்டவை. இதனால்தான், அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கடல்நீரைக் கொண்டு உளூ செய்யலாமா என்று கேட்கப்பட்டபோது, அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«هُوَ الطَّهُورُ مَاؤُهُ، الْحِلُّ مَيْتَتُه»\n\r\n\n\r\n(அதன் நீர் தூய்மையானது, அதில் செத்து மிதப்பவை அனுமதிக்கப்பட்டவை.) இதனை இமாம் மாலிக், அஷ்-ஷாஃபிஈ, அஹ்மத் மற்றும் சுனன் நூலாசிரியர்கள் 'ஜையித்' (ஆதாரப்பூர்வமான) அறிவிப்பாளர் தொடருடன் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nوَجَعَلَ بَيْنَهُمَا بَرْزَخاً وَحِجْراً مَّحْجُوراً\n\r\n\n\r\n(மேலும் அவற்றுக்கிடையே ஒரு திரையையும் மீற முடியாத ஒரு தடையையும் அவன் ஏற்படுத்தினான்.) அதாவது, நன்னீருக்கும் உவர்நீருக்கும் இடையில்.\n\r\n\n\r\nبَرْزَخاً\n\r\n\n\r\n(திரை) என்பது ஒரு தடுப்பாகும், இது நிலப்பகுதியைக் குறிக்கும்.\n\r\n\n\r\nوَحِجْراً مَّحْجُوراً\n\r\n\n\r\n(மீற முடியாத தடை) என்பது, ஒன்றோடொன்று கலப்பதைத் தடுக்கும் ஒரு தடையாகும். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nمَرَجَ الْبَحْرَيْنِ يَلْتَقِيَانِ - بَيْنَهُمَا بَرْزَخٌ لاَّ يَبْغِيَانِ فَبِأَىِّ ءَالاءِ رَبِّكُمَا تُكَذِّبَانِ\n\r\n\n\r\n(அவன் இரு கடல்களையும் சந்திக்கச் செய்கிறான். அவற்றுக்கிடையே ஒரு திரை உள்ளது; அதை அவை மீறாது. ஆகவே, உங்கள் இறைவனின் அருட்கொடைகளில் எதனை நீங்கள் இருவரும் பொய்ப்பிப்பீர்கள்?) (55:19-21)\n\r\n\n\r\nأَمَّن جَعَلَ الْأَرْضَ قَرَاراً وَجَعَلَ خِلاَلَهَآ أَنْهَاراً وَجَعَلَ لَهَا رَوَاسِىَ وَجَعَلَ بَيْنَ الْبَحْرَيْنِ حَاجِزاً أَءِلـهٌ مَّعَ اللهِ بَلْ أَكْثَرُهُمْ لاَ يَعْلَمُونَ\n\r\n\n\r\n(பூமியை வசிக்கத்தக்க இடமாக ஆக்கியவனும், அதன் இடையே ஆறுகளை ஓடச் செய்தவனும், அதற்காக உறுதியான மலைகளை அமைத்தவனும், இரு கடல்களுக்கிடையே ஒரு தடுப்பை ஏற்படுத்தியவனும் யார்? அல்லாஹ்வுடன் வேறு ஏதேனும் ஒரு கடவுள் இருக்கின்றாரா? இல்லை! அவர்களில் பெரும்பாலானோர் அறியமாட்டார்கள்.) (27:61)\n\r\n\n\r\nوَهُوَ الَّذِى خَلَقَ مِنَ الْمَآءِ بَشَراً\n\r\n\n\r\n(அவன்தான் மனிதனை நீரிலிருந்து படைத்தான்,) அதாவது, அவன் மனிதனை ஒரு பலவீனமான விந்துத் துளியிலிருந்து (நுத்ஃபா) படைத்து, அவனுக்கு ஒரு வடிவத்தைக் கொடுத்து, அவன் நாடியபடி ஆண், பெண் என அவனது உருவத்தை முழுமைப்படுத்தினான்.\n\r\n\n\r\nفَجَعَلَهُ نَسَباً وَصِهْراً\n\r\n\n\r\n(மேலும் அவனுக்காக இரத்த உறவுகளையும், திருமண பந்தங்கள் மூலமான உறவுகளையும் ஏற்படுத்தினான்.) ஆரம்பத்தில் அவன் ஒருவருடைய பிள்ளையாக இருக்கிறான், பிறகு திருமணம் செய்து ஒருவருக்கு மருமகனாகிறான், பின்னர் அவனுக்கே மருமகன்களும் திருமண உறவு முறைகளும் உருவாகின்றன. இவை அனைத்தும் ஒரு அற்பமான திரவத்திலிருந்து உருவாகின்றன. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَكَانَ رَبُّكَ قَدِيراً\n\r\n\n\r\n(மேலும் உமது இறைவன் தான் நாடியதைச் செய்ய பேராற்றல் உடையவன்.)"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=60\" class=\"link\">25:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:60 ஐ பார்க்கவும்"},"56":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=60\" class=\"link\">25:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:60 ஐ பார்க்கவும்"},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=60\" class=\"link\">25:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:60 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=60\" class=\"link\">25:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:60 ஐ பார்க்கவும்"},"59":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=60\" class=\"link\">25:60</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:60 ஐ பார்க்கவும்"},"60":{"html":"<strong>இணைவைப்பாளர்களின் அறியாமை</strong><br />\r\n<br />\r\nஇணைவைப்பாளர்கள் எவ்வளவு அறியாமையில் இருக்கிறார்கள் என்பதை அல்லாஹ் நமக்குத் தெளிவுபடுத்துகிறான்; அல்லாஹ்வை வணங்குவதற்குப் பதிலாக, தங்களுக்கு நன்மையோ அல்லது தீமையோ செய்ய எந்த ஆற்றலும் இல்லாத சிலைகளை அவர்கள் வணங்குகிறார்கள். அவர்கள் எந்தவித ஆதாரமும் அத்தாட்சியும் இன்றி இதனைச் செய்கிறார்கள்; அவர்களின் மனோ இச்சைகளும் சுய விருப்பங்களும் மட்டுமே அவர்களை இவ்வாறு செய்யத் தூண்டின. எனவே, அவர்கள் இந்தச் சிலைகளைப் பாதுகாப்பாளர்களாக ஏற்றுக்கொண்டு அவற்றுக்காகப் போராடுகிறார்கள்; மேலும் அவற்றுக்காக அல்லாஹ்வையும், அவனது தூதரையும், இறைநம்பிக்கையாளர்களையும் எதிர்க்கிறார்கள். இதனைப் போன்றே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">ظَهِيراً</span><br />\r\n<br />\r\n(இறைமறுப்பாளன் தன் இறைவனுக்கு எதிராக உதவி செய்பவனாக இருக்கிறான்.) அதாவது, அவன் அல்லாஹ்வின் கூட்டத்திற்கு எதிராக ஷைத்தானுக்கு ஆதரவாளனாக இருக்கிறான். ஆனால் அல்லாஹ்வின் கூட்டத்தினரே வெற்றி பெறுவார்கள் என்பதை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاتَّخَذُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَةً</span> <span class=\"quran-arabic-font text-success\">لَّعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يُنصَرُونَ</span> - <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعُونَ</span> <span class=\"quran-arabic-font text-success\">نَصْرَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">جُندٌ</span> <span class=\"quran-arabic-font text-success\">مٌّحْضَرُونَ</span><br />\r\n<br />\r\n(தங்களுக்கு உதவி கிடைக்கும் என்ற நம்பிக்கையில் அல்லாஹ்வையன்றி பிற தெய்வங்களை அவர்கள் ஏற்படுத்திக் கொண்டார்கள். அத்தெய்வங்களால் அவர்களுக்கு உதவ முடியாது; ஆனால் இவர்களோ அத்தெய்வங்களுக்காகத் திரட்டப்பட்ட படைகளாக இருக்கின்றனர்.) (<a href=\"qurandisp.php?sura=36&ayah=74\" class=\"link\">36:74</a>-75). அதாவது அல்லாஹ்வைத் தவிர அவர்கள் வணங்கும் அந்தத் தெய்வங்களால் அவர்களுக்கு உதவ முடியாது. இந்த அறிவற்ற மக்கள் அந்தச் சிலைகளுக்காகப் படைகளாக நின்று, அவற்றிற்காகப் போராடவும் அவற்றின் புனிதத் தலங்களைப் பாதுகாக்கவும் தயாராக இருக்கிறார்கள். ஆனால் இறுதியில் இந்த உலகத்திலும் மறுமையிலும் வெற்றி என்பது அல்லாஹ்வுக்கும், அவனது தூதருக்கும், இறைநம்பிக்கையாளர்களுக்கும் மட்டுமே உரியதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">الْكَـفِرُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">ظَهِيراً</span><br />\r\n<br />\r\n(இறைமறுப்பாளன் தன் இறைவனுக்கு எதிராக உதவி செய்பவனாக இருக்கிறான்.) இது குறித்து முஜாஹித் அவர்கள் கூறினார்கள்: \"அவன் அல்லாஹ்வுக்கு மாறு செய்வதில் ஷைத்தானுக்கு ஆதரவளித்து உதவுகிறான்.\"<br />\r\n<br />\r\n<strong>நற்செய்தி கூறுபவராகவும் எச்சரிக்கை செய்பவராகவும் தூதர் (ஸல்)</strong><br />\r\n<br />\r\nபிறகு அல்லாஹ் தனது தூதரிடம் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَـكَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مُبَشِّراً</span> <span class=\"quran-arabic-font text-success\">وَنَذِيراً</span><br />\r\n<br />\r\n(மேலும், நாம் உம்மை நற்செய்தி கூறுபவராகவும் எச்சரிக்கை செய்பவராகவுமே தவிர அனுப்பவில்லை.) அதாவது, இறைநம்பிக்கையாளர்களுக்கு நற்செய்தி கூறுபவராகவும், இறைமறுப்பாளர்களுக்கு எச்சரிக்கை செய்பவராகவும்; அல்லாஹ்வுக்குக் கீழ்ப்படிபவர்களுக்குச் சொர்க்கத்தைப் பற்றிய நற்செய்தியை வழங்குபவராகவும், அல்லாஹ்வின் கட்டளைகளை மீறுபவர்களுக்குக் கடுமையான தண்டனை குறித்து எச்சரிப்பவராகவும் (உம்மை அனுப்பினோம்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَتَّخِذَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">سَبِيلاً</span><br />\r\n<br />\r\n(கூறுவீராக: \"இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை; ஆனால், தன் இறைவனிடம் ஒரு வழியை ஏற்படுத்திக் கொள்ள விரும்புபவரைத் தவிர.\") 'இந்தச் செய்தியை எத்திவைப்பதற்கும், இந்த எச்சரிக்கைக்கும் உங்கள் செல்வத்திலிருந்து நான் எந்தப் பிரதிபலனையும் கேட்கவில்லை; நான் இதனை அல்லாஹ்வுக்காக மட்டுமே செய்கிறேன், அவன் மிகவும் உயர்ந்தவன்.' (இதன் பொருள், பின்பற்றப்பட வேண்டிய ஒரு வழிமுறை என்பதாகும்.) இது குறித்து அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَسْتَقِيمَ</span><br />\r\n<br />\r\n(உங்களில் நேராக நடக்க விரும்புவோருக்கு (இது அறிவுரையாகும்)) (<a href=\"qurandisp.php?sura=81&ayah=28\" class=\"link\">81:28</a>).<br />\r\n<br />\r\nஅல்லாஹ்வின் மீது நம்பிக்கை வைக்குமாறு தூதருக்குக் கட்டளை, மற்றும் அவனது சில பண்புகள்<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَوَكَّلْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْحَىِّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span><br />\r\n<br />\r\n(மரணிக்காத, என்றும் உயிரோடிருப்பவன் மீது உமது பொறுப்புகளை ஒப்படைப்பீராக (நம்பிக்கை வைப்பீராக),) அதாவது, உமது அனைத்துக் காரியங்களிலும், ஒருபோதும் மரணிக்காத, என்றும் உயிரோடிருப்பவனான அல்லாஹ்வின் மீது நம்பிக்கை வையுங்கள். அவன் எத்தகையவன் என்றால்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الاٌّوَّلُ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّخِرُ</span> <span class=\"quran-arabic-font text-success\">وَالظَّـهِرُ</span> <span class=\"quran-arabic-font text-success\">وَالْبَـطِنُ</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ</span><br />\r\n<br />\r\n(அவனே முதலாமவன், இறுதியானவன், வெளியானவன், உள்ளானவன். மேலும் அவன் அனைத்தையும் நன்கறிந்தவன்.) (<a href=\"qurandisp.php?sura=57&ayah=3\" class=\"link\">57:3</a>). அவன் நித்தியமானவன், என்றென்றும் நிலைத்திருப்பவன், என்றும் உயிரோடிருப்பவன், தன்னிறைவு பெற்றவன், அனைத்துப் பொருட்களுக்கும் இறைவனும் அதிபதியுமாவான். அவனிடமே நீங்கள் எப்போதும் திரும்ப வேண்டும். அல்லாஹ் ஒருவனே நீங்கள் நம்பிக்கை வைக்க வேண்டியவன் மற்றும் அடைக்கலம் தேட வேண்டியவன்; அவன் உங்களுக்குப் போதுமானவன், உமது உதவியாளனாகவும் ஆதரவாளனாகவும் இருந்து உம்மை வெற்றிபெறச் செய்வான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَـأَيُّهَا</span> <span class=\"quran-arabic-font text-success\">الرَّسُولُ</span> <span class=\"quran-arabic-font text-success\">بَلِّغْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّبِّكَ</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَفْعَلْ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">بَلَّغْتَ</span> <span class=\"quran-arabic-font text-success\">رِسَالَتَهُ</span> <span class=\"quran-arabic-font text-success\">وَاللَّهُ</span> <span class=\"quran-arabic-font text-success\">يَعْصِمُكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span><br />\r\n<br />\r\n(தூதரே! உமது இறைவனிடமிருந்து உமக்கு இறக்கப்பட்டதை எத்திவைப்பீராக. நீர் அவ்வாறு செய்யாவிட்டால், அவனது தூதுச் செய்தியை நீர் எத்திவைத்தவராக மாட்டீர். மேலும் அல்லாஹ் உம்மை மனிதர்களிடமிருந்து பாதுகாப்பான்.) (<a href=\"qurandisp.php?sura=5&ayah=67\" class=\"link\">5:67</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَبِّحْ</span> <span class=\"quran-arabic-font text-success\">بِحَمْدِهِ</span><br />\r\n<br />\r\n(அவனது புகழைக் கொண்டு அவனைத் துதிப்பீராக,) இதன் பொருள், அவனைப் புகழ்வதையும் துதிப்பதையும் இணைத்துச் செய்யுங்கள் என்பதாகும். எனவே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறுவார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">سُبْحَانَكَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">وَبِحَمْدِك</span>»<br />\r\n<br />\r\n(எங்கள் இறைவா! அல்லாஹ்வே! நீ தூய்மையானவன், உன்னைப் புகழ்ந்து துதிக்கிறேன்.) ஆகவே, இந்த வசனத்தின் பொருள்: அவனை வணங்குவதிலும் அவன் மீது நம்பிக்கை வைப்பதிலும் உண்மையாக இருங்கள் என்பதாகும். இது பின்வரும் வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">رَّبُّ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَغْرِبِ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">إِلَـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">فَاتَّخِذْهُ</span> <span class=\"quran-arabic-font text-success\">وَكِيلاً</span><br />\r\n<br />\r\n(கிழக்கு மற்றும் மேற்கின் இறைவன்; அவனைத் தவிர வேறு இறைவன் இல்லை. எனவே அவனையே உமது பொறுப்பாளனாக ஆக்கிக் கொள்வீராக.) (<a href=\"qurandisp.php?sura=73&ayah=9\" class=\"link\">73:9</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاعْبُدْهُ</span> <span class=\"quran-arabic-font text-success\">وَتَوَكَّلْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span><br />\r\n<br />\r\n(எனவே அவனையே வணங்குவீராக, அவன் மீதே நம்பிக்கை வைப்பீராக.) (<a href=\"qurandisp.php?sura=11&ayah=123\" class=\"link\">11:123</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَعَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">تَوَكَّلْنَا</span><br />\r\n<br />\r\n(கூறுவீராக: \"அவனே அளவற்ற அருளாளன், அவன் மீதே நாங்கள் ஈமான் (நம்பிக்கை) கொண்டோம், அவனையே நாங்கள் சார்ந்திருக்கிறோம்.\") (<a href=\"qurandisp.php?sura=67&ayah=29\" class=\"link\">67:29</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَفَى</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بِذُنُوبِ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span> <span class=\"quran-arabic-font text-success\">خَبِيراً</span><br />\r\n<br />\r\n(மேலும் தனது அடியார்களின் பாவங்களை நன்கு அறிந்தவனாக அவன் போதுமானவன்.) அதாவது, அவனது முழுமையான அறிவிலிருந்து எதுவும் மறைந்திருக்க முடியாது; ஓர் அணுவளவு கூட அவனுக்குத் தெரியாமல் இருக்க முடியாது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">السَّمَـوَتِ</span> <span class=\"quran-arabic-font text-success\">وَالاٌّرْضَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَا</span><br />\r\n<br />\r\n(அவனே வானங்களையும் பூமியையும் மற்றும் அவற்றுக்கு இடைப்பட்டவற்றையும் படைத்தவன்...) அதாவது, அவன் மரணிக்காத, என்றும் உயிரோடிருப்பவன். அவன் படைப்பாளன், பரிபாலிப்பவன் மற்றும் அனைத்துப் பொருட்களின் அதிபதி. அவன் தனது பேராற்றலால் மிக உயர்ந்த மற்றும் பரந்த ஏழு வானங்களையும், ஆழமான மற்றும் அடர்த்தியான ஏழு பூமிகளையும் படைத்தான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سِتَّةِ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">اسْتَوَى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعَرْشِ</span><br />\r\n<br />\r\n(ஆறு நாட்களில்; பின்னர் அவன் அர்ஷின் மீது உயர்ந்தான்.) அதாவது, அவன் அனைத்து விவகாரங்களையும் நிர்வகிக்கிறான், சத்தியத்தின் அடிப்படையில் தீர்ப்பளிக்கிறான்; மேலும் தீர்ப்பளிப்பவர்களில் அவனே சிறந்தவன்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span> <span class=\"quran-arabic-font text-success\">فَاسْأَلْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">خَبِيراً</span><br />\r\n<br />\r\n(அவன் அளவற்ற அருளாளன்! அவனைப் பற்றி நன்கு அறிந்தவரிடம் கேட்பீராக.) அதாவது, அவனைப் பற்றி மிகச் சரியாக அறிந்தவரிடம் கேட்டுத் தெரிந்துகொள்ளுங்கள், அவரைப் பின்பற்றுங்கள், அவரை உமது முன்மாதிரியாக எடுத்துக் கொள்ளுங்கள். அல்லாஹ்வைப் பற்றி அவனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களை விட வேறு எவரும் அதிகம் அறிந்திருக்க முடியாது என்பது அனைவரும் அறிந்ததே. அவர்கள் இந்த உலகத்திலும் மறுமையிலும் ஆதமின் மக்களின் முழுமையான தலைவர். அவர்கள் தனது மனோ இச்சையின்படி பேசுவதில்லை; மாறாக தமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி)யையே எத்திவைக்கிறார்கள். அவர்கள் கூறுவது உண்மையாகும்; அவர்களது முடிவே இறுதியானது. ஏதேனும் சர்ச்சை ஏற்படும்போது மக்கள் அவர்களிடம் தீர்வு பெறக் கடமைப்பட்டுள்ளனர். அவர்களது சொல்லுக்கும் செயலுக்கும் இணக்கமானவையே சரியானவை; அவற்றுக்கு முரணானவை யாரால் சொல்லப்பட்டாலும் அல்லது செய்யப்பட்டாலும் அவை நிராகரிக்கப்பட வேண்டியவை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِن</span> <span class=\"quran-arabic-font text-success\">تَنَازَعْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span><br />\r\n<br />\r\n(உங்களுக்குள் ஏதேனும் ஒரு விஷயத்தில் முரண்பட்டால்...) (<a href=\"qurandisp.php?sura=4&ayah=59\" class=\"link\">4:59</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">اخْتَلَفْتُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">فَحُكْمُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(மேலும் நீங்கள் எந்த விஷயத்தில் முரண்பட்டாலும் அதற்கான தீர்ப்பு அல்லாஹ்விடமே உள்ளது.) (<a href=\"qurandisp.php?sura=42&ayah=10\" class=\"link\">42:10</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَمَّتْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">صِدْقاً</span> <span class=\"quran-arabic-font text-success\">وَعَدْلاً</span><br />\r\n<br />\r\n(உமது இறைவனின் வார்த்தை உண்மையாலும் நீதியாலும் முழுமை பெற்றுவிட்டது.) (<a href=\"qurandisp.php?sura=6&ayah=115\" class=\"link\">6:115</a>). அதாவது, அவன் உண்மையை உரைத்தான், அவனது கட்டளைகளிலும் தடைகளிலும் அவன் நீதியோடும் நியாயத்தோடும் இருக்கிறான். இதையே அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَاسْأَلْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">خَبِيراً</span><br />\r\n<br />\r\n(அவனைப் பற்றி நன்கு அறிந்தவரிடம் கேட்பீராக.)<br />\r\n<br />\r\n<strong>இணைவைப்பாளர்களுக்குக் கண்டனம்</strong><br />\r\n<br />\r\nஅல்லாஹ்வைத் தவிர்த்து சிலைகளுக்கும் மற்றவர்களுக்கும் ஸஜ்தா செய்யும் இணைவைப்பாளர்களை அல்லாஹ் கண்டிக்கிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">اسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span><br />\r\n<br />\r\n(மேலும் அவர்களிடம், \"அர்-ரஹ்மானுக்கு ஸஜ்தா செய்யுங்கள்!\" என்று கூறப்பட்டால், அவர்கள், \"அர்-ரஹ்மான் என்றால் என்ன?\" என்று கேட்கின்றனர்.) அதாவது: \"அர்-ரஹ்மானை எங்களுக்குத் தெரியாது.\" அல்லாஹ்வை அவனது பெயரான 'அர்-ரஹ்மான்' (அளவற்ற அருளாளன்) என்று அழைப்பதை அவர்கள் விரும்பவில்லை. அல்-ஹுதைபிய்யா உடன்படிக்கையின் போது, நபி (ஸல்) அவர்கள் எழுத்தாளரிடம்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اكْتُبْ</span> <span class=\"quran-arabic-font text-success\">بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيم</span>»<br />\r\n<br />\r\n(\"பிஸ்மில்லாஹிர் ரஹ்மானிர் ரஹீம் - அளவற்ற அருளாளன், நிகரற்ற அன்புடையோனாகிய அல்லாஹ்வின் பெயரால் எழுதுங்கள்\" என்று கூறினார்கள்.) அதற்கு அவர்கள், \"அர்-ரஹ்மானையோ அல்லது அர்-ரஹீமையோ எங்களுக்குத் தெரியாது. நீர் வழக்கமாக எழுதுவதைப் போலவே 'பிஸ்மிக்க அல்லாஹும்ம' (யா அல்லாஹ்! உனது பெயரால்) என்று எழுதுவீராக\" எனக் கூறினர். எனவே அல்லாஹ் இந்த வசனங்களை இறக்கினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلِ</span> <span class=\"quran-arabic-font text-success\">ادْعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">ادْعُواْ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنَ</span> <span class=\"quran-arabic-font text-success\">أَيًّا</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَدْعُواْ</span> <span class=\"quran-arabic-font text-success\">فَلَهُ</span> <span class=\"quran-arabic-font text-success\">الاٌّسْمَآءَ</span> <span class=\"quran-arabic-font text-success\">الْحُسْنَى</span><br />\r\n<br />\r\n(கூறுவீராக: \"அல்லாஹ் என்று அழையுங்கள் அல்லது அர்-ரஹ்மான் என்று அழையுங்கள்; நீங்கள் எந்தப் பெயரால் அவனை அழைத்தாலும் அவனுக்கு மிக அழகிய பெயர்கள் உண்டு.\") (<a href=\"qurandisp.php?sura=17&ayah=110\" class=\"link\">17:110</a>). அதாவது அவனே அல்லாஹ், அவனே அளவற்ற அருளாளன். மேலும் இந்த வசனத்தில் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمُ</span> <span class=\"quran-arabic-font text-success\">اسْجُدُواْ</span> <span class=\"quran-arabic-font text-success\">لِلرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنُ</span><br />\r\n<br />\r\n(மேலும் அவர்களிடம், \"அர்-ரஹ்மானுக்கு ஸஜ்தா செய்யுங்கள்!\" என்று கூறப்பட்டால், அவர்கள், \"அர்-ரஹ்மான் என்றால் என்ன?\" என்று கேட்கின்றனர்.) அதாவது: இந்தப் பெயரை நாங்கள் அறியமாட்டோம் அல்லது அங்கீகரிக்க மாட்டோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَنَسْجُدُ</span> <span class=\"quran-arabic-font text-success\">لِمَا</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُنَا</span><br />\r\n<br />\r\n(நீர் எங்களுக்குக் கட்டளையிடுவதற்காக நாங்கள் ஸஜ்தா செய்வோமா?) அதாவது, \"நீர் சொல்வதற்காக மட்டுமே நாங்கள் ஸஜ்தா செய்ய வேண்டுமா?\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَزَادَهُمْ</span> <span class=\"quran-arabic-font text-success\">نُفُوراً</span><br />\r\n<br />\r\n(மேலும் இது அவர்களுக்கு வெறுப்பையே அதிகப்படுத்தியது.) இறைநம்பிக்கையாளர்களைப் பொறுத்தவரை, அவர்கள் அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வை வணங்குகிறார்கள்; அவனுக்கு மட்டுமே இறைத்தன்மையை உரியதாக்கி, அவனுக்கு ஸஜ்தா செய்கிறார்கள். சூரா அல்-ஃபுர்கானின் இந்த ஸஜ்தா வசனத்தை ஓதுபவரும் கேட்பவரும் ஸஜ்தா செய்வது ஆகுமானது மற்றும் அங்கீகரிக்கப்பட்டது என்பதில் அறிஞர்கள் ஒருமித்த கருத்தைக் கொண்டுள்ளனர். அல்லாஹ்வே நன்கு அறிந்தவன்.<br />\r\n<br />","text":"இணைவைப்பாளர்களின் அறியாமை\n\r\n\n\r\nஇணைவைப்பாளர்கள் எவ்வளவு அறியாமையில் இருக்கிறார்கள் என்பதை அல்லாஹ் நமக்குத் தெளிவுபடுத்துகிறான்; அல்லாஹ்வை வணங்குவதற்குப் பதிலாக, தங்களுக்கு நன்மையோ அல்லது தீமையோ செய்ய எந்த ஆற்றலும் இல்லாத சிலைகளை அவர்கள் வணங்குகிறார்கள். அவர்கள் எந்தவித ஆதாரமும் அத்தாட்சியும் இன்றி இதனைச் செய்கிறார்கள்; அவர்களின் மனோ இச்சைகளும் சுய விருப்பங்களும் மட்டுமே அவர்களை இவ்வாறு செய்யத் தூண்டின. எனவே, அவர்கள் இந்தச் சிலைகளைப் பாதுகாப்பாளர்களாக ஏற்றுக்கொண்டு அவற்றுக்காகப் போராடுகிறார்கள்; மேலும் அவற்றுக்காக அல்லாஹ்வையும், அவனது தூதரையும், இறைநம்பிக்கையாளர்களையும் எதிர்க்கிறார்கள். இதனைப் போன்றே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَكَانَ الْكَـفِرُ عَلَى رَبِّهِ ظَهِيراً\n\r\n\n\r\n(இறைமறுப்பாளன் தன் இறைவனுக்கு எதிராக உதவி செய்பவனாக இருக்கிறான்.) அதாவது, அவன் அல்லாஹ்வின் கூட்டத்திற்கு எதிராக ஷைத்தானுக்கு ஆதரவாளனாக இருக்கிறான். ஆனால் அல்லாஹ்வின் கூட்டத்தினரே வெற்றி பெறுவார்கள் என்பதை அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nوَاتَّخَذُواْ مِن دُونِ اللَّهِ ءَالِهَةً لَّعَلَّهُمْ يُنصَرُونَ - لاَ يَسْتَطِيعُونَ نَصْرَهُمْ وَهُمْ لَهُمْ جُندٌ مٌّحْضَرُونَ\n\r\n\n\r\n(தங்களுக்கு உதவி கிடைக்கும் என்ற நம்பிக்கையில் அல்லாஹ்வையன்றி பிற தெய்வங்களை அவர்கள் ஏற்படுத்திக் கொண்டார்கள். அத்தெய்வங்களால் அவர்களுக்கு உதவ முடியாது; ஆனால் இவர்களோ அத்தெய்வங்களுக்காகத் திரட்டப்பட்ட படைகளாக இருக்கின்றனர்.) (36:74-75). அதாவது அல்லாஹ்வைத் தவிர அவர்கள் வணங்கும் அந்தத் தெய்வங்களால் அவர்களுக்கு உதவ முடியாது. இந்த அறிவற்ற மக்கள் அந்தச் சிலைகளுக்காகப் படைகளாக நின்று, அவற்றிற்காகப் போராடவும் அவற்றின் புனிதத் தலங்களைப் பாதுகாக்கவும் தயாராக இருக்கிறார்கள். ஆனால் இறுதியில் இந்த உலகத்திலும் மறுமையிலும் வெற்றி என்பது அல்லாஹ்வுக்கும், அவனது தூதருக்கும், இறைநம்பிக்கையாளர்களுக்கும் மட்டுமே உரியதாகும்.\n\r\n\n\r\nوَكَانَ الْكَـفِرُ عَلَى رَبِّهِ ظَهِيراً\n\r\n\n\r\n(இறைமறுப்பாளன் தன் இறைவனுக்கு எதிராக உதவி செய்பவனாக இருக்கிறான்.) இது குறித்து முஜாஹித் அவர்கள் கூறினார்கள்: \"அவன் அல்லாஹ்வுக்கு மாறு செய்வதில் ஷைத்தானுக்கு ஆதரவளித்து உதவுகிறான்.\"\n\r\n\n\r\nநற்செய்தி கூறுபவராகவும் எச்சரிக்கை செய்பவராகவும் தூதர் (ஸல்)\n\r\n\n\r\nபிறகு அல்லாஹ் தனது தூதரிடம் கூறுகிறான்:\n\r\n\n\r\nوَمَآ أَرْسَلْنَـكَ إِلاَّ مُبَشِّراً وَنَذِيراً\n\r\n\n\r\n(மேலும், நாம் உம்மை நற்செய்தி கூறுபவராகவும் எச்சரிக்கை செய்பவராகவுமே தவிர அனுப்பவில்லை.) அதாவது, இறைநம்பிக்கையாளர்களுக்கு நற்செய்தி கூறுபவராகவும், இறைமறுப்பாளர்களுக்கு எச்சரிக்கை செய்பவராகவும்; அல்லாஹ்வுக்குக் கீழ்ப்படிபவர்களுக்குச் சொர்க்கத்தைப் பற்றிய நற்செய்தியை வழங்குபவராகவும், அல்லாஹ்வின் கட்டளைகளை மீறுபவர்களுக்குக் கடுமையான தண்டனை குறித்து எச்சரிப்பவராகவும் (உம்மை அனுப்பினோம்).\n\r\n\n\r\nقُلْ مَآ أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِلاَّ مَن شَآءَ أَن يَتَّخِذَ إِلَى رَبِّهِ سَبِيلاً\n\r\n\n\r\n(கூறுவீராக: \"இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கேட்கவில்லை; ஆனால், தன் இறைவனிடம் ஒரு வழியை ஏற்படுத்திக் கொள்ள விரும்புபவரைத் தவிர.\") 'இந்தச் செய்தியை எத்திவைப்பதற்கும், இந்த எச்சரிக்கைக்கும் உங்கள் செல்வத்திலிருந்து நான் எந்தப் பிரதிபலனையும் கேட்கவில்லை; நான் இதனை அல்லாஹ்வுக்காக மட்டுமே செய்கிறேன், அவன் மிகவும் உயர்ந்தவன்.' (இதன் பொருள், பின்பற்றப்பட வேண்டிய ஒரு வழிமுறை என்பதாகும்.) இது குறித்து அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلِمَن شَآءَ مِنكُمْ أَن يَسْتَقِيمَ\n\r\n\n\r\n(உங்களில் நேராக நடக்க விரும்புவோருக்கு (இது அறிவுரையாகும்)) (81:28).\n\r\n\n\r\nஅல்லாஹ்வின் மீது நம்பிக்கை வைக்குமாறு தூதருக்குக் கட்டளை, மற்றும் அவனது சில பண்புகள்\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَتَوَكَّلْ عَلَى الْحَىِّ الَّذِى لاَ يَمُوتُ\n\r\n\n\r\n(மரணிக்காத, என்றும் உயிரோடிருப்பவன் மீது உமது பொறுப்புகளை ஒப்படைப்பீராக (நம்பிக்கை வைப்பீராக),) அதாவது, உமது அனைத்துக் காரியங்களிலும், ஒருபோதும் மரணிக்காத, என்றும் உயிரோடிருப்பவனான அல்லாஹ்வின் மீது நம்பிக்கை வையுங்கள். அவன் எத்தகையவன் என்றால்:\n\r\n\n\r\nالاٌّوَّلُ وَالاٌّخِرُ وَالظَّـهِرُ وَالْبَـطِنُ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ\n\r\n\n\r\n(அவனே முதலாமவன், இறுதியானவன், வெளியானவன், உள்ளானவன். மேலும் அவன் அனைத்தையும் நன்கறிந்தவன்.) (57:3). அவன் நித்தியமானவன், என்றென்றும் நிலைத்திருப்பவன், என்றும் உயிரோடிருப்பவன், தன்னிறைவு பெற்றவன், அனைத்துப் பொருட்களுக்கும் இறைவனும் அதிபதியுமாவான். அவனிடமே நீங்கள் எப்போதும் திரும்ப வேண்டும். அல்லாஹ் ஒருவனே நீங்கள் நம்பிக்கை வைக்க வேண்டியவன் மற்றும் அடைக்கலம் தேட வேண்டியவன்; அவன் உங்களுக்குப் போதுமானவன், உமது உதவியாளனாகவும் ஆதரவாளனாகவும் இருந்து உம்மை வெற்றிபெறச் செய்வான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nيَـأَيُّهَا الرَّسُولُ بَلِّغْ مَآ أُنزِلَ إِلَيْكَ مِن رَّبِّكَ وَإِن لَّمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ\n\r\n\n\r\n(தூதரே! உமது இறைவனிடமிருந்து உமக்கு இறக்கப்பட்டதை எத்திவைப்பீராக. நீர் அவ்வாறு செய்யாவிட்டால், அவனது தூதுச் செய்தியை நீர் எத்திவைத்தவராக மாட்டீர். மேலும் அல்லாஹ் உம்மை மனிதர்களிடமிருந்து பாதுகாப்பான்.) (5:67).\n\r\n\n\r\nوَسَبِّحْ بِحَمْدِهِ\n\r\n\n\r\n(அவனது புகழைக் கொண்டு அவனைத் துதிப்பீராக,) இதன் பொருள், அவனைப் புகழ்வதையும் துதிப்பதையும் இணைத்துச் செய்யுங்கள் என்பதாகும். எனவே அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறு கூறுவார்கள்:\n\r\n\n\r\n«سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِك»\n\r\n\n\r\n(எங்கள் இறைவா! அல்லாஹ்வே! நீ தூய்மையானவன், உன்னைப் புகழ்ந்து துதிக்கிறேன்.) ஆகவே, இந்த வசனத்தின் பொருள்: அவனை வணங்குவதிலும் அவன் மீது நம்பிக்கை வைப்பதிலும் உண்மையாக இருங்கள் என்பதாகும். இது பின்வரும் வசனங்களைப் போன்றது:\n\r\n\n\r\nرَّبُّ الْمَشْرِقِ وَالْمَغْرِبِ لاَ إِلَـهَ إِلاَّ هُوَ فَاتَّخِذْهُ وَكِيلاً\n\r\n\n\r\n(கிழக்கு மற்றும் மேற்கின் இறைவன்; அவனைத் தவிர வேறு இறைவன் இல்லை. எனவே அவனையே உமது பொறுப்பாளனாக ஆக்கிக் கொள்வீராக.) (73:9).\n\r\n\n\r\nفَاعْبُدْهُ وَتَوَكَّلْ عَلَيْهِ\n\r\n\n\r\n(எனவே அவனையே வணங்குவீராக, அவன் மீதே நம்பிக்கை வைப்பீராக.) (11:123).\n\r\n\n\r\nقُلْ هُوَ الرَّحْمَـنُ ءَامَنَّا بِهِ وَعَلَيْهِ تَوَكَّلْنَا\n\r\n\n\r\n(கூறுவீராக: \"அவனே அளவற்ற அருளாளன், அவன் மீதே நாங்கள் ஈமான் (நம்பிக்கை) கொண்டோம், அவனையே நாங்கள் சார்ந்திருக்கிறோம்.\") (67:29).\n\r\n\n\r\nوَكَفَى بِهِ بِذُنُوبِ عِبَادِهِ خَبِيراً\n\r\n\n\r\n(மேலும் தனது அடியார்களின் பாவங்களை நன்கு அறிந்தவனாக அவன் போதுமானவன்.) அதாவது, அவனது முழுமையான அறிவிலிருந்து எதுவும் மறைந்திருக்க முடியாது; ஓர் அணுவளவு கூட அவனுக்குத் தெரியாமல் இருக்க முடியாது.\n\r\n\n\r\nالَّذِى خَلَقَ السَّمَـوَتِ وَالاٌّرْضَ وَمَا بَيْنَهُمَا\n\r\n\n\r\n(அவனே வானங்களையும் பூமியையும் மற்றும் அவற்றுக்கு இடைப்பட்டவற்றையும் படைத்தவன்...) அதாவது, அவன் மரணிக்காத, என்றும் உயிரோடிருப்பவன். அவன் படைப்பாளன், பரிபாலிப்பவன் மற்றும் அனைத்துப் பொருட்களின் அதிபதி. அவன் தனது பேராற்றலால் மிக உயர்ந்த மற்றும் பரந்த ஏழு வானங்களையும், ஆழமான மற்றும் அடர்த்தியான ஏழு பூமிகளையும் படைத்தான்.\n\r\n\n\r\nفِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ\n\r\n\n\r\n(ஆறு நாட்களில்; பின்னர் அவன் அர்ஷின் மீது உயர்ந்தான்.) அதாவது, அவன் அனைத்து விவகாரங்களையும் நிர்வகிக்கிறான், சத்தியத்தின் அடிப்படையில் தீர்ப்பளிக்கிறான்; மேலும் தீர்ப்பளிப்பவர்களில் அவனே சிறந்தவன்.\n\r\n\n\r\nالرَّحْمَـنُ فَاسْأَلْ بِهِ خَبِيراً\n\r\n\n\r\n(அவன் அளவற்ற அருளாளன்! அவனைப் பற்றி நன்கு அறிந்தவரிடம் கேட்பீராக.) அதாவது, அவனைப் பற்றி மிகச் சரியாக அறிந்தவரிடம் கேட்டுத் தெரிந்துகொள்ளுங்கள், அவரைப் பின்பற்றுங்கள், அவரை உமது முன்மாதிரியாக எடுத்துக் கொள்ளுங்கள். அல்லாஹ்வைப் பற்றி அவனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களை விட வேறு எவரும் அதிகம் அறிந்திருக்க முடியாது என்பது அனைவரும் அறிந்ததே. அவர்கள் இந்த உலகத்திலும் மறுமையிலும் ஆதமின் மக்களின் முழுமையான தலைவர். அவர்கள் தனது மனோ இச்சையின்படி பேசுவதில்லை; மாறாக தமக்கு அருளப்பட்ட வஹீ (இறைச்செய்தி)யையே எத்திவைக்கிறார்கள். அவர்கள் கூறுவது உண்மையாகும்; அவர்களது முடிவே இறுதியானது. ஏதேனும் சர்ச்சை ஏற்படும்போது மக்கள் அவர்களிடம் தீர்வு பெறக் கடமைப்பட்டுள்ளனர். அவர்களது சொல்லுக்கும் செயலுக்கும் இணக்கமானவையே சரியானவை; அவற்றுக்கு முரணானவை யாரால் சொல்லப்பட்டாலும் அல்லது செய்யப்பட்டாலும் அவை நிராகரிக்கப்பட வேண்டியவை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nفَإِن تَنَازَعْتُمْ فِى شَىْءٍ\n\r\n\n\r\n(உங்களுக்குள் ஏதேனும் ஒரு விஷயத்தில் முரண்பட்டால்...) (4:59).\n\r\n\n\r\nوَمَا اخْتَلَفْتُمْ فِيهِ مِن شَىْءٍ فَحُكْمُهُ إِلَى اللَّهِ\n\r\n\n\r\n(மேலும் நீங்கள் எந்த விஷயத்தில் முரண்பட்டாலும் அதற்கான தீர்ப்பு அல்லாஹ்விடமே உள்ளது.) (42:10).\n\r\n\n\r\nوَتَمَّتْ كَلِمَةُ رَبِّكَ صِدْقاً وَعَدْلاً\n\r\n\n\r\n(உமது இறைவனின் வார்த்தை உண்மையாலும் நீதியாலும் முழுமை பெற்றுவிட்டது.) (6:115). அதாவது, அவன் உண்மையை உரைத்தான், அவனது கட்டளைகளிலும் தடைகளிலும் அவன் நீதியோடும் நியாயத்தோடும் இருக்கிறான். இதையே அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\nفَاسْأَلْ بِهِ خَبِيراً\n\r\n\n\r\n(அவனைப் பற்றி நன்கு அறிந்தவரிடம் கேட்பீராக.)\n\r\n\n\r\nஇணைவைப்பாளர்களுக்குக் கண்டனம்\n\r\n\n\r\nஅல்லாஹ்வைத் தவிர்த்து சிலைகளுக்கும் மற்றவர்களுக்கும் ஸஜ்தா செய்யும் இணைவைப்பாளர்களை அல்லாஹ் கண்டிக்கிறான்:\n\r\n\n\r\nوَإِذَا قِيلَ لَهُمُ اسْجُدُواْ لِلرَّحْمَـنِ قَالُواْ وَمَا الرَّحْمَـنُ\n\r\n\n\r\n(மேலும் அவர்களிடம், \"அர்-ரஹ்மானுக்கு ஸஜ்தா செய்யுங்கள்!\" என்று கூறப்பட்டால், அவர்கள், \"அர்-ரஹ்மான் என்றால் என்ன?\" என்று கேட்கின்றனர்.) அதாவது: \"அர்-ரஹ்மானை எங்களுக்குத் தெரியாது.\" அல்லாஹ்வை அவனது பெயரான 'அர்-ரஹ்மான்' (அளவற்ற அருளாளன்) என்று அழைப்பதை அவர்கள் விரும்பவில்லை. அல்-ஹுதைபிய்யா உடன்படிக்கையின் போது, நபி (ஸல்) அவர்கள் எழுத்தாளரிடம்:\n\r\n\n\r\n«اكْتُبْ بِسْمِ اللهِ الرَّحْمنِ الرَّحِيم»\n\r\n\n\r\n(\"பிஸ்மில்லாஹிர் ரஹ்மானிர் ரஹீம் - அளவற்ற அருளாளன், நிகரற்ற அன்புடையோனாகிய அல்லாஹ்வின் பெயரால் எழுதுங்கள்\" என்று கூறினார்கள்.) அதற்கு அவர்கள், \"அர்-ரஹ்மானையோ அல்லது அர்-ரஹீமையோ எங்களுக்குத் தெரியாது. நீர் வழக்கமாக எழுதுவதைப் போலவே 'பிஸ்மிக்க அல்லாஹும்ம' (யா அல்லாஹ்! உனது பெயரால்) என்று எழுதுவீராக\" எனக் கூறினர். எனவே அல்லாஹ் இந்த வசனங்களை இறக்கினான்:\n\r\n\n\r\nقُلِ ادْعُواْ اللَّهَ أَوِ ادْعُواْ الرَّحْمَـنَ أَيًّا مَّا تَدْعُواْ فَلَهُ الاٌّسْمَآءَ الْحُسْنَى\n\r\n\n\r\n(கூறுவீராக: \"அல்லாஹ் என்று அழையுங்கள் அல்லது அர்-ரஹ்மான் என்று அழையுங்கள்; நீங்கள் எந்தப் பெயரால் அவனை அழைத்தாலும் அவனுக்கு மிக அழகிய பெயர்கள் உண்டு.\") (17:110). அதாவது அவனே அல்லாஹ், அவனே அளவற்ற அருளாளன். மேலும் இந்த வசனத்தில் அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَإِذَا قِيلَ لَهُمُ اسْجُدُواْ لِلرَّحْمَـنِ قَالُواْ وَمَا الرَّحْمَـنُ\n\r\n\n\r\n(மேலும் அவர்களிடம், \"அர்-ரஹ்மானுக்கு ஸஜ்தா செய்யுங்கள்!\" என்று கூறப்பட்டால், அவர்கள், \"அர்-ரஹ்மான் என்றால் என்ன?\" என்று கேட்கின்றனர்.) அதாவது: இந்தப் பெயரை நாங்கள் அறியமாட்டோம் அல்லது அங்கீகரிக்க மாட்டோம்.\n\r\n\n\r\nأَنَسْجُدُ لِمَا تَأْمُرُنَا\n\r\n\n\r\n(நீர் எங்களுக்குக் கட்டளையிடுவதற்காக நாங்கள் ஸஜ்தா செய்வோமா?) அதாவது, \"நீர் சொல்வதற்காக மட்டுமே நாங்கள் ஸஜ்தா செய்ய வேண்டுமா?\"\n\r\n\n\r\nوَزَادَهُمْ نُفُوراً\n\r\n\n\r\n(மேலும் இது அவர்களுக்கு வெறுப்பையே அதிகப்படுத்தியது.) இறைநம்பிக்கையாளர்களைப் பொறுத்தவரை, அவர்கள் அளவற்ற அருளாளனும் நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வை வணங்குகிறார்கள்; அவனுக்கு மட்டுமே இறைத்தன்மையை உரியதாக்கி, அவனுக்கு ஸஜ்தா செய்கிறார்கள். சூரா அல்-ஃபுர்கானின் இந்த ஸஜ்தா வசனத்தை ஓதுபவரும் கேட்பவரும் ஸஜ்தா செய்வது ஆகுமானது மற்றும் அங்கீகரிக்கப்பட்டது என்பதில் அறிஞர்கள் ஒருமித்த கருத்தைக் கொண்டுள்ளனர். அல்லாஹ்வே நன்கு அறிந்தவன்."},"61":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=62\" class=\"link\">25:62</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:62 ஐ பார்க்கவும்"},"62":{"html":"<strong>அல்லாஹ்வின் மகத்துவத்தையும் பேராற்றலையும் குறிப்பிடுதல்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தன்னைத் தானே மகிமைப்படுத்துவதோடு, முஜாஹித் (ரழி), ஸஈத் பின் ஜுபைர் (ரழி), அபூ ஸாலிஹ் (ரழி), அல்-ஹஸன் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோரின் கருத்துப்படி, வானங்களில் அவன் படைத்துள்ள 'அல்-புரூஜ்' எனும் பிரம்மாண்டமான நட்சத்திரங்களின் அழகைப் புகழ்கிறான். இது பின்வரும் வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">زَيَّنَّا</span> <span class=\"quran-arabic-font text-success\">السَّمَاءَ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا</span> <span class=\"quran-arabic-font text-success\">بِمَصَابِيحَ﴿</span> (நிச்சயமாக நாம் உலக வானத்தை விளக்குகளால் அலங்கரித்திருக்கிறோம்) (<a href=\"qurandisp.php?sura=67&ayah=5\" class=\"link\">67:5</a>).<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾تَبَارَكَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">بُرُوجًا</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">سِرَاجًا﴿</span> (வானத்தில் நட்சத்திர மண்டலங்களை அமைத்து, அதில் ஒரு விளக்கை ஆக்கியவன் பாக்கியமிக்கவன்). அந்த விளக்கு என்பது ஒரு விளக்கைப் போன்று பிரகாசிக்கும் சூரியனைக் குறிக்கும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَجَعَلْنَا</span> <span class=\"quran-arabic-font text-success\">سِرَاجًا</span> <span class=\"quran-arabic-font text-success\">وَهَّاجًا﴿</span> (மேலும், பிரகாசிக்கும் ஒரு விளக்கையும் நாம் ஆக்கினோம்) (<a href=\"qurandisp.php?sura=78&ayah=13\" class=\"link\">78:13</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَمَرًا</span> <span class=\"quran-arabic-font text-success\">مُّنِيرًا﴿</span> (மேலும் ஒளிவீசும் ஒரு சந்திரனையும் (ஆக்கினான்).) இதன் பொருள், சூரியனின் ஒளியிலிருந்து மாறுபட்டு, மற்றொன்றின் ஒளியால் ஒளிரக்கூடியதாகவும் பிரகாசிக்கக்கூடியதாகவும் சந்திரனை ஆக்கினான் என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾هُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">ضِيَاءً</span> <span class=\"quran-arabic-font text-success\">وَالْقَمَرَ</span> <span class=\"quran-arabic-font text-success\">نُورًا﴿</span> (அவனே சூரியனைப் பிரகாசமாகவும், சந்திரனை ஒளியாகவும் ஆக்கினான்) (<a href=\"qurandisp.php?sura=10&ayah=5\" class=\"link\">10:5</a>).<br />\r\n<br />\r\nமேலும் நூஹ் (அலை) அவர்கள் தனது மக்களிடம் கூறியதாக அல்லாஹ் குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَوْا</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">سَمَاوَاتٍ</span> <span class=\"quran-arabic-font text-success\">طِبَاقًا</span> - <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرَ</span> <span class=\"quran-arabic-font text-success\">فِيهِنَّ</span> <span class=\"quran-arabic-font text-success\">نُورًا</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">سِرَاجًا﴿</span> (அல்லாஹ் எவ்வாறு ஏழு வானங்களை ஒன்றன் மேல் ஒன்றாகப் படைத்துள்ளான் என்பதை நீங்கள் பார்க்கவில்லையா? மேலும், அவற்றில் சந்திரனை ஒளியாகவும், சூரியனை விளக்காகவும் அவன் ஆக்கியிருக்கிறான்) (<a href=\"qurandisp.php?sura=71&ayah=15\" class=\"link\">71:15</a>-16).<br />\r\n<br />\r\nபிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">جَعَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">وَالنَّهَارَ</span> <span class=\"quran-arabic-font text-success\">خِلْفَةً﴿</span> (அவன்தான் இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக (கில்ஃபதன்) வருமாறு செய்தான்). அதாவது, முடிவில்லாத சுழற்சியில் ஒன்று சென்றபின் மற்றொன்று எனத் தொடர்ச்சியாக வருகின்றன. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَسَخَّرَ</span> <span class=\"quran-arabic-font text-success\">لَكُمُ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسَ</span> <span class=\"quran-arabic-font text-success\">وَالْقَمَرَ</span> <span class=\"quran-arabic-font text-success\">دَائِبَيْنِ﴿</span> (மேலும் சூரியனையும் சந்திரனையும் தத்தமது பாதையில் சீராகச் செல்லுமாறு உங்களுக்காக அவன் வசப்படுத்தினான்) (<a href=\"qurandisp.php?sura=14&ayah=33\" class=\"link\">14:33</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يُغْشِي</span> <span class=\"quran-arabic-font text-success\">اللَّيْلَ</span> <span class=\"quran-arabic-font text-success\">النَّهَارَ</span> <span class=\"quran-arabic-font text-success\">يَطْلُبُهُ</span> <span class=\"quran-arabic-font text-success\">حَثِيثًا﴿</span> (அவன் இரவைப் பகலால் மூடுகிறான்; அது அதனைத் தொடர்ந்து விரைவாகத் தேடி வருகிறது) (<a href=\"qurandisp.php?sura=7&ayah=54\" class=\"link\">7:54</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَا</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">يَنْبَغِي</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تُدْرِكَ</span> <span class=\"quran-arabic-font text-success\">الْقَمَرَ﴿</span> (சூரியன் சந்திரனை முந்த முடியாது) (<a href=\"qurandisp.php?sura=36&ayah=40\" class=\"link\">36:40</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لِمَنْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَذَّكَّرَ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">شُكُورًا﴿</span> (நினைவு கூர விரும்புபவருக்காக அல்லது நன்றி செலுத்த விரும்புபவருக்காக.) அதாவது, தனது அடியார்கள் தன்னை வணங்குவதற்கான நேரங்களை அறிந்து கொள்வதற்காக அல்லாஹ் இவ்விரண்டையும் ஒன்றன்பின் ஒன்றாக வரச் செய்துள்ளான். எனவே, இரவில் ஏதேனும் ஒரு வணக்கத்தைத் தவறவிட்டவர் அதனைப் பகலில் நிறைவேற்றிக் கொள்ளலாம்; பகலில் ஏதேனும் ஒரு வணக்கத்தைத் தவறவிட்டவர் அதனை இரவில் நிறைவேற்றிக் கொள்ளலாம்.<br />\r\n<br />\r\nஒரு ஸஹீஹான ஹதீஸில் இவ்வாறு பதிவு செய்யப்பட்டுள்ளது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">عَزَّ</span> <span class=\"quran-arabic-font text-success\">وَجَلَّ</span> <span class=\"quran-arabic-font text-success\">يَبْسُطُ</span> <span class=\"quran-arabic-font text-success\">يَدَهُ</span> <span class=\"quran-arabic-font text-success\">بِاللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">لِيَتُوبَ</span> <span class=\"quran-arabic-font text-success\">مُسِيءُ</span> <span class=\"quran-arabic-font text-success\">النَّهَارِ،</span> <span class=\"quran-arabic-font text-success\">وَيَبْسُطُ</span> <span class=\"quran-arabic-font text-success\">يَدَهُ</span> <span class=\"quran-arabic-font text-success\">بِالنَّهَارِ</span> <span class=\"quran-arabic-font text-success\">لِيَتُوبَ</span> <span class=\"quran-arabic-font text-success\">مُسِيءُ</span> <span class=\"quran-arabic-font text-success\">اللَّيْلِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَطْلُعَ</span> <span class=\"quran-arabic-font text-success\">الشَّمْسُ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَغْرِبِهَا</span>»<span class=\"quran-arabic-font text-success\">﴿</span> (பகலில் பாவம் செய்தவர் மன்னிப்புக் கோருவதற்காக அல்லாஹ் இரவில் தனது கையை விரிக்கிறான். இரவில் பாவம் செய்தவர் மன்னிப்புக் கோருவதற்காக அவன் பகலில் தனது கையை விரிக்கிறான். சூரியன் மேற்கிலிருந்து உதயமாகும் வரை.) முஜாஹித் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோர் கூறினார்கள்: \"கில்ஃபதன் (Khilfatan) என்றால் 'வேறுபட்டவை' என்று பொருள், அதாவது ஒன்று இருளாகவும் மற்றொன்று ஒளியாகவும் இருப்பதால் இவ்வாறு கூறப்படுகிறது.\"<br />\r\n<br />","text":"அல்லாஹ்வின் மகத்துவத்தையும் பேராற்றலையும் குறிப்பிடுதல்\n\r\n\n\r\nஇங்கே அல்லாஹ் தன்னைத் தானே மகிமைப்படுத்துவதோடு, முஜாஹித் (ரழி), ஸஈத் பின் ஜுபைர் (ரழி), அபூ ஸாலிஹ் (ரழி), அல்-ஹஸன் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோரின் கருத்துப்படி, வானங்களில் அவன் படைத்துள்ள 'அல்-புரூஜ்' எனும் பிரம்மாண்டமான நட்சத்திரங்களின் அழகைப் புகழ்கிறான். இது பின்வரும் வசனத்தைப் போன்றது: ﴾وَلَقَدْ زَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ﴿ (நிச்சயமாக நாம் உலக வானத்தை விளக்குகளால் அலங்கரித்திருக்கிறோம்) (67:5).\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾تَبَارَكَ الَّذِي جَعَلَ فِي السَّمَاءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَاجًا﴿ (வானத்தில் நட்சத்திர மண்டலங்களை அமைத்து, அதில் ஒரு விளக்கை ஆக்கியவன் பாக்கியமிக்கவன்). அந்த விளக்கு என்பது ஒரு விளக்கைப் போன்று பிரகாசிக்கும் சூரியனைக் குறிக்கும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾وَجَعَلْنَا سِرَاجًا وَهَّاجًا﴿ (மேலும், பிரகாசிக்கும் ஒரு விளக்கையும் நாம் ஆக்கினோம்) (78:13).\n\r\n\n\r\n﴾وَقَمَرًا مُّنِيرًا﴿ (மேலும் ஒளிவீசும் ஒரு சந்திரனையும் (ஆக்கினான்).) இதன் பொருள், சூரியனின் ஒளியிலிருந்து மாறுபட்டு, மற்றொன்றின் ஒளியால் ஒளிரக்கூடியதாகவும் பிரகாசிக்கக்கூடியதாகவும் சந்திரனை ஆக்கினான் என்பதாகும். இதனை அல்லாஹ் இவ்வாறு கூறுகிறான்: ﴾هُوَ الَّذِي جَعَلَ الشَّمْسَ ضِيَاءً وَالْقَمَرَ نُورًا﴿ (அவனே சூரியனைப் பிரகாசமாகவும், சந்திரனை ஒளியாகவும் ஆக்கினான்) (10:5).\n\r\n\n\r\nமேலும் நூஹ் (அலை) அவர்கள் தனது மக்களிடம் கூறியதாக அல்லாஹ் குறிப்பிடுகிறான்: ﴾أَلَمْ تَرَوْا كَيْفَ خَلَقَ اللَّهُ سَبْعَ سَمَاوَاتٍ طِبَاقًا - وَجَعَلَ الْقَمَرَ فِيهِنَّ نُورًا وَجَعَلَ الشَّمْسَ سِرَاجًا﴿ (அல்லாஹ் எவ்வாறு ஏழு வானங்களை ஒன்றன் மேல் ஒன்றாகப் படைத்துள்ளான் என்பதை நீங்கள் பார்க்கவில்லையா? மேலும், அவற்றில் சந்திரனை ஒளியாகவும், சூரியனை விளக்காகவும் அவன் ஆக்கியிருக்கிறான்) (71:15-16).\n\r\n\n\r\nபிறகு அல்லாஹ் கூறுகிறான்: ﴾وَهُوَ الَّذِي جَعَلَ اللَّيْلَ وَالنَّهَارَ خِلْفَةً﴿ (அவன்தான் இரவையும் பகலையும் ஒன்றன்பின் ஒன்றாக (கில்ஃபதன்) வருமாறு செய்தான்). அதாவது, முடிவில்லாத சுழற்சியில் ஒன்று சென்றபின் மற்றொன்று எனத் தொடர்ச்சியாக வருகின்றன. அல்லாஹ் கூறுகிறான்: ﴾وَسَخَّرَ لَكُمُ الشَّمْسَ وَالْقَمَرَ دَائِبَيْنِ﴿ (மேலும் சூரியனையும் சந்திரனையும் தத்தமது பாதையில் சீராகச் செல்லுமாறு உங்களுக்காக அவன் வசப்படுத்தினான்) (14:33).\n\r\n\n\r\n﴾يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا﴿ (அவன் இரவைப் பகலால் மூடுகிறான்; அது அதனைத் தொடர்ந்து விரைவாகத் தேடி வருகிறது) (7:54).\n\r\n\n\r\n﴾لَا الشَّمْسُ يَنْبَغِي لَهَا أَنْ تُدْرِكَ الْقَمَرَ﴿ (சூரியன் சந்திரனை முந்த முடியாது) (36:40).\n\r\n\n\r\n﴾لِمَنْ أَرَادَ أَنْ يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا﴿ (நினைவு கூர விரும்புபவருக்காக அல்லது நன்றி செலுத்த விரும்புபவருக்காக.) அதாவது, தனது அடியார்கள் தன்னை வணங்குவதற்கான நேரங்களை அறிந்து கொள்வதற்காக அல்லாஹ் இவ்விரண்டையும் ஒன்றன்பின் ஒன்றாக வரச் செய்துள்ளான். எனவே, இரவில் ஏதேனும் ஒரு வணக்கத்தைத் தவறவிட்டவர் அதனைப் பகலில் நிறைவேற்றிக் கொள்ளலாம்; பகலில் ஏதேனும் ஒரு வணக்கத்தைத் தவறவிட்டவர் அதனை இரவில் நிறைவேற்றிக் கொள்ளலாம்.\n\r\n\n\r\nஒரு ஸஹீஹான ஹதீஸில் இவ்வாறு பதிவு செய்யப்பட்டுள்ளது: ﴾«إِنَّ اللهَ عَزَّ وَجَلَّ يَبْسُطُ يَدَهُ بِاللَّيْلِ لِيَتُوبَ مُسِيءُ النَّهَارِ، وَيَبْسُطُ يَدَهُ بِالنَّهَارِ لِيَتُوبَ مُسِيءُ اللَّيْلِ حَتَّى تَطْلُعَ الشَّمْسُ مِنْ مَغْرِبِهَا»﴿ (பகலில் பாவம் செய்தவர் மன்னிப்புக் கோருவதற்காக அல்லாஹ் இரவில் தனது கையை விரிக்கிறான். இரவில் பாவம் செய்தவர் மன்னிப்புக் கோருவதற்காக அவன் பகலில் தனது கையை விரிக்கிறான். சூரியன் மேற்கிலிருந்து உதயமாகும் வரை.) முஜாஹித் (ரழி) மற்றும் கத்தாதா (ரழி) ஆகியோர் கூறினார்கள்: \"கில்ஃபதன் (Khilfatan) என்றால் 'வேறுபட்டவை' என்று பொருள், அதாவது ஒன்று இருளாகவும் மற்றொன்று ஒளியாகவும் இருப்பதால் இவ்வாறு கூறப்படுகிறது.\""},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=67\" class=\"link\">25:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:67 ஐ பார்க்கவும்"},"64":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=67\" class=\"link\">25:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:67 ஐ பார்க்கவும்"},"65":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=67\" class=\"link\">25:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:67 ஐ பார்க்கவும்"},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=67\" class=\"link\">25:67</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:67 ஐ பார்க்கவும்"},"67":{"html":"<strong>அளவற்ற அருளாளனின் அடியார்களின் பண்புகள்</strong><br />\r\n<br />\r\nஇவை அல்லாஹ்வின் இறைநம்பிக்கையுள்ள அடியார்களின் பண்புகளாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَعِبَادُ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَمْشُونَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">هَوْناً</span><br />\r\n<br />\r\n(அவர்கள் பூமியில் 'ஹவ்னா' (பணிவுடன்) நடப்பார்கள்,) அதாவது அவர்கள் கர்வத்துடனும் பெருமையுடனும் இல்லாமல், கண்ணியத்துடனும் பணிவுடனும் நடப்பார்கள். இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمْشِ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مَرَحًا</span><br />\r\n<br />\r\n(மேலும், பூமியில் அகந்தையடனும் பெருமையுடனும் நடக்காதீர்...) (<a href=\"qurandisp.php?sura=17&ayah=37\" class=\"link\">17:37</a>). எனவே, இம்மக்கள் கர்வத்துடனோ, அகந்தையிலோ அல்லது பெருமையிலோ நடப்பதில்லை. இதற்காக அவர்கள் தங்களின் பணிவைக் காட்டுவதற்காக நோயாளிகளைப் போலக் காட்டிக்கொண்டு நடக்க வேண்டும் என்பது பொருளல்ல. ஏனெனில், ஆதமுடைய மக்களின் தலைவரான நபி (ஸல்) அவர்கள் ஒரு மேட்டிலிருந்து இறங்கி வருவது போலவும், பூமி அவர்களுக்குக் கீழ் சுருட்டப்படுவது போலவும் (வேகமாகவும் உறுதியாகவும்) நடப்பார்கள். இங்கே 'ஹவ்ன்' என்பதன் பொருள் அமைதியும் கண்ணியமுமாகும். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">أَتَيْتُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّلَاةَ</span> <span class=\"quran-arabic-font text-success\">فَلَا</span> <span class=\"quran-arabic-font text-success\">تَأْتُوهَا</span> <span class=\"quran-arabic-font text-success\">وَأَنْتُمْ</span> <span class=\"quran-arabic-font text-success\">تَسْعَونَ،</span> <span class=\"quran-arabic-font text-success\">وَأْتُوهَا</span> <span class=\"quran-arabic-font text-success\">وَعَلَيْكُمُ</span> <span class=\"quran-arabic-font text-success\">السَّكِينَةُ</span> <span class=\"quran-arabic-font text-success\">فَمَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَكْتُمْ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">فَصَلُّوا،</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">فَاتَكُمْ</span> <span class=\"quran-arabic-font text-success\">فَأَتِمُّوا</span>»<br />\r\n<br />\r\n(நீங்கள் தொழுகைக்கு வரும்போது, அவசரமாக ஓடி வராதீர்கள். அமைதியுடனும் நிதானத்துடனும் வாருங்கள். உங்களுக்குக் கிடைத்ததைத் தொழுது கொள்ளுங்கள், நீங்கள் தவறவிட்டதைப் பூர்த்தி செய்யுங்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">خَاطَبَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْجَاهِلُونَ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَلاَماً</span><br />\r\n<br />\r\n(அறிவீனர்கள் அவர்களுடன் உரையாடும்போது, அவர்கள் \"ஸலாமா\" என்று கூறுவார்கள்.) அறிவில்லாதவர்கள் அவர்களைத் தீய வார்த்தைகளால் ஏசினால், அவர்கள் அதே போன்று பதிலளிக்க மாட்டார்கள். மாறாக அவர்கள் மன்னித்து, அதைப் புறக்கணித்து, நல்ல வார்த்தைகளையே பேசுவார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறே செய்தார்கள்: மக்கள் எவ்வளவு அறிவீனர்களாக நடந்துகொண்டார்களோ, அவ்வளவு அதிகமாக அவர்கள் பொறுமையைக் கையாண்டார்கள். அல்லாஹ் கூறுவது போல்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">سَمِعُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّغْوَ</span> <span class=\"quran-arabic-font text-success\">أَعْرَضُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் 'லக்வ்' (வீணான பேச்சுக்களை) செவியுறும்போது, அதைப் புறக்கணிப்பார்கள்) (<a href=\"qurandisp.php?sura=28&ayah=55\" class=\"link\">28:55</a>). பின்னர் அல்லாஹ், அவர்களுடைய இரவுகள் மிகச் சிறந்த இரவுகள் என்று கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَبِيتُونَ</span> <span class=\"quran-arabic-font text-success\">لِرَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">سُجَّداً</span> <span class=\"quran-arabic-font text-success\">وَقِيَامًا</span><br />\r\n<br />\r\n(மேலும், அவர்கள் தங்கள் இறைவனுக்கு ஸஜ்தா செய்தும், நின்றும் வணங்கி இரவைக் கழிப்பார்கள்.) அதாவது, அவனை வணங்கியும் அவனுக்குக் கீழ்ப்படிந்தும் இருப்பார்கள். இது இந்த வசனங்களைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَهْجَعُونَ</span> - <span class=\"quran-arabic-font text-success\">وَبِالْأَسْحَارِ</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَغْفِرُونَ</span><br />\r\n<br />\r\n(அவர்கள் இரவில் மிகக் குறைந்த நேரமே உறங்குபவர்களாக இருந்தனர். மேலும், வைகறை நேரங்களில் அவர்கள் மன்னிப்புக் கோரிக்கொண்டிருப்பார்கள்) (<a href=\"qurandisp.php?sura=51&ayah=17\" class=\"link\">51:17</a>-18).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَتَجَافَى</span> <span class=\"quran-arabic-font text-success\">جُنُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">الْمَضَاجِعِ</span><br />\r\n<br />\r\n(அவர்களுடைய விலாப்பகுதிகள் படுக்கைகளை விட்டு விலகியிருக்கும்...) (<a href=\"qurandisp.php?sura=32&ayah=16\" class=\"link\">32:16</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَمَّنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">قَانِتٌ</span> <span class=\"quran-arabic-font text-success\">ءَانَآءَ</span> <span class=\"quran-arabic-font text-success\">الَّيْلِ</span> <span class=\"quran-arabic-font text-success\">سَاجِداً</span> <span class=\"quran-arabic-font text-success\">وَقَائِماً</span> <span class=\"quran-arabic-font text-success\">يَحْذَرُ</span> <span class=\"quran-arabic-font text-success\">الْآخِرَةَ</span> <span class=\"quran-arabic-font text-success\">وَيَرْجُواْ</span> <span class=\"quran-arabic-font text-success\">رَحْمَةَ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span><br />\r\n<br />\r\n(எவர் மறுமையை அஞ்சி, தன் இறைவனின் அருளை நம்பி, இரவின் நேரங்களில் ஸஜ்தா செய்தவராகவும், நின்றவராகவும் இறைவனுக்குக் கீழ்ப்படிந்து வணங்குகிறாரோ (அவர் மற்றவர்களுக்குச் சமமாவாரா?)) (<a href=\"qurandisp.php?sura=39&ayah=9\" class=\"link\">39:9</a>).<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اصْرِفْ</span> <span class=\"quran-arabic-font text-success\">عَنَّا</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">جَهَنَّمَ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَهَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَرَاماً</span><br />\r\n<br />\r\n(மேலும், அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நரகத்தின் வேதனையை எங்களை விட்டு அகற்றுவாயாக. நிச்சயமாக, அதன் வேதனை நீங்காத தண்டனையாகும்.\") அதாவது, அது எப்போதும் இருக்கக்கூடியது மற்றும் ஒருபோதும் முடிவடையாதது. அல்-ஹஸன் (ரஹ்) அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">عَذَابَهَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">غَرَاماً</span><br />\r\n<br />\r\n(நிச்சயமாக, அதன் வேதனை ஒருபோதும் பிரிக்க முடியாத, நிரந்தரமான தண்டனையாகும்.) ஆதமுடைய மகனைத் தாக்கிவிட்டுப் பின்னர் மறைந்துவிடும் எதுவும் 'கராம்' (நீங்காத தண்டனை) ஆகாது. வானங்களும் பூமியும் நிலைத்திருக்கும் வரை நீடிப்பதே பிரிக்க முடியாத, நிரந்தரமான தண்டனையாகும். இதுவே ஸுலைமான் அத்-தைமி (ரஹ்) அவர்களின் கருத்தாகவும் இருந்தது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهَا</span> <span class=\"quran-arabic-font text-success\">سَآءَتْ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَمُقَاماً</span><br />\r\n<br />\r\n(நிச்சயமாக, அது தங்குமிடமாகவும் வசிப்பிடமாகவும் மிகவும் கெட்டது.) அதாவது, அது வசிப்பதற்கு எவ்வளவு மோசமான இடமாகவும், தங்குவதற்கு எவ்வளவு மோசமான இடமாகவும் இருக்கிறது என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَنفَقُواْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُسْرِفُواْ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَقْتُرُواْ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் செலவு செய்யும்போது வீண்விரயம் செய்யமாட்டார்கள்; கஞ்சத்தனமும் செய்யமாட்டார்கள்...) அவர்கள் தேவைக்கு அதிகமாகச் செலவு செய்து வீண்விரயம் செய்பவர்களும் அல்லர், அல்லது தங்கள் குடும்பத்தினரின் தேவைகளுக்குப் போதுமான அளவு செலவு செய்யாமல் கஞ்சத்தனம் செய்பவர்களும் அல்லர். மாறாக, அவர்கள் ஒரு சிறந்த மற்றும் சீரான வழியைப் பின்பற்றுகிறார்கள். <span class=\"quran-arabic-font text-success\">خَيْرُ</span> <span class=\"quran-arabic-font text-success\">الْأُمُورِ</span> <span class=\"quran-arabic-font text-success\">أَوْسَاطُهَا</span> காரியங்களில் சிறந்தது நடுநிலையானதாகும்; அது ஒரு பக்கமோ அல்லது மறு பக்கமோ தீவிரமாக இருப்பதில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">قَوَاماً</span><br />\r\n<br />\r\n(மாறாக அவற்றுக்கிடையே நடுநிலையாக இருப்பார்கள்.) இது இந்த வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَجْعَلْ</span> <span class=\"quran-arabic-font text-success\">يَدَكَ</span> <span class=\"quran-arabic-font text-success\">مَغْلُولَةً</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">عُنُقِكَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَبْسُطْهَا</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">الْبَسْطِ</span><br />\r\n<br />\r\n(உமது கையை உமது கழுத்துடன் கட்டப்பட்டதாக ஆக்கிக்கொள்ளாதீர்; மேலும் அதை முழுமையாக விரித்தும் விடாதீர்.) (<a href=\"qurandisp.php?sura=17&ayah=29\" class=\"link\">17:29</a>)<br />\r\n<br />","text":"அளவற்ற அருளாளனின் அடியார்களின் பண்புகள்\n\r\n\n\r\nஇவை அல்லாஹ்வின் இறைநம்பிக்கையுள்ள அடியார்களின் பண்புகளாகும்:\n\r\n\n\r\nوَعِبَادُ الرَّحْمَنِ الَّذِينَ يَمْشُونَ عَلَى الْأَرْضِ هَوْناً\n\r\n\n\r\n(அவர்கள் பூமியில் 'ஹவ்னா' (பணிவுடன்) நடப்பார்கள்,) அதாவது அவர்கள் கர்வத்துடனும் பெருமையுடனும் இல்லாமல், கண்ணியத்துடனும் பணிவுடனும் நடப்பார்கள். இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَلاَ تَمْشِ فِى الْأَرْضِ مَرَحًا\n\r\n\n\r\n(மேலும், பூமியில் அகந்தையடனும் பெருமையுடனும் நடக்காதீர்...) (17:37). எனவே, இம்மக்கள் கர்வத்துடனோ, அகந்தையிலோ அல்லது பெருமையிலோ நடப்பதில்லை. இதற்காக அவர்கள் தங்களின் பணிவைக் காட்டுவதற்காக நோயாளிகளைப் போலக் காட்டிக்கொண்டு நடக்க வேண்டும் என்பது பொருளல்ல. ஏனெனில், ஆதமுடைய மக்களின் தலைவரான நபி (ஸல்) அவர்கள் ஒரு மேட்டிலிருந்து இறங்கி வருவது போலவும், பூமி அவர்களுக்குக் கீழ் சுருட்டப்படுவது போலவும் (வேகமாகவும் உறுதியாகவும்) நடப்பார்கள். இங்கே 'ஹவ்ன்' என்பதன் பொருள் அமைதியும் கண்ணியமுமாகும். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا أَتَيْتُمُ الصَّلَاةَ فَلَا تَأْتُوهَا وَأَنْتُمْ تَسْعَونَ، وَأْتُوهَا وَعَلَيْكُمُ السَّكِينَةُ فَمَا أَدْرَكْتُمْ مِنْهَا فَصَلُّوا، وَمَا فَاتَكُمْ فَأَتِمُّوا»\n\r\n\n\r\n(நீங்கள் தொழுகைக்கு வரும்போது, அவசரமாக ஓடி வராதீர்கள். அமைதியுடனும் நிதானத்துடனும் வாருங்கள். உங்களுக்குக் கிடைத்ததைத் தொழுது கொள்ளுங்கள், நீங்கள் தவறவிட்டதைப் பூர்த்தி செய்யுங்கள்.)\n\r\n\n\r\nوَإِذَا خَاطَبَهُمُ الْجَاهِلُونَ قَالُواْ سَلاَماً\n\r\n\n\r\n(அறிவீனர்கள் அவர்களுடன் உரையாடும்போது, அவர்கள் \"ஸலாமா\" என்று கூறுவார்கள்.) அறிவில்லாதவர்கள் அவர்களைத் தீய வார்த்தைகளால் ஏசினால், அவர்கள் அதே போன்று பதிலளிக்க மாட்டார்கள். மாறாக அவர்கள் மன்னித்து, அதைப் புறக்கணித்து, நல்ல வார்த்தைகளையே பேசுவார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவ்வாறே செய்தார்கள்: மக்கள் எவ்வளவு அறிவீனர்களாக நடந்துகொண்டார்களோ, அவ்வளவு அதிகமாக அவர்கள் பொறுமையைக் கையாண்டார்கள். அல்லாஹ் கூறுவது போல்:\n\r\n\n\r\nوَإِذَا سَمِعُواْ اللَّغْوَ أَعْرَضُواْ عَنْهُ\n\r\n\n\r\n(மேலும், அவர்கள் 'லக்வ்' (வீணான பேச்சுக்களை) செவியுறும்போது, அதைப் புறக்கணிப்பார்கள்) (28:55). பின்னர் அல்லாஹ், அவர்களுடைய இரவுகள் மிகச் சிறந்த இரவுகள் என்று கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِينَ يَبِيتُونَ لِرَبِّهِمْ سُجَّداً وَقِيَامًا\n\r\n\n\r\n(மேலும், அவர்கள் தங்கள் இறைவனுக்கு ஸஜ்தா செய்தும், நின்றும் வணங்கி இரவைக் கழிப்பார்கள்.) அதாவது, அவனை வணங்கியும் அவனுக்குக் கீழ்ப்படிந்தும் இருப்பார்கள். இது இந்த வசனங்களைப் போன்றது:\n\r\n\n\r\nكَانُواْ قَلِيلاً مِّن الَّيْلِ مَا يَهْجَعُونَ - وَبِالْأَسْحَارِ هُمْ يَسْتَغْفِرُونَ\n\r\n\n\r\n(அவர்கள் இரவில் மிகக் குறைந்த நேரமே உறங்குபவர்களாக இருந்தனர். மேலும், வைகறை நேரங்களில் அவர்கள் மன்னிப்புக் கோரிக்கொண்டிருப்பார்கள்) (51:17-18).\n\r\n\n\r\nتَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ\n\r\n\n\r\n(அவர்களுடைய விலாப்பகுதிகள் படுக்கைகளை விட்டு விலகியிருக்கும்...) (32:16).\n\r\n\n\r\nأَمَّنْ هُوَ قَانِتٌ ءَانَآءَ الَّيْلِ سَاجِداً وَقَائِماً يَحْذَرُ الْآخِرَةَ وَيَرْجُواْ رَحْمَةَ رَبِّهِ\n\r\n\n\r\n(எவர் மறுமையை அஞ்சி, தன் இறைவனின் அருளை நம்பி, இரவின் நேரங்களில் ஸஜ்தா செய்தவராகவும், நின்றவராகவும் இறைவனுக்குக் கீழ்ப்படிந்து வணங்குகிறாரோ (அவர் மற்றவர்களுக்குச் சமமாவாரா?)) (39:9).\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِينَ يَقُولُونَ رَبَّنَا اصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ إِنَّ عَذَابَهَا كَانَ غَرَاماً\n\r\n\n\r\n(மேலும், அவர்கள் கூறுவார்கள்: \"எங்கள் இறைவனே! நரகத்தின் வேதனையை எங்களை விட்டு அகற்றுவாயாக. நிச்சயமாக, அதன் வேதனை நீங்காத தண்டனையாகும்.\") அதாவது, அது எப்போதும் இருக்கக்கூடியது மற்றும் ஒருபோதும் முடிவடையாதது. அல்-ஹஸன் (ரஹ்) அவர்கள் இந்த வசனத்தைப் பற்றிக் கூறினார்கள்:\n\r\n\n\r\nإِنَّ عَذَابَهَا كَانَ غَرَاماً\n\r\n\n\r\n(நிச்சயமாக, அதன் வேதனை ஒருபோதும் பிரிக்க முடியாத, நிரந்தரமான தண்டனையாகும்.) ஆதமுடைய மகனைத் தாக்கிவிட்டுப் பின்னர் மறைந்துவிடும் எதுவும் 'கராம்' (நீங்காத தண்டனை) ஆகாது. வானங்களும் பூமியும் நிலைத்திருக்கும் வரை நீடிப்பதே பிரிக்க முடியாத, நிரந்தரமான தண்டனையாகும். இதுவே ஸுலைமான் அத்-தைமி (ரஹ்) அவர்களின் கருத்தாகவும் இருந்தது.\n\r\n\n\r\nإِنَّهَا سَآءَتْ مُسْتَقَرّاً وَمُقَاماً\n\r\n\n\r\n(நிச்சயமாக, அது தங்குமிடமாகவும் வசிப்பிடமாகவும் மிகவும் கெட்டது.) அதாவது, அது வசிப்பதற்கு எவ்வளவு மோசமான இடமாகவும், தங்குவதற்கு எவ்வளவு மோசமான இடமாகவும் இருக்கிறது என்பதாகும்.\n\r\n\n\r\nوَالَّذِينَ إِذَآ أَنفَقُواْ لَمْ يُسْرِفُواْ وَلَمْ يَقْتُرُواْ\n\r\n\n\r\n(மேலும், அவர்கள் செலவு செய்யும்போது வீண்விரயம் செய்யமாட்டார்கள்; கஞ்சத்தனமும் செய்யமாட்டார்கள்...) அவர்கள் தேவைக்கு அதிகமாகச் செலவு செய்து வீண்விரயம் செய்பவர்களும் அல்லர், அல்லது தங்கள் குடும்பத்தினரின் தேவைகளுக்குப் போதுமான அளவு செலவு செய்யாமல் கஞ்சத்தனம் செய்பவர்களும் அல்லர். மாறாக, அவர்கள் ஒரு சிறந்த மற்றும் சீரான வழியைப் பின்பற்றுகிறார்கள். خَيْرُ الْأُمُورِ أَوْسَاطُهَا காரியங்களில் சிறந்தது நடுநிலையானதாகும்; அது ஒரு பக்கமோ அல்லது மறு பக்கமோ தீவிரமாக இருப்பதில்லை.\n\r\n\n\r\nوَكَانَ بَيْنَ ذَلِكَ قَوَاماً\n\r\n\n\r\n(மாறாக அவற்றுக்கிடையே நடுநிலையாக இருப்பார்கள்.) இது இந்த வசனத்தைப் போன்றது:\n\r\n\n\r\nوَلاَ تَجْعَلْ يَدَكَ مَغْلُولَةً إِلَى عُنُقِكَ وَلاَ تَبْسُطْهَا كُلَّ الْبَسْطِ\n\r\n\n\r\n(உமது கையை உமது கழுத்துடன் கட்டப்பட்டதாக ஆக்கிக்கொள்ளாதீர்; மேலும் அதை முழுமையாக விரித்தும் விடாதீர்.) (17:29)"},"68":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=71\" class=\"link\">25:71</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:71 ஐ பார்க்கவும்"},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=71\" class=\"link\">25:71</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:71 ஐ பார்க்கவும்"},"70":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=71\" class=\"link\">25:71</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:71 ஐ பார்க்கவும்"},"71":{"html":"<strong>அளவற்ற அருளாளனின் அடியார்களின் பண்புகளில் ஷிர்க், கொலை மற்றும் விபச்சாரத்தைத் தவிர்ப்பதும் அடங்கும்</strong><br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் **பதிவு செய்துள்ளதாவது:** அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாவது: \"பாவங்களிலேயே மிகவும் பாரதூரமானது எது?\" என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَجْعَلَ</span> <span class=\"quran-arabic-font text-success\">للهِ</span> <span class=\"quran-arabic-font text-success\">نِدًّا</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">خَلَقَك</span>»<br />\r\n<br />\r\n(அல்லாஹ் உன்னைப் படைத்திருக்க, அவனுக்கு நீ ஒரு நிகரை ஏற்படுத்துவதாகும்.) அவர் கேட்டார், \"அதற்கடுத்து எது?\" அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تَقْتُلَ</span> <span class=\"quran-arabic-font text-success\">وَلَدَكَ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَطْعَمَ</span> <span class=\"quran-arabic-font text-success\">مَعَك</span>»<br />\r\n<br />\r\n(உன்னுடன் சேர்ந்து உணவு உண்பான் என்ற அச்சத்தில் உனது குழந்தையை நீ கொலை செய்வதாகும்.) அவர் கேட்டார், \"அதற்கடுத்து எது?\" அதற்கு அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تُزَانِي</span> <span class=\"quran-arabic-font text-success\">حَلِيلَةَ</span> <span class=\"quran-arabic-font text-success\">جَارِك</span>»<br />\r\n<br />\r\n(உனது அண்டை வீட்டாருடைய மனைவியுடன் நீ விபச்சாரம் செய்வதாகும்.) அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள், \"பின்னர் அல்லாஹ் அதனை உறுதிப்படுத்தும் விதமாக பின்வரும் வசனத்தை வஹீ (இறைச்செய்தி)யாக இறக்கினான்:<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَـهًا</span> <span class=\"quran-arabic-font text-success\">آخَرَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَقْتُلُونَ</span> <span class=\"quran-arabic-font text-success\">النَّفْسَ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">حَرَّمَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَزْنُونَ</span>**<br />\r\n<br />\r\n(மேலும், அவர்கள் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளையும் அழைக்க மாட்டார்கள்; அல்லாஹ் புனிதப்படுத்திய உயிரை (நியாயமின்றி)க் கொலை செய்யமாட்டார்கள்; மேலும் விபச்சாரம் செய்யமாட்டார்கள்.)\" இதனை அந்-நஸாயீ, அல்-புகாரீ மற்றும் முஸ்லிம் ஆகியோரும் பதிவு செய்துள்ளனர். ஸயீத் பின் ஜுபைர் அவர்கள் கூறியதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: ஷிர்க் செய்த மக்களில் சிலர் அதிகளவில் கொலைகளையும் விபச்சாரங்களையும் செய்திருந்தார்கள். பிறகு அவர்கள் முஹம்மது (ஸல்) அவர்களிடம் வந்து, \"நீங்கள் கூறுவதும் மக்களை அழைப்பதும் நல்லதாக உள்ளது. நாங்கள் செய்த பாவங்களுக்குப் பரிகாரம் காண்பதற்கு ஏதேனும் வழி உள்ளது என்று எங்களுக்குத் தெரிவித்தால் நன்றாக இருக்கும்\" என்று கூறினார்கள். அப்போது இந்த வசனம் அருளப்பட்டது:<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَدْعُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَـهًا</span> <span class=\"quran-arabic-font text-success\">آخَرَ</span>**<br />\r\n<br />\r\n(மேலும், அவர்கள் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளையும் அழைக்க மாட்டார்கள்...) மேலும் இந்த வசனமும் அருளப்பட்டது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يعِبَادِىَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَسْرَفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span><br />\r\n<br />\r\n(கூறுவீராக: \"தங்களுக்குத் தாமே வரம்பு மீறிக்கொண்ட என் அடியார்களே!\") (<a href=\"qurandisp.php?sura=39&ayah=53\" class=\"link\">39:53</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَفْعَلْ</span> <span class=\"quran-arabic-font text-success\">ذلِكَ</span> <span class=\"quran-arabic-font text-success\">يَلْقَ</span> <span class=\"quran-arabic-font text-success\">أَثَاماً</span><br />\r\n<br />\r\n(இதைச் செய்பவர் அதாமா-வைச் சந்திப்பார்.) 'அதாமா' என்பது நரகத்தில் உள்ள ஒரு பள்ளத்தாக்கு என்று அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது. இக்ரிமா அவர்களும் 'அதாமா' என்பது நரகத்திலுள்ள பள்ளத்தாக்குகளைக் குறிக்கும் என்றும், அங்கு தாம்பத்திய உறவில் (விபச்சாரத்தில்) ஈடுபடுபவர்கள் தண்டிக்கப்படுவார்கள் என்றும் கூறினார்கள். இது ஸயீத் பின் ஜுபைர் மற்றும் முஜாஹித் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அஸ்-ஸுத்தீ அவர்கள், 'அதாமா' என்பது தண்டனையைக் குறிக்கிறது என்று கூறினார்கள். இது வசனத்தின் வெளிப்படையான பொருளுக்கு மிக நெருக்கமாக உள்ளது. இந்த விளக்கம், அடுத்து வரும் வசனத்திற்குப் பொருத்தமாக அமைகிறது:<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">يُضَاعَفْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span>**<br />\r\n<br />\r\n(மறுமை நாளில் அவனுக்கான வேதனை இரட்டிப்பாக்கப்படும்,) அதாவது, அது மீண்டும் மீண்டும் கடுமையாக்கப்படும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَيَخْلُدْ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">مُهَاناً</span><br />\r\n<br />\r\n(மேலும், அவன் இழிவுபடுத்தப்பட்டவனாக அதில் நிரந்தரமாகத் தங்குவான்;) இகழப்பட்டு, அவமானப்படுத்தப்பட்டவனாக.<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَابَ</span> <span class=\"quran-arabic-font text-success\">وَءَامَنَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">عَمَلاً</span> <span class=\"quran-arabic-font text-success\">صَالِحاً</span>**<br />\r\n<br />\r\n(தவ்பா (மன்னிப்பு) கோரி, ஈமான் கொண்டு, நற்செயல்களைச் செய்பவர்களைத் தவிர;) இதன் பொருள், இத்தகு தீய செயல்களைச் செய்பவர்கள் விவரிக்கப்பட்டவாறு தண்டிக்கப்படுவார்கள் என்பதாகும்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَابَ</span><br />\r\n<br />\r\n(மன்னிப்பு கோரியவர்களைத் தவிர), அதாவது; இந்த உலகிலேயே அச்செயல்கள் அனைத்திலிருந்தும் அல்லாஹ்விடம் தவ்பா செய்பவர்கள்; நிச்சயமாக அல்லாஹ் அவர்களின் தவ்பாவை ஏற்றுக்கொள்வான். கொலை செய்தவரின் தவ்பா ஏற்றுக்கொள்ளப்படும் என்பதற்கு இது ஆதாரமாகும். ஸூரத்துந் நிஸாவில் உள்ள வசனத்திற்கும் இதற்கும் முரண்பாடு ஏதுமில்லை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَقْتُلْ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِناً</span> <span class=\"quran-arabic-font text-success\">مُّتَعَمِّداً</span><br />\r\n<br />\r\n(யார் ஒரு நம்பிக்கையாளரை வேண்டுமென்றே கொலை செய்கிறானோ) (<a href=\"qurandisp.php?sura=4&ayah=93\" class=\"link\">4:93</a>). ஏனெனில் இது மதீனாவில் அருளப்பட்டிருந்தாலும், இதன் பொருள் பொதுவானதாகும். மேலும், தவ்பா செய்யாத ஒருவரைப் பற்றியே இது குறிப்பிடுவதாகக் கொள்ளலாம். ஏனெனில், தற்போது நாம் பார்க்கும் வசனம் (<a href=\"qurandisp.php?sura=25&ayah=70\" class=\"link\">25:70</a>) தவ்பா செய்பவர்களுக்கு மட்டுமே மன்னிப்பு உண்டு என்று கூறுகிறது. மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُشْرَكَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَيَغْفِرُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">دُونَ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لِمَن</span> <span class=\"quran-arabic-font text-success\">يَشَآءُ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான். ஆனால், அதைத் தவிர மற்றவற்றைத் தான் நாடியோருக்கு மன்னிப்பான்) (<a href=\"qurandisp.php?sura=4&ayah=48\" class=\"link\">4:48</a>). மேலும் ஆதாரப்பூர்வமான ஸுன்னாவில், கொலை செய்தவரின் தவ்பா ஏற்றுக்கொள்ளப்படும் என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. நூறு பேரைக் கொலை செய்துவிட்டுப் பின்னர் தவ்பா செய்த ஒருவரின் வரலாற்றிலும் அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொண்டான் என்று வந்துள்ளது. இது போன்ற மற்ற ஹதீஸ்களும் இதனை உறுதிப்படுத்துகின்றன.<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">فَأُوْلَـئِكَ</span> <span class=\"quran-arabic-font text-success\">يُبَدِّلُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِهِمْ</span> <span class=\"quran-arabic-font text-success\">حَسَنَاتٍ</span> <span class=\"quran-arabic-font text-success\">وَكَانَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span>**<br />\r\n<br />\r\n(அத்தகையோரின் தீமைகளை அல்லாஹ் நன்மைகளாக மாற்றிவிடுவான். மேலும் அல்லாஹ் மிக்க மன்னிப்பவனாகவும், மகா கருணையாளனாகவும் இருக்கிறான்.) இமாம் அஹ்மத் அவர்கள் **பதிவு செய்துள்ளதாவது:** அபூ தர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَأَعْرِفُ</span> <span class=\"quran-arabic-font text-success\">آخِرَ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">خُرُوجًا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">النَّارِ،</span> <span class=\"quran-arabic-font text-success\">وَآخِرَ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">دُخُولًا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ،</span> <span class=\"quran-arabic-font text-success\">يُؤْتَى</span> <span class=\"quran-arabic-font text-success\">بِرَجُلٍ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">نَحُّوا</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">كِبَارَ</span> <span class=\"quran-arabic-font text-success\">ذُنُوبِهِ</span> <span class=\"quran-arabic-font text-success\">وَسَلُوهُ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">صِغَارِهَا،</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>: <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">عَمِلْتَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَذَا،</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،</span> <span class=\"quran-arabic-font text-success\">وَعَمِلْتَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَذَا،</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">نَعَمْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُنْكِرَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا،</span> <span class=\"quran-arabic-font text-success\">فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَةٍ</span> <span class=\"quran-arabic-font text-success\">حَسَنَةً،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">عَمِلْتُ</span> <span class=\"quran-arabic-font text-success\">أَشْيَاءَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَرَاهَا</span> <span class=\"quran-arabic-font text-success\">ههُنَا</span>»<br />\r\n<br />\r\n(நரகத்திலிருந்து கடைசியாக வெளியே வருபவனையும், சொர்க்கத்தில் கடைசியாக நுழைபவனையும் நான் நிச்சயமாக அறிவேன். ஒரு மனிதன் கொண்டுவரப்பட்டு, \"அவனுடைய பெரும் பாவங்களை மறைத்துவிட்டு, அவனுடைய சிறு பாவங்களைப் பற்றிக் கேளுங்கள்\" என்று கூறப்படும். அவனிடம், \"இன்ன நாளில் நீ இன்னின்ன காரியங்களைச் செய்தாய் அல்லவா?\" என்று கேட்கப்படும். அவன் \"ஆம்\" என்று கூறுவான்; எதனையும் அவனால் மறுக்க முடியாது. பிறகு அவனிடம், \"உனது ஒவ்வொரு தீமைக்கும் பதிலாக உனக்கு ஒரு நன்மை உண்டு\" என்று கூறப்படும். அப்போது அவன், \"என் இறைவா! நான் இங்கு காணாத இன்னும் பல தீய காரியங்களையும் செய்துள்ளேனே!\" என்று கூறுவான்.)\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது கடவாய்ப் பற்கள் தெரியும் அளவுக்குப் புன்னகைத்தார்கள் என்று அபூ தர் (ரழி) அவர்கள் கூறினார்கள். இதனை முஸ்லிம் பதிவு செய்துள்ளார்.<br />\r\n<br />\r\nஇப்னு அபீ ஹாதிம் அவர்கள் **பதிவு செய்துள்ளதாவது: அபூ ஜஅஃபர்** அவர்கள் மஃகூலிடமிருந்து கேட்டதாகப் பதிவு செய்துள்ளார்கள்: \"கண்புருவங்கள் கண்களின் மீது விழுந்து கொண்டிருந்த ஒரு முதியவர் வந்து, 'அல்லாஹ்வின் தூதரே! ஒரு மனிதன் துரோகங்களும் ஒழுக்கக்கேடுகளும் செய்துள்ளான். அவன் செய்யாத எந்தத் தீமையும் இல்லை. அவனது பாவங்கள் மனிதகுலம் முழுமைக்கும் பங்கிடப்பட்டால், அவர்கள் அனைவரும் அழிந்துவிடுவார்கள். அவனுக்குத் தவ்பா (மன்னிப்பு) உண்டா?' என்று கேட்டார். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَأَسْلَمْتَ؟</span>»<br />\r\n<br />\r\n(நீர் இஸ்லாத்தை ஏற்றுக்கொண்டீரா?) அவர் கூறினார், \"நிச்சயமாக நான், வணக்கத்திற்குரியவன் அல்லாஹ்வைத் தவிர வேறு யாருமில்லை என்றும், அவனுக்கு இணை துணை ஏதுமில்லை என்றும், முஹம்மது (ஸல்) அவர்கள் அவனது அடியாரும் தூதருமாவார் என்றும் சாட்சி கூறுகிறேன்.\" நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللهَ</span> <span class=\"quran-arabic-font text-success\">غَافِرٌ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنْتَ</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ،</span> <span class=\"quran-arabic-font text-success\">وَمُبَدِّلُ</span> <span class=\"quran-arabic-font text-success\">سَيِّئَاتِكَ</span> <span class=\"quran-arabic-font text-success\">حَسَنَات</span>»<br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ் நீர் அவ்வாறு செய்த அனைத்தையும் மன்னித்துவிடுவான்; உமது தீமைகளை நன்மைகளாக மாற்றிவிடுவான்.) அந்த மனிதர் கேட்டார்: \"அல்லாஹ்வின் தூதரே! எனது துரோகங்களையும் ஒழுக்கக்கேடுகளையும் கூடவா?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَغَدَرَاتُكَ</span> <span class=\"quran-arabic-font text-success\">وَفَجَرَاتُك</span>»<br />\r\n<br />\r\n(உமது துரோகங்களையும் ஒழுக்கக்கேடுகளையும் கூடத்தான்.) அந்த மனிதர் 'லா இலாஹ இல்லல்லாஹ்' என்றும் 'அல்லாஹு அக்பர்' என்றும் முழங்கியவாறே சென்றார்.\" அல்லாஹ் தனது அடியார்கள் அனைவர் மீதும் அவனது கருணை எவ்வாறு பரவியுள்ளது என்பதையும், அவர்களில் எவர் அவனிடம் தவ்பா செய்தாலும் - அது பெரிய பாவமோ சிறிய பாவமோ - அவனது தவ்பாவை அவன் ஏற்றுக்கொள்வான் என்பதையும் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n**<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">تَابَ</span> <span class=\"quran-arabic-font text-success\">وَعَمِلَ</span> <span class=\"quran-arabic-font text-success\">صَالِحاً</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">يَتُوبُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَتاباً</span>**<br />\r\n<br />\r\n(மேலும், யார் தவ்பா செய்து, நற்செயல்களைச் செய்கிறாரோ, நிச்சயமாக அவர் அல்லாஹ்விடம் சிறந்த முறையில் திரும்புகிறார்.) அதாவது, அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொள்வான். இது பின்வரும் வசனங்களைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَعْمَلْ</span> <span class=\"quran-arabic-font text-success\">سُوءاً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَظْلِمْ</span> <span class=\"quran-arabic-font text-success\">نَفْسَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَسْتَغْفِرِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَجِدِ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">غَفُوراً</span> <span class=\"quran-arabic-font text-success\">رَّحِيماً</span><br />\r\n<br />\r\n(மேலும், எவர் ஒரு தீமையைச் செய்தோ அல்லது தனக்குத்தானே அநீதி இழைத்தோ பின்னர் அல்லாஹ்விடம் மன்னிப்புக் கோரினால், அவர் அல்லாஹ்வை மிக்க மன்னிப்பவனாகவும், மகா கருணையாளனாகவும் காண்பார்) (<a href=\"qurandisp.php?sura=4&ayah=110\" class=\"link\">4:110</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَعْلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">يَقْبَلُ</span> <span class=\"quran-arabic-font text-success\">التَّوْبَةَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">عِبَادِهِ</span><br />\r\n<br />\r\n(நிச்சயமாக அல்லாஹ்தான் தனது அடியார்களிடமிருந்து தவ்பாவை ஏற்றுக்கொள்கிறான் என்பதை அவர்கள் அறியவில்லையா...) (<a href=\"qurandisp.php?sura=9&ayah=104\" class=\"link\">9:104</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">يعِبَادِىَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">أَسْرَفُواْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">أَنفُسِهِمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تَقْنَطُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">رَّحْمَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(கூறுவீராக: \"தங்களுக்குத் தாமே வரம்பு மீறிக்கொண்ட என் அடியார்களே! அல்லாஹ்வின் கருணையிலிருந்து நீங்கள் நம்பிக்கை இழக்காதீர்கள்.\") (<a href=\"qurandisp.php?sura=39&ayah=53\" class=\"link\">39:53</a>) - அவனிடம் தவ்பா செய்பவர்களுக்காக.<br />\r\n<br />","text":"அளவற்ற அருளாளனின் அடியார்களின் பண்புகளில் ஷிர்க், கொலை மற்றும் விபச்சாரத்தைத் தவிர்ப்பதும் அடங்கும்\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் **பதிவு செய்துள்ளதாவது:** அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி) அவர்கள் கூறியதாவது: \"பாவங்களிலேயே மிகவும் பாரதூரமானது எது?\" என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் கேட்கப்பட்டது. அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَنْ تَجْعَلَ للهِ نِدًّا وَهُوَ خَلَقَك»\n\r\n\n\r\n(அல்லாஹ் உன்னைப் படைத்திருக்க, அவனுக்கு நீ ஒரு நிகரை ஏற்படுத்துவதாகும்.) அவர் கேட்டார், \"அதற்கடுத்து எது?\" அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَنْ تَقْتُلَ وَلَدَكَ خَشْيَةَ أَنْ يَطْعَمَ مَعَك»\n\r\n\n\r\n(உன்னுடன் சேர்ந்து உணவு உண்பான் என்ற அச்சத்தில் உனது குழந்தையை நீ கொலை செய்வதாகும்.) அவர் கேட்டார், \"அதற்கடுத்து எது?\" அதற்கு அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«أَنْ تُزَانِي حَلِيلَةَ جَارِك»\n\r\n\n\r\n(உனது அண்டை வீட்டாருடைய மனைவியுடன் நீ விபச்சாரம் செய்வதாகும்.) அப்துல்லாஹ் (ரழி) அவர்கள் கூறினார்கள், \"பின்னர் அல்லாஹ் அதனை உறுதிப்படுத்தும் விதமாக பின்வரும் வசனத்தை வஹீ (இறைச்செய்தி)யாக இறக்கினான்:\n\r\n\n\r\n**وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَـهًا آخَرَ وَلاَ يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلاَّ بِالْحَقِّ وَلاَ يَزْنُونَ**\n\r\n\n\r\n(மேலும், அவர்கள் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளையும் அழைக்க மாட்டார்கள்; அல்லாஹ் புனிதப்படுத்திய உயிரை (நியாயமின்றி)க் கொலை செய்யமாட்டார்கள்; மேலும் விபச்சாரம் செய்யமாட்டார்கள்.)\" இதனை அந்-நஸாயீ, அல்-புகாரீ மற்றும் முஸ்லிம் ஆகியோரும் பதிவு செய்துள்ளனர். ஸயீத் பின் ஜுபைர் அவர்கள் கூறியதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: ஷிர்க் செய்த மக்களில் சிலர் அதிகளவில் கொலைகளையும் விபச்சாரங்களையும் செய்திருந்தார்கள். பிறகு அவர்கள் முஹம்மது (ஸல்) அவர்களிடம் வந்து, \"நீங்கள் கூறுவதும் மக்களை அழைப்பதும் நல்லதாக உள்ளது. நாங்கள் செய்த பாவங்களுக்குப் பரிகாரம் காண்பதற்கு ஏதேனும் வழி உள்ளது என்று எங்களுக்குத் தெரிவித்தால் நன்றாக இருக்கும்\" என்று கூறினார்கள். அப்போது இந்த வசனம் அருளப்பட்டது:\n\r\n\n\r\n**وَالَّذِينَ لاَ يَدْعُونَ مَعَ اللَّهِ إِلَـهًا آخَرَ**\n\r\n\n\r\n(மேலும், அவர்கள் அல்லாஹ்வுடன் வேறு எந்தக் கடவுளையும் அழைக்க மாட்டார்கள்...) மேலும் இந்த வசனமும் அருளப்பட்டது:\n\r\n\n\r\nقُلْ يعِبَادِىَ الَّذِينَ أَسْرَفُواْ عَلَى أَنفُسِهِمْ\n\r\n\n\r\n(கூறுவீராக: \"தங்களுக்குத் தாமே வரம்பு மீறிக்கொண்ட என் அடியார்களே!\") (39:53).\n\r\n\n\r\nوَمَن يَفْعَلْ ذلِكَ يَلْقَ أَثَاماً\n\r\n\n\r\n(இதைச் செய்பவர் அதாமா-வைச் சந்திப்பார்.) 'அதாமா' என்பது நரகத்தில் உள்ள ஒரு பள்ளத்தாக்கு என்று அப்துல்லாஹ் பின் அம்ர் (ரழி) அவர்கள் கூறியதாகப் பதிவு செய்யப்பட்டுள்ளது. இக்ரிமா அவர்களும் 'அதாமா' என்பது நரகத்திலுள்ள பள்ளத்தாக்குகளைக் குறிக்கும் என்றும், அங்கு தாம்பத்திய உறவில் (விபச்சாரத்தில்) ஈடுபடுபவர்கள் தண்டிக்கப்படுவார்கள் என்றும் கூறினார்கள். இது ஸயீத் பின் ஜுபைர் மற்றும் முஜாஹித் ஆகியோரிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது. அஸ்-ஸுத்தீ அவர்கள், 'அதாமா' என்பது தண்டனையைக் குறிக்கிறது என்று கூறினார்கள். இது வசனத்தின் வெளிப்படையான பொருளுக்கு மிக நெருக்கமாக உள்ளது. இந்த விளக்கம், அடுத்து வரும் வசனத்திற்குப் பொருத்தமாக அமைகிறது:\n\r\n\n\r\n**يُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ**\n\r\n\n\r\n(மறுமை நாளில் அவனுக்கான வேதனை இரட்டிப்பாக்கப்படும்,) அதாவது, அது மீண்டும் மீண்டும் கடுமையாக்கப்படும்.\n\r\n\n\r\nوَيَخْلُدْ فِيهِ مُهَاناً\n\r\n\n\r\n(மேலும், அவன் இழிவுபடுத்தப்பட்டவனாக அதில் நிரந்தரமாகத் தங்குவான்;) இகழப்பட்டு, அவமானப்படுத்தப்பட்டவனாக.\n\r\n\n\r\n**إِلاَّ مَن تَابَ وَءَامَنَ وَعَمِلَ عَمَلاً صَالِحاً**\n\r\n\n\r\n(தவ்பா (மன்னிப்பு) கோரி, ஈமான் கொண்டு, நற்செயல்களைச் செய்பவர்களைத் தவிர;) இதன் பொருள், இத்தகு தீய செயல்களைச் செய்பவர்கள் விவரிக்கப்பட்டவாறு தண்டிக்கப்படுவார்கள் என்பதாகும்,\n\r\n\n\r\nإِلاَّ مَن تَابَ\n\r\n\n\r\n(மன்னிப்பு கோரியவர்களைத் தவிர), அதாவது; இந்த உலகிலேயே அச்செயல்கள் அனைத்திலிருந்தும் அல்லாஹ்விடம் தவ்பா செய்பவர்கள்; நிச்சயமாக அல்லாஹ் அவர்களின் தவ்பாவை ஏற்றுக்கொள்வான். கொலை செய்தவரின் தவ்பா ஏற்றுக்கொள்ளப்படும் என்பதற்கு இது ஆதாரமாகும். ஸூரத்துந் நிஸாவில் உள்ள வசனத்திற்கும் இதற்கும் முரண்பாடு ஏதுமில்லை:\n\r\n\n\r\nوَمَن يَقْتُلْ مُؤْمِناً مُّتَعَمِّداً\n\r\n\n\r\n(யார் ஒரு நம்பிக்கையாளரை வேண்டுமென்றே கொலை செய்கிறானோ) (4:93). ஏனெனில் இது மதீனாவில் அருளப்பட்டிருந்தாலும், இதன் பொருள் பொதுவானதாகும். மேலும், தவ்பா செய்யாத ஒருவரைப் பற்றியே இது குறிப்பிடுவதாகக் கொள்ளலாம். ஏனெனில், தற்போது நாம் பார்க்கும் வசனம் (25:70) தவ்பா செய்பவர்களுக்கு மட்டுமே மன்னிப்பு உண்டு என்று கூறுகிறது. மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّ اللَّهَ لاَ يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَن يَشَآءُ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் தனக்கு இணை கற்பிக்கப்படுவதை மன்னிக்க மாட்டான். ஆனால், அதைத் தவிர மற்றவற்றைத் தான் நாடியோருக்கு மன்னிப்பான்) (4:48). மேலும் ஆதாரப்பூர்வமான ஸுன்னாவில், கொலை செய்தவரின் தவ்பா ஏற்றுக்கொள்ளப்படும் என்று அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடமிருந்து அறிவிக்கப்பட்டுள்ளது. நூறு பேரைக் கொலை செய்துவிட்டுப் பின்னர் தவ்பா செய்த ஒருவரின் வரலாற்றிலும் அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொண்டான் என்று வந்துள்ளது. இது போன்ற மற்ற ஹதீஸ்களும் இதனை உறுதிப்படுத்துகின்றன.\n\r\n\n\r\n**فَأُوْلَـئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ وَكَانَ اللَّهُ غَفُوراً رَّحِيماً**\n\r\n\n\r\n(அத்தகையோரின் தீமைகளை அல்லாஹ் நன்மைகளாக மாற்றிவிடுவான். மேலும் அல்லாஹ் மிக்க மன்னிப்பவனாகவும், மகா கருணையாளனாகவும் இருக்கிறான்.) இமாம் அஹ்மத் அவர்கள் **பதிவு செய்துள்ளதாவது:** அபூ தர் (ரழி) அவர்கள் கூறியதாவது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنِّي لَأَعْرِفُ آخِرَ أَهْلِ النَّارِ خُرُوجًا مِنَ النَّارِ، وَآخِرَ أَهْلِ الْجَنَّةِ دُخُولًا إِلَى الْجَنَّةِ، يُؤْتَى بِرَجُلٍ فَيَقُولُ: نَحُّوا عَنْهُ كِبَارَ ذُنُوبِهِ وَسَلُوهُ عَنْ صِغَارِهَا، قَالَ: فَيُقَالُ لَهُ: عَمِلْتَ يَوْمَ كَذَا، كَذَا وَكَذَا، وَعَمِلْتَ يَوْمَ كَذَا، كَذَا وَكَذَا، فَيَقُولُ: نَعَمْ لَا يَسْتَطِيعُ أَنْ يُنْكِرَ مِنْ ذَلِكَ شَيْئًا، فَيُقَالُ: فَإِنَّ لَكَ بِكُلِّ سَيِّئَةٍ حَسَنَةً، فَيَقُولُ: يَا رَبِّ عَمِلْتُ أَشْيَاءَ لَا أَرَاهَا ههُنَا»\n\r\n\n\r\n(நரகத்திலிருந்து கடைசியாக வெளியே வருபவனையும், சொர்க்கத்தில் கடைசியாக நுழைபவனையும் நான் நிச்சயமாக அறிவேன். ஒரு மனிதன் கொண்டுவரப்பட்டு, \"அவனுடைய பெரும் பாவங்களை மறைத்துவிட்டு, அவனுடைய சிறு பாவங்களைப் பற்றிக் கேளுங்கள்\" என்று கூறப்படும். அவனிடம், \"இன்ன நாளில் நீ இன்னின்ன காரியங்களைச் செய்தாய் அல்லவா?\" என்று கேட்கப்படும். அவன் \"ஆம்\" என்று கூறுவான்; எதனையும் அவனால் மறுக்க முடியாது. பிறகு அவனிடம், \"உனது ஒவ்வொரு தீமைக்கும் பதிலாக உனக்கு ஒரு நன்மை உண்டு\" என்று கூறப்படும். அப்போது அவன், \"என் இறைவா! நான் இங்கு காணாத இன்னும் பல தீய காரியங்களையும் செய்துள்ளேனே!\" என்று கூறுவான்.)\" அப்போது அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் தமது கடவாய்ப் பற்கள் தெரியும் அளவுக்குப் புன்னகைத்தார்கள் என்று அபூ தர் (ரழி) அவர்கள் கூறினார்கள். இதனை முஸ்லிம் பதிவு செய்துள்ளார்.\n\r\n\n\r\nஇப்னு அபீ ஹாதிம் அவர்கள் **பதிவு செய்துள்ளதாவது: அபூ ஜஅஃபர்** அவர்கள் மஃகூலிடமிருந்து கேட்டதாகப் பதிவு செய்துள்ளார்கள்: \"கண்புருவங்கள் கண்களின் மீது விழுந்து கொண்டிருந்த ஒரு முதியவர் வந்து, 'அல்லாஹ்வின் தூதரே! ஒரு மனிதன் துரோகங்களும் ஒழுக்கக்கேடுகளும் செய்துள்ளான். அவன் செய்யாத எந்தத் தீமையும் இல்லை. அவனது பாவங்கள் மனிதகுலம் முழுமைக்கும் பங்கிடப்பட்டால், அவர்கள் அனைவரும் அழிந்துவிடுவார்கள். அவனுக்குத் தவ்பா (மன்னிப்பு) உண்டா?' என்று கேட்டார். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கேட்டார்கள்:\n\r\n\n\r\n«أَأَسْلَمْتَ؟»\n\r\n\n\r\n(நீர் இஸ்லாத்தை ஏற்றுக்கொண்டீரா?) அவர் கூறினார், \"நிச்சயமாக நான், வணக்கத்திற்குரியவன் அல்லாஹ்வைத் தவிர வேறு யாருமில்லை என்றும், அவனுக்கு இணை துணை ஏதுமில்லை என்றும், முஹம்மது (ஸல்) அவர்கள் அவனது அடியாரும் தூதருமாவார் என்றும் சாட்சி கூறுகிறேன்.\" நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«فَإِنَّ اللهَ غَافِرٌ لَكَ مَا كُنْتَ كَذَلِكَ، وَمُبَدِّلُ سَيِّئَاتِكَ حَسَنَات»\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ் நீர் அவ்வாறு செய்த அனைத்தையும் மன்னித்துவிடுவான்; உமது தீமைகளை நன்மைகளாக மாற்றிவிடுவான்.) அந்த மனிதர் கேட்டார்: \"அல்லாஹ்வின் தூதரே! எனது துரோகங்களையும் ஒழுக்கக்கேடுகளையும் கூடவா?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَغَدَرَاتُكَ وَفَجَرَاتُك»\n\r\n\n\r\n(உமது துரோகங்களையும் ஒழுக்கக்கேடுகளையும் கூடத்தான்.) அந்த மனிதர் 'லா இலாஹ இல்லல்லாஹ்' என்றும் 'அல்லாஹு அக்பர்' என்றும் முழங்கியவாறே சென்றார்.\" அல்லாஹ் தனது அடியார்கள் அனைவர் மீதும் அவனது கருணை எவ்வாறு பரவியுள்ளது என்பதையும், அவர்களில் எவர் அவனிடம் தவ்பா செய்தாலும் - அது பெரிய பாவமோ சிறிய பாவமோ - அவனது தவ்பாவை அவன் ஏற்றுக்கொள்வான் என்பதையும் நமக்குக் கூறுகிறான். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n**وَمَن تَابَ وَعَمِلَ صَالِحاً فَإِنَّهُ يَتُوبُ إِلَى اللَّهِ مَتاباً**\n\r\n\n\r\n(மேலும், யார் தவ்பா செய்து, நற்செயல்களைச் செய்கிறாரோ, நிச்சயமாக அவர் அல்லாஹ்விடம் சிறந்த முறையில் திரும்புகிறார்.) அதாவது, அல்லாஹ் அவரது தவ்பாவை ஏற்றுக்கொள்வான். இது பின்வரும் வசனங்களைப் போன்றதாகும்:\n\r\n\n\r\nوَمَن يَعْمَلْ سُوءاً أَوْ يَظْلِمْ نَفْسَهُ ثُمَّ يَسْتَغْفِرِ اللَّهَ يَجِدِ اللَّهَ غَفُوراً رَّحِيماً\n\r\n\n\r\n(மேலும், எவர் ஒரு தீமையைச் செய்தோ அல்லது தனக்குத்தானே அநீதி இழைத்தோ பின்னர் அல்லாஹ்விடம் மன்னிப்புக் கோரினால், அவர் அல்லாஹ்வை மிக்க மன்னிப்பவனாகவும், மகா கருணையாளனாகவும் காண்பார்) (4:110).\n\r\n\n\r\nأَلَمْ يَعْلَمُواْ أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ\n\r\n\n\r\n(நிச்சயமாக அல்லாஹ்தான் தனது அடியார்களிடமிருந்து தவ்பாவை ஏற்றுக்கொள்கிறான் என்பதை அவர்கள் அறியவில்லையா...) (9:104).\n\r\n\n\r\nقُلْ يعِبَادِىَ الَّذِينَ أَسْرَفُواْ عَلَى أَنفُسِهِمْ لاَ تَقْنَطُواْ مِن رَّحْمَةِ اللَّهِ\n\r\n\n\r\n(கூறுவீராக: \"தங்களுக்குத் தாமே வரம்பு மீறிக்கொண்ட என் அடியார்களே! அல்லாஹ்வின் கருணையிலிருந்து நீங்கள் நம்பிக்கை இழக்காதீர்கள்.\") (39:53) - அவனிடம் தவ்பா செய்பவர்களுக்காக."},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=74\" class=\"link\">25:74</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:74 ஐ பார்க்கவும்"},"73":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=74\" class=\"link\">25:74</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:74 ஐ பார்க்கவும்"},"74":{"html":"<strong>அளவற்ற அருளாளனின் அடியார்களின் மேலதிகப் பண்புகள்</strong><br />\r\n<br />\r\nஇவை அளவற்ற அருளாளனின் அடியார்களின் மேலதிகப் பண்புகளாகும். அவர்கள் பொய்க்குச் சாட்சி சொல்ல மாட்டார்கள்; இதில் பொய், ஒழுக்கக்கேடு, இறைநிராகரிப்பு, தீய சொற்கள் மற்றும் வீணான வார்த்தைகள் ஆகியவை அடங்கும். அம்ர் பின் கய்ஸ் (ரஹ்) கூறினார்கள்: \"இது ஒழுக்கக்கேடான (தாம்பத்திய உறவு தொடர்பான) சபைகளைக் குறிக்கும்.\" இந்த வசனம்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْهَدُونَ</span> <span class=\"quran-arabic-font text-success\">الزُّورَ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் பொய்யானவற்றுக்குச் சாட்சி கூறமாட்டார்கள்,) என்பது பொய்சாட்சி சொல்வதைக் குறிப்பதாகவும் கூறப்படுகிறது; அதாவது வேண்டுமென்றே பிறரைப் பற்றிப் பொய் கூறுவதாகும். இரண்டு ஸஹீஹ் நூல்களிலும் அபூ பக்ரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மூன்று முறை கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">أُنَبِّئُكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَكْبَرِ</span> <span class=\"quran-arabic-font text-success\">الْكَبَائِرِ؟</span>»<br />\r\n<br />\r\n(பெரும் பாவங்களிலேயே மிகப்பெரிய பாவத்தைப் பற்றி நான் உங்களுக்கு அறிவிக்கட்டுமா?) நாங்கள், “நிச்சயமாக, அல்லாஹ்வின் தூதரே!” என்று கூறினோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">الشِّرْكُ</span> <span class=\"quran-arabic-font text-success\">بِاللهِ</span> <span class=\"quran-arabic-font text-success\">وَعُقُوقُ</span> <span class=\"quran-arabic-font text-success\">الْوَالِدَيْن</span>»<br />\r\n<br />\r\n(அல்லாஹ்வுக்கு இணை கற்பித்தலும், பெற்றோரை அவமதிப்பதும் (பெற்றோருக்கு மாறு செய்வதும்).) அவர்கள் சாய்ந்து கொண்டிருந்தார்கள், பிறகு நிமிர்ந்து அமர்ந்து மேலும் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">وَقَوْلُ</span> <span class=\"quran-arabic-font text-success\">الزُّورِ،</span> <span class=\"quran-arabic-font text-success\">أَلَا</span> <span class=\"quran-arabic-font text-success\">وَشَهَادَةُ</span> <span class=\"quran-arabic-font text-success\">الزُّور</span>»<br />\r\n<br />\r\n(எச்சரிக்கை! பொய் பேசுவதையும் பொய் சாட்சி சொல்வதையும் தவிருங்கள்.) அவர்கள் நிறுத்த மாட்டார்களா என்று நாங்கள் நினைக்கும் வரை அதையே திரும்பத் திரும்பக் கூறிக் கொண்டிருந்தார்கள்.\" இந்தச் சூழலில் இருந்து, பொய்யானவற்றுக்குச் சாட்சி கூறாதவர்கள் என்பதன் பொருள், அத்தகைய வீணான காரியங்கள் நடக்கும் இடங்களில் அவர்கள் கலந்து கொள்ளவோ அல்லது அவை நிகழும்போது அங்கிருக்கவோ மாட்டார்கள் என்பதாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّغْوِ</span> <span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">كِراماً</span><br />\r\n<br />\r\n(மேலும், அவர்கள் வீணானவற்றைக் கடந்து செல்ல நேரிடும்போது, கண்ணியமான முறையிலேயே கடந்து செல்வார்கள்.) அவர்கள் பொய் மற்றும் வீண் காரியங்கள் நடக்கும் இடங்களுக்குச் செல்ல மாட்டார்கள்; ஒருவேளை அவர்கள் அதைக் கடந்து செல்ல நேர்ந்தால், அது தங்களைச் சிறிதளவும் மாசுபடுத்தாதவாறு கண்ணியமாக விலகிச் செல்வார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">مَرُّواْ</span> <span class=\"quran-arabic-font text-success\">كِراماً</span><br />\r\n<br />\r\n(அவர்கள் கண்ணியமான முறையிலேயே கடந்து செல்வார்கள்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">ذُكِّرُوا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِ</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَخِرُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">صُمّاً</span> <span class=\"quran-arabic-font text-success\">وَعُمْيَاناً</span><br />\r\n<br />\r\n(மேலும், அவர்கள் தங்களுடைய இறைவனின் வசனங்களைக் கொண்டு நினைவூட்டப்பட்டால், அவற்றின் மீது செவிடர்களாகவும் குருடர்களாகவும் விழ மாட்டார்கள்.) இதுவும் நம்பிக்கையாளர்களின் ஒரு பண்பாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">ذُكِرَ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">وَجِلَتْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">تُلِيَتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">آيَاتُهُ</span> <span class=\"quran-arabic-font text-success\">زَادَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">إِيمَانًا</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span> <span class=\"quran-arabic-font text-success\">يَتَوَكَّلُونَ</span><br />\r\n<br />\r\n(நம்பிக்கையாளர்கள் யாரென்றால், அல்லாஹ்வைப் பற்றி நினைவூட்டப்பட்டால் அவர்களுடைய இதயங்கள் பயந்து நடுங்கும்; அவனுடைய வசனங்கள் அவர்களுக்கு ஓதிக் காண்பிக்கப்பட்டால், அது அவர்களது ஈமானை (நம்பிக்கையை) அதிகப்படுத்தும்; மேலும் அவர்கள் தங்கள் இறைவன் மீதே முழு நம்பிக்கை வைப்பார்கள்.) (<a href=\"qurandisp.php?sura=8&ayah=2\" class=\"link\">8:2</a>). இவர்கள் இறைநிராகரிப்பாளர்களைப் போன்றவர்கள் அல்ல. அவர்கள் அல்லாஹ்வின் வசனங்களைக் கேட்கும்போது, அதனால் அவர்கள் பாதிக்கப்படுவதில்லை அல்லது தங்கள் வழிகளை மாற்றிக்கொள்வதுமில்லை. மாறாக, அல்லாஹ் கூறுவது போல அவர்கள் தங்கள் இறைநிராகரிப்பு, அநியாயம், அறியாமை மற்றும் வழிகேட்டிலேயே பிடிவாதமாக இருக்கிறார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أُنزِلَتْ</span> <span class=\"quran-arabic-font text-success\">سُورَةٌ</span> <span class=\"quran-arabic-font text-success\">فَمِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّن</span> <span class=\"quran-arabic-font text-success\">يَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَيُّكُمْ</span> <span class=\"quran-arabic-font text-success\">زَادَتْهُ</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">إِيمَانًا</span> <span class=\"quran-arabic-font text-success\">فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءامَنُواْ</span> <span class=\"quran-arabic-font text-success\">فَزَادَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">إِيمَانًا</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">يَسْتَبْشِرُونَ</span> <span class=\"quran-arabic-font text-success\">وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِم</span> <span class=\"quran-arabic-font text-success\">مَّرَضٌ</span> <span class=\"quran-arabic-font text-success\">فَزَادَتْهُمْ</span> <span class=\"quran-arabic-font text-success\">رِجْسًا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رِجْسِهِمْ</span><br />\r\n<br />\r\n(யாதொரு அத்தியாயம் அருளப்பட்டால், “உங்களில் யாருக்கு இது ஈமானை (நம்பிக்கையை) அதிகப்படுத்தியது?” என்று கேட்போரும் அவர்களில் உண்டு. நம்பிக்கை கொண்டவர்களுக்கு அது அவர்களது ஈமானை அதிகப்படுத்துகிறது; அவர்கள் மகிழ்ச்சி கொள்கிறார்கள். ஆனால், யாருடைய இதயங்களில் நோய் இருக்கிறதோ, அவர்களுடைய அழுக்குடன் மேலும் அழுக்கையே (சந்தேகத்தையே) அது அதிகப்படுத்துகிறது.) (<a href=\"qurandisp.php?sura=9&ayah=124\" class=\"link\">9:124</a>-125).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَخِرُّواْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهَا</span> <span class=\"quran-arabic-font text-success\">صُمّاً</span> <span class=\"quran-arabic-font text-success\">وَعُمْيَاناً</span><br />\r\n<br />\r\n(அவற்றின் மீது செவிடர்களாகவும் குருடர்களாகவும் விழ மாட்டார்கள்.) இதன் பொருள், இறைநிராகரிப்பாளர்களைப் போலல்லாமல், இவர்கள் அல்லாஹ்வின் வசனங்களைக் கேட்கும்போது, அவற்றைக் கேட்காத செவிடர்களைப் போலவோ அல்லது காணாத குருடர்களைப் போலவோ புறக்கணிக்காமல், அவற்றின் பால் கவனம் செலுத்துவார்கள் என்பதாகும். அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">هَبْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجِنَا</span> <span class=\"quran-arabic-font text-success\">وَذُرِّيَّاتِنَا</span> <span class=\"quran-arabic-font text-success\">قُرَّةَ</span> <span class=\"quran-arabic-font text-success\">أَعْيُنٍ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் கூறுகிறார்கள்: “எங்கள் இறைவனே! எங்கள் மனைவியரிடமிருந்தும் எங்களது சந்ததியினரிடமிருந்தும் எங்களுக்குக் கண் குளிர்ச்சியைத் தந்தருள்வாயாக...”) இதன் பொருள், தங்களுக்குக் கீழ்ப்படியும், அல்லாஹ்வை மட்டுமே வணங்கும் மற்றும் அவனுக்கு எதையும் இணைகற்பிக்காத சந்ததிகளைத் தங்களுக்கு வழங்குமாறு அல்லாஹ்விடம் பிரார்த்திப்பவர்கள் என்பதாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: “இதன் பொருள், அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடந்து, இவ்வுலகிலும் மறுமையிலும் தங்களுக்கு மகிழ்ச்சியைத் தரும் சந்ததிகளாக அவர்கள் இருப்பார்கள் என்பதாகும்.” இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள், ஜுபைர் பின் நுஃபைர் (ரஹ்) அவர்கள் கூறினார்கள்: “நாங்கள் ஒரு நாள் அல்-மிக்தாத் பின் அல்-அஸ்வத் (ரழி) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவ்வழியாகச் சென்ற ஒரு மனிதர், ‘அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைக் கண்ட இந்த இரண்டு கண்களும் எவ்வளவு பாக்கியம் பெற்றவை! நீங்கள் கண்டதை நாங்களும் கண்டிருக்க வேண்டுமே, நீங்கள் சாட்சியாக இருந்த நிகழ்வுகளில் நாங்களும் இருந்திருக்க வேண்டுமே!’ என்று கூறினார்.” அல்-மிக்தாத் (ரழி) அவர்கள் கோபமடைந்தார்கள். அந்த மனிதர் நல்லதைத் தவிர வேறு எதுவும் கூறாதபோது அவர் ஏன் கோபமடைந்தார் என்று எனக்கு ஆச்சரியமாக இருந்தது. பிறகு அவர்கள் அந்த மனிதரிடம் திரும்பி, “அல்லாஹ் ஒருவனை (அக்காலத்தில்) இல்லாதிருக்கச் செய்திருக்கும்போது, அவன் ஏன் அங்கே இருந்திருக்க வேண்டுமென்று விரும்புகிறான்? அவன் அங்கு இருந்திருந்தால் எப்படி நடந்திருப்பான் என்பது அவனுக்குத் தெரியாதே! அல்லாஹ்வின் மீது ஆணையாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பார்த்த எத்தனையோ பேர் இருக்கிறார்கள்; ஆனால் அவர்கள் அவரை ஏற்றுக் கொள்ளாததாலும், அவரை நம்பாததாலும் அல்லாஹ் அவர்களை முகங்குப்புற நரகில் வீழ்த்துவான். உங்கள் இறைவன் மீதும், உங்கள் நபி கொண்டு வந்த வஹி (இறைச்செய்தி) மீதும் நம்பிக்கை கொண்டவர்களாக உங்கள் தாய்மார்களின் கருவறைகளிலிருந்து அல்லாஹ் உங்களை வெளிக்கொணர்ந்ததற்கும், அந்தச் சோதனை மற்றவர்களுக்குச் சென்று உங்களுக்கு வராமல் இருந்ததற்கும் நீங்கள் நன்றி செலுத்த வேண்டாமா? எந்த ஒரு நபியும் அனுப்பப்பட்டதிலேயே மிகவும் கடினமான காலகட்டத்தில், நீண்ட அறியாமைக் காலத்திற்குப் பிறகு அல்லாஹ் தன் நபியை அனுப்பினான். அக்காலத்தில் மக்கள் சிலை வணக்கத்தை விடச் சிறந்த மார்க்கத்தை அறிந்திருக்கவில்லை. அவர் சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறியும் அளவுகோலை (புர்கான்) கொண்டு வந்தார். அது தந்தையை மகனிடமிருந்து பிரித்தது. ஒரு மனிதன் தன் தந்தை, மகன் அல்லது சகோதரன் ஒரு நிராகரிப்பாளன் என்பதை உணர்வான்; அல்லாஹ் அவனது இதயத்தை ஈமானுக்குத் திறந்துவிட்டதால், தன் உறவினர் அந்த நிலையில் இறந்தால் நரகிற்குச் செல்வார் என்பதை அவன் அறிந்திருந்தான். அதனால், தன் அன்புக்குரியவர் நரக நெருப்பில் இருப்பார் என்பதைத் தெரிந்தே அவனால் நிம்மதியாக இருக்க முடியவில்லை. இதையே அல்லாஹ் இந்த வசனத்தில் குறிப்பிடுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">هَبْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجِنَا</span> <span class=\"quran-arabic-font text-success\">وَذُرِّيَّاتِنَا</span> <span class=\"quran-arabic-font text-success\">قُرَّةَ</span> <span class=\"quran-arabic-font text-success\">أَعْيُنٍ</span><br />\r\n<br />\r\n(மேலும், அவர்கள் கூறுகிறார்கள்: “எங்கள் இறைவனே! எங்கள் மனைவியரிடமிருந்தும் எங்களது சந்ததியினரிடமிருந்தும் எங்களுக்குக் கண் குளிர்ச்சியைத் தந்தருள்வாயாக...”) இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் (ஆதாரப்பூர்வமானது) ஆகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاجْعَلْنَا</span> <span class=\"quran-arabic-font text-success\">لِلْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">إِمَاماً</span><br />\r\n<br />\r\n(மேலும், இறையச்சம் உடையவர்களுக்கு (தக்வா உள்ளவர்களுக்கு) எங்களை ஒரு முன்மாதிரியாக (தலைவர்களாக) ஆக்குவாயாக.) இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன், அஸ்-ஸுத்தி, கதாதா மற்றும் ரபிஃ பின் அனஸ் (ரஹ்) ஆகியோர் கூறினார்கள்: “நற்காரியங்களில் மற்றவர்கள் பின்பற்றக்கூடிய முன்மாதிரிமிக்க தலைவர்கள்.” மற்றவர்கள் கூறினார்கள்: “பிறரை நன்மையின் பால் அழைக்கும் வழிகாட்டிகள்.” அவர்கள் தங்கள் இபாதத்துகள் (வணக்க வழிபாடுகள்) தங்கள் பிள்ளைகள் மற்றும் சந்ததியினரின் வழிபாடுகளுடன் இணைந்திருக்க வேண்டும் என்றும், தங்கள் நேர்வழி தங்களோடு நின்றுவிடாமல் மற்றவர்களுக்கும் பயனளிக்க வேண்டும் என்றும் விரும்பினார்கள். இது அதிக நற்கூலியையும் சிறந்த முடிவையும் தரும். ஸஹீஹ் முஸ்லிமில் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">مَاتَ</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">آدَمَ</span> <span class=\"quran-arabic-font text-success\">انْقَطَعَ</span> <span class=\"quran-arabic-font text-success\">عَمَلُهُ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">ثَلَاثٍ</span>: <span class=\"quran-arabic-font text-success\">وَلَدٍ</span> <span class=\"quran-arabic-font text-success\">صَالِحٍ</span> <span class=\"quran-arabic-font text-success\">يَدْعُو</span> <span class=\"quran-arabic-font text-success\">لَهُ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">عِلْمٍ</span> <span class=\"quran-arabic-font text-success\">يُنْتَفَعُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">بَعْدِهِ،</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">صَدَقَةٍ</span> <span class=\"quran-arabic-font text-success\">جَارِيَة</span>»<br />\r\n<br />\r\n(ஆதமுடைய மகன் இறந்துவிட்டால், மூன்று விஷயங்களைத் தவிர அவனுடைய செயல்பாடுகள் அனைத்தும் நின்றுவிடுகின்றன: அவனுக்காகப் பிரார்த்தனை செய்யும் ஸாலிஹான (நல்ல) பிள்ளை, அவனுக்குப் பிறகு பிறர் பயனடையும் கல்வி, அல்லது நிலையான தர்மம் (ஸதக்கத்துல் ஜாரியா).)<br />\r\n<br />","text":"அளவற்ற அருளாளனின் அடியார்களின் மேலதிகப் பண்புகள்\n\r\n\n\r\nஇவை அளவற்ற அருளாளனின் அடியார்களின் மேலதிகப் பண்புகளாகும். அவர்கள் பொய்க்குச் சாட்சி சொல்ல மாட்டார்கள்; இதில் பொய், ஒழுக்கக்கேடு, இறைநிராகரிப்பு, தீய சொற்கள் மற்றும் வீணான வார்த்தைகள் ஆகியவை அடங்கும். அம்ர் பின் கய்ஸ் (ரஹ்) கூறினார்கள்: \"இது ஒழுக்கக்கேடான (தாம்பத்திய உறவு தொடர்பான) சபைகளைக் குறிக்கும்.\" இந்த வசனம்,\n\r\n\n\r\nلاَ يَشْهَدُونَ الزُّورَ\n\r\n\n\r\n(மேலும், அவர்கள் பொய்யானவற்றுக்குச் சாட்சி கூறமாட்டார்கள்,) என்பது பொய்சாட்சி சொல்வதைக் குறிப்பதாகவும் கூறப்படுகிறது; அதாவது வேண்டுமென்றே பிறரைப் பற்றிப் பொய் கூறுவதாகும். இரண்டு ஸஹீஹ் நூல்களிலும் அபூ பக்ரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது: \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் மூன்று முறை கூறினார்கள்:\n\r\n\n\r\n«أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ؟»\n\r\n\n\r\n(பெரும் பாவங்களிலேயே மிகப்பெரிய பாவத்தைப் பற்றி நான் உங்களுக்கு அறிவிக்கட்டுமா?) நாங்கள், “நிச்சயமாக, அல்லாஹ்வின் தூதரே!” என்று கூறினோம். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«الشِّرْكُ بِاللهِ وَعُقُوقُ الْوَالِدَيْن»\n\r\n\n\r\n(அல்லாஹ்வுக்கு இணை கற்பித்தலும், பெற்றோரை அவமதிப்பதும் (பெற்றோருக்கு மாறு செய்வதும்).) அவர்கள் சாய்ந்து கொண்டிருந்தார்கள், பிறகு நிமிர்ந்து அமர்ந்து மேலும் கூறினார்கள்:\n\r\n\n\r\n«أَلَا وَقَوْلُ الزُّورِ، أَلَا وَشَهَادَةُ الزُّور»\n\r\n\n\r\n(எச்சரிக்கை! பொய் பேசுவதையும் பொய் சாட்சி சொல்வதையும் தவிருங்கள்.) அவர்கள் நிறுத்த மாட்டார்களா என்று நாங்கள் நினைக்கும் வரை அதையே திரும்பத் திரும்பக் கூறிக் கொண்டிருந்தார்கள்.\" இந்தச் சூழலில் இருந்து, பொய்யானவற்றுக்குச் சாட்சி கூறாதவர்கள் என்பதன் பொருள், அத்தகைய வீணான காரியங்கள் நடக்கும் இடங்களில் அவர்கள் கலந்து கொள்ளவோ அல்லது அவை நிகழும்போது அங்கிருக்கவோ மாட்டார்கள் என்பதாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَإِذَا مَرُّواْ بِاللَّغْوِ مَرُّواْ كِراماً\n\r\n\n\r\n(மேலும், அவர்கள் வீணானவற்றைக் கடந்து செல்ல நேரிடும்போது, கண்ணியமான முறையிலேயே கடந்து செல்வார்கள்.) அவர்கள் பொய் மற்றும் வீண் காரியங்கள் நடக்கும் இடங்களுக்குச் செல்ல மாட்டார்கள்; ஒருவேளை அவர்கள் அதைக் கடந்து செல்ல நேர்ந்தால், அது தங்களைச் சிறிதளவும் மாசுபடுத்தாதவாறு கண்ணியமாக விலகிச் செல்வார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nمَرُّواْ كِراماً\n\r\n\n\r\n(அவர்கள் கண்ணியமான முறையிலேயே கடந்து செல்வார்கள்.)\n\r\n\n\r\nوَالَّذِينَ إِذَا ذُكِّرُوا بِآيَاتِ رَبِّهِمْ لَمْ يَخِرُّواْ عَلَيْهَا صُمّاً وَعُمْيَاناً\n\r\n\n\r\n(மேலும், அவர்கள் தங்களுடைய இறைவனின் வசனங்களைக் கொண்டு நினைவூட்டப்பட்டால், அவற்றின் மீது செவிடர்களாகவும் குருடர்களாகவும் விழ மாட்டார்கள்.) இதுவும் நம்பிக்கையாளர்களின் ஒரு பண்பாகும்:\n\r\n\n\r\nالَّذِينَ إِذَا ذُكِرَ اللَّهُ وَجِلَتْ قُلُوبُهُمْ وَإِذَا تُلِيَتْ عَلَيْهِمْ آيَاتُهُ زَادَتْهُمْ إِيمَانًا وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ\n\r\n\n\r\n(நம்பிக்கையாளர்கள் யாரென்றால், அல்லாஹ்வைப் பற்றி நினைவூட்டப்பட்டால் அவர்களுடைய இதயங்கள் பயந்து நடுங்கும்; அவனுடைய வசனங்கள் அவர்களுக்கு ஓதிக் காண்பிக்கப்பட்டால், அது அவர்களது ஈமானை (நம்பிக்கையை) அதிகப்படுத்தும்; மேலும் அவர்கள் தங்கள் இறைவன் மீதே முழு நம்பிக்கை வைப்பார்கள்.) (8:2). இவர்கள் இறைநிராகரிப்பாளர்களைப் போன்றவர்கள் அல்ல. அவர்கள் அல்லாஹ்வின் வசனங்களைக் கேட்கும்போது, அதனால் அவர்கள் பாதிக்கப்படுவதில்லை அல்லது தங்கள் வழிகளை மாற்றிக்கொள்வதுமில்லை. மாறாக, அல்லாஹ் கூறுவது போல அவர்கள் தங்கள் இறைநிராகரிப்பு, அநியாயம், அறியாமை மற்றும் வழிகேட்டிலேயே பிடிவாதமாக இருக்கிறார்கள்:\n\r\n\n\r\nوَإِذَا مَآ أُنزِلَتْ سُورَةٌ فَمِنْهُمْ مَّن يَقُولُ أَيُّكُمْ زَادَتْهُ هَذِهِ إِيمَانًا فَأَمَّا الَّذِينَ ءامَنُواْ فَزَادَتْهُمْ إِيمَانًا وَهُمْ يَسْتَبْشِرُونَ وَأَمَّا الَّذِينَ فِى قُلُوبِهِم مَّرَضٌ فَزَادَتْهُمْ رِجْسًا إِلَى رِجْسِهِمْ\n\r\n\n\r\n(யாதொரு அத்தியாயம் அருளப்பட்டால், “உங்களில் யாருக்கு இது ஈமானை (நம்பிக்கையை) அதிகப்படுத்தியது?” என்று கேட்போரும் அவர்களில் உண்டு. நம்பிக்கை கொண்டவர்களுக்கு அது அவர்களது ஈமானை அதிகப்படுத்துகிறது; அவர்கள் மகிழ்ச்சி கொள்கிறார்கள். ஆனால், யாருடைய இதயங்களில் நோய் இருக்கிறதோ, அவர்களுடைய அழுக்குடன் மேலும் அழுக்கையே (சந்தேகத்தையே) அது அதிகப்படுத்துகிறது.) (9:124-125).\n\r\n\n\r\nلَمْ يَخِرُّواْ عَلَيْهَا صُمّاً وَعُمْيَاناً\n\r\n\n\r\n(அவற்றின் மீது செவிடர்களாகவும் குருடர்களாகவும் விழ மாட்டார்கள்.) இதன் பொருள், இறைநிராகரிப்பாளர்களைப் போலல்லாமல், இவர்கள் அல்லாஹ்வின் வசனங்களைக் கேட்கும்போது, அவற்றைக் கேட்காத செவிடர்களைப் போலவோ அல்லது காணாத குருடர்களைப் போலவோ புறக்கணிக்காமல், அவற்றின் பால் கவனம் செலுத்துவார்கள் என்பதாகும். அவன் கூறுகிறான்:\n\r\n\n\r\nوَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ\n\r\n\n\r\n(மேலும், அவர்கள் கூறுகிறார்கள்: “எங்கள் இறைவனே! எங்கள் மனைவியரிடமிருந்தும் எங்களது சந்ததியினரிடமிருந்தும் எங்களுக்குக் கண் குளிர்ச்சியைத் தந்தருள்வாயாக...”) இதன் பொருள், தங்களுக்குக் கீழ்ப்படியும், அல்லாஹ்வை மட்டுமே வணங்கும் மற்றும் அவனுக்கு எதையும் இணைகற்பிக்காத சந்ததிகளைத் தங்களுக்கு வழங்குமாறு அல்லாஹ்விடம் பிரார்த்திப்பவர்கள் என்பதாகும். இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: “இதன் பொருள், அல்லாஹ்வுக்குக் கீழ்ப்படிந்து நடந்து, இவ்வுலகிலும் மறுமையிலும் தங்களுக்கு மகிழ்ச்சியைத் தரும் சந்ததிகளாக அவர்கள் இருப்பார்கள் என்பதாகும்.” இமாம் அஹ்மத் (ரஹ்) அவர்கள் பதிவு செய்துள்ளார்கள், ஜுபைர் பின் நுஃபைர் (ரஹ்) அவர்கள் கூறினார்கள்: “நாங்கள் ஒரு நாள் அல்-மிக்தாத் பின் அல்-அஸ்வத் (ரழி) அவர்களுடன் அமர்ந்திருந்தோம். அப்போது அவ்வழியாகச் சென்ற ஒரு மனிதர், ‘அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைக் கண்ட இந்த இரண்டு கண்களும் எவ்வளவு பாக்கியம் பெற்றவை! நீங்கள் கண்டதை நாங்களும் கண்டிருக்க வேண்டுமே, நீங்கள் சாட்சியாக இருந்த நிகழ்வுகளில் நாங்களும் இருந்திருக்க வேண்டுமே!’ என்று கூறினார்.” அல்-மிக்தாத் (ரழி) அவர்கள் கோபமடைந்தார்கள். அந்த மனிதர் நல்லதைத் தவிர வேறு எதுவும் கூறாதபோது அவர் ஏன் கோபமடைந்தார் என்று எனக்கு ஆச்சரியமாக இருந்தது. பிறகு அவர்கள் அந்த மனிதரிடம் திரும்பி, “அல்லாஹ் ஒருவனை (அக்காலத்தில்) இல்லாதிருக்கச் செய்திருக்கும்போது, அவன் ஏன் அங்கே இருந்திருக்க வேண்டுமென்று விரும்புகிறான்? அவன் அங்கு இருந்திருந்தால் எப்படி நடந்திருப்பான் என்பது அவனுக்குத் தெரியாதே! அல்லாஹ்வின் மீது ஆணையாக, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைப் பார்த்த எத்தனையோ பேர் இருக்கிறார்கள்; ஆனால் அவர்கள் அவரை ஏற்றுக் கொள்ளாததாலும், அவரை நம்பாததாலும் அல்லாஹ் அவர்களை முகங்குப்புற நரகில் வீழ்த்துவான். உங்கள் இறைவன் மீதும், உங்கள் நபி கொண்டு வந்த வஹி (இறைச்செய்தி) மீதும் நம்பிக்கை கொண்டவர்களாக உங்கள் தாய்மார்களின் கருவறைகளிலிருந்து அல்லாஹ் உங்களை வெளிக்கொணர்ந்ததற்கும், அந்தச் சோதனை மற்றவர்களுக்குச் சென்று உங்களுக்கு வராமல் இருந்ததற்கும் நீங்கள் நன்றி செலுத்த வேண்டாமா? எந்த ஒரு நபியும் அனுப்பப்பட்டதிலேயே மிகவும் கடினமான காலகட்டத்தில், நீண்ட அறியாமைக் காலத்திற்குப் பிறகு அல்லாஹ் தன் நபியை அனுப்பினான். அக்காலத்தில் மக்கள் சிலை வணக்கத்தை விடச் சிறந்த மார்க்கத்தை அறிந்திருக்கவில்லை. அவர் சத்தியத்தையும் அசத்தியத்தையும் பிரித்தறியும் அளவுகோலை (புர்கான்) கொண்டு வந்தார். அது தந்தையை மகனிடமிருந்து பிரித்தது. ஒரு மனிதன் தன் தந்தை, மகன் அல்லது சகோதரன் ஒரு நிராகரிப்பாளன் என்பதை உணர்வான்; அல்லாஹ் அவனது இதயத்தை ஈமானுக்குத் திறந்துவிட்டதால், தன் உறவினர் அந்த நிலையில் இறந்தால் நரகிற்குச் செல்வார் என்பதை அவன் அறிந்திருந்தான். அதனால், தன் அன்புக்குரியவர் நரக நெருப்பில் இருப்பார் என்பதைத் தெரிந்தே அவனால் நிம்மதியாக இருக்க முடியவில்லை. இதையே அல்லாஹ் இந்த வசனத்தில் குறிப்பிடுகிறான்:\n\r\n\n\r\nوَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ أَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ أَعْيُنٍ\n\r\n\n\r\n(மேலும், அவர்கள் கூறுகிறார்கள்: “எங்கள் இறைவனே! எங்கள் மனைவியரிடமிருந்தும் எங்களது சந்ததியினரிடமிருந்தும் எங்களுக்குக் கண் குளிர்ச்சியைத் தந்தருள்வாயாக...”) இதன் அறிவிப்பாளர் தொடர் ஸஹீஹ் (ஆதாரப்பூர்வமானது) ஆகும்.\n\r\n\n\r\nوَاجْعَلْنَا لِلْمُتَّقِينَ إِمَاماً\n\r\n\n\r\n(மேலும், இறையச்சம் உடையவர்களுக்கு (தக்வா உள்ளவர்களுக்கு) எங்களை ஒரு முன்மாதிரியாக (தலைவர்களாக) ஆக்குவாயாக.) இப்னு அப்பாஸ் (ரழி), அல்-ஹஸன், அஸ்-ஸுத்தி, கதாதா மற்றும் ரபிஃ பின் அனஸ் (ரஹ்) ஆகியோர் கூறினார்கள்: “நற்காரியங்களில் மற்றவர்கள் பின்பற்றக்கூடிய முன்மாதிரிமிக்க தலைவர்கள்.” மற்றவர்கள் கூறினார்கள்: “பிறரை நன்மையின் பால் அழைக்கும் வழிகாட்டிகள்.” அவர்கள் தங்கள் இபாதத்துகள் (வணக்க வழிபாடுகள்) தங்கள் பிள்ளைகள் மற்றும் சந்ததியினரின் வழிபாடுகளுடன் இணைந்திருக்க வேண்டும் என்றும், தங்கள் நேர்வழி தங்களோடு நின்றுவிடாமல் மற்றவர்களுக்கும் பயனளிக்க வேண்டும் என்றும் விரும்பினார்கள். இது அதிக நற்கூலியையும் சிறந்த முடிவையும் தரும். ஸஹீஹ் முஸ்லிமில் அபூ ஹுரைரா (ரழி) அவர்கள் அறிவித்ததாகப் பதிவு செய்யப்பட்டுள்ளது, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا مَاتَ ابْنُ آدَمَ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثٍ: وَلَدٍ صَالِحٍ يَدْعُو لَهُ، أَوْ عِلْمٍ يُنْتَفَعُ بِهِ مِنْ بَعْدِهِ، أَوْ صَدَقَةٍ جَارِيَة»\n\r\n\n\r\n(ஆதமுடைய மகன் இறந்துவிட்டால், மூன்று விஷயங்களைத் தவிர அவனுடைய செயல்பாடுகள் அனைத்தும் நின்றுவிடுகின்றன: அவனுக்காகப் பிரார்த்தனை செய்யும் ஸாலிஹான (நல்ல) பிள்ளை, அவனுக்குப் பிறகு பிறர் பயனடையும் கல்வி, அல்லது நிலையான தர்மம் (ஸதக்கத்துல் ஜாரியா).)"},"75":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=77\" class=\"link\">25:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:77 ஐ பார்க்கவும்"},"76":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=25&ayah=77\" class=\"link\">25:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 25:77 ஐ பார்க்கவும்"},"77":{"html":"<strong>அர்ரஹ்மானின் அடியார்களுக்குக் கிடைக்கும் நற்கூலியும், மக்காவாசிகளுக்கு விடுக்கப்படும் எச்சரிக்கையும்</strong><br />\r\n<br />\r\nதனது இறைநம்பிக்கையுள்ள அடியார்களின் அழகிய பண்புகளையும், அவர்களின் சிறந்த சொற்களையும் செயல்களையும் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أُوْلَـئِكَ﴿</span><br />\r\n<br />\r\n(இவர்கள்) அதாவது, இத்தகைய பண்புகளால் வர்ணிக்கப்பட்டவர்கள், <span class=\"quran-arabic-font text-success\">﴾يُجْزَوْنَ﴿</span><br />\r\n<br />\r\n(நற்கூலி வழங்கப்படுவார்கள்) மறுமை நாளில், <span class=\"quran-arabic-font text-success\">﴾الْغُرْفَةَ﴿</span><br />\r\n<br />\r\n(உயர்ந்த இடத்தைக் கொண்டு), அதுதான் சுவர்க்கமாகும். அபூ ஜஃபர் அல்-பாகிர், ஸயீத் பின் ஜுபைர், அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தீ ஆகியோர், \"அது மிக உயரத்தில் இருப்பதால் அவ்வாறு அழைக்கப்பட்டது\" என்று கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾بِمَا</span> <span class=\"quran-arabic-font text-success\">صَبَرُواْ﴿</span><br />\r\n<br />\r\n(அவர்கள் பொறுமையாக இருந்த காரணத்தால்.) அதாவது, அவர்கள் செய்த நற்செயல்களில் உறுதியுடன் காட்டிய பொறுமையின் காரணமாக. <span class=\"quran-arabic-font text-success\">﴾وَيُلَقَّوْنَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n<br />\r\n(அங்கே அவர்கள் வரவேற்கப்படுவார்கள்) அதாவது, சுவர்க்கத்தில், <span class=\"quran-arabic-font text-success\">﴾تَحِيَّةً</span> <span class=\"quran-arabic-font text-success\">وَسَلَـماً﴿</span><br />\r\n<br />\r\n(வாழ்த்துக்களுடனும், சாந்தி மற்றும் மரியாதையுடனும்.) இதன் பொருள், அவர்கள் கண்ணியமான முகமன் (வாழ்த்து) மற்றும் மரியாதைக்குரிய வார்த்தைகளுடன் முதலில் வரவேற்கப்படுவார்கள். அவர்களுக்குச் சாந்தியும் அமைதியும் கிடைக்கும். வானவர்கள் ஒவ்வொரு வாசலிலிருந்தும் அவர்களிடம் நுழைந்து, \"நீங்கள் பொறுமையைக் கடைப்பிடித்ததற்காக உங்கள் மீது ஸலாம் (சாந்தி) உண்டாவதாக! உங்கள் இறுதி இருப்பிடம் எவ்வளவு சிறப்பானது!\" என்று கூறுவார்கள். <span class=\"quran-arabic-font text-success\">﴾خَـلِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَآ﴿</span><br />\r\n<br />\r\n(அதில் அவர்கள் நிரந்தரமாகத் தங்கியிருப்பார்கள்) அதாவது, அவர்கள் அங்கேயே தங்கிவிடுவார்கள்; ஒருபோதும் அங்கிருந்து வெளியேறவோ, இடம்பெயரவோ அல்லது மரணிக்கவோ மாட்டார்கள். அவர்கள் அங்கிருந்து வெளியேறவோ அல்லது வேறு இடத்திற்குச் செல்லவோ விரும்ப மாட்டார்கள். இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">سُعِدُواْ</span> <span class=\"quran-arabic-font text-success\">فَفِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">خَالِدِينَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">دَامَتِ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتُ</span> <span class=\"quran-arabic-font text-success\">وَالأَرْضُ﴿</span><br />\r\n<br />\r\n(பாக்கியம் பெற்றவர்கள் சுவர்க்கத்தில் இருப்பார்கள்; வானங்களும் பூமியும் நிலைத்திருக்கும் காலமெல்லாம் அவர்கள் அதில் நிரந்தரமாகத் தங்கியிருப்பார்கள்) (<a href=\"qurandisp.php?sura=11&ayah=108\" class=\"link\">11:108</a>). <span class=\"quran-arabic-font text-success\">﴾حَسُنَتْ</span> <span class=\"quran-arabic-font text-success\">مُسْتَقَرّاً</span> <span class=\"quran-arabic-font text-success\">وَمُقَاماً﴿</span><br />\r\n<br />\r\n(அது தங்குமிடமாகவும், ஓய்வெடுக்கும் இடமாகவும் மிகவும் அழகானது.) அதன் தோற்றம் மிக அழகானது; தங்குவதற்கும் ஓய்வெடுப்பதற்கும் அது மிகச் சிறந்த இடமாகும். பிறகு அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾قُلْ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَعْبَؤُا</span> <span class=\"quran-arabic-font text-success\">بِكُمْ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">لَوْلاَ</span> <span class=\"quran-arabic-font text-success\">دُعَآؤُكُمْ﴿</span><br />\r\n<br />\r\n(கூறுவீராக: \"நீங்கள் அவனைப் பிரார்த்திப்பதன் (வணங்குவதன்) காரணமாக அன்றி, என் இறைவன் உங்கள் மீது கவனம் செலுத்த மாட்டான்...\") அதாவது, நீங்கள் அவனை வணங்கவில்லை என்றால் அவன் உங்கள் மீது கவனம் செலுத்த மாட்டான். ஏனெனில், மனிதர்களைத் தன்னை மட்டுமே வணங்குவதற்காகவும், காலையிலும் மாலையிலும் தன்னைத் துதிப்பதற்காகவுமே அவன் படைத்தான். அவனது கூற்று: <span class=\"quran-arabic-font text-success\">﴾فَقَدْ</span> <span class=\"quran-arabic-font text-success\">كَذَّبْتُمْ﴿</span><br />\r\n<br />\r\n(ஆனால், நீங்களோ நிச்சயமாக (சத்தியத்தைப்) பொய்யாக்கினீர்கள்.) \"ஓ நிராகரிப்பாளர்களே!\" <span class=\"quran-arabic-font text-success\">﴾فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">لِزَاماً﴿</span><br />\r\n<br />\r\n(ஆகவே, அந்தத் தண்டனை உங்களை ஒருபோதும் பிரியாது.) அதாவது, உங்களது அந்த மறுப்பு ஒருபோதும் உங்களை விட்டு நீங்காது; அது இவ்வுலகிலும் மறுமையிலும் உங்களின் தண்டனைக்கும், அழிவிற்கும், நாசத்திற்கும் காரணமாக அமையும். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி), உபை பின் கஅப் (ரழி), முஹம்மது பின் கஅப் அல்-குரழீ, முஜாஹித், அத்-தஹ்ஹாக், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் விளக்கியது போல், இது பத்ருப் போர் நடைபெற்ற நாளையும் குறிக்கும். <span class=\"quran-arabic-font text-success\">﴾فَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">يَكُونُ</span> <span class=\"quran-arabic-font text-success\">لِزَاماً﴿</span><br />\r\n<br />\r\n(ஆகவே, அந்தத் தண்டனை உங்களை ஒருபோதும் பிரியாது.) அல்-ஹஸன் அல்-பஸரீ அவர்கள் கூறுகையில், \"இது மறுமை நாளைக் குறிக்கும்\" என்றார்கள். இந்த இரண்டு விளக்கங்களுக்கும் இடையில் எவ்வித முரண்பாடும் இல்லை. இத்துடன் ஸூரத்துல் ஃபுர்கானின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது.<br />\r\n<br />","text":"அர்ரஹ்மானின் அடியார்களுக்குக் கிடைக்கும் நற்கூலியும், மக்காவாசிகளுக்கு விடுக்கப்படும் எச்சரிக்கையும்\n\r\n\n\r\nதனது இறைநம்பிக்கையுள்ள அடியார்களின் அழகிய பண்புகளையும், அவர்களின் சிறந்த சொற்களையும் செயல்களையும் குறிப்பிட்ட பிறகு அல்லாஹ் கூறுகிறான்: ﴾أُوْلَـئِكَ﴿\n\r\n\n\r\n(இவர்கள்) அதாவது, இத்தகைய பண்புகளால் வர்ணிக்கப்பட்டவர்கள், ﴾يُجْزَوْنَ﴿\n\r\n\n\r\n(நற்கூலி வழங்கப்படுவார்கள்) மறுமை நாளில், ﴾الْغُرْفَةَ﴿\n\r\n\n\r\n(உயர்ந்த இடத்தைக் கொண்டு), அதுதான் சுவர்க்கமாகும். அபூ ஜஃபர் அல்-பாகிர், ஸயீத் பின் ஜுபைர், அத்-தஹ்ஹாக் மற்றும் அஸ்-ஸுத்தீ ஆகியோர், \"அது மிக உயரத்தில் இருப்பதால் அவ்வாறு அழைக்கப்பட்டது\" என்று கூறினார்கள். ﴾بِمَا صَبَرُواْ﴿\n\r\n\n\r\n(அவர்கள் பொறுமையாக இருந்த காரணத்தால்.) அதாவது, அவர்கள் செய்த நற்செயல்களில் உறுதியுடன் காட்டிய பொறுமையின் காரணமாக. ﴾وَيُلَقَّوْنَ فِيهَا﴿\n\r\n\n\r\n(அங்கே அவர்கள் வரவேற்கப்படுவார்கள்) அதாவது, சுவர்க்கத்தில், ﴾تَحِيَّةً وَسَلَـماً﴿\n\r\n\n\r\n(வாழ்த்துக்களுடனும், சாந்தி மற்றும் மரியாதையுடனும்.) இதன் பொருள், அவர்கள் கண்ணியமான முகமன் (வாழ்த்து) மற்றும் மரியாதைக்குரிய வார்த்தைகளுடன் முதலில் வரவேற்கப்படுவார்கள். அவர்களுக்குச் சாந்தியும் அமைதியும் கிடைக்கும். வானவர்கள் ஒவ்வொரு வாசலிலிருந்தும் அவர்களிடம் நுழைந்து, \"நீங்கள் பொறுமையைக் கடைப்பிடித்ததற்காக உங்கள் மீது ஸலாம் (சாந்தி) உண்டாவதாக! உங்கள் இறுதி இருப்பிடம் எவ்வளவு சிறப்பானது!\" என்று கூறுவார்கள். ﴾خَـلِدِينَ فِيهَآ﴿\n\r\n\n\r\n(அதில் அவர்கள் நிரந்தரமாகத் தங்கியிருப்பார்கள்) அதாவது, அவர்கள் அங்கேயே தங்கிவிடுவார்கள்; ஒருபோதும் அங்கிருந்து வெளியேறவோ, இடம்பெயரவோ அல்லது மரணிக்கவோ மாட்டார்கள். அவர்கள் அங்கிருந்து வெளியேறவோ அல்லது வேறு இடத்திற்குச் செல்லவோ விரும்ப மாட்டார்கள். இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾وَأَمَّا الَّذِينَ سُعِدُواْ فَفِي الْجَنَّةِ خَالِدِينَ فِيهَا مَا دَامَتِ السَّمَاوَاتُ وَالأَرْضُ﴿\n\r\n\n\r\n(பாக்கியம் பெற்றவர்கள் சுவர்க்கத்தில் இருப்பார்கள்; வானங்களும் பூமியும் நிலைத்திருக்கும் காலமெல்லாம் அவர்கள் அதில் நிரந்தரமாகத் தங்கியிருப்பார்கள்) (11:108). ﴾حَسُنَتْ مُسْتَقَرّاً وَمُقَاماً﴿\n\r\n\n\r\n(அது தங்குமிடமாகவும், ஓய்வெடுக்கும் இடமாகவும் மிகவும் அழகானது.) அதன் தோற்றம் மிக அழகானது; தங்குவதற்கும் ஓய்வெடுப்பதற்கும் அது மிகச் சிறந்த இடமாகும். பிறகு அல்லாஹ் கூறுகிறான்: ﴾قُلْ مَا يَعْبَؤُا بِكُمْ رَبِّى لَوْلاَ دُعَآؤُكُمْ﴿\n\r\n\n\r\n(கூறுவீராக: \"நீங்கள் அவனைப் பிரார்த்திப்பதன் (வணங்குவதன்) காரணமாக அன்றி, என் இறைவன் உங்கள் மீது கவனம் செலுத்த மாட்டான்...\") அதாவது, நீங்கள் அவனை வணங்கவில்லை என்றால் அவன் உங்கள் மீது கவனம் செலுத்த மாட்டான். ஏனெனில், மனிதர்களைத் தன்னை மட்டுமே வணங்குவதற்காகவும், காலையிலும் மாலையிலும் தன்னைத் துதிப்பதற்காகவுமே அவன் படைத்தான். அவனது கூற்று: ﴾فَقَدْ كَذَّبْتُمْ﴿\n\r\n\n\r\n(ஆனால், நீங்களோ நிச்சயமாக (சத்தியத்தைப்) பொய்யாக்கினீர்கள்.) \"ஓ நிராகரிப்பாளர்களே!\" ﴾فَسَوْفَ يَكُونُ لِزَاماً﴿\n\r\n\n\r\n(ஆகவே, அந்தத் தண்டனை உங்களை ஒருபோதும் பிரியாது.) அதாவது, உங்களது அந்த மறுப்பு ஒருபோதும் உங்களை விட்டு நீங்காது; அது இவ்வுலகிலும் மறுமையிலும் உங்களின் தண்டனைக்கும், அழிவிற்கும், நாசத்திற்கும் காரணமாக அமையும். அப்துல்லாஹ் பின் மஸ்ஊத் (ரழி), உபை பின் கஅப் (ரழி), முஹம்மது பின் கஅப் அல்-குரழீ, முஜாஹித், அத்-தஹ்ஹாக், கதாதா, அஸ்-ஸுத்தீ மற்றும் பலர் விளக்கியது போல், இது பத்ருப் போர் நடைபெற்ற நாளையும் குறிக்கும். ﴾فَسَوْفَ يَكُونُ لِزَاماً﴿\n\r\n\n\r\n(ஆகவே, அந்தத் தண்டனை உங்களை ஒருபோதும் பிரியாது.) அல்-ஹஸன் அல்-பஸரீ அவர்கள் கூறுகையில், \"இது மறுமை நாளைக் குறிக்கும்\" என்றார்கள். இந்த இரண்டு விளக்கங்களுக்கும் இடையில் எவ்வித முரண்பாடும் இல்லை. இத்துடன் ஸூரத்துல் ஃபுர்கானின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் நன்றியும் அல்லாஹ்வுக்கே உரியது."}}};})(self);
